const gitaData = {"chapters":[{"chapter":1,"name":"अर्जुनविषादयोग","name_meaning":"Arjuna's Dilemma","name_translation":"Arjuna Visada Yoga","verses_count":47},{"chapter":2,"name":"सांख्ययोग","name_meaning":"Transcendental Knowledge","name_translation":"Sankhya Yoga","verses_count":72},{"chapter":3,"name":"कर्मयोग","name_meaning":"Path of Selfless Service","name_translation":"Karma Yoga","verses_count":43},{"chapter":4,"name":"ज्ञानकर्मसंन्यासयोग","name_meaning":"Path of Knowledge and the Disciplines of Action","name_translation":"Jnana Karma Sanyasa Yoga","verses_count":42},{"chapter":5,"name":"कर्मसंन्यासयोग","name_meaning":"Path of Renunciation","name_translation":"Karma Sanyasa Yoga","verses_count":29},{"chapter":6,"name":"ध्यानयोग","name_meaning":"Path of Meditation","name_translation":"Dhyana Yoga","verses_count":47},{"chapter":7,"name":"ज्ञानविज्ञानयोग","name_meaning":"Self-Knowledge and Enlightenment","name_translation":"Gyaan Vigyana Yoga","verses_count":30},{"chapter":8,"name":"अक्षरब्रह्मयोग","name_meaning":"Path of the Eternal God","name_translation":"Akshara Brahma Yoga","verses_count":28},{"chapter":9,"name":"राजविद्याराजगुह्ययोग","name_meaning":"Yoga through the King of Sciences","name_translation":"Raja Vidya Yoga","verses_count":34},{"chapter":10,"name":"विभूतियोग","name_meaning":"Yoga through Appreciating the Infinite Opulences of God","name_translation":"Vibhooti Yoga","verses_count":42},{"chapter":11,"name":"विश्वरूपदर्शनयोग","name_meaning":"Yoga through Beholding the Cosmic Form of God","name_translation":"Vishwaroopa Darshana Yoga","verses_count":55},{"chapter":12,"name":"भक्तियोग","name_meaning":"The Yoga of Devotion","name_translation":"Bhakti Yoga","verses_count":20},{"chapter":13,"name":"क्षेत्र-क्षेत्रज्ञविभागयोग","name_meaning":"Yoga through Distinguishing the Field and the Knower of the Field","name_translation":"Ksetra Ksetrajna Vibhaaga Yoga","verses_count":35},{"chapter":14,"name":"गुणत्रयविभागयोग","name_meaning":"Yoga through Understanding the Three Modes of Material Nature","name_translation":"Gunatraya Vibhaga Yoga","verses_count":27},{"chapter":15,"name":"पुरुषोत्तमयोग","name_meaning":"The Yoga of the Supreme Divine Personality","name_translation":"Purushottama Yoga","verses_count":20},{"chapter":16,"name":"दैवासुरसम्पद्विभागयोग","name_meaning":"Yoga through Discerning the Divine and Demoniac Natures","name_translation":"Daivasura Sampad Vibhaga Yoga","verses_count":24},{"chapter":17,"name":"श्रद्धात्रयविभागयोग","name_meaning":"Yoga through Discerning the Three Divisions of Faith","name_translation":"Sraddhatraya Vibhaga Yoga","verses_count":28},{"chapter":18,"name":"मोक्षसंन्यासयोग","name_meaning":"Yoga through the Perfection of Renunciation and Surrender","name_translation":"Moksha Sanyaas Yoga","verses_count":78}],"verses":{"1.1":{"chapter":1,"verse":1,"sloka":"धृतराष्ट्र उवाच\n\nधर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः।\n\nमामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय।।1.1।।","transliteration":"dhṛitarāśhtra uvācha\ndharma-kṣhetre kuru-kṣhetre samavetā yuyutsavaḥ\nmāmakāḥ pāṇḍavāśhchaiva kimakurvata sañjaya","english":"Dhritarashtra said, \"What did my people and the sons of Pandu do when they had assembled together, eager for battle, on the holy plain of Kurukshetra, O Sanjaya?\"","hindi":"धृतराष्ट्र ने कहा -- हे संजय ! धर्मभूमि कुरुक्षेत्र में एकत्र हुए युद्ध के इच्छुक (युयुत्सव:) मेरे और पाण्डु के पुत्रों ने क्या किया?","gujarati":"ધૃતરાષ્ટ્રે કહ્યું -- હે સંજય! ધર્મભૂમિ કુરુક્ષેત્રમાં યુદ્ધની ઈચ્છાથી એકત્ર થયેલા મારા અને પાંડુના પુત્રોએ શું કર્યું?"},"1.2":{"chapter":1,"verse":2,"sloka":"सञ्जय उवाच\n\nदृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा।\n\nआचार्यमुपसङ्गम्य राजा वचनमब्रवीत्।।1.2।।","transliteration":"sañjaya uvācha\ndṛiṣhṭvā tu pāṇḍavānīkaṁ vyūḍhaṁ duryodhanastadā\nāchāryamupasaṅgamya rājā vachanamabravīt","english":"Sanjaya said: Having seen the army of the Pandavas drawn up in battle array, King Duryodhana approached his teacher, Drona, and spoke these words.","hindi":"संजय ने कहा -- पाण्डव-सैन्य की व्यूह रचना देखकर राजा दुर्योधन ने आचार्य द्रोण के पास जाकर ये वचन कहे।","gujarati":"સંજયે કહ્યું -- પાંડવોની સેનાની વ્યૂહરચના જોઈને, રાજા દુર્યોધન આચાર્ય દ્રોણ પાસે ગયા અને આ વચન કહ્યું."},"1.3":{"chapter":1,"verse":3,"sloka":"पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम्।\n\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता।।1.3।।","transliteration":"paśhyaitāṁ pāṇḍu-putrāṇām āchārya mahatīṁ chamūm\nvyūḍhāṁ drupada-putreṇa tava śhiṣhyeṇa dhīmatā","english":"Behold, O Teacher! This mighty army of the sons of Pandu, arrayed by the son of Drupada, thy wise disciple.","hindi":"हे आचार्य ! आपके बुद्धिमान शिष्य द्रुपदपुत्र (धृष्टद्द्युम्न) द्वारा व्यूहाकार खड़ी की गयी पाण्डु पुत्रों की इस महती सेना को देखिये।","gujarati":"હે આચાર્ય! તમારા બુદ્ધિમાન શિષ્ય, દ્રુપદપુત્ર (ધૃષ્ટદ્યુમ્ન) દ્વારા વ્યૂહાકારે ગોઠવાયેલી પાંડુપુત્રોની આ વિશાળ સેનાને જુઓ."},"1.4":{"chapter":1,"verse":4,"sloka":"अत्र शूरा महेष्वासा भीमार्जुनसमा युधि।\n\nयुयुधानो विराटश्च द्रुपदश्च महारथः।।1.4।।","transliteration":"atra śhūrā maheṣhvāsā bhīmārjuna-samā yudhi\nyuyudhāno virāṭaśhcha drupadaśhcha mahā-rathaḥ","english":"Here are heroes, mighty archers, equal in battle to Bhima and Arjuna, Yuyudhana (Satyaki), Virata, and Drupada—all mighty warriors.","hindi":"इस सेना में महान् धनुर्धारी शूर योद्धा है ,  जो युद्ध में भीम और अर्जुन के समान हैं , जैसे --  युयुधान, विराट तथा महारथी राजा द्रुपद।","gujarati":"આ સેનામાં મહાન ધનુર્ધારી અને શૂરવીર યોદ્ધાઓ છે, જે યુદ્ધમાં ભીમ અને અર્જુન સમાન છે — જેમ કે યુયુધાન, વિરાટ અને મહારથી રાજા દ્રુપદ."},"1.5":{"chapter":1,"verse":5,"sloka":"धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान्।\n\nपुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुङ्गवः।।1.5।।","transliteration":"dhṛiṣhṭaketuśhchekitānaḥ kāśhirājaśhcha vīryavān\npurujit kuntibhojaśhcha śhaibyaśhcha nara-puṅgavaḥ\nyudhāmanyuśhcha vikrānta uttamaujāśhcha vīryavān","english":"Dhrishtaketu, Chekitana, the valiant king of Kasi, Purujit, Kuntibhoja, and Saibya—the best of men.","hindi":"धृष्टकेतु, चेकितान, बलवान काशिराज,  पुरुजित्, कुन्तिभोज और मनुष्यों में श्रेष्ठ शैब्य।","gujarati":"ધૃષ્ટકેતુ, ચેકિતાન, બળવાન કાશીરાજ, પુરુજિત, કુંતિભોજ અને પુરુષોમાં શ્રેષ્ઠ શૈબ્ય."},"1.6":{"chapter":1,"verse":6,"sloka":"युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान्।\n\nसौभद्रो द्रौपदेयाश्च सर्व एव महारथाः।।1.6।।","transliteration":"saubhadro draupadeyāśhcha sarva eva mahā-rathāḥ","english":"The strong Yudhamanyu and the brave Uttamaujas, the son of Subhadra (Abhimanyu, the son of Subhadra and Arjuna), and the sons of Draupadi, all of them great charioteers (great heroes).\"","hindi":"पराक्रमी युधामन्यु,  बलवान् उत्तमौजा,  सुभद्रापुत्र (अभिमन्यु) और द्रोपदी के पुत्र -- ये सब महारथी हैं।","gujarati":"પરાક્રમી યુધામન્યુ, બળવાન ઉત્તમૌજા, સુભદ્રાપુત્ર (અભિમન્યુ) અને દ્રૌપદીના પુત્રો — આ સૌ મહારથી છે."},"1.7":{"chapter":1,"verse":7,"sloka":"अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम।\n\nनायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते।।1.7।।","transliteration":"asmākaṁ tu viśhiṣhṭā ye tānnibodha dwijottama\nnāyakā mama sainyasya sanjñārthaṁ tānbravīmi te","english":"Know also, O best among the twice-born! the names of those who are the most distinguished amongst ourselves, the leaders of my army; these I name to you for your information.","hindi":"हे द्विजोत्तम ! हमारे पक्ष में भी जो विशिष्ट योद्धागण हैं , उनको आप जान लीजिये; आपकी जानकारी के लिये अपनी सेना के नायकों के नाम मैं आपको बताता हूँ।","gujarati":"હે દ્વિજોત્તમ! હવે આપણા પક્ષમાં પણ જે વિશિષ્ટ યોદ્ધાઓ છે, તેમને આપ જાણી લો. તમારી જાણકારી માટે હું મારી સેનાના નાયકોના નામ આપને જણાવું છું."},"1.8":{"chapter":1,"verse":8,"sloka":"भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः।\n\nअश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च।।1.8।।","transliteration":"bhavānbhīṣhmaśhcha karṇaśhcha kṛipaśhcha samitiñjayaḥ\naśhvatthāmā vikarṇaśhcha saumadattis tathaiva cha","english":"\"Thou thyself, Bhishma, Karna, Kripa, the victorious in war, Asvatthama, Vikarna, and Bhurisrava, the son of Somadatta—all these are ready for battle.\"","hindi":"एक तो स्वयं आप, भीष्म, कर्ण, और युद्ध विजयी कृपाचार्य तथा अश्वत्थामा, विकर्ण और सोमदत्त का पुत्र है।","gujarati":"એક તો સ્વયં આપ, ભીષ્મ, કર્ણ અને યુદ્ધવિજયી કૃપાચાર્ય તથા અશ્વત્થામા, વિકર્ણ અને સોમદત્તનો પુત્ર ભૂરિશ્રવા."},"1.9":{"chapter":1,"verse":9,"sloka":"अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः।\n\nनानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः।।1.9।।","transliteration":"anye cha bahavaḥ śhūrā madarthe tyaktajīvitāḥ\nnānā-śhastra-praharaṇāḥ sarve yuddha-viśhāradāḥ","english":"And also many other heroes, ready to give up their lives for my sake, armed with various weapons and missiles, all well-skilled in battle.","hindi":"मेरे लिए प्राण त्याग करने के लिए तैयार, अनेक प्रकार के शस्त्रास्त्रों से सुसज्जित तथा युद्ध में कुशल और भी अनेक शूर वीर हैं।","gujarati":"અને બીજા પણ ઘણા શૂરવીરો છે જેઓ મારે માટે પોતાના પ્રાણ ત્યાગવા તૈયાર છે. તેઓ અનેક પ્રકારના શસ્ત્રાસ્ત્રોથી સુસજ્જ અને યુદ્ધકળામાં નિપુણ છે."},"1.10":{"chapter":1,"verse":10,"sloka":"अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम्।\n\nपर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम्।।1.10।।","transliteration":"aparyāptaṁ tadasmākaṁ balaṁ bhīṣhmābhirakṣhitam\nparyāptaṁ tvidameteṣhāṁ balaṁ bhīmābhirakṣhitam","english":"Our army, marshalled by Bhishma, is insufficient, whereas theirs, marshalled by Bhima, is sufficient.","hindi":"भीष्म के द्वारा हमारी रक्षित सेना अपर्याप्त है; किन्तु भीम द्वारा रक्षित उनकी सेना पर्याप्त है अथवा, भीष्म के द्वारा रक्षित हमारी सेना अपरिमित है किन्तु भीम के द्वारा रक्षित उनकी सेना परिमित ही है।","gujarati":"ભીષ્મપિતામહ દ્વારા રક્ષાયેલી આપણી સેના સર્વ પ્રકારે અજેય છે, જ્યારે ભીમ દ્વારા રક્ષાયેલી એમની સેના મર્યાદિત છે."},"1.11":{"chapter":1,"verse":11,"sloka":"अयनेषु च सर्वेषु यथाभागमवस्थिताः।\n\nभीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि।।1.11।।","transliteration":"ayaneṣhu cha sarveṣhu yathā-bhāgamavasthitāḥ\nbhīṣhmamevābhirakṣhantu bhavantaḥ sarva eva hi","english":"Therefore, do all of you, stationed in your respective positions in the several divisions of the army, protect Bhishma alone.","hindi":"विभिन्न मोर्चों पर अपने-अपने स्थान पर स्थित रहते हुए आप सब लोग भीष्म पितामह की ही सब ओर से रक्षा करें।","gujarati":"આથી, પોતપોતાના મોરચે રહીને, આપ સૌ બધી બાજુથી ફક્ત ભીષ્મપિતામહની જ રક્ષા કરો."},"1.12":{"chapter":1,"verse":12,"sloka":"तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः।\n\nसिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान्।।1.12।।","transliteration":"tasya sañjanayan harṣhaṁ kuru-vṛiddhaḥ pitāmahaḥ\nsiṁha-nādaṁ vinadyochchaiḥ śhaṅkhaṁ dadhmau pratāpavān","english":"His glorious grandsire, the oldest of the Kauravas, roared like a lion to cheer Duryodhana and blew his conch.","hindi":"उस समय कौरवों में वृद्ध, प्रतापी पितामह भीष्म ने उस (दुर्योधन) के हृदय में हर्ष उत्पन्न करते हुये उच्च स्वर में गरज कर शंखध्वनि की।","gujarati":"ત્યારે, કૌરવોમાં સૌથી વૃદ્ધ, પ્રતાપી પિતામહ ભીષ્મે દુર્યોધનને હર્ષ પમાડતા, સિંહની જેમ ગર્જના કરીને ઉચ્ચ સ્વરે શંખનાદ કર્યો."},"1.13":{"chapter":1,"verse":13,"sloka":"ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः।\n\nसहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत्।।1.13।।","transliteration":"tataḥ śhaṅkhāśhcha bheryaśhcha paṇavānaka-gomukhāḥ\nsahasaivābhyahanyanta sa śhabdastumulo ’bhavat","english":"Then, suddenly, conches, kettledrums, tabors, drums, and cow horns blared forth from the Kaurava side, and the sound was tremendous.","hindi":"तत्पश्चात् शंख, नगारे, ढोल व शृंगी आदि वाद्य एक साथ ही बज उठे, जिनका बड़ा भयंकर शब्द हुआ।","gujarati":"ત્યારપછી શંખ, નગારા, ઢોલ અને રણશિંગા જેવા વાજિંત્રો એકસાથે વાગી ઊઠ્યા, અને તેમનો અવાજ અત્યંત ભયંકર હતો."},"1.14":{"chapter":1,"verse":14,"sloka":"ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ।\n\nमाधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः।।1.14।।","transliteration":"tataḥ śhvetairhayairyukte mahati syandane sthitau\nmādhavaḥ pāṇḍavaśhchaiva divyau śhaṅkhau pradadhmatuḥ","english":"Then, Madhava (Krishna) and the son of Pandu (Arjuna), seated in the magnificent chariot yoked with white horses, blew divine conches.","hindi":"इसके उपरान्त श्वेत अश्वों से युक्त भव्य रथ में बैठे हुये माधव (श्रीकृष्ण) और पाण्डुपुत्र अर्जुन ने भी अपने दिव्य शंख बजाये।","gujarati":"ત્યારપછી, સફેદ ઘોડાઓ જોડેલા ભવ્ય રથમાં બિરાજમાન શ્રીકૃષ્ણ (માધવ) અને અર્જુન (પાંડુપુત્ર) એ પણ પોતાના દિવ્ય શંખ વગાડ્યા."},"1.15":{"chapter":1,"verse":15,"sloka":"पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः।\n\nपौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः।।1.15।।","transliteration":"pāñchajanyaṁ hṛiṣhīkeśho devadattaṁ dhanañjayaḥ\npauṇḍraṁ dadhmau mahā-śhaṅkhaṁ bhīma-karmā vṛikodaraḥ","english":"Hrishikesha blew the Panchajanya, Arjuna blew the Devadatta, and Bhima, the wolf-bellied doer of terrible deeds, blew the great conch Paundra.","hindi":"भगवान् हृषीकेश ने पांचजन्य, धनंजय (अर्जुन) ने देवदत्त तथा भयंकर कर्म करने वाले भीम ने पौण्डू नामक महाशंख बजाया।","gujarati":"ભગવાન હૃષીકેશે પાંચજન્ય નામનો, અર્જુને દેવદત્ત નામનો અને ભયંકર કર્મો કરનાર ભીમસેને પૌંડ્ર નામનો મહાશંખ વગાડ્યો."},"1.16":{"chapter":1,"verse":16,"sloka":"अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः।\n\nनकुलः सहदेवश्च सुघोषमणिपुष्पकौ।।1.16।।","transliteration":"anantavijayaṁ rājā kuntī-putro yudhiṣhṭhiraḥ\nnakulaḥ sahadevaśhcha sughoṣha-maṇipuṣhpakau","english":"King Yudhishthira, the son of Kunti, blew the Anantavijaya; Nakula and Sahadeva blew the Sughosha and the Manipushpaka.","hindi":"कुन्तीपुत्र राजा युधिष्ठिर ने अनन्त विजय नामक शंख और नकुल व सहदेव ने क्रमश:  सुघोष और मणिपुष्पक नामक शंख बजाये।","gujarati":"કુંતીપુત્ર રાજા યુધિષ્ઠિરે અનંતવિજય નામનો શંખ અને નકુલ તથા સહદેવે અનુક્રમે સુઘોષ અને મણિપુષ્પક નામના શંખ વગાડ્યા."},"1.17":{"chapter":1,"verse":17,"sloka":"काश्यश्च परमेष्वासः शिखण्डी च महारथः।\n\nधृष्टद्युम्नो विराटश्च सात्यकिश्चापराजितः।।1.17।।","transliteration":"kāśhyaśhcha parameṣhvāsaḥ śhikhaṇḍī cha mahā-rathaḥ\ndhṛiṣhṭadyumno virāṭaśhcha sātyakiśh chāparājitaḥ","english":"The king of Kasi, an excellent archer, Sikhandi, the mighty car-warrior, Dhrishtadyumna, Virata, and Satyaki, the unconquered.","hindi":"श्रेष्ठ धनुषवाले काशिराज, महारथी शिखण्डी, धृष्टद्युम्न,  राजा विराट और अजेय सात्यकि।","gujarati":"શ્રેષ્ઠ ધનુર્ધારી કાશીરાજ, મહારથી શિખંડી, ધૃષ્ટદ્યુમ્ન, વિરાટ અને અજેય સાત્યકિ."},"1.18":{"chapter":1,"verse":18,"sloka":"द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते।\n\nसौभद्रश्च महाबाहुः शङ्खान्दध्मुः पृथक्पृथक्।।1.18।।","transliteration":"drupado draupadeyāśhcha sarvaśhaḥ pṛithivī-pate\nsaubhadraśhcha mahā-bāhuḥ śhaṅkhāndadhmuḥ pṛithak pṛithak","english":"Drupada and the sons of Draupadi, O Lord of the Earth, and the son of Subhadra, the mighty-armed, blew their conches each separately.","hindi":"हे राजन् ! राजा द्रुपद,  द्रौपदी के पुत्र और महाबाहु सौभद्र (अभिमन्यु) इन सब ने अलग-अलग शंख बजाये।","gujarati":"હે રાજન! દ્રુપદ, દ્રૌપદીના પુત્રો અને મહાબાહુ સુભદ્રાપુત્ર અભિમન્યુ, આ સૌએ પણ પોતપોતાના શંખ વગાડ્યા."},"1.19":{"chapter":1,"verse":19,"sloka":"स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत्।\n\nनभश्च पृथिवीं चैव तुमुलो व्यनुनादयन्।।1.19।।","transliteration":"sa ghoṣho dhārtarāṣhṭrāṇāṁ hṛidayāni vyadārayat\nnabhaśhcha pṛithivīṁ chaiva tumulo nunādayan","english":"The tumultuous sound rent the hearts of Dhritarashtra's party, reverberating through both heaven and earth.","hindi":"वह भयंकर घोष आकाश और पृथ्वी पर गूँजने लगा और उसने धृतराष्ट्र के पुत्रों के हृदय विदीर्ण कर दिये।","gujarati":"તે ભયંકર શબ્દથી આકાશ અને પૃથ્વી ગુંજી ઊઠ્યા અને તેણે ધૃતરાષ્ટ્રના પુત્રો (કૌરવો) ના હૃદય ચીરી નાખ્યા."},"1.20":{"chapter":1,"verse":20,"sloka":"अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः।\n\nप्रवृत्ते शस्त्रसंपाते धनुरुद्यम्य पाण्डवः।।1.20।।","transliteration":"atha vyavasthitān dṛiṣhṭvā dhārtarāṣhṭrān kapi-dhwajaḥ\npravṛitte śhastra-sampāte dhanurudyamya pāṇḍavaḥ\nhṛiṣhīkeśhaṁ tadā vākyam idam āha mahī-pate","english":"Then, seeing the people of Dhritarashtra's party standing arrayed and the discharge of weapons about to begin, Arjuna, the son of Pandu whose ensign was a monkey, took up his bow and said the following to Krishna, O Lord of the Earth.","hindi":"हे महीपते ! इस प्रकार जब युद्ध प्रारम्भ होने वाला ही था कि कपिध्वज अर्जुन ने धृतराष्ट्र के पुत्रों को स्थित देखकर धनुष उठाकर भगवान् हृषीकेश से ये शब्द कहे।","gujarati":"હે રાજન! હવે જેમની ધજા પર હનુમાનજી બિરાજમાન છે તેવા અર્જુને, ધૃતરાષ્ટ્રના પુત્રોને યુદ્ધ માટે તૈયાર જોઈને, શસ્ત્રપ્રહારની તૈયારી સમયે, પોતાનું ધનુષ્ય ઉપાડીને ભગવાન હૃષીકેશને આ વચન કહ્યું."},"1.21":{"chapter":1,"verse":21,"sloka":"अर्जुन उवाच\n\nहृषीकेशं तदा वाक्यमिदमाह महीपते।\n\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत।।1.21।।","transliteration":"arjuna uvācha\nsenayor ubhayor madhye rathaṁ sthāpaya me ’chyuta","english":"Arjuna said, \"O Krishna, place my chariot in the middle between the two armies, so that I may behold those who stand here, desirous to fight, and know with whom I must fight when the battle is about to commence.\"","hindi":"अर्जुन ने कहा -- हे! अच्युत मेरे रथ को दोनों सेनाओं के मध्य खड़ा कीजिये।","gujarati":"અર્જુને કહ્યું -- હે અચ્યુત! મારા રથને બંને સેનાઓની વચ્ચે ઊભો રાખો."},"1.22":{"chapter":1,"verse":22,"sloka":"यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान्।\n\nकैर्मया सह योद्धव्यमस्मिन्रणसमुद्यमे।।1.22।।","transliteration":"yāvadetān nirīkṣhe ’haṁ yoddhu-kāmān avasthitān\nkairmayā saha yoddhavyam asmin raṇa-samudyame","english":"Arjuna said, \"O Krishna, place my chariot in the middle between the two armies, so that I may behold those who stand here, desirous to fight, and know with whom I must fight when the battle is about to commence.\"","hindi":"जिससे मैं युद्ध की इच्छा से खड़े इन लोगों का निरीक्षण कर सकूँ कि इस युद्ध में मुझे किनके साथ युद्ध करना है।","gujarati":"જેથી હું અહીં યુદ્ધની ઈચ્છાથી ઊભેલા લોકોને બરાબર જોઈ શકું અને જાણી શકું કે આ યુદ્ધમાં મારે કોની કોની સાથે લડવાનું છે."},"1.23":{"chapter":1,"verse":23,"sloka":"योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः।\n\nधार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः।।1.23।।","transliteration":"yotsyamānān avekṣhe ’haṁ ya ete ’tra samāgatāḥ\ndhārtarāṣhṭrasya durbuddher yuddhe priya-chikīrṣhavaḥ","english":"For I desire to observe those who are assembled here to fight, wishing to please in battle the evil-minded Duryodhana—the son of Dhritarashtra.","hindi":"दुर्बुद्धि धार्तराष्ट्र (दुर्योधन) का युद्ध में प्रिय चाहने वाले जो ये राजा लोग यहाँ एकत्र हुए हैं, उन युद्ध करने वालों को मैं देखूँगा।","gujarati":"હું એ યોદ્ધાઓને જોવા માંગુ છું જેઓ અહીં દુર્બુદ્ધિ દુર્યોધન(ધૃતરાષ્ટ્રના પુત્ર)ને યુદ્ધમાં પ્રસન્ન કરવાની ઈચ્છાથી એકત્ર થયા છે."},"1.24":{"chapter":1,"verse":24,"sloka":"संजय उवाच\n\nएवमुक्तो हृषीकेशो गुडाकेशेन भारत।\n\nसेनयोरुभयोर्मध्ये स्थापयित्वा रथोत्तमम्।।1.24।।","transliteration":"sañjaya uvācha\nevam ukto hṛiṣhīkeśho guḍākeśhena bhārata\nsenayor ubhayor madhye sthāpayitvā rathottamam","english":"Sanjaya said, Thus addressed by Arjuna, Krishna stationed the best of chariots, O Dhritarashtra, in the midst of the two armies.","hindi":"संजय ने कहा -- हे भारत (धृतराष्ट्र) ! अर्जुन के इस प्रकार कहने पर भगवान् हृषीकेश ने दोनों सेनाओं के मध्य उत्तम रथ को खड़ा करके।","gujarati":"સંજયે કહ્યું -- હે ભરતવંશી (ધૃતરાષ્ટ્ર)! અર્જુને આમ કહેતા, ભગવાન હૃષીકેશે તે ઉત્તમ રથને બંને સેનાઓની વચ્ચે ઊભો રાખ્યો."},"1.25":{"chapter":1,"verse":25,"sloka":"भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम्।\n\nउवाच पार्थ पश्यैतान्समवेतान्कुरूनिति।।1.25।।","transliteration":"bhīṣhma-droṇa-pramukhataḥ sarveṣhāṁ cha mahī-kṣhitām\nuvācha pārtha paśhyaitān samavetān kurūn iti","english":"In front of Bhishma and Drona, and all the rulers of the earth, he said: \"O Arjuna, son of Pritha, behold these Kurus gathered together.\"","hindi":"भीष्म, द्रोण तथा पृथ्वी के समस्त शासकों के समक्ष उन्होंने कहा, \"हे पार्थ यहाँ एकत्र हुये कौरवों को देखो\"।","gujarati":"અને ભીષ્મ, દ્રોણ તથા પૃથ્વીના સર્વ શાસકોની સામે કહ્યું, \"હે પાર્થ! અહીં એકત્ર થયેલા આ કૌરવોને જો.\""},"1.26":{"chapter":1,"verse":26,"sloka":"तत्रापश्यत्स्थितान्पार्थः पितृ़नथ पितामहान्।\n\nआचार्यान्मातुलान्भ्रातृ़न्पुत्रान्पौत्रान्सखींस्तथा।।1.26।।","transliteration":"tatrāpaśhyat sthitān pārthaḥ pitṝīn atha pitāmahān\nāchāryān mātulān bhrātṝīn putrān pautrān sakhīṁs tathā\nśhvaśhurān suhṛidaśh chaiva senayor ubhayor api","english":"Then, Arjuna (son of Pritha) saw there (in the armies) stationed fathers, grandfathers, teachers, maternal uncles, brothers, sons, grandsons, and friends.","hindi":"वहाँ अर्जुन ने उन दोनों सेनाओं में खड़े पिता के भाइयों,  पितामहों,  आचार्यों,  मामाओं, भाइयों, पुत्रों,  पौत्रों,  मित्रों,  श्वसुरों और सुहृदों को भी देखा।","gujarati":"ત્યાં અર્જુને બંને સેનાઓમાં ઉપસ્થિત પોતાના કાકા-દાદાઓ, પિતામહો, આચાર્યો, મામાઓ, ભાઈઓ, પુત્રો, પૌત્રો તથા મિત્રોને જોયા."},"1.27":{"chapter":1,"verse":27,"sloka":"श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि।\n\nतान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान्।।1.27।।","transliteration":"tān samīkṣhya sa kaunteyaḥ sarvān bandhūn avasthitān\nkṛipayā parayāviṣhṭo viṣhīdann idam abravīt","english":"He saw fathers-in-law and friends in both the armies. The son of Kunti, Arjuna, seeing all those kinsmen thus standing arrayed, spoke sorrowfully, deeply filled with pity.","hindi":"इस प्रकार उन सब बन्धु-बान्धवों को खड़े देखकर कुन्ती पुत्र अर्जुन का मन करुणा से भर गया और विषादयुक्त होकर उसने यह कहा।","gujarati":"તથા સસરાઓ અને શુભચિંતકોને પણ જોયા. તે બધા જ સ્વજનોને ત્યાં ઉપસ્થિત જોઈને, કુંતીપુત્ર અર્જુન અત્યંત કરુણાથી ભરાઈ ગયો અને શોક સાથે આ વચન બોલ્યો."},"1.28":{"chapter":1,"verse":28,"sloka":"अर्जुन उवाच\n\nकृपया परयाऽऽविष्टो विषीदन्निदमब्रवीत्।\n\nदृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम्।।1.28।।","transliteration":"arjuna uvācha\ndṛiṣhṭvemaṁ sva-janaṁ kṛiṣhṇa yuyutsuṁ samupasthitam","english":"Arjuna said, \"O Krishna, seeing my kinsmen arrayed here, eager to fight,","hindi":"अर्जुन ने कहा -- हे कृष्ण ! युद्ध की इच्छा रखकर उपस्थित हुए इन स्वजनों को देखकर मेरे अंग शिथिल हुये जाते हैं, मुख भी सूख रहा है और मेरे शरीर में कम्प तथा रोमांच हो रहा है।।","gujarati":"અર્જુને કહ્યું -- હે કૃષ્ણ! યુદ્ધની ઈચ્છાથી અહીં એકત્ર થયેલા આ મારા સ્વજનોને જોઈને મારા અંગો શિથિલ થઈ રહ્યા છે અને મોં સુકાઈ રહ્યું છે."},"1.29":{"chapter":1,"verse":29,"sloka":"सीदन्ति मम गात्राणि मुखं च परिशुष्यति।\n\nवेपथुश्च शरीरे मे रोमहर्षश्च जायते।।1.29।।","transliteration":"sīdanti mama gātrāṇi mukhaṁ cha pariśhuṣhyati\nvepathuśh cha śharīre me roma-harṣhaśh cha jāyate","english":"My limbs fail, my mouth is parched, my body quivers, and my hair stands on end.","hindi":"अर्जुन ने कहा -- हे कृष्ण !  युद्ध की इच्छा रखकर उपस्थित हुए इन स्वजनों को देखकर मेरे अंग शिथिल हुये जाते हैं,  मुख भी सूख रहा है और मेरे शरीर में कम्प तथा रोमांच हो रहा है।","gujarati":"મારા શરીરમાં કંપારી છૂટી રહી છે અને રૂંવાડા ઊભા થઈ ગયા છે."},"1.30":{"chapter":1,"verse":30,"sloka":"गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते।\n\nन च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः।।1.30।।","transliteration":"gāṇḍīvaṁ sraṁsate hastāt tvak chaiva paridahyate\nna cha śhaknomy avasthātuṁ bhramatīva cha me manaḥ","english":"The Gandiva slips from my hand, and my skin burns all over; I am unable to stand, and my mind is reeling, as it were.","hindi":"मेरे हाथ से गाण्डीव (धनुष) गिर रहा है और त्वचा जल रही है। मेरा मन भ्रमित सा हो रहा है,  और मैं खड़े रहने में असमर्थ हूँ।","gujarati":"મારા હાથમાંથી ગાંડીવ ધનુષ્ય સરી રહ્યું છે અને મારી ત્વચામાં બળતરા થઈ રહી છે. મારું મન ભ્રમિત થઈ રહ્યું છે અને હું ઊભા રહેવા માટે પણ અસમર્થ છું."},"1.31":{"chapter":1,"verse":31,"sloka":"निमित्तानि च पश्यामि विपरीतानि केशव।\n\nन च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे।।1.31।।","transliteration":"nimittāni cha paśhyāmi viparītāni keśhava\nna cha śhreyo ’nupaśhyāmi hatvā sva-janam āhave","english":"And I see ill omens, O Kesava. I do not see any good in slaying my kinsmen in battle.","hindi":"हे केशव ! मैं शकुनों को भी विपरीत ही देख रहा हूँ और युद्ध में (आहवे) अपने स्वजनों को मारकर कोई कल्याण भी नहीं देखता हूँ।","gujarati":"હે કેશવ! મને વિપરીત શુકનો દેખાઈ રહ્યા છે. યુદ્ધમાં પોતાના જ સ્વજનોને મારીને મને કોઈ કલ્યાણ દેખાતું નથી."},"1.32":{"chapter":1,"verse":32,"sloka":"न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च।\n\nकिं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा।।1.32।।","transliteration":"na kāṅkṣhe vijayaṁ kṛiṣhṇa na cha rājyaṁ sukhāni cha\nkiṁ no rājyena govinda kiṁ bhogair jīvitena vā","english":"I desire not victory, O Krishna, nor kingdom, nor pleasures.What use is dominion to us, O Krishna, or pleasures or even life?","hindi":"हे कृष्ण ! मैं न विजय चाहता हूँ, न राज्य और न सुखों को ही चाहता हूँ। हे गोविन्द ! हमें राज्य से अथवा भोगों से और जीने से भी क्या प्रयोजन है?।","gujarati":"હે કૃષ્ણ! હું વિજય, રાજ્ય કે સુખની ઈચ્છા રાખતો નથી. હે ગોવિંદ! અમને આવા રાજ્ય, ભોગ કે જીવનથી પણ શું લાભ?"},"1.33":{"chapter":1,"verse":33,"sloka":"येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च।\n\nत इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च।।1.33।।","transliteration":"yeṣhām arthe kāṅkṣhitaṁ no rājyaṁ bhogāḥ sukhāni cha\nta ime ’vasthitā yuddhe prāṇāṁs tyaktvā dhanāni cha","english":"Those for whose sake we desire kingdom, enjoyments, and pleasures stand here in battle, having renounced life and wealth.","hindi":"हमें जिनके लिये राज्य,  भोग और सुखादि की इच्छा है,  वे ही लोग धन और जीवन की आशा को त्यागकर युद्ध में खड़े हैं।","gujarati":"જેમના માટે આપણે રાજ્ય, ભોગ અને સુખ ઈચ્છીએ છીએ, તેઓ જ આજે પોતાના પ્રાણ અને ધનની આશા ત્યાગીને યુદ્ધમાં ઊભા છે."},"1.34":{"chapter":1,"verse":34,"sloka":"आचार्याः पितरः पुत्रास्तथैव च पितामहाः।\n\nमातुलाः श्चशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा।।1.34।।","transliteration":"āchāryāḥ pitaraḥ putrās tathaiva cha pitāmahāḥ\nmātulāḥ śhvaśhurāḥ pautrāḥ śhyālāḥ sambandhinas tathā","english":"Teachers, fathers, sons, and grandfathers, maternal uncles, fathers-in-law, grandsons, brothers-in-law, and other relatives—","hindi":"वे लोग गुरुजन,  ताऊ,  चाचा,  पुत्र,  पितामह,   श्वसुर,  पोते,  श्यालक तथा अन्य सम्बन्धी हैं।","gujarati":"અહીં આચાર્યો, પિતાઓ, પુત્રો, પિતામહો, મામાઓ, સસરાઓ, પૌત્રો, સાળાઓ અને અન્ય સંબંધીઓ જ છે."},"1.35":{"chapter":1,"verse":35,"sloka":"एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन।\n\nअपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते।।1.35।।","transliteration":"etān na hantum ichchhāmi ghnato ’pi madhusūdana\napi trailokya-rājyasya hetoḥ kiṁ nu mahī-kṛite","english":"These I do not wish to kill, O Krishna, even though they kill me, for the sake of dominion over the three worlds; leave alone killing them for the sake of the earth.\"","hindi":"हे मधुसूदन !  इनके मुझे मारने पर अथवा त्रैलोक्य के राज्य के लिये भी मैं इनको मारना नहीं चाहता,  फिर पृथ्वी के लिए कहना ही क्या है।","gujarati":"હે મધુસૂદન! ભલે તેઓ મને મારી નાખે, તો પણ હું તેમને મારવા નથી ઈચ્છતો, ત્રણેય લોકના રાજ્ય માટે પણ નહીં, તો પછી આ પૃથ્વી માટે તો શું કહેવું?"},"1.36":{"chapter":1,"verse":36,"sloka":"निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन।\n\nपापमेवाश्रयेदस्मान्हत्वैतानाततायिनः।।1.36।।","transliteration":"nihatya dhārtarāṣhṭrān naḥ kā prītiḥ syāj janārdana\npāpam evāśhrayed asmān hatvaitān ātatāyinaḥ","english":"By killing these sons of Dhritarashtra, what pleasure could be ours, O Janardana? Only sin would accrue to us from killing these felons.","hindi":"हे जनार्दन ! धृतराष्ट्र के पुत्रों की हत्या करके हमें क्या प्रसन्नता होगी?  इन आततायियों को मारकर तो हमें केवल पाप ही लगेगा।","gujarati":"હે જનાર્દન! ધૃતરાષ્ટ્રના પુત્રોને મારીને અમને શો આનંદ મળશે? આ આતતાયીઓને મારીને તો અમને માત્ર પાપ જ લાગશે."},"1.37":{"chapter":1,"verse":37,"sloka":"तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान्।\n\nस्वजनं हि कथं हत्वा सुखिनः स्याम माधव।।1.37।।","transliteration":"tasmān nārhā vayaṁ hantuṁ dhārtarāṣhṭrān sa-bāndhavān \nsva-janaṁ hi kathaṁ hatvā sukhinaḥ syāma mādhava","english":"Therefore, we should not kill the sons of Dhritarashtra, our relatives; for how can we be happy by killing our own kin, O Madhava (Krishna)?","hindi":"हे माधव  !  इसलिये अपने बान्धव धृतराष्ट्र के पुत्रों को मारना हमारे लिए योग्य नहीं है,  क्योंकि स्वजनों को मारकर हम कैसे सुखी होंगे।","gujarati":"આથી, હે માધવ! આપણા જ બાંધવ, ધૃતરાષ્ટ્રના પુત્રોનો વધ કરવો અમારે માટે યોગ્ય નથી. પોતાના જ સ્વજનોને મારીને આપણે કેવી રીતે સુખી થઈ શકીએ?"},"1.38":{"chapter":1,"verse":38,"sloka":"यद्यप्येते न पश्यन्ति लोभोपहतचेतसः।\n\nकुलक्षयकृतं दोषं मित्रद्रोहे च पातकम्।।1.38।।","transliteration":"yady apy ete na paśhyanti lobhopahata-chetasaḥ\nkula-kṣhaya-kṛitaṁ doṣhaṁ mitra-drohe cha pātakam","english":"Though they, with intelligence overpowered by greed, see no evil in the destruction of families and no sin in hostility to friends,","hindi":"यद्यपि लोभ से भ्रष्टचित्त हुये ये लोग कुलनाशकृत दोष और मित्र द्रोह में पाप नहीं देखते हैं।","gujarati":"ભલે લોભને કારણે જેમની બુદ્ધિ ભ્રષ્ટ થઈ છે તેવા આ લોકો કુળનો નાશ કરવામાં રહેલો દોષ અને મિત્રદ્રોહમાં રહેલું પાપ નથી જોઈ શકતા,"},"1.39":{"chapter":1,"verse":39,"sloka":"कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम्।\n\nकुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन।।1.39।।","transliteration":"kathaṁ na jñeyam asmābhiḥ pāpād asmān nivartitum\nkula-kṣhaya-kṛitaṁ doṣhaṁ prapaśhyadbhir janārdana","english":"Why should we not, who clearly see the evil in the destruction of families, learn to turn away from this sin, O Janardana (Krishna)?","hindi":"परन्तु,  हेे जनार्दन !  कुलक्षय से होने वाले दोष को जानने वाले हम लोगों को इस पाप से विरत होने के लिए क्यों नहीं सोचना चाहिये।","gujarati":"પરંતુ હે જનાર્દન! કુળના નાશથી થનારા દોષને જાણનારા આપણે આ પાપમાંથી દૂર હટવાનો વિચાર શા માટે ન કરવો જોઈએ?"},"1.40":{"chapter":1,"verse":40,"sloka":"कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः।\n\nधर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत।।1.40।।","transliteration":"kula-kṣhaye praṇaśhyanti kula-dharmāḥ sanātanāḥ\ndharme naṣhṭe kulaṁ kṛitsnam adharmo ’bhibhavaty uta","english":"In the destruction of a family, the immemorial religious rites of that family perish; on the destruction of spirituality, impiety indeed, overwhelms the whole family.","hindi":"कुल के नष्ट होने से सनातन धर्म नष्ट हो जाते हैं। धर्म नष्ट होने पर सम्पूर्ण कुल को अधर्म (पाप) दबा लेता है।","gujarati":"કુળનો નાશ થવાથી સનાતન કુળ-ધર્મ નષ્ટ પામે છે. ધર્મનો નાશ થવાથી સંપૂર્ણ કુળમાં પાપ અને અધર્મ ફેલાઈ જાય છે."},"1.41":{"chapter":1,"verse":41,"sloka":"अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः।\n\nस्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः।।1.41।।","transliteration":"adharmābhibhavāt kṛiṣhṇa praduṣhyanti kula-striyaḥ\nstrīṣhu duṣhṭāsu vārṣhṇeya jāyate varṇa-saṅkaraḥ","english":"O Krishna, by the prevalence of impiety, the women of the family become corrupt; and, when women are corrupted, O Varshenya (descendant of Vrishni), intermingling of castes arises.","hindi":"हे कृष्ण ! पाप के अधिक बढ़ जाने से कुल की स्त्रियां दूषित हो जाती हैं,  और हे वार्ष्णेय ! स्त्रियों के दूषित होने पर वर्णसंकर उत्पन्न होता है।","gujarati":"હે કૃષ્ણ! પાપ વધી જવાથી કુળની સ્ત્રીઓ દૂષિત થાય છે, અને હે વાર્ષ્ણેય! સ્ત્રીઓ દૂષિત થવાથી વર્ણસંકર ઉત્પન્ન થાય છે."},"1.42":{"chapter":1,"verse":42,"sloka":"सङ्करो नरकायैव कुलघ्नानां कुलस्य च।\n\nपतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः।।1.42।।","transliteration":"saṅkaro narakāyaiva kula-ghnānāṁ kulasya cha\npatanti pitaro hy eṣhāṁ lupta-piṇḍodaka-kriyāḥ","english":"Confusion of castes leads to hell for the slayers of the family, for their forebears fall, deprived of the offerings of rice-balls and libations of water.","hindi":"वह वर्णसंकर कुलघातियों को और कुल को नरक में ले जाने का कारण बनता है। पिण्ड और जलदान की क्रिया से वंचित इनके पितर भी नरक में गिर जाते हैं।","gujarati":"વર્ણસંકરતા કુળનો નાશ કરનારાઓને અને કુળને નરકમાં લઈ જાય છે. પિંડદાન અને તર્પણની ક્રિયાઓ ન મળવાથી તેમના પિતૃઓનું પણ પતન થાય છે."},"1.43":{"chapter":1,"verse":43,"sloka":"दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः।\n\nउत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः।।1.43।।","transliteration":"doṣhair etaiḥ kula-ghnānāṁ varṇa-saṅkara-kārakaiḥ\nutsādyante jāti-dharmāḥ kula-dharmāśh cha śhāśhvatāḥ","english":"By these evil deeds of the destroyers of the family, which cause confusion of castes, the eternal religious rites of the caste and the family are destroyed.","hindi":"इन वर्णसंकर कारक दोषों से कुलघाती दोषों से सनातन कुलधर्म और जातिधर्म नष्ट हो जाते हैं।","gujarati":"આ વર્ણસંકરતા ફેલાવનારા દોષોને કારણે કુળનો નાશ કરનારાઓના સનાતન કુળધર્મ અને જાતિધર્મ નષ્ટ થઈ જાય છે."},"1.44":{"chapter":1,"verse":44,"sloka":"उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन।\n\nनरकेऽनियतं वासो भवतीत्यनुशुश्रुम।।1.44।।","transliteration":"utsanna-kula-dharmāṇāṁ manuṣhyāṇāṁ janārdana\nnarake ‘niyataṁ vāso bhavatītyanuśhuśhruma","english":"We have heard, O Janardana, that those men in whose families the religious practices have been destroyed are inevitably destined to dwell in hell for an unknown period.","hindi":"हे जनार्दन !  हमने सुना है कि जिनके यहां कुल धर्म नष्ट हो जाता है,  उन मनुष्यों का अनियत काल तक नरक में वास होता है।","gujarati":"હે જનાર્દન! અમે સાંભળ્યું છે કે જેમના કુળધર્મ નષ્ટ થઈ જાય છે, તેવા મનુષ્યોને અનિશ્ચિત કાળ સુધી નરકમાં વાસ કરવો પડે છે."},"1.45":{"chapter":1,"verse":45,"sloka":"अहो बत महत्पापं कर्तुं व्यवसिता वयम्।\n\nयद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः।।1.45।।","transliteration":"aho bata mahat pāpaṁ kartuṁ vyavasitā vayam\nyad rājya-sukha-lobhena hantuṁ sva-janam udyatāḥ","english":"Alas! We are involved in a great sin, for we are prepared to kill our kinsmen, out of greed for the pleasures of a kingdom.","hindi":"अहो  !  शोक है कि हम लोग बड़ा भारी पाप करने का निश्चय कर बैठे हैं,  जो कि इस राज्यसुख के लोभ से अपने कुटुम्ब का नाश करने के लिये तैयार हो गये हैं।","gujarati":"અરે, આ કેટલા દુઃખની વાત છે કે આપણે રાજ્ય અને સુખના લોભમાં પોતાના જ સ્વજનોનો નાશ કરવા તૈયાર થઈને મોટું પાપ કરવા જઈ રહ્યા છીએ."},"1.46":{"chapter":1,"verse":46,"sloka":"यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः।\n\nधार्तराष्ट्रा रणे हन्युस्तन्मे क्षेमतरं भवेत्।।1.46।।","transliteration":"yadi mām apratīkāram aśhastraṁ śhastra-pāṇayaḥ\ndhārtarāṣhṭrā raṇe hanyus tan me kṣhemataraṁ bhavet","english":"If the sons of Dhritarashtra, with weapons in hand, should slay me in battle, unresisting and unarmed, that would be better for me.","hindi":"यदि मुझ शस्त्ररहित और प्रतिकार न करने वाले को ये शस्त्रधारी कौरव रण में मारें,  तो भी वह मेरे लिये कल्याणकारक होगा।","gujarati":"જો શસ્ત્રોથી સજ્જ ધૃતરાષ્ટ્રના પુત્રો શસ્ત્રરહિત અને સામનો ન કરનાર એવા મને રણભૂમિમાં મારી નાખે, તો તે મારા માટે વધુ કલ્યાણકારી હશે."},"1.47":{"chapter":1,"verse":47,"sloka":"सञ्जय उवाच\n\nएवमुक्त्वाऽर्जुनः संख्ये रथोपस्थ उपाविशत्।\n\nविसृज्य सशरं चापं शोकसंविग्नमानसः।।1.47।।","transliteration":"sañjaya uvācha\nevam uktvārjunaḥ saṅkhye rathopastha upāviśhat\nvisṛijya sa-śharaṁ chāpaṁ śhoka-saṁvigna-mānasaḥ","english":"Sanjaya said, Having thus spoken in the midst of the battlefield, Arjuna cast away his bow and arrow and, his mind overwhelmed with sorrow, sat down on the seat of the chariot.","hindi":"संजय ने कहा  --  रणभूमि (संख्ये) में शोक से उद्विग्न मनवाला अर्जुन इस प्रकार कहकर बाणसहित धनुष को त्याग कर रथ के पिछले भाग में बैठ गया।","gujarati":"સંજયે કહ્યું -- રણભૂમિમાં આમ કહીને, શોકથી વ્યાકુળ મનવાળા અર્જુને બાણ સહિત ધનુષ્યનો ત્યાગ કર્યો અને રથના પાછલા ભાગમાં બેસી ગયો."},"2.1":{"chapter":2,"verse":1,"sloka":"सञ्जय उवाच\n\nतं तथा कृपयाऽविष्टमश्रुपूर्णाकुलेक्षणम्।\n\nविषीदन्तमिदं वाक्यमुवाच मधुसूदनः।।2.1।।","transliteration":"sañjaya uvācha\ntaṁ tathā kṛipayāviṣhṭamaśhru pūrṇākulekṣhaṇam\nviṣhīdantamidaṁ vākyam uvācha madhusūdanaḥ","english":"Sanjaya said: To him who was thus overcome by pity, whose eyes were filled with tears, and who was despondent and agitated, Krishna, the destroyer of Madhu, spoke these words.","hindi":"संजय ने कहा: इस प्रकार करुणा से व्याप्त, आँसुओं से भरे नेत्रों वाले और विषादग्रस्त अर्जुन को देखकर मधुसूदन श्रीकृष्ण ने ये वचन कहे।","gujarati":"સંજયે કહ્યું: આ પ્રમાણે કરુણા અને વિષાદથી વ્યાપ્ત, આંસુઓથી ભરેલા નેત્રોવાળા અને ગભરાયેલા અર્જુનને જોઈને મધુસૂદન શ્રીકૃષ્ણે આ વચન કહ્યાં."},"2.2":{"chapter":2,"verse":2,"sloka":"श्री भगवानुवाच\n\nकुतस्त्वा कश्मलमिदं विषमे समुपस्थितम्।\n\nअनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन।।2.2।।","transliteration":"śhrī bhagavān uvācha\nkutastvā kaśhmalamidaṁ viṣhame samupasthitam\nanārya-juṣhṭamaswargyam akīrti-karam arjuna","english":"The Blessed Lord said, 'My dear Arjuna, how has this impurity come upon you? It is not at all befitting a man who knows the value of life. It leads not to higher planets but to infamy.'","hindi":"श्री भगवान् ने कहा - हे अर्जुन! इस विषम समय में तुम्हारे भीतर यह कायरतापूर्ण मोह कहाँ से आया? यह न तो श्रेष्ठ पुरुषों के आचरण के अनुकूल है, न स्वर्ग देने वाला है और न ही कीर्ति दिलाने वाला है।","gujarati":"શ્રી ભગવાને કહ્યું - હે અર્જુન! આ વિકટ સમયે તારામાં આ અનાદિ અને અપવિત્ર મોહ ક્યાંથી આવ્યો? આ વર્તન ઉમદા મનુષ્યોને શોભતું નથી, આ ન તો સ્વર્ગ તરફ લઈ જનારું છે કે ન તો કીર્તિ અપાવનારું છે."},"2.3":{"chapter":2,"verse":3,"sloka":"क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते।\n\nक्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप।।2.3।।","transliteration":"klaibyaṁ mā sma gamaḥ pārtha naitat tvayyupapadyate\nkṣhudraṁ hṛidaya-daurbalyaṁ tyaktvottiṣhṭha parantapa","english":"Do not yield to impotence, O son of Pritha. It does not befit you. Cast off this base weakness of the heart and arise, O conqueror of foes.","hindi":"हे पार्थ! नपुंसकता को प्राप्त मत हो, यह तुम्हें शोभा नहीं देती। हृदय की इस तुच्छ दुर्बलता का त्याग करो और हे शत्रुओं को जीतने वाले, उठ खड़े हो।","gujarati":"હે પાર્થ! તું ક્લેબત્વ (નપુંસકતા) ને પ્રાપ્ત ન થા, તને આ શોભતું નથી. હૃદયની આ ક્ષુદ્ર દુર્બળતાનો ત્યાગ કર અને હે પરંતપ, ઊભો થા."},"2.4":{"chapter":2,"verse":4,"sloka":"अर्जुन उवाच\n\nकथं भीष्ममहं संख्ये द्रोणं च मधुसूदन।\n\nइषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन।।2.4।।","transliteration":"arjuna uvācha\nkathaṁ bhīṣhmam ahaṁ sankhye droṇaṁ cha madhusūdana\niṣhubhiḥ pratiyotsyāmi pūjārhāvari-sūdana","english":"Arjuna said: 'O Madhusudana, killer of the demon Madhu, how can I counterattack with arrows in this battle against Bhishma and Drona, who are worthy of my deepest veneration? O slayer of enemies, they are my superiors and deserve to be worshipped.'","hindi":"अर्जुन ने कहा: 'हे मधुसूदन! मैं रणभूमि में किस प्रकार भीष्म पितामह और द्रोणाचार्य के विरुद्ध बाण चलाकर युद्ध करूँगा? हे अरिसूदन, वे दोनों ही मेरे पूजनीय हैं, अतः उनके प्रति सम्मान भाव रखते हुए मैं उन पर प्रहार कैसे कर सकता हूँ?'","gujarati":"અર્જુને કહ્યું: 'હે મધુસુદન! હું રણભૂમિમાં ભીષ્મ અને દ્રોણ જેવા પૂજનીય વડીલો સામે બાણોથી કેવી રીતે લડીશ? હે અરિદમન, તેઓ તો પૂજવા યોગ્ય છે, તો શું હું તેમના પર પ્રહાર કરી શકું?'"},"2.5":{"chapter":2,"verse":5,"sloka":"गुरूनहत्वा हि महानुभावान्\n\nश्रेयो भोक्तुं भैक्ष्यमपीह लोके।\n\nहत्वार्थकामांस्तु गुरूनिहैव\n\nभुञ्जीय भोगान् रुधिरप्रदिग्धान्।।2.5।।","transliteration":"gurūnahatvā hi mahānubhāvān\nśhreyo bhoktuṁ bhaikṣhyamapīha loke\nhatvārtha-kāmāṁstu gurūnihaiva\nbhuñjīya bhogān rudhira-pradigdhān","english":"It is better to live by begging in this world than to slay these noble teachers. By killing them, even if I gain worldly wealth and desires, I would be enjoying fruits stained with their blood.","hindi":"इन महानुभाव गुरुजनों को मारने की अपेक्षा इस संसार में भिक्षा माँगकर निर्वाह करना कहीं अधिक श्रेष्ठ है। क्योंकि, गुरुजनों को मारकर जो धन और भोग मुझे प्राप्त होंगे, वे रक्त से सने हुए होंगे और उनसे मुझे शांति नहीं मिलेगी।","gujarati":"આ મહાનુભાવ ગુરુજનોને મારવા કરતા તો આ સંસારમાં ભિક્ષા માંગીને જીવન નિર્વાહ કરવો વધારે શ્રેષ્ઠ છે. કારણ કે ગુરુજનોને મારીને જે ધન અને ભોગવિલાસ મળશે, તે તો લોહીથી ખરડાયેલા હશે."},"2.6":{"chapter":2,"verse":6,"sloka":"न चैतद्विद्मः कतरन्नो गरीयो\n\nयद्वा जयेम यदि वा नो जयेयुः।\n\nयानेव हत्वा न जिजीविषाम\n\nस्तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः।।2.6।।","transliteration":"na chaitadvidmaḥ kataranno garīyo\nyadvā jayema yadi vā no jayeyuḥ\nyāneva hatvā na jijīviṣhāmas\nte ’vasthitāḥ pramukhe dhārtarāṣhṭrāḥ","english":"We do not know which is better for us—that we conquer them or that they conquer us. Even those sons of Dhritarashtra, whom having killed we would not wish to live, stand arrayed before us.","hindi":"हम नहीं जानते कि हमारे लिए क्या बेहतर है—हम उन्हें जीतें या वे हमें जीतें। जिन धृतराष्ट्र के पुत्रों को मारकर हम जीना नहीं चाहते, वे ही हमारे सामने युद्ध के लिए खड़े हैं।","gujarati":"અમે જાણતા નથી કે અમારા માટે શું શ્રેષ્ઠ છે—કે અમે તેમને જીતીએ કે તેઓ અમને જીતે. જેમને મારીને અમે જીવવા પણ નથી માંગતા, તે ધૃતરાષ્ટ્રના પુત્રો જ અમારી સામે ઊભા છે."},"2.7":{"chapter":2,"verse":7,"sloka":"कार्पण्यदोषोपहतस्वभावः\n\nपृच्छामि त्वां धर्मसंमूढचेताः।\n\nयच्छ्रेयः स्यान्निश्िचतं ब्रूहि तन्मे\n\nशिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम्।।2.7।।","transliteration":"kārpaṇya-doṣhopahata-svabhāvaḥ\npṛichchhāmi tvāṁ dharma-sammūḍha-chetāḥ\nyach-chhreyaḥ syānniśhchitaṁ brūhi tanme\nśhiṣhyaste ’haṁ śhādhi māṁ tvāṁ prapannam","english":"My heart is overwhelmed by pity, and my mind is confused regarding my duty. I beseech You, tell me decisively what is best for me. I am Your disciple; instruct me, for I have taken refuge in You.","hindi":"करुणा के कलुष से अभिभूत और कर्तव्य के विषय में मोहित चित्त वाला मैं आपसे पूछता हूँ कि जो निश्चित रूप से श्रेयस्कर हो, वह मेरे लिए कहिए। मैं आपका शिष्य हूँ, इसलिए आप मुझे अपना मानकर उपदेश दीजिये क्योंकि मैं आपकी शरण में हूँ।","gujarati":"કાર્પણ્યદોષથી ભરેલા મારા અંતઃકરણમાં હું કર્તવ્યના વિષયમાં મૂંઝવણમાં છું; હું તમને પૂછું છું કે જે મારા માટે શ્રેયસ્કર હોય તે નિશ્ચિત કરીને મને કહો. હું તમારો શિષ્ય છું અને તમારી શરણાગતિ સ્વીકારી છે, તો મને ઉપદેશ આપો."},"2.8":{"chapter":2,"verse":8,"sloka":"न हि प्रपश्यामि ममापनुद्या\n\nद्यच्छोकमुच्छोषणमिन्द्रियाणाम्।\n\nअवाप्य भूमावसपत्नमृद्धम्\n\nराज्यं सुराणामपि चाधिपत्यम्।।2.8।।","transliteration":"na hi prapaśhyāmi mamāpanudyād\nyach-chhokam uchchhoṣhaṇam-indriyāṇām\navāpya bhūmāv-asapatnamṛiddhaṁ\nrājyaṁ surāṇāmapi chādhipatyam","english":"I do not see any means to remove this sorrow which is drying up my senses, even if I were to obtain an unrivaled, prosperous kingdom on earth or even lordship over the celestials.","hindi":"पृथ्वी पर निष्कण्टक समृद्ध राज्य को और देवताओं के स्वामित्व को प्राप्त होकर भी मैं उस उपाय को नहीं देखता हूँ, जो मेरी इन्द्रियों को सुखाने वाले इस शोक को दूर कर सके।","gujarati":"પૃથ્વી પર નિષ્કંટક અને સમૃદ્ધ રાજ્ય મેળવીને, કે દેવતાઓનું સ્વામિત્વ પ્રાપ્ત કરીને પણ હું એવો કોઈ ઉપાય નથી જોતો, જે મારી ઇન્દ્રિયોને સુકવી નાખતા આ શોકને દૂર કરી શકે."},"2.9":{"chapter":2,"verse":9,"sloka":"सञ्जय उवाच\n\nएवमुक्त्वा हृषीकेशं गुडाकेशः परन्तप।\n\nन योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह।।2.9।।","transliteration":"sañjaya uvācha\nevam-uktvā hṛiṣhīkeśhaṁ guḍākeśhaḥ parantapa\nna yotsya iti govindam uktvā tūṣhṇīṁ babhūva ha","english":"Sanjaya said: Having spoken thus to Hrishikesha, the Lord of the senses, Arjuna, the conqueror of sleep and destroyer of foes, said to Govinda, 'I will not fight,' and became silent.","hindi":"संजय ने कहा: हृषीकेश (इन्द्रियों के स्वामी) से इस प्रकार कहकर, निद्रा को जीतने वाले और शत्रुओं का संहार करने वाले अर्जुन ने गोविन्द से कहा, 'मैं युद्ध नहीं करूँगा' और वे चुप हो गए।","gujarati":"સંજયે કહ્યું: ઇન્દ્રિયોના સ્વામી હૃષીકેશને આ પ્રમાણે કહીને, નિદ્રાને જીતનાર અને શત્રુઓનો સંહાર કરનાર અર્જુને ગોવિંદને કહ્યું, 'હું યુદ્ધ નહીં કરું' અને તે મૌન થઈ ગયા."},"2.10":{"chapter":2,"verse":10,"sloka":"तमुवाच हृषीकेशः प्रहसन्निव भारत।\n\nसेनयोरुभयोर्मध्ये विषीदन्तमिदं वचः।।2.10।।","transliteration":"tam-uvācha hṛiṣhīkeśhaḥ prahasanniva bhārata\nsenayorubhayor-madhye viṣhīdantam-idaṁ vachaḥ","english":"O descendant of Bharata, as both armies stood ready, Krishna, smiling, spoke these words to the grief-stricken Arjuna in the midst of the two forces.","hindi":"हे भरतवंशी! दोनों सेनाओं के मध्य शोकाकुल अर्जुन से, भगवान श्रीकृष्ण ने मानो मुस्कुराते हुए ये वचन कहे।","gujarati":"હે ભરતવંશી! બંને સેનાઓની વચ્ચે શોકગ્રસ્ત અર્જુન પ્રત્યે, ભગવાન શ્રીકૃષ્ણ જાણે હસી રહ્યા હોય તેમ આ વચનો બોલ્યા."},"2.11":{"chapter":2,"verse":11,"sloka":"श्री भगवानुवाच\n\nअशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे।\n\nगतासूनगतासूंश्च नानुशोचन्ति पण्डिताः।।2.11।।","transliteration":"śhrī bhagavān uvācha\naśhochyān-anvaśhochas-tvaṁ prajñā-vādānśh cha bhāṣhase\ngatāsūn-agatāsūnśh-cha nānuśhochanti paṇḍitāḥ","english":"The Blessed Lord said: You grieve for those who should not be grieved for, yet you speak words of wisdom. The wise grieve neither for the living nor for the dead.","hindi":"श्री भगवान ने कहा: तुम न शोक करने योग्य मनुष्यों के लिए शोक करते हो और ज्ञानियों जैसी बातें भी करते हो, परन्तु जिनका जीवन चला गया है और जिनका जीवन अभी शेष है, उनके लिए शोक न तो ज्ञानी करते हैं और न ही करना चाहिए।","gujarati":"શ્રી ભગવાન બોલ્યા: જેઓ શોક કરવાને યોગ્ય નથી, તેમના માટે તું શોક કરે છે અને પંડિતો જેવી વાતો કરે છે, પરંતુ જ્ઞાની પુરુષો જીવતા કે મરેલા કોઈના માટે શોક કરતા નથી."},"2.12":{"chapter":2,"verse":12,"sloka":"न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः।\n\nन चैव न भविष्यामः सर्वे वयमतः परम्।।2.12।।","transliteration":"na tvevāhaṁ jātu nāsaṁ na tvaṁ neme janādhipāḥ\nna chaiva na bhaviṣhyāmaḥ sarve vayamataḥ param","english":"Never was there a time when I did not exist, nor you, nor all these kings; nor in the future shall any of us cease to be.","hindi":"न तो ऐसा कभी था कि मैं नहीं था, न तुम नहीं थे, और न ही ये समस्त राजा नहीं थे; और न ही ऐसा कभी होगा कि भविष्य में हम नहीं रहेंगे।","gujarati":"એવો કોઈ કાળ નહોતો જ્યારે હું, તમે અથવા આ તમામ રાજાઓ અસ્તિત્વમાં નહોતા, અને ભવિષ્યમાં પણ એવું ક્યારેય નહીં બને કે આપણે નહીં હોઈએ."},"2.13":{"chapter":2,"verse":13,"sloka":"देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा।\n\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति।।2.13।।","transliteration":"dehino ’smin yathā dehe kaumāraṁ yauvanaṁ jarā\ntathā dehāntara-prāptir dhīras tatra na muhyati","english":"Just as the soul experiences childhood, youth, and old age within this current body, it similarly undergoes the transition into another body; a person of steady wisdom is not deluded by this change.","hindi":"जैसे जीवात्मा के लिए इस देह में बाल्यावस्था, युवावस्था और वृद्धावस्था होती है, वैसे ही उसको दूसरे शरीर की प्राप्ति होती है। धीर पुरुष इस परिवर्तन को लेकर मोहग्रस्त नहीं होते।","gujarati":"જેમ આ દેહમાં દેહી (આત્મા) બાળપણ, જુવાની અને વૃદ્ધાવસ્થા અનુભવે છે, તેમ જ તેને બીજો દેહ પ્રાપ્ત થાય છે; આ બાબતે ધીર પુરુષ મોહિત થતો નથી."},"2.14":{"chapter":2,"verse":14,"sloka":"मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः।\n\nआगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत।।2.14।।","transliteration":"mātrā-sparśhās tu kaunteya śhītoṣhṇa-sukha-duḥkha-dāḥ\nāgamāpāyino ’nityās tans-titikṣhasva bhārata","english":"O son of Kunti, the contact between the senses and their objects creates sensations of cold and heat, pleasure and pain. These experiences are transient, having both a beginning and an end; therefore, O Arjuna, one must learn to endure them with equanimity.","hindi":"हे कुन्तीपुत्र! इन्द्रियों का विषयों के साथ संयोग ही शीत-उष्ण और सुख-दुःख को उत्पन्न करने वाला है। ये संयोग उत्पत्ति और विनाशशील हैं, अतः वे अनित्य हैं। हे भरतवंशी अर्जुन, उन्हें धैर्यपूर्वक सहन करो।","gujarati":"હે કુંતીપુત્ર! ઇન્દ્રિયો અને વિષયોનો સંયોગ જ શીત-ઉષ્ણ અને સુખ-દુઃખ આપનારો છે. આ સંયોગો ઉત્પત્તિ અને વિનાશવાળા એટલે કે અનિત્ય છે, માટે હે ભરતવંશી અર્જુન, તું તેને સહન કર."},"2.15":{"chapter":2,"verse":15,"sloka":"यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ।\n\nसमदुःखसुखं धीरं सोऽमृतत्वाय कल्पते।।2.15।।","transliteration":"yaṁ hi na vyathayantyete puruṣhaṁ puruṣharṣhabha\nsama-duḥkha-sukhaṁ dhīraṁ so ’mṛitatvāya kalpate","english":"O noble among men, that steadfast person whom these sense-objects do not agitate, who remains unchanged in pleasure and pain, is alone eligible for immortality.","hindi":"हे पुरुषश्रेष्ठ! जो धीर पुरुष सुख और दुःख को समान समझता है और जिसे ये सांसारिक विषय विचलित नहीं कर पाते, वही अमृतत्व (मोक्ष) के योग्य है।","gujarati":"હે પુરુષશ્રેષ્ઠ! જે સ્થિર મનવાળા પુરુષને આ ઇન્દ્રિયોના વિષયો વ્યથિત કરી શકતા નથી અને જે સુખ-દુઃખમાં સમાન રહે છે, તે જ અમૃતત્વ (મોક્ષ) પ્રાપ્ત કરવા યોગ્ય છે."},"2.16":{"chapter":2,"verse":16,"sloka":"नासतो विद्यते भावो नाभावो विद्यते सतः।\n\nउभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः।।2.16।।","transliteration":"nāsato vidyate bhāvo nābhāvo vidyate sataḥ\nubhayorapi dṛiṣhṭo ’nta stvanayos tattva-darśhibhiḥ","english":"The unreal has no existence, and the real never ceases to be; the truth of both has been perceived by the seers of the ultimate reality.","hindi":"असत् वस्तु का तो अस्तित्व नहीं है और सत् का कभी अभाव नहीं है। इन दोनों का ही तत्त्व, तत्त्वदर्शी ज्ञानियों द्वारा देखा गया है।","gujarati":"અસત્ય વસ્તુનું અસ્તિત્વ નથી અને સત્યનો ક્યારેય અભાવ થતો નથી. તત્ત્વજ્ઞાનીઓએ આ બંનેના મૂળ સ્વરૂપને જાણી લીધું છે."},"2.17":{"chapter":2,"verse":17,"sloka":"अविनाशि तु तद्विद्धि येन सर्वमिदं ततम्।\n\nविनाशमव्ययस्यास्य न कश्चित् कर्तुमर्हति।।2.17।।","transliteration":"avināśhi tu tadviddhi yena sarvam idaṁ tatam\nvināśham avyayasyāsya na kaśhchit kartum arhati","english":"Know that to be indestructible by which all this is pervaded. No one can cause the destruction of that, the Imperishable.","hindi":"विनाशरहित तुम उसको जानो जिससे यह सारा जगत व्याप्त है। इस अविनाशी तत्त्व का नाश करने में कोई भी समर्थ नहीं है।","gujarati":"જેના વડે આ આખું જગત વ્યાપ્ત છે, તેને તું અવિનાશી જાણ. આ અવ્યયનું વિનાશ કરવા માટે કોઈ પણ સમર્થ નથી."},"2.18":{"chapter":2,"verse":18,"sloka":"अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः।\n\nअनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत।।2.18।।","transliteration":"antavanta ime dehā nityasyoktāḥ śharīriṇaḥ\nanāśhino ’prameyasya tasmād yudhyasva bhārata","english":"The material bodies of the eternal, indestructible, and immeasurable soul are subject to an end; therefore, fight, O descendant of Bharata.","hindi":"नाशरहित, अप्रमेय और नित्य स्वरूप आत्मा के ये शरीर नाशवान कहे गए हैं, इसलिए हे भरतवंशी अर्जुन! तुम युद्ध करो।","gujarati":"આ વિનાશી શરીરની અંદર રહેલો આત્મા નિત્ય, અવિનાશી અને અપ્રમેય છે; માટે હે અર્જુન, તું યુદ્ધ કર."},"2.19":{"chapter":2,"verse":19,"sloka":"य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम्।\n\nउभौ तौ न विजानीतो नायं हन्ति न हन्यते।।2.19।।","transliteration":"ya enaṁ vetti hantāraṁ yaśh chainaṁ manyate hatam\nubhau tau na vijānīto nāyaṁ hanti na hanyate","english":"He who considers the Self to be the slayer, and he who considers It to be slain, both of them are ignorant; for the Self neither kills nor is it killed.","hindi":"जो इस आत्मा को मारने वाला समझता है और जो इसको मरा हुआ मानता है, वे दोनों ही सत्य को नहीं जानते; क्योंकि यह आत्मा न किसी को मारता है और न ही किसी के द्वारा मारा जा सकता है।","gujarati":"જે આ આત્માને મારનાર માને છે અને જે એને મરેલો માને છે, તે બંને અજ્ઞાની છે; કારણ કે આ આત્મા ન કોઈને મારે છે અને ન કોઈના દ્વારા મારી શકાય છે."},"2.20":{"chapter":2,"verse":20,"sloka":"न जायते म्रियते वा कदाचि\n\nन्नायं भूत्वा भविता वा न भूयः।\n\nअजो नित्यः शाश्वतोऽयं पुराणो\n\nन हन्यते हन्यमाने शरीरे।।2.20।।","transliteration":"na jāyate mriyate vā kadāchin\nnāyaṁ bhūtvā bhavitā vā na bhūyaḥ\najo nityaḥ śhāśhvato ’yaṁ purāṇo\nna hanyate hanyamāne śharīre","english":"It is never born, nor does it ever die; nor, once having been, does it ever cease to be. Unborn, eternal, everlasting, and ancient, it is not slain when the body is slain.","hindi":"न यह कभी जन्मता है और न मरता ही है। न यह कभी था और न भविष्य में न रहने वाला है। यह अजन्मा, नित्य, शाश्वत और पुरातन है, शरीर के नष्ट होने पर भी यह नष्ट नहीं होता है।","gujarati":"આ આત્મા ક્યારેય જન્મતો નથી અને ક્યારેય મરતો પણ નથી. તે જન્મીને ફરી પાછો થનારો નથી, એટલે કે તેનો ક્યારેય અભાવ થતો નથી. તે અજન્મા, નિત્ય, શાશ્વત અને પુરાણ છે; શરીરના નાશ થવાથી પણ આ આત્મા નાશ પામતો નથી."},"2.21":{"chapter":2,"verse":21,"sloka":"वेदाविनाशिनं नित्यं य एनमजमव्ययम्।\n\nकथं स पुरुषः पार्थ कं घातयति हन्ति कम्।।2.21।।","transliteration":"vedāvināśhinaṁ nityaṁ ya enam ajam avyayam\nkathaṁ sa puruṣhaḥ pārtha kaṁ ghātayati hanti kam","english":"O Partha, how can a person who knows the soul to be indestructible, eternal, birthless, and immutable kill anyone or cause anyone to be killed?","hindi":"हे पार्थ! जो पुरुष इस आत्मा को अविनाशी, नित्य, अजन्मा और अव्यय जानता है, वह भला किसको मरवाएगा और कैसे किसी की हत्या करेगा?","gujarati":"હે પાર્થ! જે મનુષ્ય આ આત્માને વિનાશરહિત, નિત્ય, અજન્મા અને અવિનાશી જાણે છે, તે કેવી રીતે કોને મારે છે અથવા કેવી રીતે કોઈને મરાવે છે?"},"2.22":{"chapter":2,"verse":22,"sloka":"वासांसि जीर्णानि यथा विहाय\n\nनवानि गृह्णाति नरोऽपराणि।\n\nतथा शरीराणि विहाय जीर्णा\n\nन्यन्यानि संयाति नवानि देही।।2.22।।","transliteration":"vāsānsi jīrṇāni yathā vihāya\nnavāni gṛihṇāti naro ’parāṇi\ntathā śharīrāṇi vihāya jīrṇānya\nnyāni sanyāti navāni dehī","english":"Just as a person casts off worn-out garments and wears new ones, likewise, the embodied soul casts off worn-out bodies and enters others that are new.","hindi":"जैसे मनुष्य पुराने वस्त्रों को त्यागकर दूसरे नए वस्त्रों को धारण करता है, वैसे ही जीवात्मा पुराने शरीरों को त्यागकर नए शरीरों को प्राप्त होता है।","gujarati":"જેમ મનુષ્ય જૂનાં વસ્ત્રોનો ત્યાગ કરીને બીજા નવાં વસ્ત્રો ધારણ કરે છે, તેમ જ દેહી આત્મા જૂનાં શરીરોનો ત્યાગ કરીને બીજા નવાં શરીરો ધારણ કરે છે."},"2.23":{"chapter":2,"verse":23,"sloka":"नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः।\n\nन चैनं क्लेदयन्त्यापो न शोषयति मारुतः।।2.23।।","transliteration":"nainaṁ chhindanti śhastrāṇi nainaṁ dahati pāvakaḥ\nna chainaṁ kledayantyāpo na śhoṣhayati mārutaḥ","english":"Weapons cannot cut the soul, fire cannot burn it, water cannot wet it, and wind cannot dry it.","hindi":"इस आत्मा को शस्त्र काट नहीं सकते, अग्नि इसे जला नहीं सकती, जल इसे भिगो नहीं सकता और वायु इसे सुखा नहीं सकती।","gujarati":"આ આત્માને શસ્ત્રો કાપી શકતા નથી, અગ્નિ તેને બાળી શકતી નથી, જળ તેને ભીંજવી શકતું નથી અને વાયુ તેને સૂકવી શકતી નથી."},"2.24":{"chapter":2,"verse":24,"sloka":"अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च।\n\nनित्यः सर्वगतः स्थाणुरचलोऽयं सनातनः।।2.24।।","transliteration":"achchhedyo ’yam adāhyo ’yam akledyo ’śhoṣhya eva cha\nnityaḥ sarva-gataḥ sthāṇur achalo ’yaṁ sanātanaḥ","english":"This soul cannot be cut, burned, wetted, or dried; it is eternal, all-pervading, unchanging, immovable, and primordial.","hindi":"यह आत्मा न कभी काटी जा सकती है, न जलाई जा सकती है, न भिगोई जा सकती है और न ही सुखाई जा सकती है। यह नित्य, सर्वव्यापी, स्थिर, अचल और अनादि है।","gujarati":"આ આત્માને કોઈ કાપી શકતું નથી, બાળી શકતું નથી, પલાળી શકતું નથી કે સૂકવી શકતું નથી; તે નિત્ય, સર્વવ્યાપી, સ્થિર, અચલ અને અનાદિ છે."},"2.25":{"chapter":2,"verse":25,"sloka":"अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते।\n\nतस्मादेवं विदित्वैनं नानुशोचितुमर्हसि।।2.25।।","transliteration":"avyakto ’yam achintyo ’yam avikāryo ’yam uchyate\ntasmādevaṁ viditvainaṁ nānuśhochitum arhasi","english":"The Self is said to be unmanifest, inconceivable, and immutable. Knowing this, you should not grieve.","hindi":"यह आत्मा अव्यक्त है, अचिन्त्य है और अविकारी कहा जाता है। इसे इस प्रकार जानकर, तुम्हें शोक नहीं करना चाहिए।","gujarati":"આ આત્મા અવ્યક્ત, અચિંત્ય અને અવિકારી કહેવાય છે. તેથી આને આ રીતે જાણીને તારે શોક કરવો જોઈએ નહીં."},"2.26":{"chapter":2,"verse":26,"sloka":"अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम्।\n\nतथापि त्वं महाबाहो नैवं शोचितुमर्हसि।।2.26।।","transliteration":"atha chainaṁ nitya-jātaṁ nityaṁ vā manyase mṛitam\ntathāpi tvaṁ mahā-bāho naivaṁ śhochitum arhasi","english":"But even if you consider the Self as subject to constant birth and death, even then, O mighty-armed one, you should not grieve.","hindi":"और यदि तुम आत्मा को सदा जन्मने वाला और सदा मरने वाला ही मानो, तो भी हे महाबाहो! इस प्रकार शोक करना तुम्हारे लिए उचित नहीं है।","gujarati":"અને જો તું આત્માને સદાય જન્મનારો અને સદાય મરનારો માને, તો પણ હે મહાબાહો! આ પ્રકારે શોક કરવો તારે યોગ્ય નથી."},"2.27":{"chapter":2,"verse":27,"sloka":"जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च।\n\nतस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि।।2.27।।","transliteration":"jātasya hi dhruvo mṛityur dhruvaṁ janma mṛitasya cha\ntasmād aparihārye ’rthe na tvaṁ śhochitum arhasi","english":"For one who has been born, death is certain; and for one who has died, rebirth is certain. Therefore, you should not lament over the inevitable.","hindi":"जन्मे हुए की मृत्यु निश्चित है और मरे हुए का जन्म निश्चित है। अतः इस अपरिहार्य विषय में तुम्हें शोक नहीं करना चाहिए।","gujarati":"જન્મેલાનું મૃત્યુ નિશ્ચિત છે અને મૃત્યુ પામેલાનો જન્મ નિશ્ચિત છે; તેથી, આ અનિવાર્ય બાબતમાં તમારે શોક ન કરવો જોઈએ."},"2.28":{"chapter":2,"verse":28,"sloka":"अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत।\n\nअव्यक्तनिधनान्येव तत्र का परिदेवना।।2.28।।","transliteration":"avyaktādīni bhūtāni vyakta-madhyāni bhārata\navyakta-nidhanānyeva tatra kā paridevanā","english":"All beings are unmanifest in the beginning, manifest in the middle, and unmanifest again in the end, O Bharata. What cause is there for grief?","hindi":"हे अर्जुन! सभी प्राणी जन्म से पूर्व अव्यक्त (अदृश्य) थे, मध्य में व्यक्त (दृश्य) हैं, और मृत्यु के बाद पुनः अव्यक्त हो जाएंगे। फिर इसमें शोक करने की क्या बात है?","gujarati":"હે અર્જુન! બધા પ્રાણીઓ ઉત્પત્તિ પહેલાં અવ્યક્ત હતા, મધ્યમાં વ્યક્ત છે અને વિનાશ પછી ફરી અવ્યક્ત થઈ જશે, તો તેમાં શોક કરવાનું શું કારણ છે?"},"2.29":{"chapter":2,"verse":29,"sloka":"आश्चर्यवत्पश्यति कश्चिदेन\n\nमाश्चर्यवद्वदति तथैव चान्यः।\n\nआश्चर्यवच्चैनमन्यः श्रृणोति\n\nश्रुत्वाप्येनं वेद न चैव कश्चित्।।2.29।।","transliteration":"āśhcharya-vat paśhyati kaśhchid enan\nāśhcharya-vad vadati tathaiva chānyaḥ\nāśhcharya-vach chainam anyaḥ śhṛiṇoti\nśhrutvāpyenaṁ veda na chaiva kaśhchit","english":"One looks upon this Soul as a wonder; another speaks of It as a wonder; another hears of It as a wonder; yet, even after hearing, no one truly understands It.","hindi":"कोई इसे आश्चर्य के समान देखता है, कोई इसके विषय में आश्चर्य के समान कहता है, और कोई अन्य सुनकर भी आश्चर्य करता है; परंतु कोई भी इसे वास्तव में समझ नहीं पाता।","gujarati":"કોઈ આ આત્માને આશ્ચર્યની જેમ જુએ છે, કોઈ તેને આશ્ચર્યની જેમ વર્ણવે છે, અને કોઈ આશ્ચર્યની જેમ સાંભળે છે; છતાં સાંભળ્યા પછી પણ કોઈ તેને ખરેખર સમજી શકતું નથી."},"2.30":{"chapter":2,"verse":30,"sloka":"देही नित्यमवध्योऽयं देहे सर्वस्य भारत।\n\nतस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि।।2.30।।","transliteration":"dehī nityam avadhyo ’yaṁ dehe sarvasya bhārata\ntasmāt sarvāṇi bhūtāni na tvaṁ śhochitum arhasi","english":"The soul dwelling within all bodies is eternal and indestructible, O Arjuna; therefore, you should not grieve for any living being.","hindi":"हे अर्जुन! यह देही (आत्मा) जो सबके शरीर में स्थित है, वह सदा ही अवध्य है, अतः तुम्हें किसी भी प्राणी के लिए शोक नहीं करना चाहिए।","gujarati":"હે અર્જુન! આ દેહી આત્મા જે સર્વેના શરીરમાં રહેલો છે, તે સદાય અવિનાશી છે, તેથી તારે કોઈપણ પ્રાણી માટે શોક કરવો જોઈએ નહીં."},"2.31":{"chapter":2,"verse":31,"sloka":"स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि।\n\nधर्म्याद्धि युद्धाछ्रेयोऽन्यत्क्षत्रियस्य न विद्यते।।2.31।।","transliteration":"swa-dharmam api chāvekṣhya na vikampitum arhasi\ndharmyāddhi yuddhāch chhreyo ’nyat kṣhatriyasya na vidyate","english":"Furthermore, considering your own duty, you should not waver, for there is nothing more auspicious for a warrior than a war fought for righteousness.","hindi":"अपने स्वधर्म को देखते हुए भी तुम्हें विचलित नहीं होना चाहिए, क्योंकि एक क्षत्रिय के लिए धर्मयुद्ध से बढ़कर कोई अन्य कल्याणकारी कर्तव्य नहीं है।","gujarati":"વળી, તારા પોતાના ધર્મને જોતાં પણ તારે વિચલિત ન થવું જોઈએ, કારણ કે ક્ષત્રિય માટે ધર્મયુદ્ધથી ચડિયાતું બીજું કોઈ કલ્યાણકારી કર્તવ્ય નથી."},"2.32":{"chapter":2,"verse":32,"sloka":"यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम्।\n\nसुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम्।।2.32।।","transliteration":"yadṛichchhayā chopapannaṁ swarga-dvāram apāvṛitam\nsukhinaḥ kṣhatriyāḥ pārtha labhante yuddham īdṛiśham","english":"Happy are the Kshatriyas, O Partha, who encounter such a war as this, which has come of its own accord, opening wide the gates of heaven.","hindi":"हे पार्थ! अपने आप प्राप्त हुए और स्वर्ग के खुले द्वार के समान इस युद्ध को भाग्यशाली क्षत्रिय ही पाते हैं।","gujarati":"હે પાર્થ! ભાગ્યશાળી ક્ષત્રિયો જ આવા યુદ્ધને પામે છે, જે અચાનક આવી પડે છે અને જે સ્વર્ગના ખુલ્લા દ્વાર સમાન છે."},"2.33":{"chapter":2,"verse":33,"sloka":"अथ चैत्त्वमिमं धर्म्यं संग्रामं न करिष्यसि।\n\nततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि।।2.33।।","transliteration":"atha chet tvam imaṁ dharmyaṁ saṅgrāmaṁ na kariṣhyasi\ntataḥ sva-dharmaṁ kīrtiṁ cha hitvā pāpam avāpsyasi","english":"But if you do not fight this righteous war, then abandoning your own duty and reputation, you will incur sin.","hindi":"किंतु यदि तुम इस धर्मयुद्ध को नहीं करोगे, तो स्वधर्म और कीर्ति को खोकर पाप को ही प्राप्त होगे।","gujarati":"પરંતુ જો તું આ ધર્મયુદ્ધ નહીં કરે, તો પોતાના ધર્મ અને કીર્તિને ગુમાવીને પાપને પ્રાપ્ત કરીશ."},"2.34":{"chapter":2,"verse":34,"sloka":"अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम्।\n\nसंभावितस्य चाकीर्तिर्मरणादतिरिच्यते।।2.34।।","transliteration":"akīrtiṁ chāpi bhūtāni\nkathayiṣhyanti te ’vyayām\nsambhāvitasya chākīrtir\nmaraṇād atirichyate","english":"And people will always speak of your infamy; and for a person of honor, dishonor is worse than death.","hindi":"और सब लोग तुम्हारी सदा रहने वाली अपकीर्ति का भी वर्णन करते रहेंगे; और सम्मानित व्यक्ति के लिए तो अपकीर्ति मृत्यु से भी बढ़कर होती है।","gujarati":"અને લોકો હંમેશા તમારી કાયમી અપકીર્તિના ગુણગાન ગાતા રહેશે; અને એક માનનીય વ્યક્તિ માટે અપમાન મૃત્યુ કરતા પણ વધુ ખરાબ છે."},"2.35":{"chapter":2,"verse":35,"sloka":"भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः।\n\nयेषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम्।।2.35।।","transliteration":"bhayād raṇād uparataṁ mansyante tvāṁ mahā-rathāḥ\nyeṣhāṁ cha tvaṁ bahu-mato bhūtvā yāsyasi lāghavam","english":"The great chariot-warriors will think that you have withdrawn from the battle out of fear, and you will be held in low esteem by those who have held you in high regard.","hindi":"जिन महारथियों की दृष्टि में तुम अब तक अत्यंत सम्मानित रहे हो, वे तुम्हें भय के कारण युद्ध से भागा हुआ मानेंगे और तुम्हारी गरिमा गिर जाएगी।","gujarati":"જે મહારથીઓ તને અત્યંત માન આપતા હતા, તેઓ હવે તને ભયને કારણે યુદ્ધમાંથી નિવૃત્ત થયેલો માનશે અને તારી ગરિમા ઘટી જશે."},"2.36":{"chapter":2,"verse":36,"sloka":"अवाच्यवादांश्च बहून् वदिष्यन्ति तवाहिताः।\n\nनिन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम्।।2.36।।","transliteration":"avāchya-vādānśh cha bahūn vadiṣhyanti tavāhitāḥ\nnindantastava sāmarthyaṁ tato duḥkhataraṁ nu kim","english":"Your enemies will describe you with many unmentionable words and scorn your ability; what could be more painful than that?","hindi":"तुम्हारे शत्रु तुम्हारे सामर्थ्य की निन्दा करते हुए बहुत से अकथनीय वचन कहेंगे, इससे अधिक कष्टदायक और क्या हो सकता है?","gujarati":"તારા શત્રુઓ તારા સામર્થ્યની નિંદા કરતા અનેક અકથનીય વચનો બોલશે, જે તારા માટે અત્યંત દુઃખદાયક હશે."},"2.37":{"chapter":2,"verse":37,"sloka":"हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम्।\n\nतस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः।।2.37।।","transliteration":"hato vā prāpsyasi swargaṁ jitvā vā bhokṣhyase mahīm\ntasmād uttiṣhṭha kaunteya yuddhāya kṛita-niśhchayaḥ","english":"If slain, you will attain heaven; if victorious, you will enjoy the earth; therefore, arise, O son of Kunti, resolved to fight.","hindi":"यदि तुम युद्ध में मारे जाओगे तो स्वर्ग प्राप्त करोगे, और यदि जीत जाओगे तो पृथ्वी का भोग करोगे। इसलिए, हे कौन्तेय! युद्ध के लिए दृढ़ संकल्प होकर खड़े हो जाओ।","gujarati":"જો તું યુદ્ધમાં મરાઈશ તો સ્વર્ગ પામીશ, અને જો વિજયી થઈશ તો પૃથ્વીનો ભોગ કરીશ. તેથી, હે કૌન્તેય, યુદ્ધ કરવાનો દ્રઢ સંકલ્પ કરીને ઊભો થા."},"2.38":{"chapter":2,"verse":38,"sloka":"सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ।\n\nततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि।।2.38।।","transliteration":"sukha-duḥkhe same kṛitvā lābhālābhau jayājayau\ntato yuddhāya yujyasva naivaṁ pāpam avāpsyasi","english":"Treating pleasure and pain, gain and loss, victory and defeat as the same, engage in battle; thus, you will not incur any sin.","hindi":"सुख-दुःख, लाभ-हानि और जय-पराजय को समान समझकर, तत्पश्चात युद्ध के लिए तैयार हो जाओ; इस प्रकार युद्ध करने से तुम पाप को प्राप्त नहीं होगे।","gujarati":"સુખ-દુઃખ, લાભ-હાનિ અને જય-પરાજયને સમાન ગણીને યુદ્ધ માટે તૈયાર થા; આમ કરવાથી તને પાપ લાગશે નહીં."},"2.39":{"chapter":2,"verse":39,"sloka":"एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां श्रृणु।\n\nबुद्ध्यायुक्तो यया पार्थ कर्मबन्धं प्रहास्यसि।।2.39।।","transliteration":"eṣhā te ’bhihitā sānkhye\nbuddhir yoge tvimāṁ śhṛiṇu\nbuddhyā yukto yayā pārtha\nkarma-bandhaṁ prahāsyasi","english":"Thus far I have declared to you the wisdom of Sankhya. Now listen to the wisdom of Yoga, endowed with which, O Arjuna, you shall cast off the bonds of action.","hindi":"हे अर्जुन! यह ज्ञान तुम्हें सांख्य (ज्ञानयोग) के विषय में दिया गया है। अब कर्मयोग के विषय में सुनो, जिसे अपनाकर तुम कर्मों के बंधन को पूरी तरह नष्ट कर सकोगे।","gujarati":"હે અર્જુન! અત્યાર સુધી મેં તને સાંખ્યયોગનું જ્ઞાન આપ્યું. હવે તું કર્મયોગ વિશે સાંભળ, જેનો આશ્રય લઈને તું કર્મબંધનમાંથી મુક્ત થઈ શકીશ."},"2.40":{"chapter":2,"verse":40,"sloka":"नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते।\n\nस्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात्।।2.40।।","transliteration":"nehābhikrama-nāśho ’sti pratyavāyo na vidyate\nsvalpam apyasya dharmasya trāyate mahato bhayāt","english":"In this path, there is no loss of effort, nor is there any harm caused by partial completion. Even a small portion of this practice protects one from great fear.","hindi":"इस मार्ग में आरम्भ किए हुए कार्य का नाश नहीं होता और उसका उल्टा फल भी नहीं होता, बल्कि इस धर्म का थोड़ा सा भी अभ्यास जन्म-मरण रूप महान भय से रक्षा कर लेता है।","gujarati":"આ માર્ગમાં કરેલા પ્રયત્નનો ક્યારેય નાશ થતો નથી, કે તેમાં કોઈ વિપરીત ફળ મળતું નથી; આ ધર્મનો થોડો પણ અભ્યાસ મોટા ભયથી બચાવે છે."},"2.41":{"chapter":2,"verse":41,"sloka":"व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन।\n\nबहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम्।।2.41।।","transliteration":"vyavasāyātmikā buddhir ekeha kuru-nandana\nbahu-śhākhā hyanantāśh cha buddhayo ’vyavasāyinām","english":"O descendant of the Kurus, in this path, the resolute intellect is single-pointed, whereas the minds of the irresolute are many-branched and endless.","hindi":"हे कुरुनन्दन! इस मार्ग में निश्चयात्मक बुद्धि एक ही होती है, जबकि अस्थिर चित्त वाले मनुष्यों की बुद्धियां बहुत शाखाओं वाली और अनंत होती हैं।","gujarati":"હે કુરુનંદન! આ માર્ગમાં નિશ્ચયાત્મિકા બુદ્ધિ એક જ હોય છે, જ્યારે અસ્થિર ચિત્તવાળા મનુષ્યોની બુદ્ધિ ઘણી શાખાઓવાળી અને અનંત હોય છે."},"2.42":{"chapter":2,"verse":42,"sloka":"यामिमां पुष्पितां वाचं प्रवदन्त्यविपश्चितः।\n\nवेदवादरताः पार्थ नान्यदस्तीति वादिनः।।2.42।।","transliteration":"yāmimāṁ puṣhpitāṁ vāchaṁ pravadanty-avipaśhchitaḥ\nveda-vāda-ratāḥ pārtha nānyad astīti vādinaḥ\n kāmātmānaḥ swarga-parā janma-karma-phala-pradām\nkriyā-viśheṣha-bahulāṁ bhogaiśhwarya-gatiṁ prati","english":"O Partha, those who lack wisdom delight in the flowery words of the Vedas, which proclaim that there is nothing beyond the attainment of heavenly pleasures and the rituals that lead to them.","hindi":"हे पार्थ! जो अविवेकी जन वेदों के उन शब्दों में ही रम जाते हैं, जो सांसारिक सुखों की प्रशंसा करते हैं और कहते हैं कि इनसे बढ़कर और कुछ नहीं है, वे केवल शब्दों के जाल में फँसे रहते हैं।","gujarati":"હે પાર્થ! અવિવેકી પુરુષો વેદના એવા પુષ્પિત શબ્દોમાં રચ્યાપચ્યા રહે છે જે માત્ર કામનાઓ અને ભોગવિલાસની પ્રશંસા કરે છે અને કહે છે કે આનાથી વિશેષ બીજું કંઈ જ નથી."},"2.43":{"chapter":2,"verse":43,"sloka":"कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम्।\n\nक्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति।।2.43।।","transliteration":"kāmātmānaḥ svarga-parā \n\n janma-karma-phala-pradām\n\n kriyā-viśeṣa-bahulāṁ\n\n bhogaiśvarya-gatiṁ prati","english":"Men of small knowledge are absorbed in the flowery words of the Vedas, which advocate various ritualistic activities for the attainment of heavenly planets, resulting in good birth, power, and the like, and being desirous of sense gratification, they say that there is nothing beyond this.","hindi":"भोगों में आसक्त, स्वर्ग को ही परम लक्ष्य मानने वाले अविवेकी मनुष्य जन्म तथा कर्मफल प्रदान करने वाली अनेक प्रकार की विशिष्ट क्रियाओं का वर्णन करते हैं, ताकि वे भोग और ऐश्वर्य को प्राप्त कर सकें।","gujarati":"કામનાઓથી યુક્ત, સ્વર્ગને જ શ્રેષ્ઠ માનનારા લોકો ભોગ અને ઐશ્વર્ય પ્રાપ્ત કરાવનારી અનેક ક્રિયાઓનું વર્ણન કરે છે, જે જન્મ અને કર્મફળ આપનારી હોય છે."},"2.44":{"chapter":2,"verse":44,"sloka":"भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम्।\n\nव्यवसायात्मिका बुद्धिः समाधौ न विधीयते।।2.44।।","transliteration":"bhogaiśwvarya-prasaktānāṁ tayāpahṛita-chetasām\nvyavasāyātmikā buddhiḥ samādhau na vidhīyate","english":"For those who are deeply attached to worldly pleasures and opulence, and whose discriminative faculty is stolen away by flowery words, they cannot attain the resolute, unwavering consciousness necessary for deep meditation and spiritual absorption.","hindi":"भोग और ऐश्वर्य में आसक्त चित्त वाले, और ऐसी ही लुभावनी बातों में खोए हुए मनुष्यों की बुद्धि, परमात्मा में एकनिष्ठ होकर स्थिर नहीं हो पाती।","gujarati":"જે લોકો ભોગવિલાસ અને ઐશ્વર્યમાં આસક્ત છે અને જેમનું મન આવી વાતોથી મોહિત થઈ ગયું છે, તેમની બુદ્ધિ ઈશ્વરમાં સ્થિર કે એકાગ્ર થતી નથી."},"2.45":{"chapter":2,"verse":45,"sloka":"त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन।\n\nनिर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान्।।2.45।।","transliteration":"trai-guṇya-viṣhayā vedā nistrai-guṇyo bhavārjuna\nnirdvandvo nitya-sattva-stho niryoga-kṣhema ātmavān","english":"The Vedas deal with the three modes of material nature; O Arjuna, become transcendental to these three modes, be free from all dualities and all anxieties for gain and safety, and be established in the Self.","hindi":"वेद तीनों गुणों के विषय में हैं, हे अर्जुन! तुम त्रिगुणातीत हो जाओ, द्वंद्वों से मुक्त हो जाओ, नित्य-सत्वस्थ हो जाओ और योगक्षेम की चिंता त्यागकर आत्मवान बनो।","gujarati":"વેદોનો વિષય ત્રણેય ગુણો છે, હે અર્જુન! તું ત્રિગુણાતીત થા, નિર્દ્વંદ્વ થા, નિત્ય સત્ત્વમાં સ્થિત થા અને યોગક્ષેમની ચિંતા છોડીને આત્મવાન બન."},"2.46":{"chapter":2,"verse":46,"sloka":"यावानर्थ उदपाने सर्वतः संप्लुतोदके।\n\nतावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः।।2.46।।","transliteration":"yāvān artha udapāne sarvataḥ samplutodake\ntāvānsarveṣhu vedeṣhu brāhmaṇasya vijānataḥ","english":"Just as a small reservoir is of limited use when a vast flood covers everything, so are all the Vedas of limited use to a Brahmana who has realized the ultimate Truth.","hindi":"सब ओर जल से भर जाने पर छोटे जलाशय का जितना उपयोग होता है, ब्रह्मज्ञानी के लिए सभी वेदों का उतना ही उपयोग रह जाता है।","gujarati":"ચારે તરફ પાણીથી છલકાઈ ગયેલા જળાશયમાં મનુષ્યનો જેટલો ઉપયોગ હોય છે, તેટલો જ ઉપયોગ તત્વજ્ઞાની બ્રાહ્મણ માટે તમામ વેદોનો હોય છે."},"2.47":{"chapter":2,"verse":47,"sloka":"कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।\n\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि।।2.47।।","transliteration":"karmaṇy-evādhikāras te mā phaleṣhu kadāchana\nmā karma-phala-hetur bhūr mā te saṅgo ’stvakarmaṇi","english":"You have a right to perform your prescribed duty, but you are not entitled to the fruits of action. Never consider yourself the cause of the results of your activities, nor be attached to inaction.","hindi":"कर्म करने में ही तुम्हारा अधिकार है, उसके फलों में कभी नहीं। तुम कर्मफल के हेतु भी मत बनो और तुम्हारी अकर्म में भी आसक्ति न हो।","gujarati":"કર્મ કરવા ઉપર જ તમારો અધિકાર છે, તેના ફળો પર ક્યારેય નહીં. તમે ક્યારેય કર્મફળના હેતુરૂપ ન બનો અને તમારી અકર્મમાં પણ આસક્તિ ન હોય."},"2.48":{"chapter":2,"verse":48,"sloka":"योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।\n\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते।।2.48।।","transliteration":"yoga-sthaḥ kuru karmāṇi saṅgaṁ tyaktvā dhanañjaya\nsiddhy-asiddhyoḥ samo bhūtvā samatvaṁ yoga uchyate","english":"Perform your duty, O Arjuna, abandoning attachment and remaining steady in both success and failure, for this equanimity of mind is known as Yoga.","hindi":"हे अर्जुन, आसक्ति को त्यागकर तथा सफलता और असफलता में समभाव होकर योग में स्थित होकर कर्म करो। चित्त की इस समता को ही योग कहा जाता है।","gujarati":"હે અર્જુન, આસક્તિનો ત્યાગ કરીને તથા સિદ્ધિ અને અસિદ્ધિમાં સમભાવ રાખીને યોગમાં સ્થિત થઈને કર્મ કર. આ સમત્વને જ યોગ કહેવામાં આવે છે."},"2.49":{"chapter":2,"verse":49,"sloka":"दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय।\n\nबुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः।।2.49।।","transliteration":"dūreṇa hy-avaraṁ karma buddhi-yogād dhanañjaya\nbuddhau śharaṇam anvichchha kṛipaṇāḥ phala-hetavaḥ","english":"O Dhananjaya, keep all abominable activities far distant by the practice of devotional service, and in such consciousness surrender unto the Lord. Those who want to enjoy the fruits of their work are misers.","hindi":"हे धनंजय! समत्व बुद्धि रूप योग की अपेक्षा सकाम कर्म बहुत ही निम्न श्रेणी का है, इसलिए तू बुद्धि के योग का ही आश्रय ग्रहण कर, क्योंकि फल की इच्छा रखने वाले तो अत्यंत दीन-हीन हैं।","gujarati":"હે ધનંજય! સમત્વ બુદ્ધિરૂપ યોગની તુલનામાં સકામ કર્મ અત્યંત નિમ્ન છે; તેથી તું બુદ્ધિયોગનો આશ્રય લે, કારણ કે ફળની ઈચ્છા રાખનારા લોકો તો અત્યંત દીન છે."},"2.50":{"chapter":2,"verse":50,"sloka":"बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते।\n\nतस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम्।।2.50।।","transliteration":"buddhi-yukto jahātīha ubhe sukṛita-duṣhkṛite\ntasmād yogāya yujyasva yogaḥ karmasu kauśhalam","english":"Endowed with wisdom, one casts off both good and evil deeds in this very life. Therefore, devote yourself to Yoga; Yoga is skill in action.","hindi":"समत्वबुद्धि से युक्त मनुष्य इसी जन्म में पुण्य और पाप दोनों का त्याग कर देता है। अतः तुम योग में लग जाओ, क्योंकि कर्मों में कुशलता ही योग है।","gujarati":"સમત્વબુદ્ધિવાળો પુરુષ આ લોકમાં જ પુણ્ય અને પાપ બંનેનો ત્યાગ કરી દે છે. તેથી તું યોગમાં જોડાઈ જા; કારણ કે કર્મોમાં કુશળતા એ જ યોગ છે."},"2.51":{"chapter":2,"verse":51,"sloka":"कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः।\n\nजन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम्।।2.51।।","transliteration":"karma-jaṁ buddhi-yuktā hi phalaṁ tyaktvā manīṣhiṇaḥ\njanma-bandha-vinirmuktāḥ padaṁ gachchhanty-anāmayam","english":"The wise, established in this wisdom of equanimity, abandon the fruits of their actions, and being liberated from the cycle of birth and death, attain the state that is beyond all suffering.","hindi":"बुद्धिमान पुरुष समत्व-बुद्धि से युक्त होकर कर्मों के फल को त्याग देते हैं, और जन्म-मरण के बंधन से मुक्त होकर उस परम पद को प्राप्त कर लेते हैं जो समस्त दुखों से परे है।","gujarati":"જ્ઞાની પુરુષો સમત્વબુદ્ધિથી યુક્ત થઈને કર્મોના ફળનો ત્યાગ કરે છે, અને જન્મ-મરણના બંધનમાંથી મુક્ત થઈને તે નિર્દોષ પદને પ્રાપ્ત થાય છે જે દુઃખથી પર છે."},"2.52":{"chapter":2,"verse":52,"sloka":"यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति।\n\nतदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च।।2.52।।","transliteration":"yadā te moha-kalilaṁ buddhir vyatitariṣhyati\ntadā gantāsi nirvedaṁ śhrotavyasya śhrutasya cha","english":"When your intellect has crossed the mire of delusion, you will attain indifference to all that has been heard and all that is yet to be heard.","hindi":"जब तेरी बुद्धि मोह-रूपी दलदल को भली-भांति पार कर जाएगी, तब तू सुने हुए और सुनने योग्य सभी भोगों से विरक्त हो जाएगा।","gujarati":"જ્યારે તારી બુદ્ધિ મોહરૂપી દલદલને ઓળંગી જશે, ત્યારે તું સાંભળવા યોગ્ય અને સાંભળેલાં તમામ વિષયો પ્રત્યે ઉદાસીનતા કેળવી લઈશ."},"2.53":{"chapter":2,"verse":53,"sloka":"श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला।\n\nसमाधावचला बुद्धिस्तदा योगमवाप्स्यसि।।2.53।।","transliteration":"śhruti-vipratipannā te yadā sthāsyati niśhchalā\nsamādhāv-achalā buddhis tadā yogam avāpsyasi","english":"When your intellect, which has been bewildered by the conflicting Vedic interpretations, becomes steady and remains firmly rooted in the Self, then you shall attain the state of divine consciousness.","hindi":"श्रुति-प्रतिपन्ना विप्रतिपन्ना ते यदा स्थास्यति निश्चला समाधावचला बुद्धिस्तदा योगमवाप्स्यसि।","gujarati":"જ્યારે તારી બુદ્ધિ, જે શાસ્ત્રોના અનેક પ્રકારના વચનો સાંભળીને અત્યારે મૂંઝવાયેલી છે, તે જ્યારે સમાધિમાં અચળ અને સ્થિર થઈ જશે, ત્યારે તું યોગને પ્રાપ્ત કરીશ."},"2.54":{"chapter":2,"verse":54,"sloka":"अर्जुन उवाच\n\nस्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव।\n\nस्थितधीः किं प्रभाषेत किमासीत व्रजेत किम्।।2.54।।","transliteration":"arjuna uvācha\nsthita-prajñasya kā bhāṣhā samādhi-sthasya keśhava\nsthita-dhīḥ kiṁ prabhāṣheta kim āsīta vrajeta kim","english":"Arjuna said: O Krishna, what are the symptoms of one whose consciousness is steady and who is absorbed in transcendence? How does such a person of steady wisdom speak, how do they sit, and how do they walk?","hindi":"अर्जुन ने कहा: हे केशव! समाधि में स्थित, स्थिर बुद्धि वाले पुरुष के क्या लक्षण हैं? वह स्थिर बुद्धि वाला पुरुष कैसे बोलता है, कैसे बैठता है और कैसे चलता है?","gujarati":"અર્જુને કહ્યું: હે કૃષ્ણ, સમાધિસ્થ એવા સ્થિતપ્રજ્ઞ પુરુષનાં લક્ષણો શું છે? સ્થિતપ્રજ્ઞ પુરુષ કેવી રીતે બોલે છે, કેવી રીતે બેસે છે અને કેવી રીતે ચાલે છે?"},"2.55":{"chapter":2,"verse":55,"sloka":"श्री भगवानुवाच\n\nप्रजहाति यदा कामान् सर्वान् पार्थ मनोगतान्।\n\nआत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते।।2.55।।","transliteration":"śhrī bhagavān uvācha\nprajahāti yadā kāmān sarvān pārtha mano-gatān\nātmany-evātmanā tuṣhṭaḥ sthita-prajñas tadochyate","english":"The Blessed Lord said, 'O Partha, when a man completely casts off all desires of the mind and finds satisfaction in the Self by the Self, he is then said to be one of steady wisdom.'","hindi":"श्री भगवान ने कहा, 'हे पार्थ! जब मनुष्य मन में स्थित सभी कामनाओं को पूरी तरह त्याग देता है और आत्मा से ही आत्मा में संतुष्ट रहता है, तब वह स्थितप्रज्ञ कहा जाता है।'","gujarati":"શ્રી ભગવાને કહ્યું, 'હે પાર્થ! જ્યારે મનુષ્ય મનમાં રહેલી તમામ કામનાઓનો સંપૂર્ણ ત્યાગ કરે છે અને આત્મા દ્વારા જ આત્મામાં સંતુષ્ટ રહે છે, ત્યારે તે સ્થિતપ્રજ્ઞ કહેવાય છે.'"},"2.56":{"chapter":2,"verse":56,"sloka":"दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः।\n\nवीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते।।2.56।।","transliteration":"duḥkheṣhv-anudvigna-manāḥ sukheṣhu vigata-spṛihaḥ\nvīta-rāga-bhaya-krodhaḥ sthita-dhīr munir uchyate","english":"He whose mind is undisturbed in adversity, who is devoid of desire for pleasures, and who is free from attachment, fear, and anger, is called a sage of steady wisdom.","hindi":"दुःख में जिसका मन उद्विग्न नहीं होता, सुख में जिसकी स्पृहा निवृत्त हो गई है, और जिसके मन से राग, भय और क्रोध नष्ट हो गए हैं, वह मुनि स्थितप्रज्ञ कहलाता है।","gujarati":"જેનું મન દુઃખમાં ઉદ્વિગ્ન થતું નથી, જે સુખની ઈચ્છાઓથી પર છે, અને જે રાગ, ભય તથા ક્રોધથી મુક્ત છે, તેવા મુનિને સ્થિતપ્રજ્ઞ કહેવામાં આવે છે."},"2.57":{"chapter":2,"verse":57,"sloka":"यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम्।\n\nनाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता।।2.57।।","transliteration":"yaḥ sarvatrānabhisnehas tat tat prāpya śhubhāśhubham\nnābhinandati na dveṣhṭi tasya prajñā pratiṣhṭhitā","english":"He who remains unattached under all conditions, and who neither rejoices when encountering good nor recoils when encountering evil, his wisdom is firmly established.","hindi":"जो पुरुष सर्वत्र स्नेह रहित हुआ, उस-उस शुभ अथवा अशुभ वस्तु को प्राप्त करके न तो प्रसन्न होता है और न द्वेष करता है, उसकी बुद्धि स्थिर है।","gujarati":"જે પુરુષ સર્વત્ર સ્નેહરહિત થઈને જે જે શુભ કે અશુભ પ્રાપ્ત કરીને ન તો હર્ષ પામે છે કે ન દ્વેષ કરે છે, તેની બુદ્ધિ સ્થિર છે."},"2.58":{"chapter":2,"verse":58,"sloka":"यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः।\n\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता।।2.58।।","transliteration":"yadā sanharate chāyaṁ kūrmo ’ṅgānīva sarvaśhaḥ\nindriyāṇīndriyārthebhyas tasya prajñā pratiṣhṭhitā","english":"As a tortoise draws its limbs into its shell from every side, so when one withdraws the senses from their objects, his wisdom becomes firmly established.","hindi":"जैसे कछुआ अपने अंगों को सब ओर से समेट लेता है, वैसे ही जब यह पुरुष इन्द्रियों के विषयों से अपनी इन्द्रियों को पूरी तरह हटा लेता है, तब उसकी बुद्धि स्थिर हो जाती है।","gujarati":"જેમ કાચબો પોતાના અંગોને ચારે બાજુથી સમેટી લે છે, તેમ જ્યારે મનુષ્ય પોતાની ઇન્દ્રિયોને ઇન્દ્રિયોના વિષયોમાંથી પાછી ખેંચી લે છે, ત્યારે તેની બુદ્ધિ સ્થિર થાય છે."},"2.59":{"chapter":2,"verse":59,"sloka":"विषया विनिवर्तन्ते निराहारस्य देहिनः।\n\nरसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते।।2.59।।","transliteration":"viṣhayā vinivartante nirāhārasya dehinaḥ\nrasa-varjaṁ raso ’pyasya paraṁ dṛiṣhṭvā nivartate","english":"Sensory objects recede from an abstinent person, yet the taste for them remains; but even this longing ceases once the Supreme is realized.","hindi":"विषयों का सेवन न करने वाले पुरुष से विषय तो दूर हो जाते हैं, परन्तु उनमें रहने वाली आसक्ति नहीं जाती; लेकिन परमात्मा का साक्षात्कार होने पर वह आसक्ति भी समाप्त हो जाती है।","gujarati":"વિષયોનું સેવન ન કરનાર પુરુષથી વિષયો તો દૂર થઈ જાય છે, પરંતુ તેમાં રહેલો રાગ (આસક્તિ) રહે છે; પણ પરમાત્માનો સાક્ષાત્કાર થતા આ આસક્તિ પણ દૂર થઈ જાય છે."},"2.60":{"chapter":2,"verse":60,"sloka":"यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः।\n\nइन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः।।2.60।।","transliteration":"yatato hyapi kaunteya puruṣhasya vipaśhchitaḥ\nindriyāṇi pramāthīni haranti prasabhaṁ manaḥ","english":"O son of Kunti, the turbulent senses are so powerful that they forcibly carry away the mind of even a man of discrimination who is striving for self-control.","hindi":"हे अर्जुन, ये चंचल इन्द्रियाँ प्रयत्नशील विवेकी पुरुष के मन को भी बलपूर्वक हर लेती हैं।","gujarati":"હે અર્જુન, આ બળવાન ઇન્દ્રિયો તો પ્રયત્નશીલ અને જ્ઞાની પુરુષના મનને પણ બળપૂર્વક હરી લે છે."},"2.61":{"chapter":2,"verse":61,"sloka":"तानि सर्वाणि संयम्य युक्त आसीत मत्परः।\n\nवशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता।।2.61।।","transliteration":"tāni sarvāṇi sanyamya yukta āsīta mat-paraḥ\nvaśhe hi yasyendriyāṇi tasya prajñā pratiṣhṭhitā","english":"Having restrained them all, one should sit steadfast, intent on Me; for whose senses are under control, his wisdom is steady.","hindi":"उन समस्त इन्द्रियों को वश में करके, संयमित होकर, मेरे परायण होकर स्थित होना चाहिए। क्योंकि जिस पुरुष की इन्द्रियाँ वश में होती हैं, उसकी बुद्धि स्थिर हो जाती है।","gujarati":"તે બધી ઇન્દ્રિયોને સંયમિત કરીને, યોગયુક્ત થઈને મારા પર પરાયણ થઈને બેસવું; જેની ઇન્દ્રિયો વશમાં છે, તેની બુદ્ધિ સ્થિર છે."},"2.62":{"chapter":2,"verse":62,"sloka":"ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते।\n\nसङ्गात् संजायते कामः कामात्क्रोधोऽभिजायते।।2.62।।","transliteration":"dhyāyato viṣhayān puṁsaḥ saṅgas teṣhūpajāyate\nsaṅgāt sañjāyate kāmaḥ kāmāt krodho ’bhijāyate","english":"By meditating on the objects of the senses, attachment to them is born; from attachment, desire arises; and from desire, anger is produced.","hindi":"विषयों का चिन्तन करने वाले पुरुष की उन विषयों में आसक्ति हो जाती है, आसक्ति से उन विषयों की कामना उत्पन्न होती है और कामना में बाधा पड़ने से क्रोध उत्पन्न होता है।","gujarati":"વિષયોનું ચિંતન કરવાથી મનુષ્યની તેમાં આસક્તિ થાય છે, આસક્તિથી કામના જન્મે છે, અને કામનામાંથી ક્રોધ ઉત્પન્ન થાય છે."},"2.63":{"chapter":2,"verse":63,"sloka":"क्रोधाद्भवति संमोहः संमोहात्स्मृतिविभ्रमः।\n\nस्मृतिभ्रंशाद् बुद्धिनाशो बुद्धिनाशात्प्रणश्यति।।2.63।।","transliteration":"krodhād bhavati sammohaḥ sammohāt smṛiti-vibhramaḥ\nsmṛiti-bhranśhād buddhi-nāśho buddhi-nāśhāt praṇaśhyati","english":"From anger comes delusion; from delusion comes the loss of memory; from the loss of memory comes the destruction of discrimination; from the destruction of discrimination, one perishes.","hindi":"क्रोध से मूढ़ता उत्पन्न होती है, मूढ़ता से स्मृति में भ्रम हो जाता है, स्मृति में भ्रम होने से बुद्धि नष्ट हो जाती है, और बुद्धि नष्ट होने से मनुष्य का पतन हो जाता है।","gujarati":"ક્રોધથી મૂઢતા (મોહ) ઉત્પન્ન થાય છે, મૂઢતાથી સ્મૃતિ ભ્રમિત થાય છે, સ્મૃતિ ભ્રમિત થવાથી બુદ્ધિનો નાશ થાય છે, અને બુદ્ધિનો નાશ થતાં મનુષ્યનો વિનાશ થાય છે."},"2.64":{"chapter":2,"verse":64,"sloka":"रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन्।\n\nआत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति।।2.64।।","transliteration":"rāga-dveṣha-viyuktais tu viṣhayān indriyaiśh charan\nātma-vaśhyair-vidheyātmā prasādam adhigachchhati","english":"But the self-controlled person, moving among sense objects with the senses free from both attachment and aversion, attains peace.","hindi":"परंतु अपने वश में की हुई अन्तःकरण वाला साधक, राग और द्वेष से रहित होकर इन्द्रियों को विषयों में बरतता हुआ भी प्रसन्नता (आध्यात्मिक शांति) को प्राप्त करता है।","gujarati":"પરંતુ વશમાં કરેલા અંતઃકરણવાળો સાધક રાગ અને દ્વેષથી રહિત થઈને, પોતાના વશમાં રહેલી ઇન્દ્રિયો દ્વારા વિષયોમાં વિચરણ કરતો હોવા છતાં શાંતિને પ્રાપ્ત કરે છે."},"2.65":{"chapter":2,"verse":65,"sloka":"प्रसादे सर्वदुःखानां हानिरस्योपजायते।\n\nप्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते।।2.65।।","transliteration":"prasāde sarva-duḥkhānāṁ hānir asyopajāyate\nprasanna-chetaso hyāśhu buddhiḥ paryavatiṣhṭhate","english":"For one who is peaceful, all sorrows are destroyed; indeed, the intellect of the tranquil-minded soon becomes steady.","hindi":"प्रसन्नता प्राप्त होने पर उसके सब दुखों का नाश हो जाता है और उस प्रसन्नचित्त मनुष्य की बुद्धि शीघ्र ही सब ओर से हटकर परमात्मा में स्थिर हो जाती है।","gujarati":"પ્રસન્નતા પ્રાપ્ત થતાં તે મનુષ્યના તમામ દુઃખોનો નાશ થઈ જાય છે અને પ્રસન્ન ચિત્તવાળાની બુદ્ધિ જલ્દી જ સ્થિર થઈ જાય છે."},"2.66":{"chapter":2,"verse":66,"sloka":"नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना।\n\nन चाभावयतः शान्तिरशान्तस्य कुतः सुखम्।।2.66।।","transliteration":"nāsti buddhir-ayuktasya na chāyuktasya bhāvanā\nna chābhāvayataḥ śhāntir aśhāntasya kutaḥ sukham","english":"For one who is not connected with the Divine, there is no transcendental knowledge, and for the unsteady, there is no meditation; without meditation, there is no peace, and without peace, how can there be happiness?","hindi":"अयुक्त पुरुष में न तो ज्ञान होता है और न ही ध्यान की क्षमता; ध्यानहीन व्यक्ति को शांति नहीं मिलती और बिना शांति के सुख की प्राप्ति असंभव है।","gujarati":"જેનું મન સ્થિર નથી તેને આત્મજ્ઞાન નથી હોતું, અને અસ્થિર મનુષ્યને ધ્યાન કરવાની ક્ષમતા પણ હોતી નથી. ધ્યાન વગર શાંતિ મળતી નથી, અને જેની પાસે શાંતિ નથી તેને સુખ ક્યાંથી મળે?"},"2.67":{"chapter":2,"verse":67,"sloka":"इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते।\n\nतदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि।।2.67।।","transliteration":"indriyāṇāṁ hi charatāṁ yan mano ’nuvidhīyate\ntadasya harati prajñāṁ vāyur nāvam ivāmbhasi","english":"As a strong wind sweeps away a boat on the water, even one of the wandering senses on which the mind focuses can carry away a man's intelligence.","hindi":"जैसे जल में चलने वाली नाव को वायु हर लेती है, वैसे ही विषयों में विचरती हुई इन्द्रियों के पीछे जो मन रहता है, वह मनुष्य की बुद्धि को हर लेता है।","gujarati":"જેમ પાણીમાં તરતી નાવને વાયુ પોતાની સાથે ખેંચી જાય છે, તેમ વિષયોમાં ભટકતી ઈન્દ્રિયોમાં જે ઈન્દ્રિય પાછળ મન દોરાય છે, તે મનુષ્યની બુદ્ધિને હરી લે છે."},"2.68":{"chapter":2,"verse":68,"sloka":"तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः।\n\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता।।2.68।।","transliteration":"tasmād yasya mahā-bāho nigṛihītāni sarvaśhaḥ\nindriyāṇīndriyārthebhyas tasya prajñā pratiṣhṭhitā","english":"Therefore, O mighty-armed Arjuna, he whose senses are completely restrained from their objects, his intelligence is firmly set.","hindi":"इसलिये, हे महाबाहो! जिस पुरुष की इन्द्रियाँ अपने विषयों से सब प्रकार से निग्रह की हुई हैं, उसी की बुद्धि स्थिर है।","gujarati":"તેથી હે મહાબાહો! જે પુરુષની ઇન્દ્રિયો વિષયોમાંથી સર્વ પ્રકારે પાછી ખેંચાયેલી હોય છે, તેની જ બુદ્ધિ સ્થિર ગણાય છે."},"2.69":{"chapter":2,"verse":69,"sloka":"या निशा सर्वभूतानां तस्यां जागर्ति संयमी।\n\nयस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः।।2.69।।","transliteration":"yā niśhā sarva-bhūtānāṁ tasyāṁ jāgarti sanyamī\nyasyāṁ jāgrati bhūtāni sā niśhā paśhyato muneḥ","english":"What is night for all beings, in that the self-controlled person is awake; and when all beings are awake, that is night for the sage who sees.","hindi":"जो सब प्राणियों के लिए रात्रि है, उसमें संयमी पुरुष जागता है; और जिस समय सब प्राणी जागते हैं, वह आत्मज्ञानी मुनि के लिए रात्रि है।","gujarati":"જે બધા પ્રાણીઓ માટે રાત્રિ છે, તેમાં સંયમી પુરુષ જાગે છે, અને જ્યારે બધા પ્રાણીઓ જાગતા હોય છે, ત્યારે તે તત્વજ્ઞાની મુનિ માટે રાત્રિ સમાન છે."},"2.70":{"chapter":2,"verse":70,"sloka":"आपूर्यमाणमचलप्रतिष्ठं\n\nसमुद्रमापः प्रविशन्ति यद्वत्।\n\nतद्वत्कामा यं प्रविशन्ति सर्वे\n\nस शान्तिमाप्नोति न कामकामी।।2.70।।","transliteration":"āpūryamāṇam achala-pratiṣhṭhaṁ\nsamudram āpaḥ praviśhanti yadvat\ntadvat kāmā yaṁ praviśhanti sarve\nsa śhāntim āpnoti na kāma-kāmī","english":"As the ocean remains calm and undisturbed even though waters flow into it from all sides, so the person who remains unmoved when all desires enter them attains peace, not the one who craves for fulfillment of desires.","hindi":"जैसे सब ओर से जल के आने पर भी समुद्र अपनी मर्यादा में स्थिर रहता है, वैसे ही जिसमें सब भोग-सामग्री विचलित किए बिना समा जाती हैं, वह पुरुष शांति प्राप्त करता है; न कि वह जो कामनाओं के पीछे भागता है।","gujarati":"જેમ ચારે બાજુથી જળ આવીને ભરપૂર છતાં પણ અચળ રહેલા સમુદ્રમાં નદીઓ સમાઈ જાય છે, તેમ જેમાં સર્વ કામનાઓ લય પામે છે તે પુરુષ શાંતિને પામે છે, પણ કામનાઓ રાખનાર નહીં."},"2.71":{"chapter":2,"verse":71,"sloka":"विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः।\n\nनिर्ममो निरहंकारः स शांतिमधिगच्छति।।2.71।।","transliteration":"vihāya kāmān yaḥ sarvān pumānśh charati niḥspṛihaḥ\nnirmamo nirahankāraḥ sa śhāntim adhigachchhati","english":"That person who abandons all cravings and acts free from longing, without the sense of 'mine' and without ego, attains true peace.","hindi":"जो मनुष्य समस्त कामनाओं का त्याग करके, इच्छा और ममता से रहित होकर तथा अहंकार को छोड़कर विचरण करता है, वही शांति को प्राप्त होता है।","gujarati":"જે મનુષ્ય તમામ કામનાઓનો ત્યાગ કરીને, સ્પૃહા વગર, મમતા રહિત અને અહંકાર મુક્ત થઈને વિચરે છે, તે શાંતિ પ્રાપ્ત કરે છે."},"2.72":{"chapter":2,"verse":72,"sloka":"एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति।\n\nस्थित्वाऽस्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति।।2.72।।","transliteration":"eṣhā brāhmī sthitiḥ pārtha naināṁ prāpya vimuhyati\nsthitvāsyām anta-kāle ’pi brahma-nirvāṇam ṛichchhati","english":"O son of Pritha, this is the state of the God-realized soul, attaining which one is no longer deluded. Being established in this state even at the hour of death, one attains oneness with the Supreme Brahman.","hindi":"हे अर्जुन, यह ब्रह्म को प्राप्त हुए पुरुष की स्थिति है, जिसे पाकर मनुष्य फिर कभी मोहित नहीं होता। अन्तकाल में भी इस स्थिति में स्थित होकर वह ब्रह्मनिर्वाण (ब्रह्म के साथ एकत्व) को प्राप्त हो जाता है।","gujarati":"હે અર્જુન, આ બ્રહ્મને પ્રાપ્ત થયેલા પુરુષની સ્થિતિ છે, જેને પામીને મનુષ્ય ફરી ક્યારેય મોહિત થતો નથી. અંતકાળે પણ આ સ્થિતિમાં સ્થિત થઈને મનુષ્ય બ્રહ્મનિર્વાણ પામે છે."},"3.1":{"chapter":3,"verse":1,"sloka":"अर्जुन उवाच\n\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन।\n\nतत्किं कर्मणि घोरे मां नियोजयसि केशव।।3.1।।","transliteration":"arjuna uvācha\njyāyasī chet karmaṇas te matā buddhir janārdana\ntat kiṁ karmaṇi ghore māṁ niyojayasi keśhava","english":"Arjuna said: If You consider knowledge superior to action, O Janardana, then why do You urge me to engage in this terrible battle, O Kesava?","hindi":"अर्जुन ने कहा: हे जनार्दन! यदि आप कर्म की अपेक्षा ज्ञान को श्रेष्ठ समझते हैं, तो फिर हे केशव! आप मुझे इस घोर युद्ध रूपी कर्म में क्यों लगा रहे हैं?","gujarati":"અર્જુને કહ્યું: હે જનાર્દન! જો તમે કર્મ કરતા જ્ઞાનને શ્રેષ્ઠ માનતા હોવ, તો પછી હે કેશવ! તમે મને આ ભયંકર યુદ્ધરૂપી કર્મમાં શા માટે પ્રવૃત્ત કરી રહ્યા છો?"},"3.2":{"chapter":3,"verse":2,"sloka":"व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे।\n\nतदेकं वद निश्िचत्य येन श्रेयोऽहमाप्नुयाम्।।3.2।।","transliteration":"vyāmiśhreṇeva vākyena buddhiṁ mohayasīva me\ntad ekaṁ vada niśhchitya yena śhreyo ’ham āpnuyām","english":"You seem to confuse my understanding with these apparently conflicting words; therefore, tell me decisively which single path will lead me to the ultimate good.","hindi":"आप मिले-जुले वचनों से मेरी बुद्धि को भ्रमित कर रहे हैं; इसलिए आप निश्चित रूप से वह एक मार्ग बताइये, जिससे मैं कल्याण को प्राप्त कर सकूँ।","gujarati":"તમારા આ મિશ્રિત વચનોથી મારી બુદ્ધિ મૂંઝાઈ રહી છે, તેથી મને નિશ્ચિતપણે એ એક માર્ગ કહો જેના દ્વારા હું કલ્યાણ પ્રાપ્ત કરી શકું."},"3.3":{"chapter":3,"verse":3,"sloka":"श्री भगवानुवाच\n\nलोकेऽस्मिन्द्विविधा निष्ठा पुरा प्रोक्ता मयानघ।\n\nज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम्।।3.3।।","transliteration":"śhrī bhagavān uvācha\nloke’smin dvi-vidhā niṣhṭhā purā proktā mayānagha\njñāna-yogena sāṅkhyānāṁ karma-yogena yoginām","english":"The Blessed Lord said: O sinless one, I have already explained that in this world there is a twofold path of spiritual practice: the path of knowledge for the introspective and the path of action for the active.","hindi":"श्री भगवान ने कहा: हे निष्पाप अर्जुन, इस संसार में मेरे द्वारा पहले दो प्रकार की निष्ठा कही गई है; सांख्ययोगियों के लिए ज्ञानयोग और योगियों के लिए कर्मयोग।","gujarati":"શ્રી ભગવાન બોલ્યા: હે નિષ્પાપ અર્જુન, આ લોકમાં મારા દ્વારા પહેલાં બે પ્રકારની નિષ્ઠા કહેવામાં આવી છે: જ્ઞાનીઓ માટે જ્ઞાનયોગ અને યોગીઓ માટે કર્મયોગ."},"3.4":{"chapter":3,"verse":4,"sloka":"न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते।\n\nन च संन्यसनादेव सिद्धिं समधिगच्छति।।3.4।।","transliteration":"na karmaṇām anārambhān naiṣhkarmyaṁ puruṣho ’śhnute\nna cha sannyasanād eva siddhiṁ samadhigachchhati","english":"Not by abstaining from work does one achieve freedom from reaction, nor by mere renunciation does one attain spiritual perfection.","hindi":"न तो कर्मों से विमुख होने से मनुष्य नैष्कर्म्य को प्राप्त होता है और न केवल त्याग कर देने से ही सिद्धि मिलती है।","gujarati":"કર્મ ન કરવાથી મનુષ્ય નૈષ્કર્મ્યની સ્થિતિને પામતો નથી, અને માત્ર ત્યાગ કરવાથી પણ તે સિદ્ધિ પ્રાપ્ત કરી શકતો નથી."},"3.5":{"chapter":3,"verse":5,"sloka":"न हि कश्िचत्क्षणमपि जातु तिष्ठत्यकर्मकृत्।\n\nकार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः।।3.5।।","transliteration":"na hi kaśhchit kṣhaṇam api jātu tiṣhṭhatyakarma-kṛit\nkāryate hyavaśhaḥ karma sarvaḥ prakṛiti-jair guṇaiḥ","english":"Verily, no one can remain for even a moment without performing action; for everyone is driven to act helplessly by the modes born of Prakriti (Nature).","hindi":"निश्चय ही कोई भी मनुष्य क्षणभर भी कर्म किए बिना नहीं रह सकता, क्योंकि प्रकृति से उत्पन्न गुणों के द्वारा सब जीव विवश होकर कर्म करने के लिए प्रेरित होते हैं।","gujarati":"ખરેખર, કોઈ પણ મનુષ્ય ક્ષણભર પણ કર્મો કર્યા વગર રહી શકતો નથી, કારણ કે પ્રકૃતિથી જન્મેલા ગુણોને લીધે દરેક વ્યક્તિ લાચાર થઈને કર્મ કરવા માટે પ્રેરાય છે."},"3.6":{"chapter":3,"verse":6,"sloka":"कर्मेन्द्रियाणि संयम्य य आस्ते मनसा स्मरन्।\n\nइन्द्रियार्थान्विमूढात्मा मिथ्याचारः स उच्यते।।3.6।।","transliteration":"karmendriyāṇi sanyamya ya āste manasā smaran\nindriyārthān vimūḍhātmā mithyāchāraḥ sa uchyate","english":"The person who restrains the organs of action but continues to dwell on sense-objects in their mind is of deluded understanding and is called a hypocrite.","hindi":"जो मूढ़ बुद्धि मनुष्य कर्मेन्द्रियों को तो वश में कर लेता है, परन्तु मन से इन्द्रियों के विषयों का चिन्तन करता रहता है, वह मिथ्याचारी अर्थात् दम्भी कहलाता है।","gujarati":"જે મૂર્ખ માણસ કર્મેન્દ્રિયોને રોકીને બેસે છે પણ મનમાં ઇન્દ્રિયોના વિષયોનું ચિંતન કરતો રહે છે, તે દંભી કહેવાય છે."},"3.7":{"chapter":3,"verse":7,"sloka":"यस्त्विन्द्रियाणि मनसा नियम्यारभतेऽर्जुन।\n\nकर्मेन्द्रियैः कर्मयोगमसक्तः स विशिष्यते।।3.7।।","transliteration":"yas tvindriyāṇi manasā niyamyārabhate ’rjuna\nkarmendriyaiḥ karma-yogam asaktaḥ sa viśhiṣhyate","english":"But he who controls the senses by the mind, O Arjuna, and engages his organs of action in the performance of Karma Yoga without attachment, he is indeed superior.","hindi":"किन्तु हे अर्जुन! जो पुरुष मन से इन्द्रियों को वश में करके अनासक्त होकर कर्मेंन्द्रियों से कर्मयोग का आचरण करता है, वह श्रेष्ठ है।","gujarati":"પરંતુ હે અર્જુન! જે મનુષ્ય મન વડે ઇન્દ્રિયોને વશમાં કરીને અનાસક્ત રહીને કર્મેન્દ્રિયો દ્વારા કર્મયોગનું આચરણ કરે છે, તે શ્રેષ્ઠ છે."},"3.8":{"chapter":3,"verse":8,"sloka":"नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः।\n\nशरीरयात्रापि च ते न प्रसिद्ध्येदकर्मणः।।3.8।।","transliteration":"niyataṁ kuru karma tvaṁ karma jyāyo hyakarmaṇaḥ\nśharīra-yātrāpi cha te na prasiddhyed akarmaṇaḥ","english":"Perform your prescribed duty, for action is superior to inaction; by inaction, even the maintenance of your body would not be possible.","hindi":"तू अपने शास्त्रविहित कर्तव्य कर्म कर, क्योंकि कर्म न करने की अपेक्षा कर्म करना श्रेष्ठ है। कर्म न करने से तो तेरा शरीर निर्वाह भी सिद्ध नहीं होगा।","gujarati":"તારા નિયત કર્મ કર, કારણ કે અકર્મ કરતાં કર્મ કરવું શ્રેષ્ઠ છે. કર્મ ન કરવાથી તો તારું શરીર નિભાવવું પણ શક્ય નહીં થાય."},"3.9":{"chapter":3,"verse":9,"sloka":"यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः।\n\nतदर्थं कर्म कौन्तेय मुक्तसंगः समाचर।।3.9।।","transliteration":"yajñārthāt karmaṇo ’nyatra loko ’yaṁ karma-bandhanaḥ\ntad-arthaṁ karma kaunteya mukta-saṅgaḥ samāchara","english":"Work done as a sacrifice (yajna) does not bind the soul; all other actions lead to karmic entanglement. Therefore, O son of Kunti, perform your duties solely as an offering, completely free from personal attachment.","hindi":"यज्ञ के निमित्त किए जाने वाले कर्मों के अलावा अन्य सभी कर्म मनुष्य को संसार के बंधन में बांधते हैं। इसलिए हे अर्जुन, आसक्ति को पूरी तरह त्यागकर केवल यज्ञ की भावना से ही अपने कर्तव्यों का पालन करो।","gujarati":"યજ્ઞ અર્થે કરવામાં આવતા કર્મો સિવાયના અન્ય કર્મો મનુષ્યને સંસારમાં બાંધે છે. તેથી, હે અર્જુન, આસક્તિનો ત્યાગ કરીને કેવળ યજ્ઞ માટે જ તારા કર્મોનું આચરણ કર."},"3.10":{"chapter":3,"verse":10,"sloka":"सहयज्ञाः प्रजाः सृष्ट्वा पुरोवाच प्रजापतिः।\n\nअनेन प्रसविष्यध्वमेष वोऽस्त्विष्टकामधुक्।।3.10।।","transliteration":"saha-yajñāḥ prajāḥ sṛiṣhṭvā purovācha prajāpatiḥ\nanena prasaviṣhyadhvam eṣha vo ’stviṣhṭa-kāma-dhuk","english":"In the beginning, the Creator fashioned all beings along with the path of sacrifice and declared, 'Through this, you shall flourish; may this sacrifice be the Kamadhenu, the cow that fulfills all your desires.'","hindi":"सृष्टि के आदि में प्रजापति ने यज्ञ के साथ मनुष्यों को रचकर कहा कि तुम इस यज्ञ के द्वारा वृद्धि को प्राप्त हो और यह यज्ञ तुम्हारे इच्छित फलों को प्रदान करने वाला हो।","gujarati":"સૃષ્ટિના આરંભમાં પ્રજાપતિએ યજ્ઞ સહિત પ્રજાનું સર્જન કરીને કહ્યું કે, આ યજ્ઞ દ્વારા તમે વૃદ્ધિ પામો અને આ યજ્ઞ તમારી મનોકામનાઓ પૂર્ણ કરનારો કામધેનુ બનો."},"3.11":{"chapter":3,"verse":11,"sloka":"देवान्भावयतानेन ते देवा भावयन्तु वः।\n\nपरस्परं भावयन्तः श्रेयः परमवाप्स्यथ।।3.11।।","transliteration":"devān bhāvayatānena te devā bhāvayantu vaḥ\nparasparaṁ bhāvayantaḥ śhreyaḥ param avāpsyatha","english":"By this, you shall nourish the gods, and may those gods nourish you; thus, mutually nourishing one another, you shall attain the highest good.","hindi":"तुम इस यज्ञ के द्वारा देवताओं की उन्नति करो और वे देवता तुम्हें उन्नति प्रदान करें; इस प्रकार परस्पर एक-दूसरे को उन्नत करते हुए तुम परम कल्याण को प्राप्त होगे।","gujarati":"આ યજ્ઞ દ્વારા તમે દેવોને સંતુષ્ટ કરો અને તે દેવો તમને સંતુષ્ટ કરે; આ રીતે પરસ્પર એકબીજાને પોષતા રહીને તમે પરમ શ્રેય પ્રાપ્ત કરશો."},"3.12":{"chapter":3,"verse":12,"sloka":"इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः।\n\nतैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः।।3.12।।","transliteration":"iṣhṭān bhogān hi vo devā dāsyante yajña-bhāvitāḥ\ntair dattān apradāyaibhyo yo bhuṅkte stena eva saḥ","english":"The celestial beings, nourished by sacrifice, will grant you your desired enjoyments. He who enjoys the gifts bestowed by them without offering back in return is verily a thief.","hindi":"यज्ञ से प्रसन्न होकर देवता तुम्हें मनचाहा फल प्रदान करेंगे। जो व्यक्ति देवताओं द्वारा दिए गए इन उपहारों का उपभोग उन्हें अर्पण किए बिना करता है, वह निश्चित रूप से चोर है।","gujarati":"યજ્ઞ દ્વારા પોષાયેલા દેવતાઓ તમને ઇચ્છિત ભોગો આપશે. જે પુરુષ તેમને આપ્યા વિના તેમના દ્વારા મળેલા ભોગોને ભોગવે છે, તે ચોક્કસપણે ચોર છે."},"3.13":{"chapter":3,"verse":13,"sloka":"यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः।\n\nभुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात्।।3.13।।","transliteration":"yajña-śhiṣhṭāśhinaḥ santo muchyante sarva-kilbiṣhaiḥ\nbhuñjate te tvaghaṁ pāpā ye pachantyātma-kāraṇāt","english":"The righteous who eat the food offered in sacrifice are freed from all sins, but those sinful people who cook food only for their own enjoyment verily eat sin.","hindi":"यज्ञ से बचे हुए अन्न को ग्रहण करने वाले सज्जन सभी पापों से मुक्त हो जाते हैं, परन्तु जो पापी केवल अपने लिए ही भोजन पकाते हैं, वे वास्तव में पाप ही खाते हैं।","gujarati":"યજ્ઞના શેષ અન્નનો આહાર કરનારા સજ્જનો સર્વ પાપોમાંથી મુક્ત થઈ જાય છે, પરંતુ જે પાપીઓ માત્ર પોતાના માટે જ ભોજન રાંધે છે, તેઓ ખરેખર પાપ જ ખાય છે."},"3.14":{"chapter":3,"verse":14,"sloka":"अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसम्भवः।\n\nयज्ञाद्भवति पर्जन्यो यज्ञः कर्मसमुद्भवः।।3.14।।","transliteration":"annād bhavanti bhūtāni parjanyād anna-sambhavaḥ\nyajñād bhavati parjanyo yajñaḥ karma-samudbhavaḥ","english":"All living beings are sustained by food; food is produced by rain; rain is generated by sacrifice; and sacrifice arises from action.","hindi":"संपूर्ण प्राणी अन्न से उत्पन्न होते हैं, अन्न की उत्पत्ति वर्षा से होती है, वर्षा यज्ञ से उत्पन्न होती है और यज्ञ कर्म से उत्पन्न होता है।","gujarati":"બધા જ પ્રાણીઓ અન્નમાંથી ઉત્પન્ન થાય છે, અન્ન વરસાદથી ઉત્પન્ન થાય છે, વરસાદ યજ્ઞથી થાય છે અને યજ્ઞ કર્મમાંથી ઉત્પન્ન થાય છે."},"3.15":{"chapter":3,"verse":15,"sloka":"कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम्।\n\nतस्मात्सर्वगतं ब्रह्म नित्यं यज्ञे प्रतिष्ठितम्।।3.15।।","transliteration":"karma brahmodbhavaṁ viddhi brahmākṣhara-samudbhavam\ntasmāt sarva-gataṁ brahma nityaṁ yajñe pratiṣhṭhitam","english":"Know that all action originates from the Vedas (Brahma), and the Vedas originate from the Imperishable Supreme Brahman. Therefore, the all-pervading Brahman is eternally established in acts of sacrifice.","hindi":"कर्म को वेद से उत्पन्न हुआ जान और वेद को अविनाशी परमात्मा से उत्पन्न हुआ समझ। इसलिए सर्वव्यापी परमात्मा सदा यज्ञ में स्थित रहते हैं।","gujarati":"કર્મ વેદમાંથી ઉત્પન્ન થયું છે અને વેદ અવિનાશી પરમાત્મામાંથી પ્રગટ થયા છે, એમ જાણ. તેથી સર્વવ્યાપી પરમાત્મા હંમેશા યજ્ઞમાં પ્રતિષ્ઠિત છે."},"3.16":{"chapter":3,"verse":16,"sloka":"एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः।\n\nअघायुरिन्द्रियारामो मोघं पार्थ स जीवति।।3.16।।","transliteration":"evaṁ pravartitaṁ chakraṁ nānuvartayatīha yaḥ\naghāyur indriyārāmo moghaṁ pārtha sa jīvati","english":"He who does not follow the cycle thus set in motion, whose life is sinful, and who revels in the senses, lives in vain, O Arjuna.","hindi":"हे पार्थ! जो मनुष्य इस प्रकार चलाए गए सृष्टि-चक्र के अनुकूल नहीं चलता, वह इंद्रियों के भोगों में ही रमने वाला पापी पुरुष व्यर्थ ही जीवित रहता है।","gujarati":"હે પાર્થ! જે મનુષ્ય આ રીતે ચલાવેલા સૃષ્ટિ-ચક્રને અનુસરતો નથી, તે ઈન્દ્રિયોના ભોગોમાં રાચતો પાપી પુરુષ વ્યર્થ જ જીવે છે."},"3.17":{"chapter":3,"verse":17,"sloka":"यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः।\n\nआत्मन्येव च सन्तुष्टस्तस्य कार्यं न विद्यते।।3.17।।","transliteration":"yas tvātma-ratir eva syād ātma-tṛiptaśh cha mānavaḥ\nātmanyeva cha santuṣhṭas tasya kāryaṁ na vidyate","english":"But for one who takes delight in the Self, who is satisfied in the Self, and who is content only in the Self, there is no duty that remains.","hindi":"परंतु जो मनुष्य आत्मा में ही रमण करने वाला, आत्मा में ही तृप्त और आत्मा में ही संतुष्ट है, उसके लिए कोई कर्तव्य शेष नहीं रहता।","gujarati":"પરંતુ જે મનુષ્ય આત્મામાં જ રમણ કરનારો, આત્મામાં જ તૃપ્ત અને આત્મામાં જ સંતુષ્ટ છે, તેના માટે કોઈ કર્તવ્ય બાકી રહેતું નથી."},"3.18":{"chapter":3,"verse":18,"sloka":"नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन।\n\nन चास्य सर्वभूतेषु कश्िचदर्थव्यपाश्रयः।।3.18।।","transliteration":"naiva tasya kṛitenārtho nākṛiteneha kaśhchana\nna chāsya sarva-bhūteṣhu kaśhchid artha-vyapāśhrayaḥ","english":"For the self-realized soul, there is no purpose in performing actions, nor is there any gain in abstaining from them; he has no need to depend on any living being for his fulfillment.","hindi":"उस महापुरुष का इस संसार में न तो कर्म करने से कोई प्रयोजन रहता है और न कर्म न करने से ही कोई लाभ होता है; तथा उसका किसी भी प्राणी पर अपने किसी स्वार्थ के लिए कोई आश्रय नहीं रहता।","gujarati":"તે પુરુષને આ જગતમાં કરેલા કર્મો સાથે કે ન કરેલા કર્મો સાથે કોઈ લેવાદેવા નથી હોતી, અને તે પોતાના કોઈપણ હેતુ માટે અન્ય કોઈ પણ જીવ પર આધાર રાખતો નથી."},"3.19":{"chapter":3,"verse":19,"sloka":"तस्मादसक्तः सततं कार्यं कर्म समाचर।\n\nअसक्तो ह्याचरन्कर्म परमाप्नोति पूरुषः।।3.19।।","transliteration":"tasmād asaktaḥ satataṁ kāryaṁ karma samāchara\nasakto hyācharan karma param āpnoti pūruṣhaḥ","english":"Therefore, always perform your prescribed duty without attachment, for by performing action without attachment, one attains the Supreme.","hindi":"इसलिए तू अनासक्त होकर निरंतर कर्तव्य कर्मों का आचरण कर, क्योंकि अनासक्त भाव से कर्म करता हुआ मनुष्य परमात्मा को प्राप्त कर लेता है।","gujarati":"તેથી, તું અનાસક્ત થઈને નિરંતર કર્તવ્ય કર્મનું આચરણ કર, કારણ કે અનાસક્ત રહીને કર્મ કરનાર મનુષ્ય પરમાત્માને પ્રાપ્ત કરે છે."},"3.20":{"chapter":3,"verse":20,"sloka":"कर्मणैव हि संसिद्धिमास्थिता जनकादयः।\n\nलोकसंग्रहमेवापि संपश्यन्कर्तुमर्हसि।।3.20।।","transliteration":"karmaṇaiva hi sansiddhim āsthitā janakādayaḥ\nloka-saṅgraham evāpi sampaśhyan kartum arhasi","english":"Kings like Janaka and others attained perfection solely through action; considering the duty of guiding the masses, you too should perform your prescribed duties.","hindi":"जनकादि ज्ञानी जन भी कर्मों के द्वारा ही परम सिद्धि को प्राप्त हुए थे। अतः लोक-संग्रह (संसार के कल्याण) को ध्यान में रखते हुए भी तुम्हें कर्म करना ही चाहिए।","gujarati":"જનક આદિ જ્ઞાની પુરુષો પણ કર્મ દ્વારા જ સિદ્ધિને પ્રાપ્ત થયા હતા; તેથી લોકસંગ્રહ (લોકકલ્યાણ)ને ધ્યાનમાં રાખીને પણ તમારે કર્મ કરવું જોઈએ."},"3.21":{"chapter":3,"verse":21,"sloka":"यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः।\n\nस यत्प्रमाणं कुरुते लोकस्तदनुवर्तते।।3.21।।","transliteration":"yad yad ācharati śhreṣhṭhas tat tad evetaro janaḥ\nsa yat pramāṇaṁ kurute lokas tad anuvartate","english":"Whatever action is performed by a great man, common men follow in his footsteps; whatever standard he sets by his exemplary conduct, the entire world pursues.","hindi":"श्रेष्ठ पुरुष जो-जो आचरण करते हैं, अन्य पुरुष भी वैसा-वैसा ही आचरण करते हैं; वह जो प्रमाण स्थापित कर देते हैं, समस्त संसार उसका अनुसरण करने लगता है।","gujarati":"શ્રેષ્ઠ પુરુષ જેવું આચરણ કરે છે, અન્ય લોકો પણ તેવું જ કરે છે; તે જે પ્રમાણ સ્થાપિત કરે છે, આખું જગત તેનું જ અનુસરણ કરે છે."},"3.22":{"chapter":3,"verse":22,"sloka":"न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किञ्चन।\n\nनानवाप्तमवाप्तव्यं वर्त एव च कर्मणि।।3.22।।","transliteration":"na me pārthāsti kartavyaṁ triṣhu lokeṣhu kiñchana\nnānavāptam avāptavyaṁ varta eva cha karmaṇi","english":"O Partha, there is no work in all the three worlds that I am compelled to do, nor is there anything I have not attained or need to attain; yet, I am always engaged in prescribed duties.","hindi":"हे अर्जुन! तीनों लोकों में मेरे लिए न तो कोई कर्तव्य है और न ही कोई ऐसी वस्तु है जिसे प्राप्त करना बाकी हो, फिर भी मैं कर्म में ही लगा रहता हूँ।","gujarati":"હે અર્જુન! ત્રણેય લોકમાં મારા માટે કંઈ પણ કર્તવ્ય નથી, કે કોઈ એવી વસ્તુ નથી જે મારે મેળવવાની બાકી હોય, છતાં હું સતત કર્મમાં જ જોડાયેલો રહું છું."},"3.23":{"chapter":3,"verse":23,"sloka":"यदि ह्यहं न वर्तेयं जातु कर्मण्यतन्द्रितः।\n\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः।।3.23।।","transliteration":"yadi hyahaṁ na varteyaṁ jātu karmaṇyatandritaḥ\nmama vartmānuvartante manuṣhyāḥ pārtha sarvaśhaḥ","english":"For if I did not engage in action, ever untiring, O Partha, men would follow My path in every way.","hindi":"क्योंकि हे पार्थ! यदि मैं कभी सावधानीपूर्वक कर्मों में न लगूँ, तो सब मनुष्य सब प्रकार से मेरे ही मार्ग का अनुसरण करेंगे।","gujarati":"કેમ કે, હે પાર્થ! જો હું કદાપિ સાવધાન થઈને કર્મમાં ન વર્તું, તો મનુષ્યો સર્વ પ્રકારે મારા જ માર્ગનું અનુસરણ કરશે."},"3.24":{"chapter":3,"verse":24,"sloka":"उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम्।\n\nसङ्करस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः।।3.24।।","transliteration":"utsīdeyur ime lokā na kuryāṁ karma ched aham\nsankarasya cha kartā syām upahanyām imāḥ prajāḥ","english":"If I were to cease from action, these worlds would perish; I would be the cause of social chaos and the destroyer of all living beings.","hindi":"यदि मैं कर्म न करूँ, तो ये समस्त लोक नष्ट हो जायेंगे और मैं वर्णसंकर का कर्ता तथा इस प्रजा का विनाश करने वाला होऊँगा।","gujarati":"જો હું કર્મ ન કરું, તો આ બધા લોકો નાશ પામશે અને હું વર્ણસંકરનો કર્તા તથા આ પ્રજાનો વિનાશ કરનાર થઈશ."},"3.25":{"chapter":3,"verse":25,"sloka":"सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत।\n\nकुर्याद्विद्वांस्तथासक्तश्िचकीर्षुर्लोकसंग्रहम्।।3.25।।","transliteration":"saktāḥ karmaṇyavidvānso yathā kurvanti bhārata\nkuryād vidvāns tathāsaktaśh chikīrṣhur loka-saṅgraham","english":"Just as the ignorant perform their duties with attachment to the results, O Bharata, so too should the wise act without attachment, desiring only the welfare of the world.","hindi":"हे भारत! जिस प्रकार अज्ञानी पुरुष फल की आसक्ति से कर्म करते हैं, उसी प्रकार विद्वानों को फल की इच्छा त्यागकर लोक-कल्याण के उद्देश्य से कर्म करना चाहिए।","gujarati":"હે ભારત! જેવી રીતે અજ્ઞાની લોકો ફળની આસક્તિથી કર્મ કરે છે, તેવી જ રીતે જ્ઞાની પુરુષોએ અનાસક્ત રહીને લોકકલ્યાણ માટે કર્મ કરવું જોઈએ."},"3.26":{"chapter":3,"verse":26,"sloka":"न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम्।\n\nजोषयेत्सर्वकर्माणि विद्वान् युक्तः समाचरन्।।3.26।।","transliteration":"na buddhi-bhedaṁ janayed ajñānāṁ karma-saṅginām\njoṣhayet sarva-karmāṇi vidvān yuktaḥ samācharan","english":"The wise should not unsettle the minds of those attached to the fruits of action; rather, they should inspire them to perform their duties by setting an example through their own dedicated engagement.","hindi":"ज्ञानी पुरुष को कर्मों में आसक्त अज्ञानियों की बुद्धि में भ्रम उत्पन्न नहीं करना चाहिए; उसे स्वयं योगयुक्त होकर समस्त कर्मों का भली-भांति आचरण करना चाहिए और उन्हें भी कर्म करने के लिए प्रेरित करना चाहिए।","gujarati":"જ્ઞાની પુરુષે કર્મોમાં આસક્ત અજ્ઞાનીઓની બુદ્ધિમાં ભ્રમ પેદા ન કરવો જોઈએ; તેણે પોતે યોગયુક્ત રહીને સર્વ કર્મો સારી રીતે કરવા જોઈએ અને તેમની પાસે પણ તેવા જ કર્મો કરાવવા જોઈએ."},"3.27":{"chapter":3,"verse":27,"sloka":"प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः।\n\nअहङ्कारविमूढात्मा कर्ताऽहमिति मन्यते।।3.27।।","transliteration":"prakṛiteḥ kriyamāṇāni guṇaiḥ karmāṇi sarvaśhaḥ\nahankāra-vimūḍhātmā kartāham iti manyate","english":"All actions are performed by the qualities of nature (gunas); but the person whose mind is deluded by ego thinks, 'I am the doer.'","hindi":"सम्पूर्ण कर्म सब प्रकार से प्रकृति के गुणों के द्वारा ही किये जाते हैं, परंतु अहंकार से मोहित हुआ पुरुष 'मैं कर्ता हूँ' ऐसा मान बैठता है।","gujarati":"બધા જ કર્મો પ્રકૃતિના ગુણો દ્વારા જ કરવામાં આવે છે, પરંતુ અહંકારથી મોહિત થયેલો મનુષ્ય 'હું કર્તા છું' એમ માની લે છે."},"3.28":{"chapter":3,"verse":28,"sloka":"तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः।\n\nगुणा गुणेषु वर्तन्त इति मत्वा न सज्जते।।3.28।।","transliteration":"tattva-vit tu mahā-bāho guṇa-karma-vibhāgayoḥ\nguṇā guṇeṣhu vartanta iti matvā na sajjate","english":"But the one who knows the truth of the divisions of the Gunas and their functions, O mighty-armed one, knowing that it is the Gunas acting upon the Gunas, does not become attached.","hindi":"परंतु हे महाबाहो! गुण विभाग और कर्मों के तत्त्व को जानने वाला ज्ञानी यह समझकर कि 'गुण ही गुणों में बरत रहे हैं', उनमें आसक्त नहीं होता।","gujarati":"પરંતુ હે મહાબાહો! ગુણ વિભાગ અને કર્મોના તત્વને જાણનાર જ્ઞાની પુરુષ એવું સમજીને કે 'ગુણો જ ગુણોમાં વર્તી રહ્યા છે', તેમાં આસક્ત થતો નથી."},"3.29":{"chapter":3,"verse":29,"sloka":"प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु।\n\nतानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत्।।3.29।।","transliteration":"prakṛiter guṇa-sammūḍhāḥ sajjante guṇa-karmasu\ntān akṛitsna-vido mandān kṛitsna-vin na vichālayet","english":"Those who are deluded by the modes of material nature become attached to the activities of these modes. The person of perfect knowledge should not unsettle those whose understanding is imperfect and who are less enlightened.","hindi":"प्रकृति के गुणों से मोहित हुए लोग गुणों और कर्मों के प्रति आसक्त रहते हैं। जो ज्ञानी पुरुष पूर्णता को प्राप्त कर चुके हैं, उन्हें चाहिए कि वे उन अल्पज्ञानी और मंदबुद्धि लोगों की श्रद्धा को विचलित न करें।","gujarati":"પ્રકૃતિના ગુણોથી મોહિત થયેલા લોકો ગુણો અને કર્મોમાં આસક્ત રહે છે. પૂર્ણ જ્ઞાની પુરુષોએ તે અલ્પજ્ઞાની અને મંદબુદ્ધિવાળા લોકોને વિચલિત કરવા જોઈએ નહીં."},"3.30":{"chapter":3,"verse":30,"sloka":"मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा।\n\nनिराशीर्निर्ममो भूत्वा युध्यस्व विगतज्वरः।।3.30।।","transliteration":"mayi sarvāṇi karmāṇi sannyasyādhyātma-chetasā\nnirāśhīr nirmamo bhūtvā yudhyasva vigata-jvaraḥ","english":"Surrendering all actions unto Me, with your mind focused on the Higher Self, free from desire and ego, and devoid of mental agony, fight.","hindi":"मुझमें अर्पण किए हुए समस्त कर्मों द्वारा, अध्यात्म-चिन्तन के द्वारा, आशा और ममता से मुक्त होकर, मानसिक संताप को त्यागकर तुम युद्ध करो।","gujarati":"મારામાં સર્વ કર્મોને સમર્પણ કરીને, આધ્યાત્મિક ચિંતન દ્વારા, આશા અને મમતાથી રહિત થઈને, માનસિક સંતાપ છોડીને તું યુદ્ધ કર."},"3.31":{"chapter":3,"verse":31,"sloka":"ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः।\n\nश्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः।।3.31।।","transliteration":"ye me matam idaṁ nityam anutiṣhṭhanti mānavāḥ\nśhraddhāvanto ’nasūyanto muchyante te ’pi karmabhiḥ","english":"Those who always practice this teaching of Mine with faith and without malice are also liberated from the bondage of karma.","hindi":"जो मनुष्य दोष-बुद्धि से रहित होकर श्रद्धापूर्वक मेरे इस उपदेश का निरंतर पालन करते हैं, वे भी कर्मों के बंधन से मुक्त हो जाते हैं।","gujarati":"જે મનુષ્યો દોષબુદ્ધિ રહિત અને શ્રદ્ધાવાન બનીને મારા આ ઉપદેશનું સદા અનુષ્ઠાન કરે છે, તેઓ પણ કર્મબંધનથી મુક્ત થઈ જાય છે."},"3.32":{"chapter":3,"verse":32,"sloka":"ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम्।\n\nसर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः।।3.32।।","transliteration":"ye tvetad abhyasūyanto nānutiṣhṭhanti me matam\nsarva-jñāna-vimūḍhāns tān viddhi naṣhṭān achetasaḥ","english":"But those who find fault with My teaching and do not follow it, being devoid of all knowledge and lacking discernment, know them to be ruined, lost to the path of spiritual progress.","hindi":"परन्तु जो मनुष्य दोष दृष्टि के कारण मेरे इस मत का अनुसरण नहीं करते, उन ज्ञानहीन और विवेकशून्य लोगों को तुम सर्वथा नष्ट हुआ ही समझो।","gujarati":"પરંતુ જે લોકો દોષની દૃષ્ટિ રાખનારા છે અને મારા આ મતનું અનુસરણ કરતા નથી, તેવા જ્ઞાનહીન અને વિવેકશૂન્ય લોકોને તું સંપૂર્ણપણે નષ્ટ થયેલા જ સમજ."},"3.33":{"chapter":3,"verse":33,"sloka":"सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि।\n\nप्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति।।3.33।।","transliteration":"sadṛiśhaṁ cheṣhṭate svasyāḥ prakṛiter jñānavān api\nprakṛitiṁ yānti bhūtāni nigrahaḥ kiṁ kariṣhyati","english":"Even a wise man acts according to his own nature; all living beings follow their nature. What can restraint do?","hindi":"ज्ञानवान् पुरुष भी अपनी प्रकृति के अनुसार चेष्टा करता है; सभी प्राणी अपनी प्रकृति का अनुसरण करते हैं। ऐसे में (बाहरी) निग्रह क्या कर सकता है?","gujarati":"જ્ઞાની પુરુષ પણ પોતાની પ્રકૃતિ અનુસાર વર્તે છે; બધા પ્રાણીઓ પ્રકૃતિને અનુસરે છે, તો પછી દમન શું કરી શકશે?"},"3.34":{"chapter":3,"verse":34,"sloka":"इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ।\n\nतयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ।।3.34।।","transliteration":"indriyasyendriyasyārthe rāga-dveṣhau vyavasthitau\ntayor na vaśham āgachchhet tau hyasya paripanthinau","english":"Attachment and aversion to the objects of the senses reside in the senses; let no one come under their control, for they are obstacles on the path.","hindi":"इन्द्रिय-इन्द्रिय के अर्थ में राग और द्वेष छिपे हुए हैं; मनुष्य को इनके वश में नहीं होना चाहिए, क्योंकि ये दोनों ही उसके मार्ग के शत्रु हैं।","gujarati":"દરેક ઇન્દ્રિયના વિષયમાં રાગ અને દ્વેષ છુપાયેલા છે; મનુષ્યે આ બંનેના વશમાં ન થવું જોઈએ, કારણ કે તે બંને તેના કલ્યાણના માર્ગમાં શત્રુ સમાન છે."},"3.35":{"chapter":3,"verse":35,"sloka":"श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।\n\nस्वधर्मे निधनं श्रेयः परधर्मो भयावहः।।3.35।।","transliteration":"śhreyān swa-dharmo viguṇaḥ para-dharmāt sv-anuṣhṭhitāt\nswa-dharme nidhanaṁ śhreyaḥ para-dharmo bhayāvahaḥ","english":"It is better to perform one's own duty imperfectly than to perform the duty of another well. It is better to die in one's own duty, for the duty of another is fraught with danger.","hindi":"अच्छी प्रकार आचरण किए हुए दूसरे के धर्म से गुणरहित भी अपना धर्म श्रेष्ठ है; अपने धर्म में मरना भी कल्याणकारी है, किन्तु दूसरे का धर्म भय को देने वाला है।","gujarati":"બીજાના ધર્મનું સારી રીતે આચરણ કરવા કરતા, ગુણરહિત હોવા છતાં પોતાનો ધર્મ શ્રેષ્ઠ છે. પોતાના ધર્મમાં મરવું પણ કલ્યાણકારી છે, પરંતુ બીજાનો ધર્મ ભય આપનારો છે."},"3.36":{"chapter":3,"verse":36,"sloka":"अर्जुन उवाच\n\nअथ केन प्रयुक्तोऽयं पापं चरति पूरुषः।\n\nअनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः।।3.36।।","transliteration":"arjuna uvācha\natha kena prayukto ’yaṁ pāpaṁ charati pūruṣhaḥ\nanichchhann api vārṣhṇeya balād iva niyojitaḥ","english":"Arjuna said: But by what is a person impelled to commit sin, even against his will, as if compelled by force, O Krishna?","hindi":"अर्जुन ने कहा - हे कृष्ण! फिर यह मनुष्य न चाहते हुए भी, किसके द्वारा प्रेरित होकर बलपूर्वक पाप कर्म करता है?","gujarati":"અર્જુને કહ્યું - હે કૃષ્ણ! તો પછી આ મનુષ્ય ન ઈચ્છવા છતાં પણ, કોના દ્વારા પ્રેરાઈને જાણે બળજબરીથી પાપ કરવા માટે પ્રેરાય છે?"},"3.37":{"chapter":3,"verse":37,"sloka":"श्री भगवानुवाच\n\nकाम एष क्रोध एष रजोगुणसमुद्भवः।\n\nमहाशनो महापाप्मा विद्ध्येनमिह वैरिणम्।।3.37।।","transliteration":"śhrī bhagavān uvācha\nkāma eṣha krodha eṣha rajo-guṇa-samudbhavaḥ\nmahāśhano mahā-pāpmā viddhyenam iha vairiṇam","english":"The Blessed Lord said: It is desire alone, born of the mode of passion, which later manifests as anger; know this to be the all-consuming, sinful enemy in this world.","hindi":"श्रीभगवान् ने कहा: यह कामना ही है, जो रजोगुण से उत्पन्न हुई है और यही बाद में क्रोध का रूप ले लेती है; इसे ही तुम इस संसार में सब कुछ भस्म करने वाला महापापी शत्रु समझो।","gujarati":"શ્રી ભગવાન બોલ્યા: આ કામના જ છે, જે રજોગુણથી ઉત્પન્ન થયેલી છે અને તે જ આગળ જતાં ક્રોધનું રૂપ ધારણ કરે છે; તું આને જ આ સંસારમાં સર્વને ભક્ષણ કરનાર પાપી શત્રુ જાણ."},"3.38":{"chapter":3,"verse":38,"sloka":"धूमेनाव्रियते वह्निर्यथाऽऽदर्शो मलेन च।\n\nयथोल्बेनावृतो गर्भस्तथा तेनेदमावृतम्।।3.38।।","transliteration":"dhūmenāvriyate vahnir yathādarśho malena cha\nyatholbenāvṛito garbhas tathā tenedam āvṛitam","english":"Just as fire is covered by smoke, a mirror by dust, and an embryo by the womb, in the same way, knowledge is enveloped by desire.","hindi":"जैसे धुएँ से अग्नि ढकी जाती है, जैसे धूल से दर्पण ढका जाता है और जैसे गर्भ (अम्नियोटिक थैली) से भ्रूण ढका रहता है, वैसे ही काम के द्वारा ज्ञान आवृत रहता है।","gujarati":"જેમ ધુમાડાથી અગ્નિ, ધૂળથી અરીસો અને ગર્ભના પડથી ગર્ભ ઢંકાયેલો રહે છે, તેમ કામ (વાસના) દ્વારા જ્ઞાન ઢંકાયેલું રહે છે."},"3.39":{"chapter":3,"verse":39,"sloka":"आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा।\n\nकामरूपेण कौन्तेय दुष्पूरेणानलेन च।।3.39।।","transliteration":"āvṛitaṁ jñānam etena jñānino nitya-vairiṇā\nkāma-rūpeṇa kaunteya duṣhpūreṇānalena cha","english":"O Arjuna, wisdom is covered by this constant enemy of the wise, in the form of desire, which is like an insatiable fire.","hindi":"हे अर्जुन! अग्नि के समान कभी न बुझने वाले और ज्ञानी मनुष्यों के नित्य शत्रु स्वरूप इस काम (कामना) से ज्ञान ढका हुआ है।","gujarati":"હે અર્જુન! જ્ઞાનીઓના આ નિત્ય શત્રુરૂપ, અગ્નિ સમાન કદી પણ તૃપ્ત ન થતી કામનાઓ દ્વારા જ્ઞાન ઢંકાયેલું રહે છે."},"3.40":{"chapter":3,"verse":40,"sloka":"इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते।\n\nएतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम्।।3.40।।","transliteration":"indriyāṇi mano buddhir asyādhiṣhṭhānam uchyate\netair vimohayatyeṣha jñānam āvṛitya dehinam","english":"The senses, the mind, and the intellect are said to be its seat; through these, it deludes the embodied one, veiling their wisdom.","hindi":"इन्द्रियाँ, मन और बुद्धि इसके निवास स्थान कहे जाते हैं; इनके द्वारा ही यह काम ज्ञान को ढँककर जीवात्मा को मोहित करता है।","gujarati":"ઇન્દ્રિયો, મન અને બુદ્ધિ તેના નિવાસસ્થાન ગણાય છે; તેમના દ્વારા તે કામ જ્ઞાનને ઢાંકીને આત્માને મોહિત કરે છે."},"3.41":{"chapter":3,"verse":41,"sloka":"तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ।\n\nपाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम्।।3.41।।","transliteration":"tasmāt tvam indriyāṇyādau niyamya bharatarṣhabha\npāpmānaṁ prajahi hyenaṁ jñāna-vijñāna-nāśhanam","english":"Therefore, O best of the Bharatas, control your senses first and then kill this sinful thing, which destroys knowledge and realization.","hindi":"इसलिये, हे अर्जुन! तुम पहले इन्द्रियों को वश में करके, ज्ञान और विज्ञान के नाशक इस कामरूप पापी को नष्ट करो।","gujarati":"તેથી, હે ભરતશ્રેષ્ઠ! તું પ્રથમ ઇન્દ્રિયોને વશ કરીને, જ્ઞાન અને વિજ્ઞાનનો નાશ કરનાર આ કામરૂપી પાપીને મારી નાખ."},"3.42":{"chapter":3,"verse":42,"sloka":"इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः।\n\nमनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः।।3.42।।","transliteration":"indriyāṇi parāṇyāhur indriyebhyaḥ paraṁ manaḥ\nmanasas tu parā buddhir yo buddheḥ paratas tu saḥ","english":"The senses are said to be superior to the body; the mind is superior to the senses; the intellect is superior to the mind; and that which is superior to the intellect is the Self.","hindi":"इन्द्रियों को शरीर से श्रेष्ठ कहा जाता है, इन्द्रियों से श्रेष्ठ मन है, मन से श्रेष्ठ बुद्धि है और जो बुद्धि से भी अत्यंत श्रेष्ठ है, वह आत्मा है।","gujarati":"ઇન્દ્રિયોને શરીર કરતા શ્રેષ્ઠ કહેવાય છે, ઇન્દ્રિયો કરતા મન શ્રેષ્ઠ છે, મન કરતા બુદ્ધિ શ્રેષ્ઠ છે અને જે બુદ્ધિથી પણ પર છે, તે આત્મા છે."},"3.43":{"chapter":3,"verse":43,"sloka":"एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना।\n\nजहि शत्रुं महाबाहो कामरूपं दुरासदम्।।3.43।।","transliteration":"evaṁ buddheḥ paraṁ buddhvā sanstabhyātmānam ātmanā\njahi śhatruṁ mahā-bāho kāma-rūpaṁ durāsadam","english":"Thus, knowing the Self to be superior to the intellect and restraining the lower self by the higher Self, O mighty-armed Arjuna, conquer this enemy in the form of desire, which is difficult to overcome.","hindi":"इस प्रकार बुद्धि से श्रेष्ठ आत्मा को जानकर और बुद्धि के द्वारा मन को संयमित करके, हे महाबाहो! तुम इस कामरूप दुर्जेय शत्रु को मार डालो।","gujarati":"આમ, બુદ્ધિથી પર એવા આત્માને જાણીને અને બુદ્ધિ દ્વારા મનને સંયમિત કરીને, હે મહાબાહો! તું આ કામરૂપી દુર્જય શત્રુનો નાશ કર."},"4.1":{"chapter":4,"verse":1,"sloka":"श्री भगवानुवाच\n\nइमं विवस्वते योगं प्रोक्तवानहमव्ययम्।\n\nविवस्वान् मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत्।।4.1।।","transliteration":"śhrī bhagavān uvācha\nimaṁ vivasvate yogaṁ proktavān aham avyayam\nvivasvān manave prāha manur ikṣhvākave ’bravīt","english":"The Blessed Lord said: I taught this imperishable science of Yoga to the sun-god, Vivasvan, who instructed it to Manu, the father of mankind, and Manu in turn taught it to Ikshvaku.","hindi":"श्रीभगवान् बोले: मैंने इस अविनाशी योग का उपदेश विवस्वान् (सूर्य) को दिया था, विवस्वान् ने मनु से कहा और मनु ने इक्ष्वाकु से कहा।","gujarati":"શ્રી ભગવાન બોલ્યા: મેં આ અવિનાશી યોગનો ઉપદેશ સૂર્યદેવ વિવસ્વાનને આપ્યો હતો; વિવસ્વાને તે મનુને કહ્યું અને મનુએ તે ઇક્ષ્વાકુને શીખવ્યો."},"4.2":{"chapter":4,"verse":2,"sloka":"एवं परम्पराप्राप्तमिमं राजर्षयो विदुः।\n\nस कालेनेह महता योगो नष्टः परन्तप।।4.2।।","transliteration":"evaṁ paramparā-prāptam imaṁ rājarṣhayo viduḥ\nsa kāleneha mahatā yogo naṣhṭaḥ parantapa","english":"This supreme science was thus received through the chain of disciplic succession, and the saintly kings understood it in that way. But in course of time, the succession was broken, and therefore the science as it is appears to be lost.","hindi":"इस प्रकार परम्परा से प्राप्त हुए इस योग को राजर्षियों ने जाना, किन्तु हे परन्तप! समय के अंतराल के कारण वह योग पृथ्वी पर नष्टप्राय हो गया।","gujarati":"આ રીતે પરંપરાથી પ્રાપ્ત થયેલા આ યોગને રાજર્ષિઓએ જાણ્યો, પરંતુ હે પરંતપ! કાળક્રમે આ યોગ આ પૃથ્વી પર નષ્ટપ્રાય થઈ ગયો છે."},"4.3":{"chapter":4,"verse":3,"sloka":"स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः।\n\nभक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम्।।4.3।।","transliteration":"sa evāyaṁ mayā te ’dya yogaḥ proktaḥ purātanaḥ\nbhakto ’si me sakhā cheti rahasyaṁ hyetad uttamam","english":"That same ancient yoga has been today imparted to you by Me, because you are My devotee and My friend; it is indeed the supreme secret.","hindi":"वही यह पुरातन योग आज मैंने तुम्हें कहा है, क्योंकि तुम मेरे भक्त और मित्र हो; यह बहुत ही उत्तम रहस्य है।","gujarati":"તે જ આ પુરાતન યોગ આજે મેં તને કહ્યો છે, કારણ કે તું મારો ભક્ત અને મિત્ર છે; આ ઉત્તમ રહસ્ય છે."},"4.4":{"chapter":4,"verse":4,"sloka":"अर्जुन उवाच\n\nअपरं भवतो जन्म परं जन्म विवस्वतः।\n\nकथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति।।4.4।।","transliteration":"arjuna uvācha\naparaṁ bhavato janma paraṁ janma vivasvataḥ\nkatham etad vijānīyāṁ tvam ādau proktavān iti","english":"Arjuna said, 'Your birth is later, and the birth of Vivasvan was prior; how then am I to understand that You taught this yoga in the beginning?'","hindi":"अर्जुन ने कहा, 'आपका जन्म तो बाद का है और विवस्वान का जन्म पहले हुआ था, फिर मैं कैसे समझूँ कि आपने ही सृष्टि के आरंभ में यह योग उपदेश दिया था?'","gujarati":"અર્જુને કહ્યું, 'તમારો જન્મ તો પછીનો છે અને સૂર્યનો (વિવસ્વાનનો) જન્મ પહેલાંનો છે, તો પછી હું કેવી રીતે માનું કે તમે જ આદિમાં આ યોગનો ઉપદેશ આપ્યો હતો?'"},"4.5":{"chapter":4,"verse":5,"sloka":"श्री भगवानुवाच\n\nबहूनि मे व्यतीतानि जन्मानि तव चार्जुन।\n\nतान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप।।4.5।।","transliteration":"śhrī bhagavān uvācha\nbahūni me vyatītāni janmāni tava chārjuna\ntānyahaṁ veda sarvāṇi na tvaṁ vettha parantapa","english":"The Blessed Lord said: Many births of Mine have passed, and so have yours, O Arjuna; I know them all, but you do not know them, O scorcher of foes.","hindi":"श्रीभगवान बोले: हे अर्जुन! मेरे और तुम्हारे बहुत से जन्म बीत चुके हैं। मैं उन सबको जानता हूँ, परन्तु हे परन्तप! तुम उनको नहीं जानते।","gujarati":"શ્રી ભગવાન બોલ્યા: હે અર્જુન! મારા અને તારા ઘણા જન્મ થઈ ગયા છે. હું તે બધાને જાણું છું, પરંતુ હે પરંતપ! તું તે બધાને જાણતો નથી."},"4.6":{"chapter":4,"verse":6,"sloka":"अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन्।\n\nप्रकृतिं स्वामधिष्ठाय संभवाम्यात्ममायया।।4.6।।","transliteration":"ajo ’pi sannavyayātmā bhūtānām īśhvaro ’pi san\nprakṛitiṁ svām adhiṣhṭhāya sambhavāmyātma-māyayā","english":"Though I am birthless and deathless, and the Lord of all living beings, I manifest through my own divine potency, controlling my material nature.","hindi":"यद्यपि मैं अजन्मा और अविनाशी हूँ और सभी प्राणियों का ईश्वर हूँ, तथापि अपनी प्रकृति को वश में करके अपनी माया से प्रकट होता हूँ।","gujarati":"જોકે હું અજન્મા અને અવિનાશી છું, અને સર્વ પ્રાણીઓનો ઈશ્વર છું, છતાં હું મારી પ્રકૃતિને વશમાં રાખીને મારી માયા વડે પ્રગટ થાઉં છું."},"4.7":{"chapter":4,"verse":7,"sloka":"यदा यदा हि धर्मस्य ग्लानिर्भवति भारत।\n\nअभ्युत्थानमधर्मस्य तदाऽऽत्मानं सृजाम्यहम्।।4.7।।","transliteration":"yadā yadā hi dharmasya glānir bhavati bhārata\nabhyutthānam adharmasya tadātmānaṁ sṛijāmyaham","english":"Whenever there is a decline of righteousness and an increase of unrighteousness, O Arjuna, then I manifest Myself.","hindi":"यदा यदा हि धर्मस्य ग्लानिर्भवति भारत। अभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम्।।","gujarati":"જ્યારે જ્યારે ધર્મની ગ્લાનિ થાય છે અને અધર્મનો વધારો થાય છે, ત્યારે ત્યારે હું સ્વયંને પ્રગટ કરું છું."},"4.8":{"chapter":4,"verse":8,"sloka":"परित्राणाय साधूनां विनाशाय च दुष्कृताम्।\n\nधर्मसंस्थापनार्थाय संभवामि युगे युगे।।4.8।।","transliteration":"paritrāṇāya sādhūnāṁ vināśhāya cha duṣhkṛitām\ndharma-sansthāpanārthāya sambhavāmi yuge yuge","english":"To protect the righteous, to destroy the wicked, and to establish the principles of righteousness, I manifest Myself in every age.","hindi":"साधु पुरुषों का उद्धार करने के लिए, पाप कर्म करने वालों का विनाश करने के लिए और धर्म की अच्छी तरह से स्थापना करने के लिए, मैं युग-युग में प्रकट हुआ करता हूँ।","gujarati":"સાધુ પુરુષોના ઉદ્ધાર માટે, પાપીઓના વિનાશ માટે અને ધર્મની સ્થાપના માટે, હું યુગે યુગે પ્રગટ થાઉં છું."},"4.9":{"chapter":4,"verse":9,"sloka":"जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः।\n\nत्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन।।4.9।।","transliteration":"janma karma cha me divyam evaṁ yo vetti tattvataḥ\ntyaktvā dehaṁ punar janma naiti mām eti so ’rjuna","english":"He who truly understands the divine nature of My birth and activities, O Arjuna, is not reborn upon leaving the body, but attains Me.","hindi":"हे अर्जुन! जो कोई मेरे जन्म और कर्मों को दिव्य रूप में जान लेता है, वह शरीर त्यागने के बाद फिर जन्म नहीं लेता, बल्कि मुझे ही प्राप्त होता है।","gujarati":"હે અર્જુન! જે મનુષ્ય મારા દિવ્ય જન્મ અને કર્મોને તત્વથી જાણી લે છે, તે શરીરનો ત્યાગ કરીને ફરીથી જન્મ લેતો નથી; તે મને જ પ્રાપ્ત થાય છે."},"4.10":{"chapter":4,"verse":10,"sloka":"वीतरागभयक्रोधा मन्मया मामुपाश्रिताः।\n\nबहवो ज्ञानतपसा पूता मद्भावमागताः।।4.10।।","transliteration":"vīta-rāga-bhaya-krodhā man-mayā mām upāśhritāḥ\nbahavo jñāna-tapasā pūtā mad-bhāvam āgatāḥ","english":"Freed from attachment, fear, and anger, absorbed in Me, taking refuge in Me, purified by the fire of knowledge, many have attained My Being.","hindi":"वीतरागभयक्रोधा मन्मया मामुपाश्रिताः। बहवो ज्ञानतपसा पूता मद्भावमागताः॥","gujarati":"જેઓ રાગ, ભય અને ક્રોધથી મુક્ત છે, જેઓ મારામાં નિમગ્ન છે અને મારા શરણાગત છે, એવા ઘણા પુરુષો જ્ઞાનરૂપી તપ દ્વારા પવિત્ર થઈને મારા સ્વરૂપને પામ્યા છે."},"4.11":{"chapter":4,"verse":11,"sloka":"ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम्।\n\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः।।4.11।।","transliteration":"ye yathā māṁ prapadyante tāns tathaiva bhajāmyaham\nmama vartmānuvartante manuṣhyāḥ pārtha sarvaśhaḥ","english":"As men approach Me, so do I reward them; all men, in all ways, follow My path, O Arjuna.","hindi":"जो मनुष्य मुझे जिस प्रकार भजते हैं, मैं उनको उसी प्रकार भजता हूँ; क्योंकि हे पार्थ! सब मनुष्य सब प्रकार से मेरे ही मार्ग का अनुसरण करते हैं।","gujarati":"જે માણસો મને જે ભાવથી ભજે છે, તેને હું તે જ રીતે ભજું છું; હે પાર્થ! બધા મનુષ્યો સર્વ પ્રકારે મારા જ માર્ગનું અનુસરણ કરે છે."},"4.12":{"chapter":4,"verse":12,"sloka":"काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः।\n\nक्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा।।4.12।।","transliteration":"kāṅkṣhantaḥ karmaṇāṁ siddhiṁ yajanta iha devatāḥ\nkṣhipraṁ hi mānuṣhe loke siddhir bhavati karmajā","english":"Those who desire success in their undertakings here on earth sacrifice to the gods, for in this human world, results from action are quickly attained.","hindi":"इस मनुष्यलोक में कर्मों के फल की कामना रखने वाले लोग देवताओं का पूजन करते हैं, क्योंकि यहाँ कर्मों से मिलने वाली सिद्धि शीघ्र प्राप्त होती है।","gujarati":"આ મનુષ્યલોકમાં કર્મનાં ફળની ઈચ્છા રાખનારા લોકો દેવતાઓની પૂજા કરે છે, કારણ કે આ લોકમાં કર્મોથી મળતી સફળતા જલ્દી પ્રાપ્ત થાય છે."},"4.13":{"chapter":4,"verse":13,"sloka":"चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः।\n\nतस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम्।।4.13।।","transliteration":"chātur-varṇyaṁ mayā sṛiṣhṭaṁ guṇa-karma-vibhāgaśhaḥ\ntasya kartāram api māṁ viddhyakartāram avyayam","english":"The fourfold social order was created by Me according to the classification of attributes (Guna) and functions (Karma). Although I am the creator of this system, know Me to be the non-doer and eternal/immutable.","hindi":"गुण और कर्मों के विभागानुसार मेरे द्वारा चार वर्णों की रचना की गई है। यद्यपि मैं इसका रचयिता हूँ, तथापि मुझे अकर्ता और अविनाशी जानो।","gujarati":"ગુણ અને કર્મોના વિભાગ અનુસાર મારા દ્વારા ચાર વર્ણોની રચના કરવામાં આવી છે. જેનો હું કર્તા હોવા છતાં, મને અકર્તા અને અવિનાશી જાણો."},"4.14":{"chapter":4,"verse":14,"sloka":"न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा।\n\nइति मां योऽभिजानाति कर्मभिर्न स बध्यते।।4.14।।","transliteration":"na māṁ karmāṇi limpanti na me karma-phale spṛihā\niti māṁ yo ’bhijānāti karmabhir na sa badhyate","english":"Actions do not taint Me, nor do I have any desire for the results of actions. One who recognizes Me in this light is never bound by the reactions of their deeds.","hindi":"कर्म मुझे लिप्त नहीं करते और न ही मुझे कर्मों के फल की कोई आकांक्षा है। जो मुझे इस प्रकार तत्व से जान लेता है, वह भी कर्मों के बन्धनों में नहीं फँसता।","gujarati":"કર્મો મને લેપાયમાન કરતા નથી, તેમ જ મને કર્મોના ફળની સ્પૃહા પણ નથી. જે મને આ રીતે તત્ત્વથી જાણી લે છે, તે પણ કર્મોના બંધનોમાં બંધાતો નથી."},"4.15":{"chapter":4,"verse":15,"sloka":"एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः।\n\nकुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम्।।4.15।।","transliteration":"evaṁ jñātvā kṛitaṁ karma pūrvair api mumukṣhubhiḥ\nkuru karmaiva tasmāttvaṁ pūrvaiḥ pūrvataraṁ kṛitam","english":"Having known this, the seekers of liberation in ancient times also performed their prescribed duties; therefore, you too should perform your actions just as the ancients did in the past.","hindi":"पूर्वकाल के मुमुक्षु पुरुषों ने भी ऐसा जानकर ही कर्म किया है, अतः तुम भी पूर्वजों द्वारा सदा से किए जाने वाले कर्मों का ही पालन करो।","gujarati":"પૂર્વના મુમુક્ષુઓએ પણ આ જાણીને જ કર્મ કર્યા છે; તેથી તું પણ પૂર્વજોએ હંમેશા કરેલા કર્મોને જ કર."},"4.16":{"chapter":4,"verse":16,"sloka":"किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः।\n\nतत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात्।।4.16।।","transliteration":"kiṁ karma kim akarmeti kavayo ’pyatra mohitāḥ\ntat te karma pravakṣhyāmi yaj jñātvā mokṣhyase ’śhubhāt","english":"What is action and what is inaction? Even the wise are perplexed in this matter. I shall explain to you that action, by knowing which you will be delivered from evil.","hindi":"कर्म क्या है और अकर्म क्या है? इस विषय में बुद्धिमान पुरुष भी मोहित हो जाते हैं। इसलिए मैं तुम्हें वह कर्म समझाऊँगा, जिसे जानकर तुम अशुभ से मुक्त हो जाओगे।","gujarati":"કર્મ શું છે અને અકર્મ શું છે? આ વિષયમાં બુદ્ધિશાળી પુરુષો પણ ભ્રમિત થઈ જાય છે. તેથી હું તને તે કર્મનું સ્વરૂપ સમજાવીશ, જેને જાણીને તું અશુભ (સંસારના બંધન) થી મુક્ત થઈ જઈશ."},"4.17":{"chapter":4,"verse":17,"sloka":"कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः।\n\nअकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः।।4.17।।","transliteration":"karmaṇo hyapi boddhavyaṁ boddhavyaṁ cha vikarmaṇaḥ\nakarmaṇaśh cha boddhavyaṁ gahanā karmaṇo gatiḥ","english":"One must understand the nature of prescribed action, the nature of prohibited action, and the nature of inaction; the path of action is indeed difficult to discern.","hindi":"कर्म का स्वरूप जानना चाहिए, विकर्म का स्वरूप भी जानना चाहिए और अकर्म का स्वरूप भी जानना चाहिए; क्योंकि कर्म की गति बहुत गहन है।","gujarati":"કર્મનું સ્વરૂપ જાણવું જોઈએ, વિકર્મનું સ્વરૂપ પણ જાણવું જોઈએ અને અકર્મનું સ્વરૂપ પણ જાણવું જોઈએ; કારણ કે કર્મની ગતિ ખૂબ ગહન છે."},"4.18":{"chapter":4,"verse":18,"sloka":"कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः।\n\nस बुद्धिमान् मनुष्येषु स युक्तः कृत्स्नकर्मकृत्।।4.18।।","transliteration":"karmaṇyakarma yaḥ paśhyed akarmaṇi cha karma yaḥ\nsa buddhimān manuṣhyeṣhu sa yuktaḥ kṛitsna-karma-kṛit","english":"He who perceives inaction in action and action in inaction is wise among men; he is a yogi and performer of all actions.","hindi":"जो कर्म में अकर्म और अकर्म में कर्म देखता है, वह मनुष्यों में बुद्धिमान है; वह योगी है और सभी कर्मों को करने वाला है।","gujarati":"જે મનુષ્ય કર્મમાં અકર્મ અને અકર્મમાં કર્મ જુએ છે, તે મનુષ્યોમાં બુદ્ધિમાન છે; તે યોગી છે અને તમામ કર્મો કરનાર છે."},"4.19":{"chapter":4,"verse":19,"sloka":"यस्य सर्वे समारम्भाः कामसङ्कल्पवर्जिताः।\n\nज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः।।4.19।।","transliteration":"yasya sarve samārambhāḥ kāma-saṅkalpa-varjitāḥ\njñānāgni-dagdha-karmāṇaṁ tam āhuḥ paṇḍitaṁ budhāḥ","english":"One whose undertakings are all free from desire and selfish motives, and whose actions have been consumed by the fire of knowledge, is called a sage by the wise.","hindi":"जिसके समस्त कार्य कामना और संकल्प से रहित हैं, तथा जिसके समस्त कर्म ज्ञानरूप अग्नि के द्वारा भस्म हो गए हैं, ऐसे पुरुष को ज्ञानीजन पण्डित कहते हैं।","gujarati":"જેના બધા કાર્યો કામના અને સંકલ્પથી રહિત છે, અને જેનાં કર્મો જ્ઞાનરૂપી અગ્નિથી ભસ્મીભૂત થઈ ગયાં છે, તેવા પુરુષને જ્ઞાનીઓ પંડિત કહે છે."},"4.20":{"chapter":4,"verse":20,"sloka":"त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः।\n\nकर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः।।4.20।।","transliteration":"tyaktvā karma-phalāsaṅgaṁ nitya-tṛipto nirāśhrayaḥ\nkarmaṇyabhipravṛitto ’pi naiva kiñchit karoti saḥ","english":"Having abandoned attachment to the fruits of the action, ever content, and depending on nothing, he does not perform any action even while being engaged in activity.","hindi":"जो पुरुष कर्मफलों की आसक्ति को त्यागकर सदैव तृप्त रहता है और किसी पर निर्भर नहीं है, वह कर्मों में पूरी तरह संलग्न रहकर भी वास्तव में कुछ नहीं करता है।","gujarati":"જે પુરુષ કર્મફળની આસક્તિને ત્યજીને હંમેશા તૃપ્ત રહે છે અને પરમાત્મા સિવાય બીજા કોઈ આશ્રયની અપેક્ષા રાખતો નથી, તે કર્મમાં પ્રવૃત્ત હોવા છતાં વાસ્તવમાં કંઈ જ કરતો નથી."},"4.21":{"chapter":4,"verse":21,"sloka":"निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः।\n\nशारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम्।।4.21।।","transliteration":"nirāśhīr yata-chittātmā tyakta-sarva-parigrahaḥ\nśhārīraṁ kevalaṁ karma kurvan nāpnoti kilbiṣham","english":"Remaining free from desire, with mind and senses controlled, and having surrendered all attachment to possessions, one who performs actions merely for the body incurs no sin.","hindi":"जिसकी आशाएँ मिट गई हैं, जिसने अपने मन और इंद्रियों को वश में कर लिया है, और जिसने सब प्रकार के संग्रह का त्याग कर दिया है, ऐसा पुरुष केवल शरीर निर्वाह के लिए कर्म करता हुआ पाप को प्राप्त नहीं होता।","gujarati":"જે આશા રહિત છે, જેણે મન અને શરીર પર નિયંત્રણ મેળવ્યું છે, અને જેણે તમામ પરિગ્રહનો ત્યાગ કર્યો છે, તે પુરુષ માત્ર શરીર નિભાવવા માટે કર્મ કરતો હોવાથી પાપને પ્રાપ્ત થતો નથી."},"4.22":{"chapter":4,"verse":22,"sloka":"यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः।\n\nसमः सिद्धावसिद्धौ च कृत्वापि न निबध्यते।।4.22।।","transliteration":"yadṛichchhā-lābha-santuṣhṭo dvandvātīto vimatsaraḥ\nsamaḥ siddhāvasiddhau cha kṛitvāpi na nibadhyate","english":"Content with whatever comes of its own accord, free from duality and envy, steady in both success and failure, such a person acts yet remains unbound by their actions.","hindi":"जो बिना प्रयत्न के स्वतः प्राप्त वस्तु में सन्तुष्ट रहता है, जो सुख-दुःख आदि द्वन्द्वों से ऊपर उठ चुका है, जो ईर्ष्या से मुक्त है और सफलता-असफलता में समान रहता है, ऐसा पुरुष कर्म करता हुआ भी कर्म के बन्धनों में नहीं फँसता।","gujarati":"જે આપમેળે પ્રાપ્ત થયેલ વસ્તુમાં સંતુષ્ટ રહે છે, જે દ્વંદ્વોથી પર અને ઈર્ષ્યાથી મુક્ત છે, જે સફળતા અને નિષ્ફળતામાં સમાન ભાવ રાખે છે, એવો પુરુષ કર્મ કરીને પણ બંધાતો નથી."},"4.23":{"chapter":4,"verse":23,"sloka":"गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः।\n\nयज्ञायाचरतः कर्म समग्रं प्रविलीयते।।4.23।।","transliteration":"gata-saṅgasya muktasya jñānāvasthita-chetasaḥ\nyajñāyācharataḥ karma samagraṁ pravilīyate","english":"The work of a man who is free from attachment, liberated, whose mind is established in self-knowledge, and who acts only as a sacrifice to the Divine, completely dissolves.","hindi":"जो पुरुष आसक्ति से रहित है, मुक्त है, जिसका मन ज्ञान में स्थित है और जो केवल यज्ञ के निमित्त ही कर्म करता है, उसके समस्त कर्म विलीन हो जाते हैं।","gujarati":"જે પુરુષ આસક્તિથી મુક્ત છે, જેનો મન જ્ઞાનમાં સ્થિત છે, અને જે માત્ર યજ્ઞ માટે જ કર્મો કરે છે, તેના તમામ કર્મો વિલીન થઈ જાય છે."},"4.24":{"chapter":4,"verse":24,"sloka":"ब्रह्मार्पणं ब्रह्महविर्ब्रह्माग्नौ ब्रह्मणा हुतम्।\n\nब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना।।4.24।।","transliteration":"brahmārpaṇaṁ brahma havir brahmāgnau brahmaṇā hutam\nbrahmaiva tena gantavyaṁ brahma-karma-samādhinā","english":"Brahman is the offering, Brahman is the oblation poured by Brahman into the fire of Brahman; Brahman is indeed that which is attained by him who always contemplates Brahman in action.","hindi":"ब्रह्म ही अर्पण है, ब्रह्म ही हवि है, ब्रह्मरूप अग्नि में ब्रह्म के द्वारा ही हवि की आहुति दी जाती है। जो पुरुष कर्म में ब्रह्म को ही देखता है, वह ब्रह्म को ही प्राप्त करता है।","gujarati":"બ્રહ્મ અર્પણ છે, બ્રહ્મ જ હવિ છે, બ્રહ્મરૂપી અગ્નિમાં બ્રહ્મ દ્વારા જ આહુતિ અપાય છે. જે પુરુષ કર્મમાં બ્રહ્મનું જ દર્શન કરે છે, તે નિશ્ચિતપણે બ્રહ્મને જ પ્રાપ્ત કરે છે."},"4.25":{"chapter":4,"verse":25,"sloka":"दैवमेवापरे यज्ञं योगिनः पर्युपासते।\n\nब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति।।4.25।।","transliteration":"daivam evāpare yajñaṁ yoginaḥ paryupāsate\nbrahmāgnāvapare yajñaṁ yajñenaivopajuhvati","english":"Some yogis perform sacrifice to the gods alone; others offer the sacrifice of the self into the fire of the Absolute.","hindi":"कुछ योगीजन देवताओं की उपासना रूपी यज्ञ करते हैं, जबकि अन्य ज्ञानीजन स्वयं को ही ब्रह्मरूप अग्नि में आहुति के रूप में समर्पित कर देते हैं।","gujarati":"કેટલાક યોગીઓ દેવતાઓની પૂજા રૂપી યજ્ઞ કરે છે, જ્યારે બીજા જ્ઞાનીઓ આત્માને જ બ્રહ્મરૂપી અગ્નિમાં યજ્ઞ તરીકે અર્પણ કરે છે."},"4.26":{"chapter":4,"verse":26,"sloka":"श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति।\n\nशब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति।।4.26।।","transliteration":"śhrotrādīnīndriyāṇyanye sanyamāgniṣhu juhvati\nśhabdādīn viṣhayānanya indriyāgniṣhu juhvati","english":"Some offer the senses, such as hearing, as a sacrifice into the fire of self-restraint, while others offer the objects of the senses, such as sound, into the fire of the senses.","hindi":"अन्य योगी श्रोत्रादि इंद्रियों को संयम रूपी अग्नि में होम करते हैं, और अन्य लोग शब्दादि विषयों को इंद्रियों रूपी अग्नि में हवन करते हैं।","gujarati":"અન્ય યોગીઓ શ્રોત્રાદિ ઇન્દ્રિયોને સંયમરૂપી અગ્નિમાં હોમ કરે છે, અને બીજા લોકો શબ્દાદિ વિષયોને ઇન્દ્રિયરૂપી અગ્નિમાં યજ્ઞ તરીકે અર્પણ કરે છે."},"4.27":{"chapter":4,"verse":27,"sloka":"सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे।\n\nआत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते।।4.27।।","transliteration":"sarvāṇīndriya-karmāṇi prāṇa-karmāṇi chāpare\nātma-sanyama-yogāgnau juhvati jñāna-dīpite","english":"Others again offer all the functions of the senses and the activities of the life-breath into the fire of the yoga of self-restraint, ignited by knowledge.","hindi":"अन्य योगीजन अपनी समस्त इन्द्रियों की क्रियाओं और प्राणों के व्यापारों को ज्ञान से प्रज्वलित आत्मसंयम रूपी योग-अग्नि में हवन कर देते हैं।","gujarati":"અન્ય યોગીઓ પોતાની તમામ ઇન્દ્રિયોની ક્રિયાઓ અને પ્રાણના વ્યાપારોને જ્ઞાન દ્વારા પ્રજ્વલિત આત્મસંયમરૂપી યોગાગ્નિમાં હોમે છે."},"4.28":{"chapter":4,"verse":28,"sloka":"द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे।\n\nस्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः।।4.28।।","transliteration":"dravya-yajñās tapo-yajñā yoga-yajñās tathāpare\nswādhyāya-jñāna-yajñāśh cha yatayaḥ sanśhita-vratāḥ","english":"Some offer their wealth, others their austerities, and still others their practice of Yoga as sacrifice; while those who observe strict vows and are self-restrained offer the study of the scriptures and the attainment of knowledge as their sacrifice.","hindi":"अन्य लोग द्रव्य-यज्ञ, तप-यज्ञ और योग-यज्ञ करने वाले होते हैं, और दूसरे कठिन व्रतों का पालन करने वाले संयमी साधक स्वाध्याय और ज्ञान-यज्ञ को अपना यज्ञ मानते हैं।","gujarati":"અન્ય લોકો દ્રવ્યરૂપી યજ્ઞ, તપરૂપી યજ્ઞ અને યોગરૂપી યજ્ઞ કરનારા હોય છે; જ્યારે કઠોર વ્રતધારી અને સંયમી મુમુક્ષુઓ સ્વાધ્યાય અને જ્ઞાનરૂપી યજ્ઞ કરે છે."},"4.29":{"chapter":4,"verse":29,"sloka":"अपाने जुह्वति प्राण प्राणेऽपानं तथाऽपरे।\n\nप्राणापानगती रुद्ध्वा प्राणायामपरायणाः।।4.29।।","transliteration":"apāne juhvati prāṇaṁ prāṇe ’pānaṁ tathāpare\nprāṇāpāna-gatī ruddhvā prāṇāyāma-parāyaṇāḥ\n apare niyatāhārāḥ prāṇān prāṇeṣhu juhvati\nsarve ’pyete yajña-vido yajña-kṣhapita-kalmaṣhāḥ","english":"Others offer the outgoing breath into the incoming, and the incoming into the outgoing, by restraining the flow of both, solely absorbed in the practice of breath control.","hindi":"अन्य योगी अपान वायु में प्राण वायु को हवन करते हैं, और प्राण वायु में अपान की आहुति देते हैं; वे प्राण और अपान की गति को रोककर, प्राणायाम परायण हो जाते हैं।","gujarati":"અન્ય યોગીઓ અપાન વાયુમાં પ્રાણ વાયુને અર્પણ કરે છે, અને પ્રાણ વાયુમાં અપાનની આહુતિ આપે છે; આમ તેઓ પ્રાણ અને અપાનની ગતિને રોકીને પ્રાણાયામના પરાયણ બને છે."},"4.30":{"chapter":4,"verse":30,"sloka":"अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति।\n\nसर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः।।4.30।।","transliteration":"apare niyatāhārāḥ prāṇān  prāṇeṣu juhvati\n\nsarve py 'ete yajña-vido yajña-kṣapita-kalmaṣāḥ","english":"Others who regulate their diet offer their life-breaths into the life-breaths as a sacrifice. All these knowers of sacrifice have their impurities cleansed by the performance of such acts.","hindi":"अन्य नियमित आहार करने वाले साधक अपने प्राणों को प्राणों में ही हवन करते हैं। ये सभी यज्ञ को जानने वाले हैं, जिनके पाप यज्ञ के अनुष्ठान से नष्ट हो जाते हैं।","gujarati":"અન્ય નિયમિત આહાર કરનારા સાધકો પોતાના પ્રાણોને પ્રાણોમાં જ હોમે છે. આ તમામ યજ્ઞને જાણનારા છે, જેમના પાપ યજ્ઞ દ્વારા નષ્ટ થઈ ગયા છે."},"4.31":{"chapter":4,"verse":31,"sloka":"यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम्।\n\nनायं लोकोऽस्त्ययज्ञस्य कुतो़ऽन्यः कुरुसत्तम।।4.31।।","transliteration":"yajña-śhiṣhṭāmṛita-bhujo yānti brahma sanātanam\nnāyaṁ loko ’styayajñasya kuto ’nyaḥ kuru-sattama","english":"Those who live on the nectar of the remains of sacrifice attain the eternal Brahman. This world is not for the one who does not sacrifice; how then can they have the other, O Arjuna?","hindi":"हे कुरुश्रेष्ठ! यज्ञ से बचे हुए अमृत रूपी अन्न को ग्रहण करने वाले योगी सनातन ब्रह्म को प्राप्त होते हैं। यज्ञ न करने वाले पुरुष के लिए यह लोक भी सुखदायक नहीं है, फिर परलोक तो उनके लिए दूर की बात है।","gujarati":"હે કુરુશ્રેષ્ઠ! યજ્ઞથી બચેલા અમૃતરૂપી અન્નનો આહાર કરનારાઓ સનાતન બ્રહ્મને પામે છે. યજ્ઞ ન કરનારા પુરુષને આ લોક પણ પ્રાપ્ત થતો નથી, તો પછી પરલોક કેવી રીતે મળે?"},"4.32":{"chapter":4,"verse":32,"sloka":"एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे।\n\nकर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे।।4.32।।","transliteration":"evaṁ bahu-vidhā yajñā vitatā brahmaṇo mukhe\nkarma-jān viddhi tān sarvān evaṁ jñātvā vimokṣhyase","english":"Thus, manifold sacrifices are described in the Vedas. Know them all to be born of action, and by knowing this, you shall be liberated.","hindi":"इस प्रकार अनेक प्रकार के यज्ञ वेदों में विस्तार से कहे गए हैं। उन सबको तुम कर्मजनित समझो; ऐसा जानकर तुम (कर्म-बंधन से) मुक्त हो जाओगे।","gujarati":"આમ, અનેક પ્રકારના યજ્ઞો વેદોમાં વિસ્તારપૂર્વક વર્ણવેલા છે. તે સૌને કર્મથી ઉત્પન્ન થયેલા જાણો; આ રીતે જાણીને તમે મુક્ત થઈ જશો."},"4.33":{"chapter":4,"verse":33,"sloka":"श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप।\n\nसर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते।।4.33।।","transliteration":"śhreyān dravya-mayād yajñāj jñāna-yajñaḥ parantapa\nsarvaṁ karmākhilaṁ pārtha jñāne parisamāpyate","english":"O Parantapa, knowledge-sacrifice is superior to sacrifice involving material objects. O Arjuna, all actions in their entirety culminate in wisdom.","hindi":"हे परंतप! द्रव्यमय यज्ञ की अपेक्षा ज्ञानयज्ञ अत्यंत श्रेष्ठ है। हे अर्जुन! समस्त कर्म समग्र रूप से ज्ञान में ही विलीन हो जाते हैं।","gujarati":"હે પરંતપ અર્જુન! દ્રવ્યમય યજ્ઞ કરતા જ્ઞાનયજ્ઞ ઘણો શ્રેષ્ઠ છે. કારણ કે, સંપૂર્ણ કર્મ માત્ર જ્ઞાનમાં જ સમાપ્ત થઈ જાય છે."},"4.34":{"chapter":4,"verse":34,"sloka":"तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया।\n\nउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः।।4.34।।","transliteration":"tad viddhi praṇipātena paripraśhnena sevayā\nupadekṣhyanti te jñānaṁ jñāninas tattva-darśhinaḥ","english":"Learn this knowledge by approaching a realized soul, offering humble prostrations, inquiring with sincerity, and serving with devotion; such enlightened beings, who have perceived the truth, will impart knowledge unto you.","hindi":"तत्वदर्शी ज्ञानियों के पास जाकर उन्हें साष्टांग प्रणाम करो, उनसे जिज्ञासा करो और उनकी सेवा करो; वे ज्ञानी पुरुष तुम्हें उस ज्ञान का उपदेश देंगे।","gujarati":"તે જ્ઞાનને તત્ત્વજ્ઞાનીઓ પાસે જઈને સાષ્ટાંગ પ્રણામ, પ્રશ્નોત્તરી અને સેવા દ્વારા જાણો; એ જ્ઞાનીઓ તમને એ સત્યનો ઉપદેશ આપશે."},"4.35":{"chapter":4,"verse":35,"sloka":"यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव।\n\nयेन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि।।4.35।।","transliteration":"yaj jñātvā na punar moham evaṁ yāsyasi pāṇḍava\nyena bhūtānyaśheṣheṇa drakṣhyasyātmanyatho mayi","english":"Having known this, O Arjuna, you will no longer fall into delusion; by this knowledge, you will see all living beings in your own self, and then in Me.","hindi":"जिस ज्ञान को जानकर तुम फिर कभी इस प्रकार मोहग्रस्त नहीं होगे, और हे अर्जुन! उस ज्ञान के द्वारा तुम संपूर्ण प्राणियों को अपने भीतर और फिर मुझे देख सकोगे।","gujarati":"જેને જાણીને તું ફરી ક્યારેય આ રીતે મોહિત નહીં થાય, અને હે અર્જુન! તે જ્ઞાન દ્વારા તું સર્વ ભૂતમાત્રને તારામાં અને ત્યારબાદ મારામાં જોઈશ."},"4.36":{"chapter":4,"verse":36,"sloka":"अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः।\n\nसर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि।।4.36।।","transliteration":"api ched asi pāpebhyaḥ sarvebhyaḥ pāpa-kṛit-tamaḥ\nsarvaṁ jñāna-plavenaiva vṛijinaṁ santariṣhyasi","english":"Even if you are the most sinful of all sinners, you shall cross over all sin by the raft of knowledge alone.","hindi":"यदि तुम सब पापियों से भी अधिक पाप करने वाले हो, तो भी ज्ञानरूपी नौका द्वारा तुम निश्चय ही सम्पूर्ण पापों से पार हो जाओगे।","gujarati":"જો તું સર્વ પાપીઓમાં પણ અતિશય પાપી હો, તો પણ તું જ્ઞાનરૂપી નૌકા દ્વારા જ નિશ્ચયપૂર્વક સર્વ પાપોથી તરી જઈશ."},"4.37":{"chapter":4,"verse":37,"sloka":"यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन।\n\nज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा।।4.37।।","transliteration":"yathaidhānsi samiddho ’gnir bhasma-sāt kurute ’rjuna\njñānāgniḥ sarva-karmāṇi bhasma-sāt kurute tathā","english":"Just as a blazing fire turns firewood into ashes, O Arjuna, the fire of knowledge likewise reduces all karmic reactions to ashes.","hindi":"जैसे प्रज्वलित अग्नि ईंधन को भस्म कर देती है, वैसे ही हे अर्जुन, ज्ञानरूपी अग्नि समस्त कर्मों को भस्म कर देती है।","gujarati":"જેમ પ્રજ્વલિત અગ્નિ લાકડાને ભસ્મીભૂત કરી નાખે છે, તેમ હે અર્જુન, જ્ઞાનરૂપી અગ્નિ બધા જ કર્મોને ભસ્મ કરી નાખે છે."},"4.38":{"chapter":4,"verse":38,"sloka":"न हि ज्ञानेन सदृशं पवित्रमिह विद्यते।\n\nतत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति।।4.38।।","transliteration":"na hi jñānena sadṛiśhaṁ pavitramiha vidyate\ntatsvayaṁ yogasansiddhaḥ kālenātmani vindati","english":"Verily, there is nothing in this world as purifying as knowledge; one who has attained perfection in Yoga finds it within the Self in due course of time.","hindi":"इस संसार में ज्ञान के समान पवित्र करने वाला निस्संदेह कुछ भी नहीं है। जो मनुष्य योग में संसिद्ध (परिपूर्ण) हो जाता है, वह समय आने पर स्वयं ही इस ज्ञान को अपने भीतर (आत्मा में) अनुभव कर लेता है।","gujarati":"આ જગતમાં જ્ઞાન જેવું પવિત્ર બીજું કંઈ નથી. જે યોગમાં સિદ્ધિ પ્રાપ્ત કરી લે છે, તે યોગ્ય સમયે તેને પોતાની અંદર જ પ્રાપ્ત કરી લે છે."},"4.39":{"chapter":4,"verse":39,"sloka":"श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः।\n\nज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति।।4.39।।","transliteration":"śhraddhāvān labhate jñānaṁ tat-paraḥ sanyatendriyaḥ\njñānaṁ labdhvā parāṁ śhāntim achireṇādhigachchhati","english":"The person of faith, who is dedicated to knowledge and has mastered their senses, attains wisdom; having attained this wisdom, they swiftly achieve supreme peace.","hindi":"श्रद्धावान, तत्पर और जीतेन्द्रिय मनुष्य ज्ञान प्राप्त करता है; ज्ञान प्राप्त करके वह शीघ्र ही परम शान्ति को प्राप्त कर लेता है।","gujarati":"શ્રદ્ધાવાન, જ્ઞાનમાં તત્પર અને ઇન્દ્રિયોને વશ કરનાર મનુષ્ય જ્ઞાન પ્રાપ્ત કરે છે; તે જ્ઞાન પ્રાપ્ત કરીને તે તરત જ પરમ શાંતિને પામે છે."},"4.40":{"chapter":4,"verse":40,"sloka":"अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति।\n\nनायं लोकोऽस्ति न परो न सुखं संशयात्मनः।।4.40।।","transliteration":"ajñaśh chāśhraddadhānaśh cha sanśhayātmā vinaśhyati\nnāyaṁ loko ’sti na paro na sukhaṁ sanśhayātmanaḥ","english":"But the ignorant, the faithless, and the doubting self perish; for the soul filled with doubt, there is neither this world, nor the world beyond, nor happiness.","hindi":"किन्तु विवेकहीन, श्रद्धारहित और संशययुक्त मनुष्य का पतन हो जाता है; संशयी आत्मा के लिए न यह लोक है, न परलोक और न ही कोई सुख।","gujarati":"પરંતુ જે અજ્ઞાની છે, શ્રદ્ધાહીન છે અને સંશયથી ભરેલો છે, તેનો વિનાશ થાય છે; સંશયી મનુષ્ય માટે ન તો આ લોક છે, ન પરલોક, કે ન કોઈ સુખ."},"4.41":{"chapter":4,"verse":41,"sloka":"योगसंन्यस्तकर्माणं ज्ञानसंछिन्नसंशयम्।\n\nआत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय।।4.41।।","transliteration":"yoga-sannyasta-karmāṇaṁ jñāna-sañchhinna-sanśhayam\nātmavantaṁ na karmāṇi nibadhnanti dhanañjaya","english":"He who has renounced actions through Yoga, whose doubts have been dispelled by knowledge, and who is self-possessed—such a one is not bound by actions, O Arjuna.","hindi":"जिसने योग द्वारा कर्मों का संन्यास कर दिया है, ज्ञान के द्वारा जिसके समस्त संशय नष्ट हो गए हैं और जो आत्म-स्थित है, हे धनंजय, ऐसे पुरुष को कर्म कभी नहीं बांधते।","gujarati":"જેણે યોગ દ્વારા કર્મોનો ત્યાગ કર્યો છે, જ્ઞાન દ્વારા જેના તમામ સંશયો નાશ પામ્યા છે અને જે આત્મસ્થ છે, તેવા પુરુષને કર્મો બાંધતા નથી, હે ધનંજય."},"4.42":{"chapter":4,"verse":42,"sloka":"तस्मादज्ञानसंभूतं हृत्स्थं ज्ञानासिनाऽऽत्मनः।\n\nछित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत।।4.42।।","transliteration":"tasmād ajñāna-sambhūtaṁ hṛit-sthaṁ jñānāsinātmanaḥ\nchhittvainaṁ sanśhayaṁ yogam ātiṣhṭhottiṣhṭha bhārata","english":"Therefore, having cut asunder the doubt in your heart born of ignorance with the sword of knowledge, establish yourself in Yoga. Arise, O Bharata!","hindi":"इसलिए, अपने हृदय में स्थित अज्ञानजनित संशय को ज्ञानरूपी तलवार से काटकर, हे भरतवंशी! योग में स्थित होकर उठ खड़े हो।","gujarati":"તેથી, તારા હૃદયમાં રહેલા અજ્ઞાનથી ઉત્પન્ન થયેલા આત્મવિષયક સંશયને જ્ઞાનરૂપી તલવારથી કાપી નાખ અને યોગનો આશ્રય લઈને ઊભો થા, હે ભારત!"},"5.1":{"chapter":5,"verse":1,"sloka":"अर्जुन उवाच\n\nसंन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि।\n\nयच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्िचतम्।।5.1।।","transliteration":"arjuna uvācha\nsannyāsaṁ karmaṇāṁ kṛiṣhṇa punar yogaṁ cha śhansasi\nyach chhreya etayor ekaṁ tan me brūhi su-niśhchitam","english":"Arjuna said: O Krishna, You speak of the renunciation of actions, and yet again of selfless service (Karma Yoga). Tell me decisively which of these two is superior.","hindi":"अर्जुन ने कहा: हे कृष्ण! आप कभी कर्मों के त्याग (संन्यास) की प्रशंसा करते हैं और कभी निष्काम कर्मयोग की। इन दोनों में से जो एक निश्चित रूप से श्रेष्ठ हो, वह मुझे बताइए।","gujarati":"અર્જુને કહ્યું: હે કૃષ્ણ! તમે કર્મોના સન્યાસની અને ફરીથી કર્મયોગની પ્રશંસા કરો છો. આ બંનેમાંથી જે એક નિશ્ચિતપણે શ્રેષ્ઠ હોય તે મને કહો."},"5.2":{"chapter":5,"verse":2,"sloka":"श्री भगवानुवाच\n\nसंन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ।\n\nतयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते।।5.2।।","transliteration":"śhrī bhagavān uvācha\nsannyāsaḥ karma-yogaśh cha niḥśhreyasa-karāvubhau\ntayos tu karma-sannyāsāt karma-yogo viśhiṣhyate","english":"The Blessed Lord said: Renunciation of action and Karma Yoga both lead to the highest bliss; but of the two, the Yoga of action is superior to the renunciation of action.","hindi":"श्रीभगवान् बोले: कर्मसंन्यास और कर्मयोग—ये दोनों ही परम कल्याण करने वाले हैं, परन्तु इन दोनों में भी कर्मसंन्यास की अपेक्षा कर्मयोग श्रेष्ठ है।","gujarati":"શ્રી ભગવાન બોલ્યા: કર્મસંન્યાસ અને કર્મયોગ એ બંને પરમ કલ્યાણ કરનારા છે; પરંતુ એ બંનેમાં કર્મસંન્યાસ કરતા કર્મયોગ શ્રેષ્ઠ છે."},"5.3":{"chapter":5,"verse":3,"sloka":"ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति।\n\nनिर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते।।5.3।।","transliteration":"jñeyaḥ sa nitya-sannyāsī yo na dveṣhṭi na kāṅkṣhati\nnirdvandvo hi mahā-bāho sukhaṁ bandhāt pramuchyate","english":"One who neither hates nor desires should be known as a perpetual renunciant; for, free from the pairs of opposites, O mighty-armed one, he is easily liberated from worldly bondage.","hindi":"जो पुरुष न किसी से द्वेष करता है और न किसी वस्तु की आकांक्षा करता है, उसे सदा संन्यासी ही समझना चाहिए। हे महाबाहो! द्वंद्वों से मुक्त हुआ मनुष्य सहज ही संसार के बंधनों से मुक्त हो जाता है।","gujarati":"જે પુરુષ કોઈની સાથે દ્વેષ કરતો નથી અને કોઈની આકાંક્ષા પણ રાખતો નથી, તે સદા સન્યાસી જ છે એમ જાણવો; હે મહાબાહુ! દ્વંદ્વોથી રહિત મનુષ્ય સરળતાથી બંધનમાંથી મુક્ત થઈ જાય છે."},"5.4":{"chapter":5,"verse":4,"sloka":"सांख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः।\n\nएकमप्यास्थितः सम्यगुभयोर्विन्दते फलम्।।5.4।।","transliteration":"sānkhya-yogau pṛithag bālāḥ pravadanti na paṇḍitāḥ\nekamapyāsthitaḥ samyag ubhayor vindate phalam","english":"Only the unwise speak of knowledge (Sankhya) and the yoga of action (Karma Yoga) as being distinct; the wise know that they are one. He who is truly established in either path attains the fruit of both.","hindi":"केवल अज्ञानी ही सांख्य योग (ज्ञानयोग) और कर्मयोग को अलग-अलग मानते हैं, ज्ञानी पुरुष ऐसा नहीं मानते। जो व्यक्ति किसी एक मार्ग का भी सम्यक् प्रकार से अनुसरण करता है, वह दोनों के फल को प्राप्त कर लेता है।","gujarati":"માત્ર અજ્ઞાનીઓ જ જ્ઞાનમાર્ગ (સાંખ્ય) અને કર્મયોગને અલગ-અલગ ગણે છે, જ્ઞાનીઓ નહીં. જે કોઈ પણ એક માર્ગમાં સાચી રીતે સ્થિત થાય છે, તે બંનેના ફળને પ્રાપ્ત કરે છે."},"5.5":{"chapter":5,"verse":5,"sloka":"यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते।\n\nएकं सांख्यं च योगं च यः पश्यति स पश्यति।।5.5।।","transliteration":"yat sānkhyaiḥ prāpyate sthānaṁ tad yogair api gamyate\nekaṁ sānkhyaṁ cha yogaṁ cha yaḥ paśhyati sa paśhyati","english":"The state attained by the Jnanis is also attained by the Karma Yogis. He who sees Knowledge and Karma Yoga as one, truly sees.","hindi":"ज्ञानियों द्वारा जो स्थान प्राप्त किया जाता है, कर्मयोगियों को भी वही प्राप्त होता है। जो पुरुष सांख्य (ज्ञान) और निष्काम कर्मयोग को फल के रूप में एक ही देखता है, वही वास्तव में सत्य को देखता है।","gujarati":"જ્ઞાનીઓ દ્વારા જે સ્થાન પ્રાપ્ત થાય છે, તે જ સ્થાન કર્મયોગીઓને પણ પ્રાપ્ત થાય છે. જે પુરુષ જ્ઞાન અને કર્મયોગને એક જ ફળ આપનારા જુએ છે, તે જ વાસ્તવમાં સાચું જુએ છે."},"5.6":{"chapter":5,"verse":6,"sloka":"संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः।\n\nयोगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति।।5.6।।","transliteration":"sannyāsas tu mahā-bāho duḥkham āptum ayogataḥ\nyoga-yukto munir brahma na chireṇādhigachchhati","english":"But renunciation, O mighty-armed one, is difficult to attain without Karma Yoga; the sage who is steadfast in Yoga quickly attains the Supreme Brahman.","hindi":"परंतु हे अर्जुन! कर्मयोग के बिना संन्यास प्राप्त करना कठिन है; योगयुक्त मुनि शीघ्र ही ब्रह्म को प्राप्त कर लेता है।","gujarati":"પરંતુ હે મહાબાહુ અર્જુન, નિષ્કામ કર્મયોગ વિના સંન્યાસ પ્રાપ્ત કરવો કઠિન છે; જે મુનિ યોગયુક્ત છે તે શીઘ્ર જ પરમાત્માને પ્રાપ્ત કરે છે."},"5.7":{"chapter":5,"verse":7,"sloka":"योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः।\n\nसर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते।।5.7।।","transliteration":"yoga-yukto viśhuddhātmā vijitātmā jitendriyaḥ\nsarva-bhūtātma-bhūtātmā kurvann api na lipyate","english":"He who is engaged in the path of selfless action, whose mind is pure, who has conquered his senses and self, and who sees his own Self in all beings, is never bound by his actions, even while performing them.","hindi":"जो कर्मयोग में स्थित है, जिसका मन शुद्ध है, जिसने स्वयं को जीत लिया है, जिसने इन्द्रियों को वश में कर लिया है और जो समस्त प्राणियों में अपनी ही आत्मा को देखता है, ऐसा पुरुष कर्म करते हुए भी उनमें लिप्त नहीं होता।","gujarati":"જે કર્મયોગમાં સ્થિત છે, જેનું અંતઃકરણ શુદ્ધ છે, જેણે પોતાના મન અને ઇન્દ્રિયોને વશ કર્યા છે અને જે તમામ પ્રાણીઓમાં એક જ આત્માનું દર્શન કરે છે, તે પુરુષ કર્મ કરતા છતાં પણ તેમાં લિપ્ત થતો નથી."},"5.8":{"chapter":5,"verse":8,"sloka":"नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित्।\n\nपश्यन् श्रृणवन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपन् श्वसन्।।5.8।।","transliteration":"naiva kiñchit karomīti yukto manyeta tattva-vit\npaśhyañ śhṛiṇvan spṛiśhañjighrann aśhnangachchhan svapañśhvasan\n pralapan visṛijan gṛihṇann unmiṣhan nimiṣhann api\nindriyāṇīndriyārtheṣhu vartanta iti dhārayan","english":"The person who knows the Truth, though engaged in seeing, hearing, touching, smelling, eating, moving, sleeping, or breathing, remains established in the conviction that he does nothing at all.","hindi":"तत्त्वज्ञानी पुरुष देखते, सुनते, स्पर्श करते, सूंघते, भोजन करते, चलते, सोते और श्वास लेते हुए भी यही मानता है कि मैं कुछ भी नहीं करता हूँ।","gujarati":"તત્વજ્ઞાની પુરુષ જોતો, સાંભળતો, સ્પર્શતો, સુંઘતો, ખાતો, ચાલતો, સૂતો કે શ્વાસ લેતો હોવા છતાં, તે દ્રઢપણે જાણે છે કે હું કંઈ જ કરતો નથી."},"5.9":{"chapter":5,"verse":9,"sloka":"प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि।\n\nइन्द्रियाणीन्द्रियार्थेषु वर्तन्त इति धारयन्।।5.9।।","transliteration":"pralapan visṛjan gṛhṇann unmiṣan nimiṣann api indriyāṇīndriyārtheṣu vartanta iti dhārayan","english":"While speaking, releasing, grasping, opening and closing the eyes, one should realize that it is merely the senses acting upon the objects of the senses.","hindi":"बोलते हुए, त्यागते हुए, ग्रहण करते हुए, आँखें खोलते और बंद करते हुए भी, योगी यह समझता है कि केवल इन्द्रियाँ ही अपने विषयों में विचरण कर रही हैं।","gujarati":"બોલતા, ત્યાગતા, ગ્રહણ કરતા અને આંખો ખોલતા કે મીંચતા પણ, તે એવું જ માને છે કે માત્ર ઇન્દ્રિયો જ પોતાના વિષયોમાં વિચરણ કરી રહી છે."},"5.10":{"chapter":5,"verse":10,"sloka":"ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः।\n\nलिप्यते न स पापेन पद्मपत्रमिवाम्भसा।।5.10।।","transliteration":"brahmaṇyādhāya karmāṇi saṅgaṁ tyaktvā karoti yaḥ\nlipyate na sa pāpena padma-patram ivāmbhasā","english":"One who performs his duty without attachment, surrendering the results unto the Supreme Lord, is untouched by sinful reactions, just as a lotus leaf remains dry even while in the water.","hindi":"जो मनुष्य समस्त कर्मों को ब्रह्म में समर्पित करके और आसक्ति को त्यागकर कर्म करता है, वह पाप से वैसे ही लिप्त नहीं होता, जैसे कमल का पत्ता जल में रहकर भी जल से नहीं भीगता।","gujarati":"જે પુરુષ બધા કર્મોને બ્રહ્મમાં અર્પણ કરીને અને આસક્તિનો ત્યાગ કરીને કાર્ય કરે છે, તે પાપથી એવી રીતે અલિપ્ત રહે છે, જેમ કમળનું પાંદડું જળમાં રહીને પણ જળથી ભીંજાતું નથી."},"5.11":{"chapter":5,"verse":11,"sloka":"कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि।\n\nयोगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वाऽऽत्मशुद्धये।।5.11।।","transliteration":"kāyena manasā buddhyā kevalair indriyair api\nyoginaḥ karma kurvanti saṅgaṁ tyaktvātma-śhuddhaye","english":"Yogis, having abandoned attachment, perform actions only through the body, mind, intellect, and senses, for the purification of the self.","hindi":"योगीजन शरीर, मन, बुद्धि और इन्द्रियों द्वारा आसक्ति को त्यागकर केवल आत्मशुद्धि के लिए कर्म करते हैं।","gujarati":"યોગીઓ આસક્તિનો ત્યાગ કરીને, શરીર, મન, બુદ્ધિ અને ઇન્દ્રિયો દ્વારા માત્ર આત્મશુદ્ધિ માટે જ કર્મ કરે છે."},"5.12":{"chapter":5,"verse":12,"sloka":"युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम्।\n\nअयुक्तः कामकारेण फले सक्तो निबध्यते।।5.12।।","transliteration":"yuktaḥ karma-phalaṁ tyaktvā śhāntim āpnoti naiṣhṭhikīm\nayuktaḥ kāma-kāreṇa phale sakto nibadhyate","english":"The person who is established in yoga, having abandoned the fruits of action, attains everlasting peace; whereas the person who is not established in yoga, being attached to the fruits of action and driven by desire, becomes bound.","hindi":"युक्त पुरुष कर्मों के फल का त्याग करके नैष्ठिकी शान्ति को प्राप्त होता है, किन्तु जो अयुक्त पुरुष है, वह कामना के वशीभूत होकर फल में आसक्त रहने के कारण बँध जाता है।","gujarati":"યોગયુક્ત પુરુષ કર્મફળનો ત્યાગ કરીને પરમ શાંતિ પામે છે; પરંતુ જે અયુક્ત (અસ્થિર) પુરુષ છે, તે કામનાથી પ્રેરાઈને ફળમાં આસક્ત થવાથી બંધાઈ જાય છે."},"5.13":{"chapter":5,"verse":13,"sloka":"सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी।\n\nनवद्वारे पुरे देही नैव कुर्वन्न कारयन्।।5.13।।","transliteration":"sarva-karmāṇi manasā sannyasyāste sukhaṁ vaśhī\nnava-dvāre pure dehī naiva kurvan na kārayan","english":"Mentally renouncing all actions and self-controlled, the embodied soul dwells happily in the city of nine gates, neither acting nor causing action.","hindi":"सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी। नवद्वारे पुरे देही नैव कुर्वन्न कारयन्।।","gujarati":"સર્વ કર્મોનો મનથી ત્યાગ કરીને, સંયમી પુરુષ નવ દ્વારવાળા આ શરીરમાં સુખપૂર્વક રહે છે, તે પોતે કંઈ કરતો નથી અને કરાવતો પણ નથી."},"5.14":{"chapter":5,"verse":14,"sloka":"न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः।\n\nन कर्मफलसंयोगं स्वभावस्तु प्रवर्तते।।5.14।।","transliteration":"na kartṛitvaṁ na karmāṇi lokasya sṛijati prabhuḥ\nna karma-phala-saṅyogaṁ svabhāvas tu pravartate","english":"The Lord does not create the sense of doership, nor actions, nor the connection between actions and their fruits; rather, it is Nature (Prakriti) that performs these functions.","hindi":"परमेश्वर न तो लोगों के लिए कर्तृत्व की रचना करते हैं, न कर्मों की, और न ही कर्मों के फल के संयोग की; यह सब तो स्वभाव (प्रकृति) द्वारा ही किया जाता है।","gujarati":"પરમેશ્વર લોકો માટે ન તો કર્તૃત્વની, ન કર્મોની, અને ન તો કર્મફળના સંયોગની રચના કરે છે, પરંતુ પ્રકૃતિ જ આ બધું કરે છે."},"5.15":{"chapter":5,"verse":15,"sloka":"नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः।\n\nअज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः।।5.15।।","transliteration":"nādatte kasyachit pāpaṁ na chaiva sukṛitaṁ vibhuḥ\najñānenāvṛitaṁ jñānaṁ tena muhyanti jantavaḥ","english":"The Supreme Lord neither accepts anyone's sin nor their merit; knowledge is enveloped by ignorance, and thus all beings are deluded.","hindi":"परमेश्वर न किसी के पाप को और न किसी के पुण्य को ही स्वीकार करते हैं; ज्ञान अज्ञान से ढका हुआ है, इसी कारण सब जीव भ्रमित हैं।","gujarati":"પરમાત્મા કોઈના પાપ કે પુણ્યને ગ્રહણ કરતા નથી; અજ્ઞાનથી જ્ઞાન ઢંકાયેલું હોવાથી જીવો મોહિત થાય છે."},"5.16":{"chapter":5,"verse":16,"sloka":"ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः।\n\nतेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम्।।5.16।।","transliteration":"jñānena tu tad ajñānaṁ yeṣhāṁ nāśhitam ātmanaḥ\nteṣhām āditya-vaj jñānaṁ prakāśhayati tat param","english":"But for those whose ignorance is destroyed by the knowledge of the Self, that knowledge, like the sun, reveals the Supreme Brahman.","hindi":"परन्तु जिनका वह अज्ञान आत्मज्ञान के द्वारा नष्ट हो जाता है, उनके लिए वह ज्ञान सूर्य के समान उस परमात्मा को प्रकाशित कर देता है।","gujarati":"પરંતુ જેમનું અજ્ઞાન આત્મજ્ઞાન દ્વારા નષ્ટ થઈ ગયું છે, તેમના માટે તે જ્ઞાન સૂર્યની જેમ પરમાત્માને પ્રકાશિત કરે છે."},"5.17":{"chapter":5,"verse":17,"sloka":"तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः।\n\nगच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः।।5.17।।","transliteration":"tad-buddhayas tad-ātmānas tan-niṣhṭhās tat-parāyaṇāḥ\ngachchhantyapunar-āvṛittiṁ jñāna-nirdhūta-kalmaṣhāḥ","english":"Those whose intellect is absorbed in That, whose self is identified with That, who are steadfast in That, and for whom That is the supreme goal, they attain the state of no return, their sins cleansed by the power of knowledge.","hindi":"जिनकी बुद्धि उस परमात्मा में लीन है, जिनका मन उसी तद्रूप हो गया है, जिनकी निष्ठा उसी में है और जो उसी को परम लक्ष्य मानते हैं, वे ज्ञान द्वारा पापमुक्त होकर अपुनरावृत्ति (मोक्ष) को प्राप्त होते हैं।","gujarati":"જેમની બુદ્ધિ તે પરમાત્મામાં લીન છે, જેમનું મન તે તદ્રૂપ થઈ ગયું છે, જેઓ તેમાં જ સ્થિર છે અને જેઓ તેને જ પરમ લક્ષ્ય માને છે, તેઓ જ્ઞાન દ્વારા પાપમુક્ત થઈને અપુનરાવૃત્તિ (મોક્ષ) ને પ્રાપ્ત થાય છે."},"5.18":{"chapter":5,"verse":18,"sloka":"विद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि।\n\nशुनि चैव श्वपाके च पण्डिताः समदर्शिनः।।5.18।।","transliteration":"vidyā-vinaya-sampanne brāhmaṇe gavi hastini\nśhuni chaiva śhva-pāke cha paṇḍitāḥ sama-darśhinaḥ","english":"The humble sages, through the lens of true knowledge, perceive the same divine essence in a learned and gentle brahmana, a cow, an elephant, a dog, and a dog-eater alike.","hindi":"ज्ञान और विनम्रता से युक्त ब्राह्मण, गाय, हाथी, कुत्ते और चाण्डाल में भी पण्डितजन समभाव से देखते हैं।","gujarati":"જ્ઞાન અને વિનયથી સંપન્ન બ્રાહ્મણ, ગાય, હાથી, કૂતરો અને ચાંડાલમાં પણ જ્ઞાનીઓ સમાન દ્રષ્ટિ રાખે છે."},"5.19":{"chapter":5,"verse":19,"sloka":"इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः।\n\nनिर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः।।5.19।।","transliteration":"ihaiva tair jitaḥ sargo yeṣhāṁ sāmye sthitaṁ manaḥ\nnirdoṣhaṁ hi samaṁ brahma tasmād brahmaṇi te sthitāḥ","english":"Even here in this world, those whose minds are established in equanimity have conquered the cycle of birth and death; for Brahman is flawless and impartial, and thus they are established in Brahman.","hindi":"जिनका मन समत्व-भाव में स्थित है, उन्होंने जीवित रहते हुए ही संसार को जीत लिया है; क्योंकि ब्रह्म निर्दोष और सम है, इसलिए वे ब्रह्म में ही स्थित हैं।","gujarati":"જેમનું મન સમત્વમાં સ્થિત છે, તેમણે આ સંસારને અહીં જ જીતી લીધો છે; કારણ કે બ્રહ્મ નિર્દોષ અને સમ છે, તેથી તેઓ બ્રહ્મમાં જ સ્થિત છે."},"5.20":{"chapter":5,"verse":20,"sloka":"न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम्।\n\nस्थिरबुद्धिरसम्मूढो ब्रह्मविद्ब्रह्मणि स्थितः।।5.20।।","transliteration":"na prahṛiṣhyet priyaṁ prāpya nodvijet prāpya chāpriyam\nsthira-buddhir asammūḍho brahma-vid brahmaṇi sthitaḥ","english":"Resting in Brahman, with a steady intellect and undeluded, the knower of Brahman neither rejoices upon obtaining what is pleasant nor grieves upon obtaining what is unpleasant.","hindi":"जो स्थिर बुद्धि वाला, संशयरहित और ब्रह्मज्ञानी है, वह प्रिय वस्तु को पाकर न तो हर्षित होता है और न ही अप्रिय वस्तु के मिलने पर दुखी होता है, क्योंकि वह निरंतर ब्रह्म में स्थित है।","gujarati":"જે સ્થિર બુદ્ધિવાળો, મોહરહિત અને બ્રહ્મવેત્તા છે, તે પ્રિય વસ્તુને પામીને હર્ષ પામતો નથી અને અપ્રિય વસ્તુને પામીને ઉદ્વિગ્ન થતો નથી, કારણ કે તે બ્રહ્મમાં સ્થિત છે."},"5.21":{"chapter":5,"verse":21,"sloka":"बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम्।\n\nस ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते।।5.21।।","transliteration":"bāhya-sparśheṣhvasaktātmā vindatyātmani yat sukham\nsa brahma-yoga-yuktātmā sukham akṣhayam aśhnute","english":"One whose mind is unattached to external sense objects finds the joy that resides within the Self; being united with the Divine through meditation, he experiences unending happiness.","hindi":"बाह्य विषयों में आसक्तिरहित अन्तःकरण वाला पुरुष आत्मा में ही सुख का अनुभव करता है; ब्रह्म के ध्यान में लीन रहने वाला वह साधक अक्षय सुख को प्राप्त करता है।","gujarati":"જેનું મન બાહ્ય વિષયોમાં આસક્ત નથી, તે આત્મામાં જ સુખનો અનુભવ કરે છે; બ્રહ્મમાં ધ્યાનસ્થ રહેલો પુરુષ અક્ષય સુખ પ્રાપ્ત કરે છે."},"5.22":{"chapter":5,"verse":22,"sloka":"ये हि संस्पर्शजा भोगा दुःखयोनय एव ते।\n\nआद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः।।5.22।।","transliteration":"ye hi sansparśha-jā bhogā duḥkha-yonaya eva te\nādyantavantaḥ kaunteya na teṣhu ramate budhaḥ","english":"The pleasures derived from contact between the senses and their objects are indeed the sources of sorrow, for they have a beginning and an end; the wise do not find joy in them, O son of Kunti.","hindi":"हे कुन्तीपुत्र! इन्द्रियों और विषयों के संयोग से उत्पन्न होने वाले जितने भी भोग हैं, वे सब दुखों के ही कारण हैं। क्योंकि ऐसे भोग आदि और अन्त वाले (अनित्य) होते हैं, इसलिए बुद्धिमान मनुष्य उनमें सुख की बुद्धि नहीं रखते।","gujarati":"હે કૌન્તેય, ઇન્દ્રિયો અને વિષયોના સંયોગથી જે ભોગ ઉત્પન્ન થાય છે તે દુઃખના જ કારણો છે, કારણ કે તેઓ આદિ અને અંતવાળા છે; તેથી જ્ઞાની પુરુષો તેમાં રમતા નથી."},"5.23":{"chapter":5,"verse":23,"sloka":"शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात्।\n\nकामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः।।5.23।।","transliteration":"śhaknotīhaiva yaḥ soḍhuṁ prāk śharīra-vimokṣhaṇāt\nkāma-krodhodbhavaṁ vegaṁ sa yuktaḥ sa sukhī naraḥ","english":"He who is able to withstand the force of desire and anger here on earth, before the shedding of the body, is a yogi and a happy person.","hindi":"जो मनुष्य शरीर त्यागने से पूर्व इसी लोक में रहते हुए काम और क्रोध से उत्पन्न वेग को सहन करने में समर्थ है, वही योगी है और वही सुखी है।","gujarati":"જે મનુષ્ય આ શરીરનો ત્યાગ કરતા પહેલાં, આ લોકમાં જ કામ અને ક્રોધથી ઉત્પન્ન થતા વેગને સહન કરવા માટે સમર્થ છે, તે યોગી છે અને તે જ સુખી મનુષ્ય છે."},"5.24":{"chapter":5,"verse":24,"sloka":"योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः।\n\nस योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति।।5.24।।","transliteration":"yo 'ntaḥ-sukho 'ntar-ārāmas tathāntar-jyotir eva yaḥ\nsa yogī brahma-nirvāṇaṁ brahma-bhūto 'dhigachchhati","english":"One who is happy from within, who enjoys the self, and whose illumination is inward, that yogi becomes one with the Absolute and attains liberation in the Supreme.","hindi":"जो पुरुष अन्तरात्मा में ही सुख वाला है, जो आत्मा में ही रमण करने वाला है और जिसका ज्ञान भी आत्मा में ही स्थित है, ऐसा वह योगी ब्रह्मरूप होकर शांत ब्रह्म को प्राप्त हो जाता है।","gujarati":"જે પુરુષ અંતરાત્મામાં જ સુખી છે, જે આત્મામાં જ રમણ કરનાર છે અને જેનું જ્ઞાન પણ આત્મામાં જ પ્રકાશિત છે, તેવો યોગી બ્રહ્મરૂપ બનીને પરમ નિર્વાણ પામે છે."},"5.25":{"chapter":5,"verse":25,"sloka":"लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः।\n\nछिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः।।5.25।।","transliteration":"labhante brahma-nirvāṇam ṛiṣhayaḥ kṣhīṇa-kalmaṣhāḥ\nchhinna-dvaidhā yatātmānaḥ sarva-bhūta-hite ratāḥ","english":"Those sages attain the absolute freedom of liberation whose sins are destroyed, whose dualities are severed, who are self-controlled, and who are devoted to the welfare of all beings.","hindi":"जिन ऋषियों के पाप नष्ट हो गए हैं, जिनके समस्त द्वैत मिट गए हैं, जो संयमी हैं और जो संपूर्ण प्राणियों के हित में तत्पर रहते हैं, वे मोक्ष को प्राप्त करते हैं।","gujarati":"જે ઋષિઓના પાપ નષ્ટ થઈ ગયા છે, જેમનો સંશય (દ્વૈત) છિન્ન-ભિન્ન થઈ ગયો છે, જેઓ સંયમી છે અને જેઓ તમામ જીવોના કલ્યાણમાં રચ્યાપચ્યા રહે છે, તેઓ મોક્ષ પ્રાપ્ત કરે છે."},"5.26":{"chapter":5,"verse":26,"sloka":"कामक्रोधवियुक्तानां यतीनां यतचेतसाम्।\n\nअभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम्।।5.26।।","transliteration":"kāma-krodha-viyuktānāṁ yatīnāṁ yata-chetasām\nabhito brahma-nirvāṇaṁ vartate viditātmanām","english":"For those self-controlled ascetics who are free from desire and anger, whose minds are disciplined, and who have realized the Self, liberation is present everywhere.","hindi":"काम और क्रोध से मुक्त, संयत-चित्त और आत्मज्ञानी यतियों के लिए सब ओर ब्रह्म (मोक्ष) ही स्थित है।","gujarati":"કામ અને ક્રોધથી રહિત, જેમના ચિત્ત સંયમી છે અને જેમણે આત્માને જાણી લીધો છે, તેવા સાધકો માટે સર્વત્ર મોક્ષ (બ્રહ્મ) જ રહેલો છે."},"5.27":{"chapter":5,"verse":27,"sloka":"स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः।\n\nप्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ।।5.27।।","transliteration":"sparśhān kṛitvā bahir bāhyānśh chakṣhuśh chaivāntare bhruvoḥ\nprāṇāpānau samau kṛitvā nāsābhyantara-chāriṇau\n yatendriya-mano-buddhir munir mokṣha-parāyaṇaḥ\nvigatechchhā-bhaya-krodho yaḥ sadā mukta eva saḥ","english":"Shutting out all external sense objects, keeping the eyes fixed between the eyebrows, and balancing the incoming and outgoing breaths within the nostrils.","hindi":"बाह्य विषयों को बाहर करके और दृष्टि को दोनों भौहों के बीच स्थित करके, नासिका में बहने वाली प्राण और अपान वायु को समान करने वाला योगी ही मुक्त है।","gujarati":"બહારના વિષયોને બહાર કાઢીને અને દ્રષ્ટિને ભ્રકુટીની વચ્ચે સ્થિર કરીને, નાસિકામાં વહેતા પ્રાણ અને અપાન વાયુને સમાન કરવા."},"5.28":{"chapter":5,"verse":28,"sloka":"यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः।\n\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः।।5.28।।","transliteration":"yatendriya-mano-buddhir  munir   mokṣa-parāyaṇaḥ vigatecchā-bhaya-krodho yaḥ sadā    mukta   eva saḥ","english":"With senses, mind, and intellect fully controlled, the sage who has made liberation their supreme goal and is free from desire, fear, and anger, is indeed forever liberated.","hindi":"जिसके इन्द्रियाँ, मन और बुद्धि संयत हैं, ऐसा मोक्षपरायण मुनि सदा के लिए मुक्त ही है, क्योंकि वह इच्छा, भय और क्रोध से पूरी तरह रहित हो गया है।","gujarati":"જેના ઇન્દ્રિયો, મન અને બુદ્ધિ સંયમિત છે, એવો મોક્ષપરાયણ મુનિ ઈચ્છા, ભય અને ક્રોધથી મુક્ત છે, તે ખરેખર હંમેશ માટે મુક્ત જ છે."},"5.29":{"chapter":5,"verse":29,"sloka":"भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्।\n\nसुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति।।5.29।।","transliteration":"bhoktāraṁ yajña-tapasāṁ sarva-loka-maheśhvaram\nsuhṛidaṁ sarva-bhūtānāṁ jñātvā māṁ śhāntim ṛichchhati","english":"He who knows Me as the enjoyer of all sacrifices and austerities, the great Lord of all the worlds, and the friend of all living beings, attains peace.","hindi":"जो मुझे समस्त यज्ञों और तपों का भोक्ता, समस्त लोकों का महान ईश्वर तथा सम्पूर्ण प्राणियों का परम मित्र जानकर पहचान लेता है, वह शान्ति को प्राप्त होता है।","gujarati":"જે મને સર્વ યજ્ઞો અને તપનો ભોક્તા, સમસ્ત લોકનો મહાન ઈશ્વર તથા સર્વ પ્રાણીઓનો પરમ મિત્ર જાણીને સમજે છે, તે શાંતિ પ્રાપ્ત કરે છે."},"6.1":{"chapter":6,"verse":1,"sloka":"श्री भगवानुवाच\n\nअनाश्रितः कर्मफलं कार्यं कर्म करोति यः।\n\nस संन्यासी च योगी च न निरग्निर्न चाक्रियः।।6.1।।","transliteration":"śhrī bhagavān uvācha\nanāśhritaḥ karma-phalaṁ kāryaṁ karma karoti yaḥ\nsa sannyāsī cha yogī cha na niragnir na chākriyaḥ","english":"The Blessed Lord said: He who performs his prescribed duty without seeking the fruits of his actions is both a sannyasi (renunciate) and a yogi, not he who merely abandons the sacrificial fire and ritual activities.","hindi":"श्री भगवान ने कहा: जो पुरुष कर्मफल की इच्छा न रखकर अपने कर्तव्य का पालन करता है, वही संन्यासी है और वही योगी है; न कि वह जो केवल अग्नि और क्रियाओं का त्याग करके बैठा है।","gujarati":"શ્રી ભગવાન બોલ્યા: જે પુરુષ કર્મના ફળનો આશ્રય લીધા વિના પોતાનું કર્તવ્ય કરે છે, તે જ સન્યાસી અને યોગી છે, નહિ કે તે જેણે માત્ર અગ્નિ અને ક્રિયાઓનો ત્યાગ કર્યો છે."},"6.2":{"chapter":6,"verse":2,"sloka":"यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव।\n\nन ह्यसंन्यस्तसङ्कल्पो योगी भवति कश्चन।।6.2।।","transliteration":"yaṁ sannyāsam iti prāhur yogaṁ taṁ viddhi pāṇḍava\nna hyasannyasta-saṅkalpo yogī bhavati kaśhchana","english":"Know that what is called renunciation is Yoga, O Arjuna; for no one becomes a Yogi who has not renounced all selfish intentions.","hindi":"हे अर्जुन! जिसे संन्यास कहते हैं, उसी को तुम योग जानो; क्योंकि संकल्पों का त्याग किए बिना कोई भी पुरुष योगी नहीं बन सकता।","gujarati":"હે અર્જુન! જેને સંન્યાસ કહે છે તેને જ તું યોગ જાણ; કારણ કે સંકલ્પોનો ત્યાગ કર્યા વગર કોઈ પણ પુરુષ યોગી બની શકતો નથી."},"6.3":{"chapter":6,"verse":3,"sloka":"आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते।\n\nयोगारूढस्य तस्यैव शमः कारणमुच्यते।।6.3।।","transliteration":"ārurukṣhor muner yogaṁ karma kāraṇam uchyate\nyogārūḍhasya tasyaiva śhamaḥ kāraṇam uchyate","english":"For one who is aspiring for yoga, work is said to be the means; for one who has already attained yoga, stillness is said to be the means.","hindi":"योग में आरूढ़ होने की इच्छा वाले मुनि के लिए कर्म करना ही साधन कहा गया है, और योगारूढ़ हो जाने पर उसी पुरुष के लिए शम (शांति या निवृत्ति) ही साधन माना गया है।","gujarati":"યોગમાં આરુઢ થવાની ઈચ્છા રાખનારા મુનિ માટે કર્મ કરવું એ જ સાધન કહેવાય છે, અને જ્યારે તે યોગારુઢ થઈ જાય, ત્યારે તે જ પુરુષ માટે શાંતિ (શમ) સાધન ગણાય છે."},"6.4":{"chapter":6,"verse":4,"sloka":"यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते।\n\nसर्वसङ्कल्पसंन्यासी योगारूढस्तदोच्यते।।6.4।।","transliteration":"yadā hi nendriyārtheṣhu na karmasv-anuṣhajjate\nsarva-saṅkalpa-sannyāsī yogārūḍhas tadochyate","english":"When a person is not attached to sense objects or to fruitive actions, and has renounced all material desires, they are said to be elevated in Yoga.","hindi":"जब मनुष्य न तो इन्द्रियों के भोगों में और न ही सकाम कर्मों में आसक्त होता है, और समस्त संकल्पों का त्याग कर देता है, तब उसे योगारूढ़ कहा जाता है।","gujarati":"જ્યારે વ્યક્તિ ઇન્દ્રિયોના વિષયોમાં કે કર્મોમાં આસક્ત નથી હોતી, અને તેણે તમામ સંકલ્પોનો ત્યાગ કર્યો હોય, ત્યારે તે યોગરૂઢ કહેવાય છે."},"6.5":{"chapter":6,"verse":5,"sloka":"उद्धरेदात्मनाऽऽत्मानं नात्मानमवसादयेत्।\n\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः।।6.5।।","transliteration":"uddhared ātmanātmānaṁ nātmānam avasādayet\nātmaiva hyātmano bandhur ātmaiva ripur ātmanaḥ","english":"One should elevate oneself by one's own self; let not one degrade oneself. For the self is the friend of the self, and the self is the enemy of the self.","hindi":"मनुष्य को चाहिए कि वह अपने मन के द्वारा अपना उद्धार करे और अपना अध:पतन न होने दे, क्योंकि यह मन ही जीवात्मा का मित्र है और यह मन ही जीवात्मा का शत्रु भी है।","gujarati":"પોતાના વડે જ પોતાનો ઉદ્ધાર કરવો અને પોતાને અધોગતિમાં ન પાડવા, કારણ કે જીવાત્મા પોતે જ પોતાનો મિત્ર છે અને પોતે જ પોતાનો શત્રુ છે."},"6.6":{"chapter":6,"verse":6,"sloka":"बन्धुरात्माऽऽत्मनस्तस्य येनात्मैवात्मना जितः।\n\nअनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत्।।6.6।।","transliteration":"bandhur ātmātmanas tasya yenātmaivātmanā jitaḥ\nanātmanas tu śhatrutve vartetātmaiva śhatru-vat","english":"For him who has conquered the self by the Self, the self is a friend; but for him who has not conquered it, this self remains an enemy like an external foe.","hindi":"जिसने स्वयं को अपने द्वारा जीत लिया है, उस मनुष्य के लिए वह स्वयं ही मित्र है; परन्तु जिसने स्वयं को नहीं जीता, उसके लिए उसका स्वयं का मन ही शत्रु के समान कार्य करता है।","gujarati":"જેણે આત્માને જીતી લીધો છે તેના માટે આત્મા મિત્ર છે, પરંતુ જેણે આત્માને જીત્યો નથી, તેના માટે તે આત્મા જ શત્રુની જેમ વર્તે છે."},"6.7":{"chapter":6,"verse":7,"sloka":"जितात्मनः प्रशान्तस्य परमात्मा समाहितः।\n\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः।।6.7।।","transliteration":"jitātmanaḥ praśhāntasya paramātmā samāhitaḥ\nśhītoṣhṇa-sukha-duḥkheṣhu tathā mānāpamānayoḥ","english":"For one who has conquered the mind and attained tranquility, the Supreme Self is already reached, as he remains equipoised in cold and heat, pleasure and pain, honor and dishonor.","hindi":"जिसने मन को जीत लिया है और जो परम शान्त है, ऐसे संयमी पुरुष के लिए परमात्मा पूर्णतः स्थित है, क्योंकि वह सर्दी-गर्मी, सुख-दुःख तथा मान-अपमान में सदैव सम रहता है।","gujarati":"જેણે મનને જીતી લીધું છે અને જે પરમ શાંત છે, એવા જીતાત્મા પુરુષ માટે પરમાત્મા સર્વત્ર સ્થિત છે; તે ઠંડી-ગરમી, સુખ-દુઃખ તથા માન-અપમાનમાં હંમેશા સમ રહે છે."},"6.8":{"chapter":6,"verse":8,"sloka":"ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः।\n\nयुक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः।।6.8।।","transliteration":"jñāna-vijñāna-tṛiptātmā kūṭa-stho vijitendriyaḥ\nyukta ityuchyate yogī sama-loṣhṭāśhma-kāñchanaḥ","english":"The yogi who is satisfied with knowledge and wisdom, who is self-controlled, and to whom a lump of earth, a stone, and gold are the same, is said to be united with the Divine.","hindi":"जो योगी ज्ञान और विज्ञान से तृप्त है, जो स्थितचित्त और जितेन्द्रिय है, तथा जिसके लिए मिट्टी, पत्थर और सोना समान हैं, वह योगी परमात्मा में स्थित कहलाता है।","gujarati":"જે યોગી જ્ઞાન અને વિજ્ઞાનથી તૃપ્ત છે, જે શાંત અને જિતેન્દ્રિય છે, તથા જેની દ્રષ્ટિમાં માટી, પથ્થર અને સોનું સમાન છે, તે યોગી પરમાત્મામાં સ્થિત ગણાય છે."},"6.9":{"chapter":6,"verse":9,"sloka":"सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु।\n\nसाधुष्वपि च पापेषु समबुद्धिर्विशिष्यते।।6.9।।","transliteration":"suhṛin-mitrāryudāsīna-madhyastha-dveṣhya-bandhuṣhu\nsādhuṣhvapi cha pāpeṣhu sama-buddhir viśhiṣhyate","english":"He who views with equal regard the well-wisher, the friend, the enemy, the indifferent, the neutral, the hateful, the relative, the righteous, and the unrighteous, is considered supreme.","hindi":"जो व्यक्ति सुहृद, मित्र, शत्रु, उदासीन, मध्यस्थ, द्वेषी, बंधु-बान्धव, पुण्यात्मा और पापियों को भी समान भाव से देखता है, वह श्रेष्ठ माना जाता है।","gujarati":"જે મનુષ્ય હિતેચ્છુ, મિત્ર, શત્રુ, તટસ્થ, મધ્યસ્થ, દ્વેષી, સગા-સંબંધી, પુણ્યાત્માઓ અને પાપીઓ પ્રત્યે પણ સમાન ભાવ રાખે છે, તે શ્રેષ્ઠ છે."},"6.10":{"chapter":6,"verse":10,"sloka":"योगी युञ्जीत सततमात्मानं रहसि स्थितः।\n\nएकाकी यतचित्तात्मा निराशीरपरिग्रहः।।6.10।।","transliteration":"yogī yuñjīta satatam ātmānaṁ rahasi sthitaḥ\nekākī yata-chittātmā nirāśhīr aparigrahaḥ","english":"A yogi should constantly engage his mind in meditation, remaining in solitude, alone, with the body and mind disciplined, free from desires and the sense of possessiveness.","hindi":"शरीर और मन को संयमित कर, आशा और संग्रह की इच्छा से मुक्त होकर, योगी को सदैव एकांत में रहकर अपने मन को एकाग्र करना चाहिए।","gujarati":"યોગીએ શરીર અને મનને કાબૂમાં રાખીને, આશા અને સંગ્રહ કરવાની વૃત્તિથી મુક્ત થઈને, એકાંતમાં રહીને નિરંતર મનને આત્મામાં સ્થિર કરવું જોઈએ."},"6.11":{"chapter":6,"verse":11,"sloka":"शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः।\n\nनात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम्।।6.11।।","transliteration":"śhuchau deśhe pratiṣhṭhāpya sthiram āsanam ātmanaḥ\nnātyuchchhritaṁ nāti-nīchaṁ chailājina-kuśhottaram","english":"Having set up a firm seat for himself in a clean place, neither too high nor too low, and covered with kusha grass, a deer skin, and a cloth, one upon the other.","hindi":"शुद्ध भूमि में कुश, मृगचर्म और वस्त्र को एक-दूसरे के ऊपर बिछाकर, न बहुत ऊँचा और न बहुत नीचा, स्थिर आसन जमाकर बैठना चाहिए।","gujarati":"શુદ્ધ ભૂમિ પર કુશ, મૃગચર્મ અને વસ્ત્ર એકબીજા પર પાથરીને, જે બહુ ઊંચું પણ ન હોય અને બહુ નીચું પણ ન હોય, તેવું સ્થિર આસન સ્થાપિત કરવું."},"6.12":{"chapter":6,"verse":12,"sloka":"तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः।\n\nउपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये।।6.12।।","transliteration":"tatraikāgraṁ manaḥ kṛitvā yata-chittendriya-kriyaḥ\nupaviśhyāsane yuñjyād yogam ātma-viśhuddhaye","english":"Seated on that seat, making the mind one-pointed and controlling the activities of the mind and senses, one should practice Yoga for the purification of the self.","hindi":"वहाँ उस आसन पर बैठकर, मन को एकाग्र करके तथा चित्त और इन्द्रियों की क्रियाओं को वश में करके, अन्तःकरण की शुद्धि के लिए योग का अभ्यास करे।","gujarati":"ત્યાં તે આસન પર બેસીને, મનને એકાગ્ર કરીને તથા ચિત્ત અને ઇન્દ્રિયોની ક્રિયાઓને વશમાં રાખીને, આત્મશુદ્ધિ માટે યોગનો અભ્યાસ કરવો જોઈએ."},"6.13":{"chapter":6,"verse":13,"sloka":"समं कायशिरोग्रीवं धारयन्नचलं स्थिरः।\n\nसंप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन्।।6.13।।","transliteration":"samaṁ kāya-śhiro-grīvaṁ dhārayann achalaṁ sthiraḥ\nsamprekṣhya nāsikāgraṁ svaṁ diśhaśh chānavalokayan","english":"Holding the body, head, and neck erect and motionless, the practitioner should remain steady, gazing at the tip of the nose without looking in any other direction.","hindi":"शरीर, सिर और गर्दन को सीधा तथा अचल रखकर, एकाग्र चित्त से अपनी नासिका के अग्र भाग पर दृष्टि टिकाए हुए, अन्य दिशाओं में न देखें।","gujarati":"શરીર, માથું અને ગ્રીવાને સીધા અને અચળ રાખીને, સ્થિર થઈને પોતાની નાસિકાના અગ્ર ભાગને નિહાળતા, અન્ય કોઈ દિશામાં ન જોવું."},"6.14":{"chapter":6,"verse":14,"sloka":"प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः।\n\nमनः संयम्य मच्चित्तो युक्त आसीत मत्परः।।6.14।।","transliteration":"praśhāntātmā vigata-bhīr brahmachāri-vrate sthitaḥ\nmanaḥ sanyamya mach-chitto yukta āsīta mat-paraḥ","english":"With a serene and fearless mind, steadfast in the vow of celibacy, having controlled the mind, the yogi should sit, absorbed in Me, with Me as their supreme goal.","hindi":"प्रशान्त चित्त, भय रहित और ब्रह्मचर्य व्रत में स्थित होकर, मन को संयमित कर तथा मुझमें मन लगाकर, वह योगी मुझे ही परम लक्ष्य मानकर स्थिर होकर बैठे।","gujarati":"શાંત મનવાળો, નિર્ભય અને બ્રહ્મચર્યના વ્રતનું પાલન કરનાર, મનને સંયમિત રાખીને, મારું ચિંતન કરતો અને મને જ પરમ લક્ષ્ય માનતો યોગી સ્થિર થઈને બેસે."},"6.15":{"chapter":6,"verse":15,"sloka":"युञ्जन्नेवं सदाऽऽत्मानं योगी नियतमानसः।\n\nशान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति।।6.15।।","transliteration":"yuñjann evaṁ sadātmānaṁ yogī niyata-mānasaḥ\nśhantiṁ nirvāṇa-paramāṁ mat-sansthām adhigachchhati","english":"Thus, by constantly keeping the mind balanced and under control, the yogi attains the supreme peace that abides in Me, which culminates in liberation.","hindi":"इस प्रकार मन को निरंतर संयमित करके योग का अभ्यास करने वाला योगी, मुझमें स्थित परम शांति और निर्वाण को प्राप्त कर लेता है।","gujarati":"આ રીતે મનને નિરંતર વશમાં રાખીને, યોગનો અભ્યાસ કરનાર યોગી મારામાં રહેલી પરમ શાંતિ અને મોક્ષને પ્રાપ્ત કરે છે."},"6.16":{"chapter":6,"verse":16,"sloka":"नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः।\n\nन चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन।।6.16।।","transliteration":"nātyaśhnatastu yogo ’sti na chaikāntam anaśhnataḥ\nna chāti-svapna-śhīlasya jāgrato naiva chārjuna","english":"Verily, Yoga is not for him who eats too much, nor for him who does not eat at all; it is not for him who sleeps too much, nor for him who keeps awake, O Arjuna.","hindi":"हे अर्जुन! यह योग न तो बहुत अधिक खाने वाले का सिद्ध होता है और न बिल्कुल न खाने वाले का; न तो बहुत अधिक सोने वाले का और न ही सदा जागने वाले का।","gujarati":"હે અર્જુન, આ યોગ ન તો બહુ ખાનારનો સિદ્ધ થાય છે, ન તો બિલકુલ ન ખાનારનો; ન તો બહુ ઊંઘનારનો, કે ન તો હંમેશા જાગતા રહેનારનો."},"6.17":{"chapter":6,"verse":17,"sloka":"युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु।\n\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा।।6.17।।","transliteration":"yuktāhāra-vihārasya yukta-cheṣhṭasya karmasu\nyukta-svapnāvabodhasya yogo bhavati duḥkha-hā","english":"Yoga becomes the destroyer of misery for one who is moderate in eating and recreation, regulated in working, and balanced in sleep and wakefulness.","hindi":"युक्त आहार-विहार करने वाले, कर्मों में यथायोग्य चेष्टा करने वाले तथा सोने और जागने में संयम रखने वाले पुरुष के लिए योग दुखों का नाश करने वाला होता है।","gujarati":"જે આહાર અને વિહારમાં નિયમિત છે, જેનાં કર્મો પણ નિયમિત છે અને જેનાં ઊંઘવા તથા જાગવાના સમય પણ મર્યાદિત છે, તેવા પુરુષ માટે યોગ દુઃખનો નાશ કરનાર બને છે."},"6.18":{"chapter":6,"verse":18,"sloka":"यदा विनियतं चित्तमात्मन्येवावतिष्ठते।\n\nनिःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा।।6.18।।","transliteration":"yadā viniyataṁ chittam ātmanyevāvatiṣhṭhate\nniḥspṛihaḥ sarva-kāmebhyo yukta ityuchyate tadā","english":"When the mind, thoroughly disciplined, rests solely in the Self, having become indifferent to all objects of desire, then it is said that one is established in Yoga.","hindi":"जब भली-भांति वश में किया हुआ चित्त नितांत आत्मस्वरूप में ही स्थित हो जाता है और समस्त भोगों की स्पृहा से रहित हो जाता है, तब वह योगी 'युक्त' कहा जाता है।","gujarati":"જ્યારે સારી રીતે વશ થયેલું ચિત્ત સંપૂર્ણપણે આત્મસ્વરૂપમાં જ સ્થિર થઈ જાય છે અને તમામ ભૌતિક ઈચ્છાઓથી મુક્ત થઈ જાય છે, ત્યારે તે 'યુક્ત' કહેવાય છે."},"6.19":{"chapter":6,"verse":19,"sloka":"यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता।\n\nयोगिनो यतचित्तस्य युञ्जतो योगमात्मनः।।6.19।।","transliteration":"yathā dīpo nivāta-stho neṅgate sopamā smṛitā\nyogino yata-chittasya yuñjato yogam ātmanaḥ","english":"Just as a lamp in a windless place does not flicker, so the Yogi whose mind is controlled remains steady while practicing meditation on the Self.","hindi":"जैसे हवा रहित स्थान में रखा हुआ दीपक कभी नहीं डगमगाता, वैसे ही अपने मन को वश में करने वाला योगी जब आत्मा में स्थित होकर योग का अभ्यास करता है, तो उसका चित्त स्थिर रहता है।","gujarati":"જેમ પવનરહિત જગ્યામાં રાખેલો દીવો સ્થિર રહે છે, તેમ પોતાના મનને વશમાં રાખનાર યોગી જ્યારે આત્મામાં સ્થિત થઈને યોગનો અભ્યાસ કરે છે, ત્યારે તેનું ચિત્ત ડગમગતું નથી."},"6.20":{"chapter":6,"verse":20,"sloka":"यत्रोपरमते चित्तं निरुद्धं योगसेवया।\n\nयत्र चैवात्मनाऽऽत्मानं पश्यन्नात्मनि तुष्यति।।6.20।।","transliteration":"yatroparamate chittaṁ niruddhaṁ yoga-sevayā\nyatra chaivātmanātmānaṁ paśhyann ātmani tuṣhyati","english":"When the mind, restrained by the practice of yoga, becomes still and attains quietude, and when one beholds the Self through the pure intellect and finds contentment in the Self alone, that state is realization.","hindi":"योग के अभ्यास से जब चित्त भली-भांति निरुद्ध होकर शांत हो जाता है, और जब साधक अपने शुद्ध मन से आत्मा को देखता हुआ स्वयं में ही संतुष्ट हो जाता है, तब वह परम अवस्था प्राप्त होती है।","gujarati":"યોગના અભ્યાસ દ્વારા જ્યારે ચિત્ત સંપૂર્ણપણે શાંત થઈ જાય છે, અને જ્યારે મનુષ્ય પોતાના નિર્મળ અંતઃકરણ વડે આત્માને આત્મામાં જોઈને સ્વયંમાં જ સંતુષ્ટ રહે છે, તે સ્થિતિને યોગની પરાકાષ્ઠા કહેવાય છે."},"6.21":{"chapter":6,"verse":21,"sloka":"सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम्।\n\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः।।6.21।।","transliteration":"sukham ātyantikaṁ yat tad buddhi-grāhyam atīndriyam\nvetti yatra na chaivāyaṁ sthitaśh chalati tattvataḥ","english":"In that state of joy, which is transcendental, known only by the intuition, and beyond the reach of the senses, one remains established, never straying from the absolute truth.","hindi":"जो अनंत सुख इंद्रियों से परे केवल शुद्ध बुद्धि द्वारा ही जाना जा सकता है, उस अवस्था में स्थित होकर योगी कभी भी अपने वास्तविक स्वरूप से विचलित नहीं होता।","gujarati":"જે અત્યંત આનંદ ઇન્દ્રિયોથી પર છે અને માત્ર શુદ્ધ બુદ્ધિ દ્વારા જ ગ્રાહ્ય છે, તે અવસ્થામાં સ્થિત થઈને યોગી ક્યારેય સત્યથી વિચલિત થતો નથી."},"6.22":{"chapter":6,"verse":22,"sloka":"यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः।\n\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते।।6.22।।","transliteration":"yaṁ labdhvā chāparaṁ lābhaṁ manyate nādhikaṁ tataḥ\nyasmin sthito na duḥkhena guruṇāpi vichālyate","english":"Having gained which, one considers no other gain superior to it; established in which, one is not moved even by the greatest sorrow.","hindi":"जिस लाभ को प्राप्त कर लेने के बाद वह उससे बढ़कर किसी अन्य लाभ को नहीं मानता, और जिसमें स्थित होकर वह बड़े-से-बड़े दुःख से भी विचलित नहीं होता।","gujarati":"જે લાભને પ્રાપ્ત કરીને તે તેનાથી અધિક કોઈ બીજો લાભ માનતો નથી અને જેમાં સ્થિત થઈને તે મોટામાં મોટા દુઃખથી પણ વિચલિત થતો નથી."},"6.23":{"chapter":6,"verse":23,"sloka":"तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम्।\n\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा।।6.23।।","transliteration":"taṁ vidyād duḥkha-sanyoga-viyogaṁ yogasaṅjñitam\nsa niśhchayena yoktavyo yogo ’nirviṇṇa-chetasā","english":"Know that this state of detachment from the experience of suffering is called Yoga. One must practice this Yoga with firm resolve and an undaunted, steady mind.","hindi":"दुःख के संयोग से जो वियोग है, उसे ही योग जानना चाहिए। इस योग का अभ्यास दृढ़ निश्चय और न घबराने वाले मन के साथ करना चाहिए।","gujarati":"દુઃખના સંયોગથી જે વિયોગ છે, તેને જ 'યોગ' જાણવો. આ યોગનો અભ્યાસ મક્કમ નિશ્ચય અને ઉત્સાહપૂર્વક મનથી કરવો જોઈએ."},"6.24":{"chapter":6,"verse":24,"sloka":"सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः।\n\nमनसैवेन्द्रियग्रामं विनियम्य समन्ततः।।6.24।।","transliteration":"saṅkalpa-prabhavān kāmāns tyaktvā sarvān aśheṣhataḥ\nmanasaivendriya-grāmaṁ viniyamya samantataḥ","english":"Abandoning without exception all desires born of mental projections, and bringing the senses under control from all sides through the power of the mind.","hindi":"संकल्प से उत्पन्न होने वाली समस्त कामनाओं का पूर्णतः त्याग करके और मन के द्वारा इन्द्रियों के समूह को सब ओर से भली-भांति वश में करके।","gujarati":"સંકલ્પથી ઉત્પન્ન થતી તમામ કામનાઓનો નિઃશેષ ત્યાગ કરીને અને મન દ્વારા ઇન્દ્રિયોના સમુદાયને સર્વ તરફથી સારી રીતે વશમાં કરીને."},"6.25":{"chapter":6,"verse":25,"sloka":"शनैः शनैरुपरमेद् बुद्ध्या धृतिगृहीतया।\n\nआत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत्।।6.25।।","transliteration":"śhanaiḥ śhanair uparamed buddhyā dhṛiti-gṛihītayā\nātma-sansthaṁ manaḥ kṛitvā na kiñchid api chintayet","english":"Little by little, one should attain tranquility with the intellect firmly restrained; having established the mind in the Self, let one not think of anything else.","hindi":"शनै: शनै: धैर्ययुक्त बुद्धि के द्वारा योगी उपरामता को प्राप्त होवे; मन को आत्मा में स्थित करके फिर अन्य कुछ भी चिन्तन न करे।","gujarati":"ધીમે ધીમે ધીરજયુક્ત બુદ્ધિ વડે શાંતિ પ્રાપ્ત કરવી જોઈએ; મનને આત્મામાં સ્થિર કરીને પછી અન્ય કોઈ પણ બાબતનું ચિંતન કરવું નહીં."},"6.26":{"chapter":6,"verse":26,"sloka":"यतो यतो निश्चरति मनश्चञ्चलमस्थिरम्।\n\nततस्ततो नियम्यैतदात्मन्येव वशं नयेत्।।6.26।।","transliteration":"yato yato niśhcharati manaśh chañchalam asthiram\ntatas tato niyamyaitad ātmanyeva vaśhaṁ nayet","english":"From whatever cause the restless and unsteady mind wanders away, let him restrain it from those objects and bring it back under the control of the Self alone.","hindi":"यह चंचल और अस्थिर मन जिन-जिन विषयों में भटकता है, योगी को चाहिए कि उन विषयों से हटाकर उसे पुनः बार-बार अपनी आत्मा के ही वश में करे।","gujarati":"આ મન ગમે તે કારણોસર જ્યાં જ્યાં ભટકે છે, ત્યાંથી તેને પાછું ખેંચીને તેને આત્માના જ નિયંત્રણમાં લાવવું જોઈએ."},"6.27":{"chapter":6,"verse":27,"sloka":"प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम्।\n\nउपैति शान्तरजसं ब्रह्मभूतमकल्मषम्।।6.27।।","transliteration":"praśhānta-manasaṁ hyenaṁ yoginaṁ sukham uttamam\nupaiti śhānta-rajasaṁ brahma-bhūtam akalmaṣham","english":"Supreme happiness comes to the yogi whose mind is peaceful, whose passions are quieted, who is free from sin, and who has attained oneness with the Supreme.","hindi":"शांत मन वाले, शांत रजोगुण वाले, पापरहित और ब्रह्म के साथ एकरूप हुए इस योगी को सर्वोच्च आनंद प्राप्त होता है।","gujarati":"જેનું મન અત્યંત શાંત છે, જેના રજોગુણ શમી ગયા છે, જે પાપરહિત છે અને જે બ્રહ્મરૂપ બની ગયો છે, તેવા યોગીને સર્વોચ્ચ આનંદ પ્રાપ્ત થાય છે."},"6.28":{"chapter":6,"verse":28,"sloka":"युञ्जन्नेवं सदाऽऽत्मानं योगी विगतकल्मषः।\n\nसुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते।।6.28।।","transliteration":"yuñjann evaṁ sadātmānaṁ yogī vigata-kalmaṣhaḥ\nsukhena brahma-sansparśham atyantaṁ sukham aśhnute","english":"Thus, the self-controlled yogi, constantly engaging his mind in meditation, becomes free from all impurities and easily attains the supreme happiness of union with the Brahman.","hindi":"इस प्रकार निरंतर आत्म-संयम में लगा हुआ निष्पाप योगी अत्यंत सरलता के साथ ब्रह्म के साथ एकरूप होकर उस अनंत आनंद का अनुभव करता है।","gujarati":"આ રીતે નિરંતર મનને આત્મામાં સ્થિર કરનાર અને પાપમુક્ત થયેલો યોગી અત્યંત સરળતાથી બ્રહ્મ સાથેના સંયોગથી પ્રાપ્ત થતા પરમ સુખનો અનુભવ કરે છે."},"6.29":{"chapter":6,"verse":29,"sloka":"सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि।\n\nईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः।।6.29।।","transliteration":"sarva-bhūta-stham ātmānaṁ sarva-bhūtāni chātmani\nīkṣhate yoga-yuktātmā sarvatra sama-darśhanaḥ","english":"A yogi whose mind is harmonized by meditation perceives the Self residing in all beings and all beings residing in the Self; indeed, he beholds the same divinity everywhere.","hindi":"योगयुक्त अंत:करण वाला और सर्वत्र समदर्शी योगी आत्मा को सब भूतों में स्थित और संपूर्ण भूतों को आत्मा में देखता है।","gujarati":"યોગયુક્ત ચિત્તવાળો અને સર્વત્ર સમાન દ્રષ્ટિ રાખનાર યોગી આત્માને બધા પ્રાણીઓમાં અને બધા પ્રાણીઓને આત્મામાં જુએ છે."},"6.30":{"chapter":6,"verse":30,"sloka":"यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति।\n\nतस्याहं न प्रणश्यामि स च मे न प्रणश्यति।।6.30।।","transliteration":"yo māṁ paśhyati sarvatra sarvaṁ cha mayi paśhyati\ntasyāhaṁ na praṇaśhyāmi sa cha me na praṇaśhyati","english":"For one who sees Me everywhere and sees everything in Me, I am never lost, nor is he ever lost to Me.","hindi":"जो मुझे सर्वत्र देखता है और सब कुछ मुझमें देखता है, उसके लिए मैं कभी अदृश्य नहीं होता और वह कभी मुझसे दूर नहीं होता।","gujarati":"જે પુરુષ મને સર્વત્ર જુએ છે અને સમગ્ર વિશ્વને મારામાં જુએ છે, તે મારાથી ક્યારેય દૂર થતો નથી, અને હું તેનાથી ક્યારેય દૂર થતો નથી."},"6.31":{"chapter":6,"verse":31,"sloka":"सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः।\n\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते।।6.31।।","transliteration":"sarva-bhūta-sthitaṁ yo māṁ bhajatyekatvam āsthitaḥ\nsarvathā vartamāno ’pi sa yogī mayi vartate","english":"He who, established in the unity of existence, worships Me as the indwelling soul in all beings, that yogi lives in Me, regardless of how they conduct their life.","hindi":"जो योगी एकत्वभाव में स्थित होकर समस्त प्राणियों में स्थित मुझे भजता है, वह सब प्रकार के कर्म करता हुआ भी मुझमें ही स्थित रहता है।","gujarati":"જે પુરુષ એકત્વભાવમાં સ્થિત થઈને તમામ ભૂતોમાં રહેલા મારા સ્વરૂપને ભજે છે, તે યોગી ગમે તે રીતે જીવતો હોય તો પણ મારામાં જ સ્થિત રહે છે."},"6.32":{"chapter":6,"verse":32,"sloka":"आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन।\n\nसुखं वा यदि वा दुःखं सः योगी परमो मतः।।6.32।।","transliteration":"ātmaupamyena sarvatra samaṁ paśhyati yo ’rjuna\nsukhaṁ vā yadi vā duḥkhaṁ sa yogī paramo mataḥ","english":"He who, through the likeness of the Self, O Arjuna, sees reality everywhere, whether in pleasure or in pain, is regarded as the highest Yogi.","hindi":"हे अर्जुन! जो योगी अपनी आत्मा के समान ही सब प्राणियों में सुख और दुःख को समान देखता है, वह परम योगी माना गया है।","gujarati":"હે અર્જુન! જે પુરુષ પોતાની આત્માની સમાન જ સર્વત્ર સુખ અને દુઃખને સમાન જુએ છે, તે પરમ યોગી માનવામાં આવે છે."},"6.33":{"chapter":6,"verse":33,"sloka":"अर्जुन उवाच\n\nयोऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन।\n\nएतस्याहं न पश्यामि चञ्चलत्वात् स्थितिं स्थिराम्।।6.33।।","transliteration":"arjuna uvācha\nyo ’yaṁ yogas tvayā proktaḥ sāmyena madhusūdana\netasyāhaṁ na paśhyāmi chañchalatvāt sthitiṁ sthirām","english":"Arjuna said: O Madhusudana, this Yoga of equanimity that You have described, I do not see how it can be maintained steadily, due to the restlessness of the mind.","hindi":"अर्जुन ने कहा: हे मधुसूदन! जो यह समत्व रूप योग आपने कहा है, मैं मन की चंचलता के कारण इसकी नित्य स्थिति को नहीं देख पा रहा हूँ।","gujarati":"અર્જુને કહ્યું: હે મધુસૂદન! જે આ સમત્વરૂપ યોગ આપે કહ્યો છે, મનની ચંચળતાને લીધે હું તેની સ્થાયી સ્થિતિ જોઈ શકતો નથી."},"6.34":{"chapter":6,"verse":34,"sloka":"चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम्।\n\nतस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम्।।6.34।।","transliteration":"chañchalaṁ hi manaḥ kṛiṣhṇa pramāthi balavad dṛiḍham\ntasyāhaṁ nigrahaṁ manye vāyor iva su-duṣhkaram","english":"For the mind is restless, turbulent, obstinate and very strong, O Krishna; to subdue it, I think, is more difficult than controlling the wind.","hindi":"क्योंकि हे कृष्ण! यह मन बड़ा ही चंचल, मथने वाला, बलवान और दृढ़ है; इसको वश में करना मैं वायु को रोकने के समान अत्यंत कठिन मानता हूँ।","gujarati":"હે કૃષ્ણ! મન તો અત્યંત ચંચળ, મથન કરનારું, બળવાન અને દ્રઢ છે; તેને વશ કરવું હું વાયુને રોકવા જેટલું જ કઠિન માનું છું."},"6.35":{"chapter":6,"verse":35,"sloka":"श्री भगवानुवाच\n\nअसंशयं महाबाहो मनो दुर्निग्रहं चलं।\n\nअभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते।।6.35।।","transliteration":"śhrī bhagavān uvācha\nasanśhayaṁ mahā-bāho mano durnigrahaṁ chalam\nabhyāsena tu kaunteya vairāgyeṇa cha gṛihyate","english":"The Blessed Lord said: 'Undoubtedly, O mighty-armed Arjuna, the mind is restless and difficult to restrain, but it is mastered through constant practice and detachment.'","hindi":"श्रीभगवान् ने कहा: 'हे महाबाहो! निसंदेह मन चंचल और कठिनता से वश में होने वाला है, परंतु हे कुन्तीपुत्र! इसे निरंतर अभ्यास और वैराग्य के द्वारा वश में किया जा सकता है।'","gujarati":"શ્રી ભગવાન બોલ્યા: 'હે મહાબાહુ અર્જુન! નિઃસંદેહ મન ચંચળ અને કઠિનતાથી વશ થાય તેવું છે, પરંતુ હે કૌંતેય! તેને અભ્યાસ અને વૈરાગ્ય દ્વારા વશમાં કરી શકાય છે.'"},"6.36":{"chapter":6,"verse":36,"sloka":"असंयतात्मना योगो दुष्प्राप इति मे मतिः।\n\nवश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः।।6.36।।","transliteration":"asaṅyatātmanā yogo duṣhprāpa iti me matiḥ\nvaśhyātmanā tu yatatā śhakyo ’vāptum upāyataḥ","english":"I believe that Yoga is difficult to attain for one whose mind is uncontrolled, but for one who has mastered their self and strives through the right means, it is attainable.","hindi":"मेरा मानना है कि जिसका मन वश में नहीं है, उसके लिए योग प्राप्त करना कठिन है, लेकिन प्रयत्नशील और संयमित व्यक्ति सही उपायों के माध्यम से इसे अवश्य प्राप्त कर सकता है।","gujarati":"મારું માનવું છે કે અસંયમિત મનવાળા પુરુષ માટે યોગ પ્રાપ્ત કરવો કઠિન છે, પરંતુ સંયમી અને પ્રયત્નશીલ પુરુષ યોગ્ય ઉપાયો દ્વારા તેને પ્રાપ્ત કરી શકે છે."},"6.37":{"chapter":6,"verse":37,"sloka":"अर्जुन उवाच\n\nअयतिः श्रद्धयोपेतो योगाच्चलितमानसः।\n\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति।।6.37।।","transliteration":"arjuna uvācha\nayatiḥ śhraddhayopeto yogāch chalita-mānasaḥ\naprāpya yoga-sansiddhiṁ kāṅ gatiṁ kṛiṣhṇa gachchhati","english":"Arjuna said: He who possesses faith but fails to control his mind, and whose mind wanders away from Yoga—what is the ultimate destination of such a person who has failed to attain perfection in Yoga, O Krishna?","hindi":"अर्जुन ने कहा: हे कृष्ण! वह व्यक्ति जो श्रद्धालु तो है, परंतु जिसका मन योग से भटक गया है और जो योग में पूर्णता प्राप्त करने में विफल रहा है, उसकी अंतिम गति क्या होती है?","gujarati":"અર્જુને કહ્યું: હે કૃષ્ણ! જે પુરુષ શ્રદ્ધાવાન તો છે, પરંતુ જેનું મન યોગમાંથી ભટકી ગયું છે અને જે યોગની સિદ્ધિ પ્રાપ્ત કરવામાં નિષ્ફળ રહ્યો છે, તેની અંતિમ ગતિ શું થાય છે?"},"6.38":{"chapter":6,"verse":38,"sloka":"कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति।\n\nअप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि।।6.38।।","transliteration":"kachchin nobhaya-vibhraṣhṭaśh chhinnābhram iva naśhyati\napratiṣhṭho mahā-bāho vimūḍho brahmaṇaḥ pathi","english":"O Mighty-armed Krishna, does not a man who deviates from the path of Yoga, failing to achieve steady realization, perish like a fragmented cloud, lost to both worldly success and spiritual liberation, being supportless and deluded?","hindi":"हे महाबाहो! यदि कोई पुरुष योगमार्ग में श्रद्धा रखने पर भी संयम न होने के कारण विचलित हो जाता है, तो क्या वह ब्रह्म की प्राप्ति के मार्ग से भटककर, सांसारिक सुख और आध्यात्मिक उन्नति—दोनों से गिरकर, छिन्न-भिन्न बादल की तरह नष्ट नहीं हो जाता?","gujarati":"હે મહાબાહુ! શું તે યોગમાર્ગમાંથી વિચલિત થયેલો, બ્રહ્મની પ્રાપ્તિના માર્ગમાં મોહિત અને આધારહીન પુરુષ, છિન્ન-ભિન્ન વાદળની જેમ બંને તરફથી ભ્રષ્ટ થઈને નષ્ટ તો નથી થઈ જતો?"},"6.39":{"chapter":6,"verse":39,"sloka":"एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः।\n\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते।।6.39।।","transliteration":"etan me sanśhayaṁ kṛiṣhṇa chhettum arhasyaśheṣhataḥ\ntvad-anyaḥ sanśhayasyāsya chhettā na hyupapadyate","english":"O Krishna, please dispel this doubt of mine completely, for there is no one else but You who can destroy this doubt.","hindi":"हे कृष्ण! मेरे इस संशय को पूरी तरह से मिटा दीजिए, क्योंकि आपके सिवाय और कोई भी इस संशय का नाश करने वाला नहीं है।","gujarati":"હે કૃષ્ણ! મારા આ સંશયને સંપૂર્ણ રીતે નષ્ટ કરો, કારણ કે તમારા સિવાય બીજું કોઈ આ સંશયને દૂર કરનાર મળી શકતું નથી."},"6.40":{"chapter":6,"verse":40,"sloka":"श्री भगवानुवाच\n\nपार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते।\n\nनहि कल्याणकृत्कश्िचद्दुर्गतिं तात गच्छति।।6.40।।","transliteration":"śhrī bhagavān uvācha\npārtha naiveha nāmutra vināśhas tasya vidyate\nna hi kalyāṇa-kṛit kaśhchid durgatiṁ tāta gachchhati","english":"The Blessed Lord said: O Arjuna, neither in this world nor in the next is there destruction for him; for no one who does good, My son, ever comes to a woeful end.","hindi":"श्रीभगवान् ने कहा: हे पार्थ! उस योगी का न तो इस लोक में और न परलोक में ही विनाश होता है; क्योंकि हे तात! कल्याणकारी मार्ग पर चलने वाला कोई भी व्यक्ति कभी दुर्गति को प्राप्त नहीं होता।","gujarati":"શ્રી ભગવાન બોલ્યા: હે પાર્થ! તે યોગીનો ન તો આ લોકમાં અને ન પરલોકમાં જ વિનાશ થાય છે; હે તાત! કલ્યાણના માર્ગે ચાલનાર કોઈ પણ વ્યક્તિ ક્યારેય દુર્ગતિને પામતી નથી."},"6.41":{"chapter":6,"verse":41,"sloka":"प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः।\n\nशुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते।।6.41।।","transliteration":"prāpya puṇya-kṛitāṁ lokān uṣhitvā śhāśhvatīḥ samāḥ\nśhuchīnāṁ śhrīmatāṁ gehe yoga-bhraṣhṭo’bhijāyate","english":"Having attained the worlds of the righteous and dwelt there for many years, he who fell from Yoga is reborn in the house of the pure and prosperous.","hindi":"योगभ्रष्ट पुरुष पुण्यवानों के लोकों को प्राप्त होकर वहाँ दीर्घकाल तक वास करके, शुद्ध और श्रीमानों के कुल में जन्म लेता है।","gujarati":"યોગભ્રષ્ટ પુરુષ પુણ્યશાળીઓના લોકને પ્રાપ્ત કરીને, ત્યાં ઘણાં વર્ષો સુધી નિવાસ કરીને, પવિત્ર અને શ્રીમંતોના કુળમાં જન્મ લે છે."},"6.42":{"chapter":6,"verse":42,"sloka":"अथवा योगिनामेव कुले भवति धीमताम्।\n\nएतद्धि दुर्लभतरं लोके जन्म यदीदृशम्।।6.42।।","transliteration":"atha vā yoginām eva kule bhavati dhīmatām\netad dhi durlabhataraṁ loke janma yad īdṛiśham","english":"Or he is born into a family of wise yogis; such a birth is indeed very difficult to obtain in this world.","hindi":"अथवा, वह ज्ञानवान् योगियों के ही कुल में जन्म लेता है; निश्चय ही, इस संसार में ऐसा जन्म मिलना अत्यंत दुर्लभ है।","gujarati":"અથવા તે જ્ઞાની યોગીઓના કુળમાં જ જન્મ લે છે; નિશ્ચય જ, આ સંસારમાં આવો જન્મ મળવો અત્યંત દુર્લભ છે."},"6.43":{"chapter":6,"verse":43,"sloka":"तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम्।\n\nयतते च ततो भूयः संसिद्धौ कुरुनन्दन।।6.43।।","transliteration":"tatra taṁ buddhi-sanyogaṁ labhate paurva-dehikam\nyatate cha tato bhūyaḥ sansiddhau kuru-nandana","english":"There he regains the knowledge acquired in his previous life, and he strives again for perfection, O son of Kuru.","hindi":"वहाँ वह पूर्व जन्म के बुद्धिसंयोग को प्राप्त कर लेता है और हे कुरुनन्दन! वह योग की सिद्धि के लिए उससे भी अधिक प्रयत्न करता है।","gujarati":"ત્યાં તે અગાઉના દેહમાં પ્રાપ્ત થયેલ બુદ્ધિના સંયોગને પામે છે અને હે કુરુનંદન! યોગની સિદ્ધિ માટે તે પહેલાં કરતાં પણ વધુ પ્રયત્ન કરે છે."},"6.44":{"chapter":6,"verse":44,"sloka":"पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः।\n\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते।।6.44।।","transliteration":"pūrvābhyāsena tenaiva hriyate hyavaśho ’pi saḥ\njijñāsur api yogasya śhabda-brahmātivartate","english":"By that very previous practice he is carried forward, even against his will. Indeed, even one who merely inquires about Yoga transcends the ritualistic pronouncements of the Vedas.","hindi":"वह पूर्व के अभ्यास से ही न चाहते हुए भी योग की ओर खिंचा चला आता है। योग का जिज्ञासु भी वेदों में वर्णित कर्मकांडों के फल से ऊपर उठ जाता है।","gujarati":"તે પૂર્વના અભ્યાસને કારણે જ તે પોતાની મરજી વિરુદ્ધ પણ યોગ તરફ ખેંચાઈ આવે છે. યોગનો જિજ્ઞાસુ પણ વેદોમાં વર્ણવેલા કર્મકાંડોના ફળથી પર થઈ જાય છે."},"6.45":{"chapter":6,"verse":45,"sloka":"प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः।\n\nअनेकजन्मसंसिद्धस्ततो याति परां गतिम्।।6.45।।","transliteration":"prayatnād yatamānas tu yogī sanśhuddha-kilbiṣhaḥ\naneka-janma-sansiddhas tato yāti parāṁ gatim","english":"But the Yogi, striving with diligent effort, purified of all sins, and perfected through many births, ultimately attains the supreme goal.","hindi":"परन्तु प्रयत्नपूर्वक अभ्यास करने वाला योगी, समस्त पापों से शुद्ध होकर और अनेक जन्मों में पूर्णता को प्राप्त होकर, अन्ततः परम गति को प्राप्त कर लेता है।","gujarati":"પરંતુ પ્રયત્નપૂર્વક સાધના કરનારો યોગી, સંપૂર્ણ પાપોથી શુદ્ધ થઈને અનેક જન્મો સુધી સાધના કરીને અંતે પરમ ગતિને પ્રાપ્ત કરે છે."},"6.46":{"chapter":6,"verse":46,"sloka":"तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः।\n\nकर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन।।6.46।।","transliteration":"tapasvibhyo ’dhiko yogī\njñānibhyo ’pi mato ’dhikaḥ\nkarmibhyaśh chādhiko yogī\ntasmād yogī bhavārjuna","english":"The yogi is considered superior to the ascetics, superior to the men of knowledge, and superior to the men of action; therefore, Arjuna, become a yogi.","hindi":"योगी तपस्वियों से श्रेष्ठ है, ज्ञानियों से भी श्रेष्ठ माना गया है और सकाम कर्म करने वालों से भी योगी श्रेष्ठ है। इसलिए, हे अर्जुन, तुम योगी बनो।","gujarati":"યોગી તપસ્વીઓ કરતા શ્રેષ્ઠ છે, જ્ઞાનીઓ કરતા પણ શ્રેષ્ઠ માનવામાં આવે છે અને સકામ કર્મ કરનારાઓ કરતા પણ યોગી શ્રેષ્ઠ છે; તેથી હે અર્જુન, તું યોગી બન."},"6.47":{"chapter":6,"verse":47,"sloka":"योगिनामपि सर्वेषां मद्गतेनान्तरात्मना।\n\nश्रद्धावान्भजते यो मां स मे युक्ततमो मतः।।6.47।।","transliteration":"yoginām api sarveṣhāṁ mad-gatenāntar-ātmanā\nśhraddhāvān bhajate yo māṁ sa me yuktatamo mataḥ","english":"And of all yogis, the one who with great faith always abides in Me, thinks of Me within himself, and renders devotional service unto Me—he is the most intimately united with Me in yoga and is the highest of all.","hindi":"योगियों में भी जो श्रद्धावान योगी मुझमें स्थित होकर अंतरात्मा से मुझे भजता है, वह मुझे सबसे श्रेष्ठ और युक्ततम मान्य है।","gujarati":"બધા યોગીઓમાં જે શ્રદ્ધાવાન યોગી પોતાના અંતરાત્માથી મારામાં સ્થિત થઈને મને ભજે છે, તે મને સર્વશ્રેષ્ઠ અને યુક્તતમ માન્ય છે."},"7.1":{"chapter":7,"verse":1,"sloka":"श्री भगवानुवाच\n\nमय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः।\n\nअसंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु।।7.1।।","transliteration":"śhrī bhagavān uvācha\nmayyāsakta-manāḥ pārtha yogaṁ yuñjan mad-āśhrayaḥ\nasanśhayaṁ samagraṁ māṁ yathā jñāsyasi tach chhṛiṇu","english":"The Blessed Lord Krishna said: O Arjuna, hear how, with your mind intent on Me, practicing Yoga and taking refuge in Me, you shall know Me fully and without any doubt.","hindi":"श्रीकृष्ण ने कहा: हे अर्जुन! अब तू सुन कि किस प्रकार मुझमें मन को लगाकर, योग का अभ्यास करते हुए और मेरी शरण होकर, तू मुझे पूर्णरूपेण और बिना किसी संशय के जान सकेगा।","gujarati":"શ્રીકૃષ્ણ ભગવાને કહ્યું: હે અર્જુન! હવે તું સાંભળ કે કઈ રીતે મારામાં મન પરોવીને, યોગનો અભ્યાસ કરતા અને મારી શરણાગતિ સ્વીકારીને, તું મને સંપૂર્ણપણે અને કોઈ પણ સંશય વગર જાણી શકીશ."},"7.2":{"chapter":7,"verse":2,"sloka":"ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः।\n\nयज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते।।7.2।।","transliteration":"jñānaṁ te ’haṁ sa-vijñānam idaṁ vakṣhyāmyaśheṣhataḥ\nyaj jñātvā neha bhūyo ’nyaj jñātavyam-avaśhiṣhyate","english":"I shall declare to you in full this knowledge, together with realization, by knowing which nothing more remains to be known in this world.","hindi":"मैं तुम्हारे लिए विज्ञान सहित इस ज्ञान को पूर्ण रूप से कहूँगा, जिसको जानकर इस संसार में फिर और कुछ भी जानने योग्य शेष नहीं रहता।","gujarati":"હું તને આ વિજ્ઞાન સહિતના જ્ઞાનને પૂર્ણતા સાથે કહીશ, જેને જાણી લીધા પછી આ સંસારમાં બીજું કંઈ પણ જાણવાનું બાકી રહેતું નથી."},"7.3":{"chapter":7,"verse":3,"sloka":"मनुष्याणां सहस्रेषु कश्िचद्यतति सिद्धये।\n\nयततामपि सिद्धानां कश्िचन्मां वेत्ति तत्त्वतः।।7.3।।","transliteration":"manuṣhyāṇāṁ sahasreṣhu kaśhchid yatati siddhaye\nyatatām api siddhānāṁ kaśhchin māṁ vetti tattvataḥ","english":"Among thousands of men, hardly one strives for perfection; and of those who strive and succeed, hardly one knows Me in truth.","hindi":"सहस्रों मनुष्यों में कोई एक ही सिद्धि के लिए प्रयत्न करता है और उन प्रयत्नशील सिद्धों में भी कोई विरला ही मुझे तत्त्व से जानता है।","gujarati":"હજારો મનુષ્યોમાંથી કોઈ એકાદ જ સિદ્ધિ માટે પ્રયત્ન કરે છે, અને તે પ્રયત્નશીલ સિદ્ધોમાં પણ કોઈ એકાદ જ મને તત્વથી જાણે છે."},"7.4":{"chapter":7,"verse":4,"sloka":"भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च।\n\nअहङ्कार इतीयं मे भिन्ना प्रकृतिरष्टधा।।7.4।।","transliteration":"bhūmir-āpo ’nalo vāyuḥ khaṁ mano buddhir eva cha\nahankāra itīyaṁ me bhinnā prakṛitir aṣhṭadhā","english":"Earth, water, fire, air, ether, mind, intellect, and egoism—thus is My Nature divided eightfold.","hindi":"पृथ्वी, जल, अग्नि, वायु, आकाश, मन, बुद्धि और अहंकार - यह आठ प्रकार से विभक्त हुई मेरी अपरा प्रकृति है।","gujarati":"પૃથ્વી, જળ, અગ્નિ, વાયુ, આકાશ, મન, બુદ્ધિ અને અહંકાર - આ આઠ પ્રકારે વિભાજિત મારી અપરા પ્રકૃતિ છે."},"7.5":{"chapter":7,"verse":5,"sloka":"अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम्।\n\nजीवभूतां महाबाहो ययेदं धार्यते जगत्।।7.5।।","transliteration":"apareyam itas tvanyāṁ prakṛitiṁ viddhi me parām\njīva-bhūtāṁ mahā-bāho yayedaṁ dhāryate jagat","english":"O mighty-armed Arjuna, this is but My inferior nature; know it as distinct from My higher nature, the life-element, by which this universe is upheld.","hindi":"हे महाबाहो! यह तो मेरी अपरा (जड़) प्रकृति है। इससे भिन्न मेरी जीवरूपी परा (चेतन) प्रकृति को जानो, जिससे यह संपूर्ण जगत् धारण किया जाता है।","gujarati":"હે મહાબાહો! આ મારી અપરા (જડ) પ્રકૃતિ છે; આનાથી ભિન્ન મારી જીવરૂપી પરા (ચેતન) પ્રકૃતિને જાણો, જેના દ્વારા આ જગત ધારણ કરાયેલું છે."},"7.6":{"chapter":7,"verse":6,"sloka":"एतद्योनीनि भूतानि सर्वाणीत्युपधारय।\n\nअहं कृत्स्नस्य जगतः प्रभवः प्रलयस्तथा।।7.6।।","transliteration":"etad-yonīni bhūtāni sarvāṇītyupadhāraya\nahaṁ kṛitsnasya jagataḥ prabhavaḥ pralayas tathā","english":"Know that all living beings are born from these two natures; thus, I, Shri Krishna, am the source of the entire universe and also its dissolution.","hindi":"यह जान लो कि सम्पूर्ण प्राणी इन दो प्रकृतियों से उत्पन्न हुए हैं; इस प्रकार, मैं, श्री कृष्ण, ही इस समस्त जगत की उत्पत्ति का कारण और प्रलय का स्थान हूँ।","gujarati":"જાણી લે કે સર્વ પ્રાણીઓ આ બે પ્રકૃતિઓમાંથી જન્મેલા છે; આ રીતે, હું, શ્રી કૃષ્ણ, સમગ્ર જગતની ઉત્પત્તિ અને પ્રલયનું સ્થાન છું."},"7.7":{"chapter":7,"verse":7,"sloka":"मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय।\n\nमयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव।।7.7।।","transliteration":"mattaḥ parataraṁ nānyat kiñchid asti dhanañjaya\nmayi sarvam idaṁ protaṁ sūtre maṇi-gaṇā iva","english":"O Arjuna, there is nothing higher than Me. Everything in this universe is strung upon Me, like clusters of gems on a thread.","hindi":"हे अर्जुन! मुझसे श्रेष्ठ कुछ भी नहीं है। यह समस्त जगत सूत्र में मणियों के समान मुझमें ही पिरोया हुआ है।","gujarati":"હે અર્જુન! મારાથી શ્રેષ્ઠ બીજું કંઈ જ નથી. આ સંપૂર્ણ જગત સૂત્રમાં મણિકાઓની જેમ મારામાં જ પરોવાયેલું છે."},"7.8":{"chapter":7,"verse":8,"sloka":"रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः।\n\nप्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु।।7.8।।","transliteration":"raso ’ham apsu kaunteya prabhāsmi śhaśhi-sūryayoḥ\npraṇavaḥ sarva-vedeṣhu śhabdaḥ khe pauruṣhaṁ nṛiṣhu","english":"I am the taste in water, O Arjuna; I am the radiance of the moon and the sun; I am the syllable Om in all the Vedas, the sound in the ether, and the virility in men.","hindi":"हे अर्जुन! मैं जल में रस हूँ, सूर्य और चन्द्रमा में प्रकाश हूँ, समस्त वेदों में ओंकार हूँ, आकाश में शब्द हूँ और मनुष्यों में पौरुष हूँ।","gujarati":"હે અર્જુન! હું જળમાં રસ છું, સૂર્ય અને ચંદ્રમાં પ્રકાશ છું, તમામ વેદોમાં ઓમકાર છું, આકાશમાં શબ્દ છું અને મનુષ્યોમાં પુરુષાર્થ (વીરતા) છું."},"7.9":{"chapter":7,"verse":9,"sloka":"पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ।\n\nजीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु।।7.9।।","transliteration":"puṇyo gandhaḥ pṛithivyāṁ cha tejaśh chāsmi vibhāvasau\njīvanaṁ sarva-bhūteṣhu tapaśh chāsmi tapasviṣhu","english":"I am the original fragrance of the earth and the heat in the fire; I am the life of all that lives, and the penance of all ascetics.","hindi":"मैं पृथ्वी में पवित्र गन्ध हूँ और अग्नि में तेज हूँ। मैं ही समस्त प्राणियों का जीवन हूँ और तपस्वियों में मैं तप हूँ।","gujarati":"હું પૃથ્વીમાં પવિત્ર સુગંધ છું અને અગ્નિમાં તેજ છું; હું સર્વ ભૂતોમાં જીવન છું અને તપસ્વીઓમાં હું તપ છું."},"7.10":{"chapter":7,"verse":10,"sloka":"बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम्।\n\nबुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम्।।7.10।।","transliteration":"bījaṁ māṁ sarva-bhūtānāṁ viddhi pārtha sanātanam\nbuddhir buddhimatām asmi tejas tejasvinām aham","english":"Know Me, O Arjuna, as the eternal seed of all beings; I am the intelligence of the intelligent, and the splendour of the splendid objects.","hindi":"हे अर्जुन! तुम मुझे समस्त जीवों का सनातन बीज जानो; मैं बुद्धिमानों की बुद्धि और तेजस्वियों का तेज हूँ।","gujarati":"હે અર્જુન! તું મને સમગ્ર જીવોનું સનાતન બીજ જાણ; હું બુદ્ધિમાન પુરુષોની બુદ્ધિ અને તેજસ્વીઓનું તેજ છું."},"7.11":{"chapter":7,"verse":11,"sloka":"बलं बलवतां चाहं कामरागविवर्जितम्।\n\nधर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ।।7.11।।","transliteration":"balaṁ balavatāṁ chāhaṁ kāma-rāga-vivarjitam\ndharmāviruddho bhūteṣhu kāmo ’smi bharatarṣhabha","english":"I am the strength of the strong, devoid of desire and attachment; and in all beings, I am the desire that is in harmony with Dharma, O Arjuna.","hindi":"हे भरतश्रेष्ठ! मैं बलवानों का कामना और आसक्ति से रहित बल हूँ तथा सब प्राणियों में धर्म के अनुकूल (धर्म के विरुद्ध न होने वाला) काम हूँ।","gujarati":"હે ભરતશ્રેષ્ઠ! હું બળવાનોનું કામના અને આસક્તિથી રહિત બળ છું અને સર્વ ભૂતોમાં ધર્મની વિરુદ્ધ ન હોય તેવી કામના હું છું."},"7.12":{"chapter":7,"verse":12,"sloka":"ये चैव सात्त्विका भावा राजसास्तामसाश्च ये।\n\nमत्त एवेति तान्विद्धि नत्वहं तेषु ते मयि।।7.12।।","transliteration":"ye chaiva sāttvikā bhāvā rājasās tāmasāśh cha ye\nmatta eveti tān viddhi na tvahaṁ teṣhu te mayi","english":"Know that all states of being—whether they are of goodness (sattva), passion (rajas), or ignorance (tamas)—emanate from Me alone. Know that although they exist in Me, I am not in them, for I am beyond their influence.","hindi":"जो भी सात्त्विक, राजसिक और तामसिक भाव हैं, उन सबको तुम मेरे से ही उत्पन्न हुए जानो; वास्तव में वे मुझमें स्थित हैं, किंतु मैं उनमें नहीं हूँ।","gujarati":"જે પણ સાત્વિક, રાજસિક અને તામસિક ભાવો છે, તે બધા મારાથી જ ઉત્પન્ન થયા છે તેમ જાણો; છતાં પણ હું તેમાં નથી, તે મારામાં છે."},"7.13":{"chapter":7,"verse":13,"sloka":"त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत्।\n\nमोहितं नाभिजानाति मामेभ्यः परमव्ययम्।।7.13।।","transliteration":"tribhir guṇa-mayair bhāvair ebhiḥ sarvam idaṁ jagat\nmohitaṁ nābhijānāti māmebhyaḥ param avyayam","english":"Deluded by these three modes of nature (gunas), the entire world fails to recognize Me, who am beyond these modes and immutable.","hindi":"प्रकृति के इन तीन गुणों से उत्पन्न भावों द्वारा मोहित हुआ यह सारा संसार, इन गुणों से परे स्थित मुझ अविनाशी को नहीं जान पाता है।","gujarati":"પ્રકૃતિના ત્રણ ગુણો દ્વારા ઉત્પન્ન થયેલા આ ભાવોથી મોહિત થયેલું આખું જગત, આ ગુણોથી પર એવા અવિનાશી મને જાણી શકતું નથી."},"7.14":{"chapter":7,"verse":14,"sloka":"दैवी ह्येषा गुणमयी मम माया दुरत्यया।\n\nमामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते।।7.14।।","transliteration":"daivī hyeṣhā guṇa-mayī mama māyā duratyayā\nmām eva ye prapadyante māyām etāṁ taranti te","english":"Verily, this divine illusion of Mine, consisting of the three gunas (modes of material nature), is difficult to overcome; but those who take refuge in Me alone cross over this illusion.","hindi":"यह दैवी त्रिगुणमयी मेरी माया बड़ी दुस्तर है। परन्तु जो मेरी शरण में आते हैं, वे इस माया को पार कर जाते हैं।","gujarati":"આ મારી દૈવી ત્રિગુણમયી માયા અત્યંત દુસ્તર છે. પરંતુ જેઓ માત્ર મારે શરણે આવે છે, તેઓ આ માયાને તરી જાય છે."},"7.15":{"chapter":7,"verse":15,"sloka":"न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः।\n\nमाययापहृतज्ञाना आसुरं भावमाश्रिताः।।7.15।।","transliteration":"na māṁ duṣhkṛitino mūḍhāḥ prapadyante narādhamāḥ\nmāyayāpahṛita-jñānā āsuraṁ bhāvam āśhritāḥ","english":"Those who are miscreants, who are grossly foolish, who are lowest among mankind, whose knowledge is stolen by illusion, and who partake of the atheistic nature of demons do not surrender unto Me.","hindi":"दुष्कर्म करने वाले, मूढ़, मनुष्यों में नीच और माया के द्वारा जिनका ज्ञान हर लिया गया है, ऐसे आसुरी स्वभाव को धारण करने वाले लोग मुझे नहीं भजते हैं।","gujarati":"દુષ્કર્મ કરનારા, મૂઢ, મનુષ્યોમાં અધમ અને માયા દ્વારા જેમનું જ્ઞાન હરી લેવામાં આવ્યું છે, એવા આસુરી સ્વભાવને ધારણ કરનારા લોકો મને ભજતા નથી."},"7.16":{"chapter":7,"verse":16,"sloka":"चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन।\n\nआर्तो जिज्ञासुरर्थार्थी ज्ञानी च भरतर्षभ।।7.16।।","transliteration":"chatur-vidhā bhajante māṁ janāḥ sukṛitino ’rjuna\nārto jijñāsur arthārthī jñānī cha bharatarṣhabha","english":"Four types of virtuous people worship Me, O Arjuna: those who are distressed, those who seek knowledge, those who seek wealth, and the wise, O best of the Bharatas.","hindi":"हे भरतवंशियों में श्रेष्ठ अर्जुन! चार प्रकार के पुण्यकर्मी मनुष्य मेरा भजन करते हैं: आर्त (दुखी), जिज्ञासु (ज्ञान की इच्छा रखने वाले), अर्थार्थी (धन की कामना वाले) और ज्ञानी।","gujarati":"હે ભરતવંશી અર્જુન! ચાર પ્રકારના પુણ્યશાળી મનુષ્યો મારું ભજન કરે છે: દુઃખી, જિજ્ઞાસુ, ધન મેળવવાની ઇચ્છા રાખનારા, અને જ્ઞાની."},"7.17":{"chapter":7,"verse":17,"sloka":"तेषां ज्ञानी नित्ययुक्त एकभक्ितर्विशिष्यते।\n\nप्रियो हि ज्ञानिनोऽत्यर्थमहं स च मम प्रियः।।7.17।।","transliteration":"teṣhāṁ jñānī nitya-yukta eka-bhaktir viśhiṣhyate\npriyo hi jñānino ’tyartham ahaṁ sa cha mama priyaḥ","english":"Among these, the wise one who is ever steadfast and devoted to the One is the best; for I, Shri Krishna, am exceedingly dear to the wise, and they are dear to Me.","hindi":"उनमें भी जो नित्य मुझमें स्थित है और अनन्य भक्ति करता है, वह ज्ञानी श्रेष्ठ है, क्योंकि मैं, श्रीकृष्ण, ज्ञानी को अत्यंत प्रिय हूँ और वह मुझे अत्यंत प्रिय है।","gujarati":"તેમાં જેઓ હંમેશા મારામાં એકાગ્ર છે અને અનન્ય ભક્તિ કરે છે, તે જ્ઞાની શ્રેષ્ઠ છે, કારણ કે હું, શ્રીકૃષ્ણ, જ્ઞાનીને અત્યંત પ્રિય છું અને તે મને અત્યંત પ્રિય છે."},"7.18":{"chapter":7,"verse":18,"sloka":"उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम्।\n\nआस्थितः स हि युक्तात्मा मामेवानुत्तमां गतिम्।।7.18।।","transliteration":"udārāḥ sarva evaite jñānī tvātmaiva me matam\nāsthitaḥ sa hi yuktātmā mām evānuttamāṁ gatim","english":"All these seekers are indeed noble, but I regard the man of wisdom as My very Self. Being steadfast, he is established in Me alone as the supreme goal.","hindi":"ये सभी उदार हैं, परन्तु ज्ञानी तो साक्षात् मेरा स्वरूप ही है, ऐसा मेरा मत है; क्योंकि वह स्थिर मन वाला ज्ञानी मुझमें ही स्थित है और मुझे ही परम गति मानकर मेरा आश्रय लिए हुए है।","gujarati":"આ બધા ઉદાર છે, પરંતુ જ્ઞાની તો મારું સ્વરૂપ જ છે, એવો મારો મત છે; કારણ કે તે સ્થિર બુદ્ધિવાળો જ્ઞાની મને જ સર્વોત્તમ ગતિ માનીને મુજમાં જ સ્થિત છે."},"7.19":{"chapter":7,"verse":19,"sloka":"बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते।\n\nवासुदेवः सर्वमिति स महात्मा सुदुर्लभः।।7.19।।","transliteration":"bahūnāṁ janmanām ante jñānavān māṁ prapadyate\nvāsudevaḥ sarvam iti sa mahātmā su-durlabhaḥ","english":"After many births of spiritual practice, the man of wisdom finds refuge in Me, realizing that everything is indeed Vasudeva, the Supreme Lord. Such a great soul (Mahatma) is exceedingly rare to find.","hindi":"बहुत जन्मों के अंत में, ज्ञानवान पुरुष सब कुछ वासुदेव ही है—यह मानकर मेरी शरण में आता है; ऐसा महात्मा अत्यंत दुर्लभ है।","gujarati":"ઘણા જન્મોના અંતે, જ્ઞાની પુરુષ 'સર્વ કાંઈ વાસુદેવ જ છે' એમ જાણીને મને ભજે છે; એવો મહાત્મા અત્યંત દુર્લભ છે."},"7.20":{"chapter":7,"verse":20,"sloka":"कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः।\n\nतं तं नियममास्थाय प्रकृत्या नियताः स्वया।।7.20।।","transliteration":"kāmais tais tair hṛita-jñānāḥ prapadyante ’nya-devatāḥ\ntaṁ taṁ niyamam āsthāya prakṛityā niyatāḥ svayā","english":"Those whose knowledge has been obscured by various desires resort to other gods, observing specific vows, constrained by their own inherent nature.","hindi":"जिनकी बुद्धि सांसारिक कामनाओं द्वारा हर ली गई है, ऐसे लोग अपने स्वभाव से विवश होकर अन्य देवताओं की पूजा करते हैं और विभिन्न नियमों का पालन करते हैं।","gujarati":"જેમનું જ્ઞાન સાંસારિક કામનાઓ દ્વારા હરી લેવાયું છે, તેવા પુરુષો પોતાના સ્વભાવથી પ્રેરાઈને તે તે નિયમોનું પાલન કરીને અન્ય દેવતાઓને ભજે છે."},"7.21":{"chapter":7,"verse":21,"sloka":"यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति।\n\nतस्य तस्याचलां श्रद्धां तामेव विदधाम्यहम्।।7.21।।","transliteration":"yo yo yāṁ yāṁ tanuṁ bhaktaḥ śhraddhayārchitum ichchhati\ntasya tasyāchalāṁ śhraddhāṁ tām eva vidadhāmyaham","english":"Whatever form any devotee desires to worship with faith, I make that same faith of his firm and unflinching.","hindi":"जो कोई भी भक्त जिस-जिस देवता के स्वरूप को श्रद्धापूर्वक पूजना चाहता है, मैं उस भक्त की उस देवता के प्रति श्रद्धा को दृढ़ और स्थिर कर देता हूँ।","gujarati":"જે કોઈ પણ ભક્ત જે જે દેવતાના સ્વરૂપને શ્રદ્ધાથી પૂજવા ઈચ્છે છે, તે તે ભક્તની તે દેવતા પ્રત્યેની શ્રદ્ધાને હું અટલ અને સ્થિર બનાવું છું."},"7.22":{"chapter":7,"verse":22,"sloka":"स तया श्रद्धया युक्तस्तस्याराधनमीहते।\n\nलभते च ततः कामान्मयैव विहितान् हि तान्।।7.22।।","transliteration":"sa tayā śhraddhayā yuktas tasyārādhanam īhate\nlabhate cha tataḥ kāmān mayaiva vihitān hi tān","english":"Endowed with such faith, he engages in the worship of that deity and obtains his desires, as these benefits are verily dispensed by Me alone.","hindi":"वह उस श्रद्धा से युक्त होकर उस देवता की पूजा में संलग्न होता है और उससे अपने अभीष्ट भोगों को प्राप्त करता है, जो वास्तव में मेरे ही द्वारा प्रदान किए जाते हैं।","gujarati":"તે શ્રદ્ધાથી યુક્ત થઈને તે દેવતાની પૂજા કરે છે અને તે દેવતા દ્વારા મારા જ નિર્ધારિત કરેલા તે મનોવાંછિત ભોગોને તે પ્રાપ્ત કરે છે."},"7.23":{"chapter":7,"verse":23,"sloka":"अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम्।\n\nदेवान्देवयजो यान्ति मद्भक्ता यान्ति मामपि।।7.23।।","transliteration":"antavat tu phalaṁ teṣhāṁ tad bhavatyalpa-medhasām\ndevān deva-yajo yānti mad-bhaktā yānti mām api","english":"But the fruits gained by those of small intelligence are limited and temporary. Those who worship the celestial gods reach them, but My devotees reach Me alone.","hindi":"परन्तु उन अल्प बुद्धि वाले मनुष्यों का वह फल नाशवान ही होता है। देवताओं को पूजने वाले देवताओं को प्राप्त होते हैं, परन्तु मेरे भक्त मुझको ही प्राप्त होते हैं।","gujarati":"પરંતુ તે અલ્પ બુદ્ધિવાળા મનુષ્યોનું તે ફળ નાશવંત હોય છે. દેવતાઓને પૂજનારા દેવતાઓને પામે છે, પણ મારા ભક્તો મને જ પામે છે."},"7.24":{"chapter":7,"verse":24,"sloka":"अव्यक्तं व्यक्ितमापन्नं मन्यन्ते मामबुद्धयः।\n\nपरं भावमजानन्तो ममाव्ययमनुत्तमम्।।7.24।।","transliteration":"avyaktaṁ vyaktim āpannaṁ manyante mām abuddhayaḥ\nparaṁ bhāvam ajānanto mamāvyayam anuttamam","english":"The unintelligent think of Me, the Unmanifest, as having taken on form, not knowing My supreme, immutable, and transcendent nature.","hindi":"अबुद्धिमान लोग मेरे अनुत्तम, अविनाशी और परम स्वरूप को न जानते हुए, मुझ अव्यक्त (निराकार) को व्यक्त (साकार) हुआ मानते हैं।","gujarati":"અલ્પબુદ્ધિવાળા લોકો મારા સર્વોત્તમ, અવિનાશી અને પરમ સ્વભાવને ન જાણતા હોવાથી, મને અવ્યક્તને વ્યક્ત થયેલું માને છે."},"7.25":{"chapter":7,"verse":25,"sloka":"नाहं प्रकाशः सर्वस्य योगमायासमावृतः।\n\nमूढोऽयं नाभिजानाति लोको मामजमव्ययम्।।7.25।।","transliteration":"nāhaṁ prakāśhaḥ sarvasya yoga-māyā-samāvṛitaḥ\nmūḍho ’yaṁ nābhijānāti loko mām ajam avyayam","english":"I am not manifest to everyone, being veiled by My Yoga-Maya. This deluded world does not know Me, the unborn and imperishable.","hindi":"अपनी योगमाया से आवृत मैं सबके सामने प्रकट नहीं होता। यह मोहित संसार मुझ अजन्मे और अविनाशी को नहीं जान पाता।","gujarati":"હું મારી યોગમાયાથી ઢંકાયેલો હોવાથી બધાને પ્રગટ થતો નથી. આ મોહિત થયેલું વિશ્વ મને, જે અજન્મા અને અવિનાશી છે, તેને જાણી શકતું નથી."},"7.26":{"chapter":7,"verse":26,"sloka":"वेदाहं समतीतानि वर्तमानानि चार्जुन।\n\nभविष्याणि च भूतानि मां तु वेद न कश्चन।।7.26।।","transliteration":"vedāhaṁ samatītāni vartamānāni chārjuna\nbhaviṣhyāṇi cha bhūtāni māṁ tu veda na kaśhchana","english":"I know all beings of the past, the present, and the future, O Arjuna, but no one truly knows Me.","hindi":"हे अर्जुन! मैं बीते हुए, वर्तमान में स्थित और भविष्य में होने वाले सब प्राणियों को जानता हूँ, परन्तु मुझे कोई भी नहीं जानता।","gujarati":"હે અર્જુન! હું ભૂતકાળમાં થઈ ગયેલા, વર્તમાનમાં રહેલા અને ભવિષ્યમાં થનારા સર્વ પ્રાણીઓને જાણું છું, પરંતુ મને કોઈ પણ જાણતું નથી."},"7.27":{"chapter":7,"verse":27,"sloka":"इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन भारत।\n\nसर्वभूतानि संमोहं सर्गे यान्ति परन्तप।।7.27।।","transliteration":"ichchhā-dveṣha-samutthena dvandva-mohena bhārata\nsarva-bhūtāni sammohaṁ sarge yānti parantapa","english":"O descendant of Bharata, O conqueror of foes, all living beings are born into delusion, overcome by the dualities of desire and aversion.","hindi":"हे भरतवंशी! हे परंतप! संसार में इच्छा और द्वेष से उत्पन्न द्वंद्वों के मोह के कारण सभी प्राणी जन्म के समय से ही भ्रमित हो जाते हैं।","gujarati":"હે ભરતવંશી! હે પરંતપ! ઈચ્છા અને દ્વેષથી ઉત્પન્ન થતા દ્વંદ્વોના મોહને કારણે બધા જ જીવો જન્મથી જ ભ્રમિત થઈ જાય છે."},"7.28":{"chapter":7,"verse":28,"sloka":"येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम्।\n\nते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः।।7.28।।","transliteration":"yeṣhāṁ tvanta-gataṁ pāpaṁ janānāṁ puṇya-karmaṇām\nte dvandva-moha-nirmuktā bhajante māṁ dṛiḍha-vratāḥ","english":"But those men of virtuous deeds whose sins have come to an end, and who are freed from the delusion of the pairs of opposites, worship Me steadfastly, with their vows.","hindi":"परन्तु जिन पुण्यकर्मा पुरुषों का पाप नष्ट हो गया है, वे द्वन्द्वरूपी मोह से मुक्त होकर दृढ़ संकल्प के साथ मेरी भक्ति में लगे रहते हैं।","gujarati":"પરંતુ જે પુણ્યકર્મી મનુષ્યોના પાપ નષ્ટ થઈ ગયા છે, તેઓ દ્વંદ્વરૂપી મોહમાંથી મુક્ત થઈને દ્રઢ વ્રતવાળા બનીને મારું ભજન કરે છે."},"7.29":{"chapter":7,"verse":29,"sloka":"जरामरणमोक्षाय मामाश्रित्य यतन्ति ये।\n\nते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम्।।7.29।।","transliteration":"jarā-maraṇa-mokṣhāya mām āśhritya yatanti ye\nte brahma tadviduḥ kṛitsnam adhyātmaṁ karma chākhilam","english":"Those who strive for liberation from old age and death, taking refuge in Me, realize in full that Brahman, the whole knowledge of the Self, and all action.","hindi":"जो मेरे शरणागत होकर जरा और मरण से मुक्ति पाने के लिए यत्न करते हैं, वे पुरुष उस ब्रह्म को, सम्पूर्ण अध्यात्म को और सम्पूर्ण कर्म को जानते हैं।","gujarati":"જેઓ જરા અને મરણથી મુક્તિ મેળવવા માટે મારા શરણે આવીને પ્રયત્ન કરે છે, તે પુરુષો તે બ્રહ્મને, સંપૂર્ણ અધ્યાત્મને અને સમગ્ર કર્મ વિશે સંપૂર્ણપણે જાણે છે."},"7.30":{"chapter":7,"verse":30,"sloka":"साधिभूताधिदैवं मां साधियज्ञं च ये विदुः।\n\nप्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः।।7.30।।","transliteration":"sādhibhūtādhidaivaṁ māṁ sādhiyajñaṁ cha ye viduḥ\nprayāṇa-kāle ’pi cha māṁ te vidur yukta-chetasaḥ","english":"Those who know Me as the governing principle of the material manifestation (Adhibhuta), of the divine beings (Adhidaiva), and of the sacrifice (Adhiyajna), they—with minds steadfast in devotion—continue to know Me even at the time of death.","hindi":"जो लोग मुझे अधिभूत, अधिदैव और अधियज्ञ के रूप में जानते हैं, वे ही युक्तचित्त होकर मृत्यु के समय में भी मुझे जान पाते हैं।","gujarati":"જેઓ મને અધિભૂત, અધિદૈવ અને અધિયજ્ઞ સહિત જાણે છે, તેવા એકાગ્ર ચિત્તવાળા પુરુષો અંતકાળમાં પણ મને જ જાણે છે."},"8.1":{"chapter":8,"verse":1,"sloka":"अर्जुन उवाच\n\nकिं तद्ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम।\n\nअधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते।।8.1।।","transliteration":"arjuna uvācha\nkiṁ tad brahma kim adhyātmaṁ kiṁ karma puruṣhottama\nadhibhūtaṁ cha kiṁ proktam adhidaivaṁ kim uchyate","english":"Arjuna said: O Supreme Person, what is Brahman? What is the individual self (Adhyatma)? What is fruitive activity (Karma)? What is said to be the material manifestation (Adhibhuta)? And what is called the divine nature (Adhidaiva)?","hindi":"अर्जुन ने पूछा: हे पुरुषोत्तम! वह ब्रह्म क्या है? अध्यात्म क्या है? कर्म क्या है? अधिभूत किसे कहा गया है? और अधिदैव क्या है?","gujarati":"અર્જુને કહ્યું: હે પુરુષોત્તમ! તે બ્રહ્મ શું છે? અધ્યાત્મ શું છે? કર્મ શું છે? અધિભૂત કોને કહેવાય છે? અને અધિદૈવ શું છે?"},"8.2":{"chapter":8,"verse":2,"sloka":"अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन।\n\nप्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः।।8.2।।","transliteration":"adhiyajñaḥ kathaṁ ko ’tra dehe ’smin madhusūdana\nprayāṇa-kāle cha kathaṁ jñeyo ’si niyatātmabhiḥ","english":"Who is the Adhiyajna here in this body, O Madhusudana, and how does He dwell in this body? And how are You, the Supreme Lord, to be realized at the time of death by those who have controlled their minds?","hindi":"हे मधुसूदन! इस शरीर में अधियज्ञ कौन है और वह कैसे है? और संयत चित्त वाले पुरुषों द्वारा अंत समय में आप किस प्रकार जानने में आते हैं?","gujarati":"હે મધુસૂદન! આ શરીરમાં અધિયજ્ઞ કોણ છે અને તે આ શરીરમાં કેવી રીતે રહે છે? અને સંયમિત ચિત્તવાળા પુરુષો દ્વારા અંત સમયે આપ કેવી રીતે જાણી શકાય છે?"},"8.3":{"chapter":8,"verse":3,"sloka":"श्री भगवानुवाच\n\nअक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते।\n\nभूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः।।8.3।।","transliteration":"śhrī bhagavān uvācha\nakṣharaṁ brahma paramaṁ svabhāvo ’dhyātmam uchyate\nbhūta-bhāvodbhava-karo visargaḥ karma-sanjñitaḥ","english":"The Supreme Lord Shri Krishna said: Brahman is the Imperishable, the Supreme; its essential nature is called Adhyatma (Self-knowledge); the offering known as Visarga, which brings beings into existence and sustains them, is termed Karma (action).","hindi":"श्रीभगवान् ने कहा: परम अक्षर (विनाशरहित) तत्त्व ब्रह्म है; 'अध्यात्म' जीव का अपना स्वरूप या आत्म-ज्ञान है; और वह यज्ञ (विसर्ग) जो समस्त प्राणियों की उत्पत्ति और पोषण का कारण है, 'कर्म' कहलाता है।","gujarati":"શ્રી ભગવાને કહ્યું: પરમ અક્ષર (વિનાશરહિત) તત્વ બ્રહ્મ છે; 'અધ્યાત્મ' એ જીવનું પોતાનું સ્વરૂપ છે; અને જે યજ્ઞ (વિસર્ગ) પ્રાણીઓના અસ્તિત્વ અને પોષણનું કારણ છે, તેને 'કર્મ' કહેવામાં આવે છે."},"8.4":{"chapter":8,"verse":4,"sloka":"अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम्।\n\nअधियज्ञोऽहमेवात्र देहे देहभृतां वर।।8.4।।","transliteration":"adhibhūtaṁ kṣharo bhāvaḥ puruṣhaśh chādhidaivatam\nadhiyajño ’ham evātra dehe deha-bhṛitāṁ vara","english":"Adhibhuta—knowledge of the perishable elements—pertains to My perishable nature, the Purusha is the Adhidaiva, and I alone am the Adhiyajna dwelling within this body, O best of the embodied, Arjuna.","hindi":"हे देहधारियों में श्रेष्ठ अर्जुन! नश्वर पदार्थों का ज्ञान अधिभूत है, दिव्य पुरुष अधिदैव है, और इस शरीर में मैं स्वयं ही अधियज्ञ हूँ।","gujarati":"હે દેહધારીઓમાં શ્રેષ્ઠ અર્જુન! ક્ષર ભાવ એટલે કે નાશવંત પદાર્થોનું જ્ઞાન અધિભૂત છે, પુરુષ (જીવાત્મા) અધિદૈવ છે, અને આ શરીરમાં હું પોતે જ અધિયજ્ઞ છું."},"8.5":{"chapter":8,"verse":5,"sloka":"अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम्।\n\nयः प्रयाति स मद्भावं याति नास्त्यत्र संशयः।।8.5।।","transliteration":"anta-kāle cha mām eva smaran muktvā kalevaram\nyaḥ prayāti sa mad-bhāvaṁ yāti nāstyatra sanśhayaḥ","english":"And whoever, leaving their body, departs while remembering Me alone at the time of death, they attain My divine state of being; there is no doubt about this.","hindi":"और जो कोई पुरुष अन्तकाल में मुझे ही स्मरण करता हुआ शरीर को त्याग कर जाता है, वह मेरे स्वरूप को प्राप्त होता है, इसमें कुछ भी संशय नहीं।","gujarati":"અને જે કોઈ અંતકાળમાં મારું જ સ્મરણ કરતો શરીરનો ત્યાગ કરે છે, તે મારા સ્વરૂપને પામે છે, આમાં કોઈ પણ સંશય નથી."},"8.6":{"chapter":8,"verse":6,"sloka":"यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम्।\n\nतं तमेवैति कौन्तेय सदा तद्भावभावितः।।8.6।।","transliteration":"yaṁ yaṁ vāpi smaran bhāvaṁ tyajatyante kalevaram\ntaṁ tam evaiti kaunteya sadā tad-bhāva-bhāvitaḥ","english":"O son of Kunti (Arjuna), whatever state of being one remembers when he quits his body at the end of life, that state he will attain without fail.","hindi":"हे कौन्तेय! मनुष्य अन्तकाल में जिस-जिस भी भाव का स्मरण करते हुए शरीर त्यागता है, उस-उस भाव को ही प्राप्त होता है, क्योंकि वह सदा उसी भाव का चिन्तन करता रहता है।","gujarati":"હે કૌન્તેય! મનુષ્ય અંતકાળમાં જે જે ભાવનું સ્મરણ કરતો કરતો શરીર ત્યાગે છે, તે તે ભાવને જ પામે છે, કારણ કે તે હંમેશા તે જ ભાવનું ચિંતન કરતો રહ્યો હોય છે."},"8.7":{"chapter":8,"verse":7,"sloka":"तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च।\n\nमय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयम्।।8.7।।","transliteration":"tasmāt sarveṣhu kāleṣhu mām anusmara yudhya cha\nmayyarpita-mano-buddhir mām evaiṣhyasyasanśhayam","english":"Therefore, at all times, remember Me and perform your duty; with your mind and intellect surrendered unto Me, you shall undoubtedly attain Me.","hindi":"इसलिए, हे अर्जुन, तुम हर समय मेरा स्मरण करो और युद्ध करो। जब तुम्हारा मन और बुद्धि पूरी तरह से मुझमें समर्पित होंगे, तो तुम निःसंदेह मुझे ही प्राप्त करोगे।","gujarati":"તેથી, હે અર્જુન, તું સર્વ કાળમાં મારું સ્મરણ કર અને યુદ્ધ કર; તારું મન અને બુદ્ધિ મારામાં અર્પણ કરીને તું નિઃસંદેહ મને જ પ્રાપ્ત કરીશ."},"8.8":{"chapter":8,"verse":8,"sloka":"अभ्यासयोगयुक्तेन चेतसा नान्यगामिना।\n\nपरमं पुरुषं दिव्यं याति पार्थानुचिन्तयन्।।8.8।।","transliteration":"abhyāsa-yoga-yuktena chetasā nānya-gāminā\nparamaṁ puruṣhaṁ divyaṁ yāti pārthānuchintayan","english":"He who meditates on the Supreme Divine Person with a mind made steadfast by the practice of yoga, without allowing it to wander elsewhere, attains Him, O Arjuna.","hindi":"हे अर्जुन! जो साधक अभ्यासयोग से युक्त होकर, अन्यत्र कहीं न जाने वाले चित्त से उस परम दिव्य पुरुष का निरंतर चिंतन करता है, वह उसको ही प्राप्त होता है।","gujarati":"હે અર્જુન! જે સાધક અભ્યાસયોગથી યુક્ત થઈને, અન્યત્ર ક્યાંય ન વિચલિત થતા ચિત્તથી પરમ દિવ્ય પુરુષનું નિરંતર ચિંતન કરે છે, તે તેમને જ પામે છે."},"8.9":{"chapter":8,"verse":9,"sloka":"कविं पुराणमनुशासितार\n\nमणोरणीयांसमनुस्मरेद्यः।\n\nसर्वस्य धातारमचिन्त्यरूप\n\nमादित्यवर्णं तमसः परस्तात्।।8.9।।","transliteration":"kaviṁ purāṇam anuśhāsitāram\naṇor aṇīyānsam anusmared yaḥ\nsarvasya dhātāram achintya-rūpam\nāditya-varṇaṁ tamasaḥ parastāt","english":"He who meditates on the Omniscient, the Ancient, the Controller of all, who is subtler than the smallest atom, the Sustainer of everything, whose form is inconceivable, who is effulgent like the sun and transcendental, existing far beyond the darkness of material ignorance.","hindi":"जो पुरुष सर्वज्ञ, अनादि, सबके नियन्ता, सूक्ष्म से भी अति सूक्ष्म, सबके धारण-पोषण करने वाले, अचिन्त्य-स्वरूप, सूर्य के समान प्रकाशमान और अज्ञान रूपी अंधकार से सर्वथा परे उस परम पुरुष का निरंतर स्मरण करता है।","gujarati":"જે પુરુષ સર્વજ્ઞ, અનાદિ, સૌના નિયંતા, અણુથી પણ અતિ સૂક્ષ્મ, સૌના ધારણ-પોષણ કરનાર, અચિંત્ય સ્વરૂપ, સૂર્ય સમાન પ્રકાશિત અને અજ્ઞાનરૂપી અંધકારથી પર એવા પરમ પુરુષનું સ્મરણ કરે છે."},"8.10":{"chapter":8,"verse":10,"sloka":"प्रयाणकाले मनसाऽचलेन\n\nभक्त्या युक्तो योगबलेन चैव।\n\nभ्रुवोर्मध्ये प्राणमावेश्य सम्यक्\n\nस तं परं पुरुषमुपैति दिव्यम्।।8.10।।","transliteration":"prayāṇa-kāle manasāchalena\nbhaktyā yukto yoga-balena chaiva\nbhruvor madhye prāṇam āveśhya samyak\nsa taṁ paraṁ puruṣham upaiti divyam","english":"At the time of death, with an unwavering mind, endowed with devotion, by the power of Yoga, fixing the whole life-breath in the middle of the two eyebrows, he reaches that resplendent Supreme Person, Shri Krishna.","hindi":"मृत्यु के समय, अचल मन से, भक्ति से युक्त होकर और योगबल से प्राण को भृकुटि के मध्य में स्थापित करके, वह साधक उस परम प्रकाशमान दिव्य पुरुष, भगवान श्री कृष्ण को प्राप्त होता है।","gujarati":"મૃત્યુના સમયે, અચળ મનથી, ભક્તિથી યુક્ત થઈને અને યોગબળ દ્વારા પ્રાણને ભ્રમર મધ્યે સ્થાપિત કરીને, તે સાધક તે પરમ પ્રકાશમાન દિવ્ય પુરુષ, ભગવાન શ્રી કૃષ્ણને પ્રાપ્ત કરે છે."},"8.11":{"chapter":8,"verse":11,"sloka":"यदक्षरं वेदविदो वदन्ति\n\nविशन्ति यद्यतयो वीतरागाः।\n\nयदिच्छन्तो ब्रह्मचर्यं चरन्ति\n\nतत्ते पदं संग्रहेण प्रवक्ष्ये।।8.11।।","transliteration":"yad akṣharaṁ veda-vido vadanti\nviśhanti yad yatayo vīta-rāgāḥ\nyad ichchhanto brahmacharyaṁ charanti\ntat te padaṁ saṅgraheṇa pravakṣhye","english":"I shall briefly describe to you that goal which the knowers of the Vedas term as the Imperishable (Akshara), which the self-controlled ascetics free from passion enter, and desiring which, seekers practice celibacy (Brahmacharya).","hindi":"वेद के ज्ञाता जिसे अक्षर कहते हैं, वीतराग यत्नशील सन्यासी जिसमें प्रवेश करते हैं, और जिसे पाने की इच्छा से साधक ब्रह्मचर्य का पालन करते हैं, उस परम पद को मैं तुम्हें संक्षेप में कहूँगा।","gujarati":"વેદના જાણકારો જેને અક્ષર (અવિનાશી) કહે છે, રાગ-દ્વેષથી મુક્ત થયેલા યત્નશીલ પુરુષો જેમાં પ્રવેશ કરે છે, અને જેને પામવાની ઈચ્છાથી સાધકો બ્રહ્મચર્યનું પાલન કરે છે, તે પરમ પદ વિશે હું તને સંક્ષેપમાં કહીશ."},"8.12":{"chapter":8,"verse":12,"sloka":"सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च।\n\nमूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम्।।8.12।।","transliteration":"sarva-dvārāṇi sanyamya mano hṛidi nirudhya cha\nmūrdhnyādhāyātmanaḥ prāṇam āsthito yoga-dhāraṇām","english":"Having restrained all the doors of the senses, confining the mind within the heart, and fixing the life-breath in the head, one should remain established in the practice of yoga.","hindi":"सब इन्द्रियों के द्वारों को रोककर, मन को हृदय में स्थिर करके और अपने प्राण को मस्तक में स्थापित करके, योग की धारणा में स्थित हो जाना चाहिए।","gujarati":"બધા જ ઇન્દ્રિયોના દ્વારોને રોકીને, મનને હૃદયમાં સ્થિર કરીને અને પ્રાણને મસ્તકમાં સ્થાપિત કરીને યોગધારણામાં સ્થિત થવું જોઈએ."},"8.13":{"chapter":8,"verse":13,"sloka":"ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन्।\n\nयः प्रयाति त्यजन्देहं स याति परमां गतिम्।।8.13।।","transliteration":"oṁ ityekākṣharaṁ brahma vyāharan mām anusmaran\nyaḥ prayāti tyajan dehaṁ sa yāti paramāṁ gatim","english":"Uttering the one-syllabled Om, the Brahman, and remembering Me, he who departs, leaving the body, attains the Supreme Goal.","hindi":"जो पुरुष ओऽम् इस एक अक्षर ब्रह्म का उच्चारण करता हुआ और मेरा स्मरण करता हुआ शरीर का त्याग करता है, वह परम गति को प्राप्त होता है।","gujarati":"જે પુરુષ 'ઓમ્' એવા એકાક્ષર બ્રહ્મનો ઉચ્ચાર કરતો અને મારું સ્મરણ કરતો શરીરનો ત્યાગ કરે છે, તે પરમ ગતિને પામે છે."},"8.14":{"chapter":8,"verse":14,"sloka":"अनन्यचेताः सततं यो मां स्मरति नित्यशः।\n\nतस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः।।8.14।।","transliteration":"ananya-chetāḥ satataṁ yo māṁ smarati nityaśhaḥ\ntasyāhaṁ sulabhaḥ pārtha nitya-yuktasya yoginaḥ","english":"O Partha, I am easily attained by that constant yogi who remembers Me daily with single-minded devotion, never thinking of anything else.","hindi":"हे पार्थ! जो योगी अनन्य चित्त होकर नित्य-निरंतर मेरा ही स्मरण करता है, उस नित्ययुक्त भक्त के लिए मैं सुलभ हूँ अर्थात् सहज ही प्राप्त हो जाता हूँ।","gujarati":"હે પાર્થ! જે અનન્ય ચિત્તવાળો પુરુષ નિત્ય-નિંતર મારું સ્મરણ કરે છે, તેવા સતત યુક્ત યોગી માટે હું સુલભ છું, અર્થાત્ હું તેને સહજતાથી પ્રાપ્ત થઈ જાઉં છું."},"8.15":{"chapter":8,"verse":15,"sloka":"मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम्।\n\nनाप्नुवन्ति महात्मानः संसिद्धिं परमां गताः।।8.15।।","transliteration":"mām upetya punar janma duḥkhālayam aśhāśhvatam\nnāpnuvanti mahātmānaḥ sansiddhiṁ paramāṁ gatāḥ","english":"Having attained Me, these great souls, who are mahatmas, do not take birth again in this world, which is a transient abode of suffering, for they have achieved the ultimate perfection.","hindi":"मुझे प्राप्त करके, वे महात्माजन पुनः इस अनित्य और दुखों के घर संसार में जन्म नहीं लेते, क्योंकि उन्होंने परम सिद्धि को प्राप्त कर लिया है।","gujarati":"મને પ્રાપ્ત કરીને, તે મહાત્માઓ આ દુઃખમય અને અનિત્ય સંસારમાં પુનર્જન્મ લેતા નથી, કારણ કે તેઓએ પરમ સિદ્ધિ મેળવી લીધી છે."},"8.16":{"chapter":8,"verse":16,"sloka":"आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन।\n\nमामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते।।8.16।।","transliteration":"ā-brahma-bhuvanāl lokāḥ punar āvartino ’rjuna\nmām upetya tu kaunteya punar janma na vidyate","english":"From the realm of Brahma down to the lowest, all worlds in this universe are subject to repeated rebirth, O Arjuna; but having attained Me, O son of Kunti, there is no rebirth.","hindi":"हे अर्जुन! ब्रह्मलोक से लेकर ये सभी लोक पुनरावृत्ति वाले हैं, किंतु हे कौन्तेय! मुझे प्राप्त कर लेने पर पुनर्जन्म नहीं होता।","gujarati":"હે અર્જુન! બ્રહ્મલોક સુધીના તમામ લોક પુનરાવર્તનશીલ છે, પરંતુ હે કૌન્તેય! મને પ્રાપ્ત કર્યા પછી ફરી જન્મ થતો નથી."},"8.17":{"chapter":8,"verse":17,"sloka":"सहस्रयुगपर्यन्तमहर्यद्ब्रह्मणो विदुः।\n\nरात्रिं युगसहस्रान्तां तेऽहोरात्रविदो जनाः।।8.17।।","transliteration":"sahasra-yuga-paryantam ahar yad brahmaṇo viduḥ\nrātriṁ yuga-sahasrāntāṁ te ’ho-rātra-vido janāḥ","english":"Those who know that the day of Brahma lasts a thousand Yugas and that the night of Brahma also lasts a thousand Yugas, are the ones who truly know what day and night are.","hindi":"जो लोग ब्रह्मा जी के एक दिन की अवधि को, जो एक हजार युगों तक चलती है, और उनकी रात्रि को, जो वह भी एक हजार युगों की है, जानते हैं, वही वास्तव में दिन और रात्रि के रहस्य को जानने वाले हैं।","gujarati":"જેઓ બ્રહ્માજીના એક દિવસને એક હજાર યુગનો અને તેમની રાત્રિને પણ એક હજાર યુગની જાણે છે, તેઓ જ સાચા અર્થમાં દિવસ અને રાત્રિના જ્ઞાતા છે."},"8.18":{"chapter":8,"verse":18,"sloka":"अव्यक्ताद्व्यक्तयः सर्वाः प्रभवन्त्यहरागमे।\n\nरात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके।।8.18।।","transliteration":"avyaktād vyaktayaḥ sarvāḥ prabhavantyahar-āgame\nrātryāgame pralīyante tatraivāvyakta-sanjñake","english":"From the Unmanifested, all the manifested worlds proceed upon the arrival of the 'day'; upon the arrival of the 'night', they dissolve indeed into that which is known as the Unmanifested.","hindi":"अव्यक्त से (ब्रह्माजी के) दिन का उदय होने पर यह संपूर्ण व्यक्त संसार उत्पन्न होता है, और रात्रि का आगमन होने पर वह पुनः उसी अव्यक्त में लीन हो जाता है।","gujarati":"અવ્યક્તમાંથી દિવસના આગમન સાથે આ તમામ વ્યક્ત સૃષ્ટિ ઉત્પન્ન થાય છે, અને રાત્રિના આગમન સાથે તે ફરીથી અવ્યક્તમાં જ વિલીન થઈ જાય છે."},"8.19":{"chapter":8,"verse":19,"sloka":"भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते।\n\nरात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे।।8.19।।","transliteration":"bhūta-grāmaḥ sa evāyaṁ bhūtvā bhūtvā pralīyate\nrātryāgame ’vaśhaḥ pārtha prabhavatyahar-āgame","english":"O Arjuna, this very same multitude of beings, repeatedly coming into existence, helplessly dissolves at the arrival of the night, and again emerges at the arrival of the day, all by the will of the Supreme Lord.","hindi":"हे अर्जुन, वही यह भूत-समुदाय बार-बार उत्पन्न होकर, विवश होकर, रात्रि के आगमन पर लीन हो जाता है और दिन के आगमन पर फिर से प्रकट हो जाता है।","gujarati":"હે અર્જુન! આ જે જીવોનો સમુદાય છે, તે વારંવાર ઉત્પન્ન થઈને, લાચાર બનીને, રાત્રિના આગમન પર લય પામે છે અને દિવસના ઉદય થતા ફરી પ્રગટ થાય છે."},"8.20":{"chapter":8,"verse":20,"sloka":"परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः।\n\nयः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति।।8.20।।","transliteration":"paras tasmāt tu bhāvo ’nyo ’vyakto ’vyaktāt sanātanaḥ\nyaḥ sa sarveṣhu bhūteṣhu naśhyatsu na vinaśhyati","english":"But truly, there exists another Unmanifested, which is eternal and higher than this unmanifest; it is not destroyed even when all beings are destroyed.","hindi":"परंतु उस अव्यक्त से भी परे, एक अन्य सनातन 'अव्यक्त' भाव है, जो समस्त प्राणियों के नष्ट हो जाने पर भी कभी नष्ट नहीं होता।","gujarati":"પરંતુ તે અવ્યક્તથી પણ પરે, એક અન્ય સનાતન 'અવ્યક્ત' ભાવ છે, જે સમસ્ત ભૂતોના નાશ થવા છતાં પોતે કદી નાશ પામતો નથી."},"8.21":{"chapter":8,"verse":21,"sloka":"अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम्।\n\nयं प्राप्य न निवर्तन्ते तद्धाम परमं मम।।8.21।।","transliteration":"avyakto ’kṣhara ityuktas tam āhuḥ paramāṁ gatim\nyaṁ prāpya na nivartante tad dhāma paramaṁ mama","english":"That which is described as the Unmanifest and the Imperishable is known as the ultimate goal. Reaching It, one does not return to this world. That is My Supreme Abode.","hindi":"जो अव्यक्त और अक्षर कहा गया है, उसी को परम गति कहते हैं। जिसे प्राप्त होकर जीव पुनः इस संसार में नहीं लौटते, वह मेरा परम धाम है।","gujarati":"જેને અવ્યક્ત અને અક્ષર કહેવામાં આવે છે, તેને જ પરમ ગતિ માનવામાં આવે છે. જેને પ્રાપ્ત કરીને મનુષ્યો પાછા ફરતા નથી, તે મારું પરમ ધામ છે."},"8.22":{"chapter":8,"verse":22,"sloka":"पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया।\n\nयस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम्।।8.22।।","transliteration":"puruṣhaḥ sa paraḥ pārtha bhaktyā labhyas tvananyayā\nyasyāntaḥ-sthāni bhūtāni yena sarvam idaṁ tatam","english":"O Arjuna, that Supreme Purusha, within whom all beings reside and by whom this entire universe is pervaded, is attainable only through unswerving, exclusive devotion.","hindi":"हे अर्जुन! वह परम पुरुष, जिसके अन्तर्गत समस्त भूत हैं और जिससे यह सम्पूर्ण जगत् व्याप्त है, केवल अनन्य भक्ति के द्वारा ही प्राप्त किया जा सकता है।","gujarati":"હે અર્જુન! તે પરમ પુરુષ, જેની અંદર સર્વ ભૂતો સ્થિત છે અને જેના દ્વારા આ સમગ્ર જગત વ્યાપ્ત છે, તે માત્ર અનન્ય ભક્તિ દ્વારા જ પ્રાપ્ત કરી શકાય છે."},"8.23":{"chapter":8,"verse":23,"sloka":"यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः।\n\nप्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ।।8.23।।","transliteration":"yatra kāle tvanāvṛittim āvṛittiṁ chaiva yoginaḥ\nprayātā yānti taṁ kālaṁ vakṣhyāmi bharatarṣhabha","english":"O best of the Bharatas, I shall now declare to you the times departing at which, the Yogis either return or do not return.","hindi":"हे भरतश्रेष्ठ! अब मैं वह काल बताऊँगा, जिसमें शरीर त्यागकर जाने वाले योगी वापस लौटते हैं और वापस नहीं लौटते हैं।","gujarati":"હે ભરતશ્રેષ્ઠ! હવે હું તમને તે સમય જણાવીશ કે જેમાં શરીર છોડીને ગયેલા યોગીઓ પાછા ફરે છે અને પાછા ફરતા નથી."},"8.24":{"chapter":8,"verse":24,"sloka":"अग्निर्ज्योतिरहः शुक्लः षण्मासा उत्तरायणम्।\n\nतत्र प्रयाता गच्छन्ति ब्रह्म ब्रह्मविदो जनाः।।8.24।।","transliteration":"agnir jyotir ahaḥ śhuklaḥ ṣhaṇ-māsā uttarāyaṇam\ntatra prayātā gachchhanti brahma brahma-vido janāḥ","english":"Fire, light, daytime, the bright fortnight, and the six months of the northern solstice—those who depart through this path, knowing the Supreme Brahman, attain Brahman.","hindi":"अग्नि, ज्योति, दिन, शुक्लपक्ष और उत्तरायण के छः महीनों में, जो ब्रह्म को जानने वाले पुरुष शरीर त्यागकर जाते हैं, वे ब्रह्म को ही प्राप्त होते हैं।","gujarati":"અગ્નિ, જ્યોતિ, દિવસ, શુક્લપક્ષ અને ઉત્તરાયણના છ મહિનાના માર્ગ દ્વારા જે બ્રહ્મવેત્તા પુરુષો દેહત્યાગ કરે છે, તેઓ બ્રહ્મને પ્રાપ્ત થાય છે."},"8.25":{"chapter":8,"verse":25,"sloka":"धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम्।\n\nतत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते।।8.25।।","transliteration":"dhūmo rātris tathā kṛiṣhṇaḥ ṣhaṇ-māsā dakṣhiṇāyanam\ntatra chāndramasaṁ jyotir yogī prāpya nivartate","english":"Attaining the lunar light through smoke, the night, the dark fortnight, and the six months of the southern path of the sun, the yogi returns to the cycle of rebirth.","hindi":"धुएं, रात्रि, कृष्णपक्ष और दक्षिणायन के छह महीनों के मार्ग का अनुसरण करके, योगी चंद्रमा के प्रकाश को प्राप्त कर पुनः संसार में लौट आता है।","gujarati":"ધુમાડો, રાત્રિ, કૃષ્ણપક્ષ અને દક્ષિણાયન છ મહિનાના માર્ગ દ્વારા ચંદ્રના પ્રકાશને પ્રાપ્ત કરીને, યોગી પુનઃ જન્મ લે છે."},"8.26":{"chapter":8,"verse":26,"sloka":"शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते।\n\nएकया यात्यनावृत्तिमन्ययाऽऽवर्तते पुनः।।8.26।।","transliteration":"śhukla-kṛiṣhṇe gatī hyete jagataḥ śhāśhvate mate\nekayā yātyanāvṛittim anyayāvartate punaḥ","english":"The bright and dark paths of this world are considered eternal; by the one, a soul attains liberation from which there is no return, while by the other, the soul returns to the cycle of birth and death.","hindi":"जगत के ये शुक्ल और कृष्ण—ये दो मार्ग सनातन माने गए हैं। इनमें से एक के द्वारा जाने पर मनुष्य वापस नहीं आता, जबकि दूसरे के द्वारा जाने पर उसे पुनः जन्म-मरण के चक्र में लौटना पड़ता है।","gujarati":"જગતના આ શુક્લ અને કૃષ્ણ એવા બે માર્ગો સનાતન માનવામાં આવ્યા છે. આમાંથી એક માર્ગ દ્વારા જનાર જીવ પરત ફરતો નથી, જ્યારે બીજા માર્ગ દ્વારા જનાર જીવને ફરી જન્મ-મરણના ચક્રમાં આવવું પડે છે."},"8.27":{"chapter":8,"verse":27,"sloka":"नैते सृती पार्थ जानन्योगी मुह्यति कश्चन।\n\nतस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन।।8.27।।","transliteration":"naite sṛitī pārtha jānan yogī muhyati kaśhchana\ntasmāt sarveṣhu kāleṣhu yoga-yukto bhavārjuna","english":"Knowing these two paths, O Arjuna, no yogi becomes deluded; therefore, at all times, be steadfast in yoga.","hindi":"हे अर्जुन, इन दोनों मार्गों को तत्त्व से जानने वाला कोई भी योगी मोहित नहीं होता। इसलिए, हे अर्जुन, तुम सर्वदा योगयुक्त बनो।","gujarati":"હે અર્જુન, આ બંને માર્ગોને જાણીને કોઈ પણ યોગી મોહિત થતો નથી; તેથી, હે અર્જુન, તું સર્વકાળે યોગયુક્ત થા."},"8.28":{"chapter":8,"verse":28,"sloka":"वेदेषु यज्ञेषु तपःसु चैव\n\nदानेषु यत्पुण्यफलं प्रदिष्टम्।\n\nअत्येति तत्सर्वमिदं विदित्वा\n\nयोगी परं स्थानमुपैति चाद्यम्।।8.28।।","transliteration":"vedeṣhu yajñeṣhu tapaḥsu chaiva\ndāneṣhu yat puṇya-phalaṁ pradiṣhṭam\natyeti tat sarvam idaṁ viditvā\nyogī paraṁ sthānam upaiti chādyam","english":"Having realized this truth, the Yogi transcends all the meritorious fruits derived from the study of the Vedas, the performance of sacrifices, the practice of austerities, and the giving of charity; such a soul attains the Supreme, Primal Abode of Lord Krishna.","hindi":"योगी पुरुष इस रहस्य को जानकर वेदाध्ययन, यज्ञ, तप और दान आदि के पुण्य फलों से ऊपर उठ जाता है और वह भगवान श्रीकृष्ण के उस परम, अनादि स्थान को प्राप्त कर लेता है।","gujarati":"યોગી પુરુષ આ રહસ્યને જાણીને વેદાધ્યયન, યજ્ઞ, તપ અને દાન કરવાથી જે પુણ્યફળ પ્રાપ્ત થાય છે, તે બધાથી પર થઈ જાય છે અને ભગવાન શ્રીકૃષ્ણના તે પરમ, આદિ સ્થાનને પ્રાપ્ત કરે છે."},"9.1":{"chapter":9,"verse":1,"sloka":"श्री भगवानुवाच\n\nइदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे।\n\nज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात्।।9.1।।","transliteration":"śhrī bhagavān uvācha\nidaṁ tu te guhyatamaṁ pravakṣhyāmyanasūyave\njñānaṁ vijñāna-sahitaṁ yaj jñātvā mokṣhyase ’śhubhāt","english":"The Supreme Lord Shri Krishna said: To you, who do not find fault, I shall now declare this most confidential knowledge, combined with realization. Having known this, you shall be liberated from the miseries of material existence.","hindi":"श्रीभगवान् ने कहा: हे अर्जुन! तुम दोष-दृष्टि से रहित हो, इसलिए मैं तुम्हें इस अत्यंत गोपनीय ज्ञान को विज्ञान सहित कहूँगा, जिसे जानकर तुम संसार-बंधन रूपी अशुभ से मुक्त हो जाओगे।","gujarati":"શ્રી ભગવાન બોલ્યા: તારા જેવા દોષ-દ્રષ્ટિ રહિત ભક્ત માટે હું આ અત્યંત ગુપ્ત એવું જ્ઞાન વિજ્ઞાન સહિત કહીશ, જેને જાણીને તું સંસારના બંધનરૂપી અશુભથી મુક્ત થઈ જઈશ."},"9.2":{"chapter":9,"verse":2,"sloka":"राजविद्या राजगुह्यं पवित्रमिदमुत्तमम्।\n\nप्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम्।।9.2।।","transliteration":"rāja-vidyā rāja-guhyaṁ pavitram idam uttamam\npratyakṣhāvagamaṁ dharmyaṁ su-sukhaṁ kartum avyayam","english":"This knowledge is the king of all sciences, the most profound of all secrets, the supreme purifier, directly perceivable by the heart, consistent with eternal righteousness (dharma), very easy to perform, and everlasting.","hindi":"यह राजविद्या है, राजगुह्य है, परम पवित्र है, प्रत्यक्ष फल देने वाली है, धर्म के अनुकूल है, करने में अत्यंत सरल है और अविनाशी है।","gujarati":"આ જ્ઞાન સર્વ વિદ્યાઓનો રાજા છે, ગુપ્તમાં ગુપ્ત છે, અત્યંત પવિત્ર છે, પ્રત્યક્ષ અનુભવ કરાવી આપનારું છે, ધર્મયુક્ત છે, કરવા માટે ખૂબ જ સરળ છે અને અવિનાશી છે."},"9.3":{"chapter":9,"verse":3,"sloka":"अश्रद्दधानाः पुरुषा धर्मस्यास्य परन्तप।\n\nअप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि।।9.3।।","transliteration":"aśhraddadhānāḥ puruṣhā dharmasyāsya parantapa\naprāpya māṁ nivartante mṛityu-samsāra-vartmani","english":"Those who have no faith in this Dharma, O Parantapa, without attaining Me, return to the path of this world of death and birth.","hindi":"हे परन्तप! इस धर्म में श्रद्धारहित पुरुष मुझे प्राप्त न होकर, मृत्युरूपी संसार के चक्र में वापस लौट आते हैं।","gujarati":"હે પરંતપ! આ ધર્મમાં શ્રદ્ધા ન રાખનારા પુરુષો મને પ્રાપ્ત કર્યા વિના, મૃત્યુરૂપી સંસારના માર્ગમાં પાછા ફરે છે."},"9.4":{"chapter":9,"verse":4,"sloka":"मया ततमिदं सर्वं जगदव्यक्तमूर्तिना।\n\nमत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः।।9.4।।","transliteration":"mayā tatam idaṁ sarvaṁ jagad avyakta-mūrtinā\nmat-sthāni sarva-bhūtāni na chāhaṁ teṣhvavasthitaḥ","english":"By Me, in My unmanifest form, this entire universe is pervaded. All beings dwell within Me, yet I do not stand within them.","hindi":"मेरे द्वारा यह सम्पूर्ण जगत् मेरे अव्यक्त रूप से व्याप्त है; सभी प्राणी मुझमें स्थित हैं, किन्तु मैं उनमें स्थित नहीं हूँ।","gujarati":"મારા દ્વારા, મારા અવ્યક્ત સ્વરૂપથી આ સમગ્ર જગત વ્યાપ્ત છે; બધા જીવો મારામાં સ્થિત છે, પરંતુ હું તેમનામાં સ્થિત નથી."},"9.5":{"chapter":9,"verse":5,"sloka":"न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम्।\n\nभूतभृन्न च भूतस्थो ममात्मा भूतभावनः।।9.5।।","transliteration":"na cha mat-sthāni bhūtāni paśhya me yogam aiśhwaram\nbhūta-bhṛin na cha bhūta-stho mamātmā bhūta-bhāvanaḥ","english":"And yet, beings do not dwell in Me; behold the mystery of My divine Yoga! Although My Self is the support of all beings and the creator of all beings, It does not dwell in them.","hindi":"और वे प्राणी मुझमें स्थित नहीं हैं; मेरे ईश्वरीय योग को देखो! समस्त प्राणियों को उत्पन्न करने वाला और धारण करने वाला मेरा स्वरूप वास्तव में उन प्राणियों में स्थित नहीं है।","gujarati":"અને છતાં પ્રાણીઓ મારામાં સ્થિત નથી; મારા દિવ્ય યોગને જુઓ! જે બધા પ્રાણીઓને ઉત્પન્ન કરે છે અને ધારણ કરે છે, તે મારું આત્મતત્વ વાસ્તવમાં તે પ્રાણીઓમાં સ્થિત નથી."},"9.6":{"chapter":9,"verse":6,"sloka":"यथाऽऽकाशस्थितो नित्यं वायुः सर्वत्रगो महान्।\n\nतथा सर्वाणि भूतानि मत्स्थानीत्युपधारय।।9.6।।","transliteration":"yathākāśha-sthito nityaṁ vāyuḥ sarvatra-go mahān\ntathā sarvāṇi bhūtāni mat-sthānītyupadhāraya","english":"Just as the mighty wind, blowing everywhere, always rests in the vast ether, know that all created beings similarly rest in Me, Shri Krishna.","hindi":"जैसे सर्वत्र विचरण करने वाली महान वायु सदा आकाश में स्थित रहती है, वैसे ही तुम जानो कि सम्पूर्ण भूत मुझमें स्थित हैं।","gujarati":"જેમ સર્વત્ર વિચરણ કરતી મહાન વાયુ સદા આકાશમાં સ્થિત રહે છે, તેમ તું જાણ કે સંપૂર્ણ ભૂત મારામાં સ્થિત છે."},"9.7":{"chapter":9,"verse":7,"sloka":"सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम्।\n\nकल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम्।।9.7।।","transliteration":"sarva-bhūtāni kaunteya prakṛitiṁ yānti māmikām\nkalpa-kṣhaye punas tāni kalpādau visṛijāmyaham","english":"O Arjuna, at the end of a Kalpa, all beings merge into My Prakriti (Nature); and at the beginning of the next Kalpa, I project them forth again.","hindi":"हे अर्जुन! कल्प के अन्त में सभी प्राणी मेरी प्रकृति में लीन हो जाते हैं और कल्प के आरम्भ में, मैं उन्हें फिर से उत्पन्न करता हूँ।","gujarati":"હે અર્જુન! કલ્પના અંતમાં સર્વ ભૂતો મારી પ્રકૃતિને પામે છે અને કલ્પના આરંભમાં હું તેમને ફરીથી ઉત્પન્ન કરું છું."},"9.8":{"chapter":9,"verse":8,"sloka":"प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः।\n\nभूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात्।।9.8।।","transliteration":"prakṛitiṁ svām avaṣhṭabhya visṛijāmi punaḥ punaḥ\nbhūta-grāmam imaṁ kṛitsnam avaśhaṁ prakṛiter vaśhāt","english":"Presiding over My own material nature, I manifest again and again this entire multitude of beings, who are helpless, being subject to the laws of Nature.","hindi":"अपनी प्रकृति को वश में करके, मैं स्वभाव के वश में होकर परतन्त्र हुए इस सम्पूर्ण प्राणी-समूह को बार-बार रचता हूँ।","gujarati":"પોતાની પ્રકૃતિને વશ કરીને, હું સ્વભાવના વશમાં હોવાને કારણે પરતંત્ર એવા આ સંપૂર્ણ પ્રાણી-સમૂહને વારંવાર રચું છું."},"9.9":{"chapter":9,"verse":9,"sloka":"न च मां तानि कर्माणि निबध्नन्ति धनञ्जय।\n\nउदासीनवदासीनमसक्तं तेषु कर्मसु।।9.9।।","transliteration":"na cha māṁ tāni karmāṇi nibadhnanti dhanañjaya\nudāsīna-vad āsīnam asaktaṁ teṣhu karmasu","english":"O Arjuna, these actions do not bind Me, for I remain like one indifferent, unattached to those actions.","hindi":"हे अर्जुन! उन कर्मों में आसक्ति रहित और उदासीन के समान स्थित मुझ परमात्मा को वे कर्म नहीं बांधते हैं।","gujarati":"હે અર્જુન! તે કર્મોમાં આસક્તિ રહિત અને ઉદાસીનની જેમ રહેલા એવા મને તે કર્મો બાંધતા નથી."},"9.10":{"chapter":9,"verse":10,"sloka":"मयाऽध्यक्षेण प्रकृतिः सूयते सचराचरम्।\n\nहेतुनाऽनेन कौन्तेय जगद्विपरिवर्तते।।9.10।।","transliteration":"mayādhyakṣheṇa prakṛitiḥ sūyate sa-charācharam\nhetunānena kaunteya jagad viparivartate","english":"Under My supervision, material nature, which is My external energy, produces all moving and non-moving beings. Because of this, O Arjuna, the cosmic manifestation is created and annihilated again and again.","hindi":"हे अर्जुन! मेरी अध्यक्षता में ही प्रकृति चराचर (स्थावर और जंगम) जगत की रचना करती है, और इसी कारण यह संसार बार-बार उत्पन्न और नष्ट होता रहता है।","gujarati":"હે અર્જુન! મારી અધ્યક્ષતામાં પ્રકૃતિ આ સ્થાવર અને જંગમ જગતને રચે છે, અને આ કારણે જ આ જગત વારંવાર ઉત્પન્ન થાય છે અને નષ્ટ પામે છે."},"9.11":{"chapter":9,"verse":11,"sloka":"अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम्।\n\nपरं भावमजानन्तो मम भूतमहेश्वरम्।।9.11।।","transliteration":"avajānanti māṁ mūḍhā mānuṣhīṁ tanum āśhritam\nparaṁ bhāvam ajānanto mama bhūta-maheśhvaram","english":"Fools disregard Me, clad in human form, not knowing My higher nature as the Supreme Lord of all beings.","hindi":"समस्त भूतों के महान् ईश्वर रूप मेरे परम भाव को न जानने वाले मूढ़ लोग मनुष्य शरीरधारी मुझ श्री कृष्ण का अनादर करते हैं।","gujarati":"સમસ્ત ભૂતોના મહાન ઈશ્વરરૂપ મારા પરમ ભાવને ન જાણનારા મૂઢ લોકો મનુષ્ય શરીરધારી મારા પ્રત્યે અનાદર કરે છે."},"9.12":{"chapter":9,"verse":12,"sloka":"मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः।\n\nराक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः।।9.12।।","transliteration":"moghāśhā mogha-karmāṇo mogha-jñānā vichetasaḥ\nrākṣhasīm āsurīṁ chaiva prakṛitiṁ mohinīṁ śhritāḥ","english":"Those who are possessed of the delusive nature of demons and atheistic beings remain caught in vain hopes, vain actions, and vain knowledge, their minds bewildered and devoid of wisdom.","hindi":"वे राक्षसी और आसुरी प्रवृत्तियों वाले लोग व्यर्थ की आशा, व्यर्थ के कर्म और व्यर्थ के ज्ञान में उलझे रहते हैं; उनका विवेक नष्ट हो चुका होता है और वे मोहित रहते हैं।","gujarati":"તેઓ રાક્ષસી અને આસુરી સ્વભાવને ધારણ કરનારા છે, જેઓ નિરર્થક આશાઓ, નિરર્થક કર્મો અને નિરર્થક જ્ઞાનમાં રચ્યાપચ્યા રહે છે; તેમનું વિવેકબુદ્ધિ જ્ઞાન નાશ પામેલું હોય છે."},"9.13":{"chapter":9,"verse":13,"sloka":"महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः।\n\nभजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम्।।9.13।।","transliteration":"mahātmānas tu māṁ pārtha daivīṁ prakṛitim āśhritāḥ\nbhajantyananya-manaso jñātvā bhūtādim avyayam","english":"But the great souls, O Arjuna, partaking of My divine nature, worship Me with a single-minded devotion, knowing Me as the imperishable source of all beings.","hindi":"हे पार्थ! परन्तु दैवी प्रकृति के आश्रित महात्मा पुरुष मुझे समस्त भूतों का आदिकारण और अव्ययस्वरूप जानकर अनन्यमन से युक्त होकर मुझे भजते हैं।","gujarati":"પરંતુ હે પાર્થ! દૈવી પ્રકૃતિનો આશરો લીધેલા મહાત્માઓ મને જ સર્વ પ્રાણીઓનું અવિનાશી અને આદિકારણ જાણીને, અનન્ય મનથી મારી ભક્તિ કરે છે."},"9.14":{"chapter":9,"verse":14,"sloka":"सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः।\n\nनमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते।।9.14।।","transliteration":"satataṁ kīrtayanto māṁ yatantaśh cha dṛiḍha-vratāḥ\nnamasyantaśh cha māṁ bhaktyā nitya-yuktā upāsate","english":"Always glorifying Me, striving, firm in their vows, prostrating themselves before Me, they worship Me with steadfast devotion.","hindi":"सतत मेरा कीर्तन करते हुए, प्रयत्नशील, दृढ़व्रती पुरुष मुझे नमस्कार करते हुए, नित्ययुक्त होकर भक्तिपूर्वक मेरी उपासना करते हैं।","gujarati":"સતત મારું કીર્તન કરતા, પ્રયત્નશીલ અને દૃઢવ્રતી પુરુષો મને પ્રણામ કરતા, નિત્યયુક્ત થઈને ભક્તિપૂર્વક મારી ઉપાસના કરે છે."},"9.15":{"chapter":9,"verse":15,"sloka":"ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते।\n\nएकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम्।।9.15।।","transliteration":"jñāna-yajñena chāpyanye yajanto mām upāsate\nekatvena pṛithaktvena bahudhā viśhvato-mukham","english":"Others also, performing the sacrifice of wisdom, worship Me—the Lord whose faces are everywhere—as the non-dual One, as the distinct individual, and as the manifold cosmic form.","hindi":"अन्य ज्ञानयोगी मुझ सर्वात्मक को एक रूप में, पृथक रूप में तथा बहुविध विश्वरूप में उपासते हैं।","gujarati":"અન્ય લોકો જ્ઞાનયજ્ઞ દ્વારા મારું પૂજન કરતા, મને એકરૂપે, પૃથકરૂપે અને અનેકરૂપે—વિશ્વતોમુખ સ્વરૂપે ઉપાસે છે."},"9.16":{"chapter":9,"verse":16,"sloka":"अहं क्रतुरहं यज्ञः स्वधाऽहमहमौषधम्।\n\nमंत्रोऽहमहमेवाज्यमहमग्निरहं हुतम्।।9.16।।","transliteration":"ahaṁ kratur ahaṁ yajñaḥ svadhāham aham auṣhadham\nmantro ’ham aham evājyam aham agnir ahaṁ hutam","english":"I am the Vedic ritual (Kratu); I am the sacrifice (Yajna); I am the offering to the ancestors (Svadha); I am the medicinal herb; I am the sacred mantra; I am the clarified butter; I am the fire; and I am the act of offering.","hindi":"मैं ही क्रतु हूँ, मैं ही यज्ञ हूँ, स्वधा (पितरों का तर्पण) भी मैं हूँ, और औषध भी मैं हूँ। मन्त्र मैं हूँ, घृत मैं हूँ, अग्नि मैं हूँ और हवन रूप क्रिया भी मैं ही हूँ।","gujarati":"હું જ ક્રતુ છું, હું જ યજ્ઞ છું, હું જ પિતૃઓને અપાતું શ્રાદ્ધ (સ્વધા) છું, અને હું જ ઔષધિ છું. હું જ મંત્ર છું, હું જ ઘી છું, હું જ અગ્નિ છું અને હું જ હવનરૂપ કર્મ છું."},"9.17":{"chapter":9,"verse":17,"sloka":"पिताऽहमस्य जगतो माता धाता पितामहः।\n\nवेद्यं पवित्रमोंकार ऋक् साम यजुरेव च।।9.17।।","transliteration":"pitāham asya jagato mātā dhātā pitāmahaḥ\nvedyaṁ pavitram oṁkāra ṛik sāma yajur eva cha","english":"I am the father of this world, the mother, the dispenser of the fruits of actions, and the grandfather; the one thing to be known, the purifier, the sacred monosyllable (Om), and also the Rik, Sama, and Yajur Vedas.","hindi":"मैं ही इस जगत का पिता, माता, धाता (धारण करने वाला) और पितामह हूँ। मैं ही जानने योग्य, पवित्र ओंकार और ऋग्वेद, सामवेद तथा यजुर्वेद भी हूँ।","gujarati":"હું આ જગતનો પિતા, માતા, ધારણ કરનાર અને પિતામહ છું. હું જ જાણવા યોગ્ય, પવિત્ર ઓમકાર અને ઋગ્વેદ, સામવેદ તથા યજુર્વેદ પણ હું જ છું."},"9.18":{"chapter":9,"verse":18,"sloka":"गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत्।\n\nप्रभवः प्रलयः स्थानं निधानं बीजमव्ययम्।।9.18।।","transliteration":"gatir bhartā prabhuḥ sākṣhī nivāsaḥ śharaṇaṁ suhṛit\nprabhavaḥ pralayaḥ sthānaṁ nidhānaṁ bījam avyayam","english":"I am the goal, the supporter, the Lord, the witness, the abode, the shelter, the friend, the origin, the dissolution, the foundation, the treasure-house, and the imperishable seed.","hindi":"गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत् । प्रभवः प्रलयः स्थानं निधानं बीजमव्ययम् ॥","gujarati":"ગતિર ભરતા પ્રભુઃ સાક્ષી નિવાસઃ શરણં સુહૃત્ । પ્રભવઃ પ્રલયઃ સ્થાનં નિધાનં બીજમવ્યયમ્ ॥"},"9.19":{"chapter":9,"verse":19,"sloka":"तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च।\n\nअमृतं चैव मृत्युश्च सदसच्चाहमर्जुन।।9.19।।","transliteration":"tapāmyaham ahaṁ varṣhaṁ nigṛihṇāmyutsṛijāmi cha\namṛitaṁ chaiva mṛityuśh cha sad asach chāham arjuna","english":"I radiate heat as the sun; I withhold and send forth the rain; I am immortality and also death, existence and non-existence, O Arjuna.","hindi":"हे अर्जुन! मैं ही सूर्य के रूप में तपता हूँ; मैं ही वर्षा का आकर्षण और उत्सर्जन करता हूँ। मैं ही अमृत और मृत्यु हूँ तथा सत् और असत् भी मैं ही हूँ।","gujarati":"હે અર્જુન! હું જ સૂર્ય રૂપે તપું છું; હું જ વરસાદને રોકું છું અને વરસાવું છું. હું જ અમૃત અને મૃત્યુ છું તથા સત્ અને અસત્ પણ હું જ છું."},"9.20":{"chapter":9,"verse":20,"sloka":"त्रैविद्या मां सोमपाः पूतपापा\n\nयज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते।\n\nते पुण्यमासाद्य सुरेन्द्रलोक\n\nमश्नन्ति दिव्यान्दिवि देवभोगान्।।9.20।।","transliteration":"trai-vidyā māṁ soma-pāḥ pūta-pāpā\nyajñair iṣhṭvā svar-gatiṁ prārthayante\nte puṇyam āsādya surendra-lokam\naśhnanti divyān divi deva-bhogān","english":"Those who are well-versed in the three Vedas, who drink the Soma juice, and who are purified of sin, worship Lord Krishna through sacrifices, seeking the attainment of heaven. Having reached the holy world of the King of gods, they partake of the divine enjoyments of the celestials.","hindi":"तीनों वेदों के ज्ञाता, सोमपान करने वाले और पापों से शुद्ध हुए पुरुष, यज्ञों द्वारा मेरी पूजा करके स्वर्ग की प्राप्ति के लिए प्रार्थना करते हैं; वे अपने पुण्यों के फलस्वरूप इन्द्रलोक में पहुँचकर देवताओं के दिव्य भोगों को भोगते हैं।","gujarati":"ત્રણ વેદોના જ્ઞાતાઓ, સોમરસનું પાન કરનારા અને પાપોથી શુદ્ધ થયેલા પુરુષો, યજ્ઞો દ્વારા ભગવાન શ્રી કૃષ્ણની પૂજા કરીને સ્વર્ગની પ્રાપ્તિની ઈચ્છા રાખે છે; તેઓ પોતાના પુણ્યના ફળરૂપે ઈન્દ્રલોકને પ્રાપ્ત કરીને સ્વર્ગમાં દેવતાઓના દિવ્ય ભોગો ભોગવે છે."},"9.21":{"chapter":9,"verse":21,"sloka":"ते तं भुक्त्वा स्वर्गलोकं विशालं\n\nक्षीणे पुण्ये मर्त्यलोकं विशन्ति।\n\nएव त्रयीधर्ममनुप्रपन्ना\n\nगतागतं कामकामा लभन्ते।।9.21।।","transliteration":"te taṁ bhuktvā swarga-lokaṁ viśhālaṁ\nkṣhīṇe puṇye martya-lokaṁ viśhanti\nevaṁ trayī-dharmam anuprapannā\ngatāgataṁ kāma-kāmā labhante","english":"Having enjoyed the vast heavenly realms, they return to this mortal world when their merits are exhausted; thus, those who follow the injunctions of the three Vedas and are filled with desires for worldly objects attain only the cycle of birth and death.","hindi":"वे उस विशाल स्वर्गलोक का उपभोग करके, पुण्य क्षीण होने पर मृत्युलोक में पुनः लौट आते हैं। इस प्रकार तीनों वेदों के विधानों का पालन करने वाले और भोगों की कामना रखने वाले पुरुष बार-बार आवागमन के चक्र को ही प्राप्त होते हैं।","gujarati":"તેઓ વિશાળ સ્વર્ગલોકનો ભોગ ભોગવીને, પુણ્ય ક્ષીણ થતા મૃત્યુલોકમાં પાછા ફરે છે. આ રીતે ત્રણેય વેદોના નિયમોનું પાલન કરનારા અને વિષયોની કામના રાખનારા પુરુષો વારંવાર આવવા-જવાના ચક્રને જ પ્રાપ્ત થાય છે."},"9.22":{"chapter":9,"verse":22,"sloka":"अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते।\n\nतेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम्।।9.22।।","transliteration":"ananyāśh chintayanto māṁ ye janāḥ paryupāsate\nteṣhāṁ nityābhiyuktānāṁ yoga-kṣhemaṁ vahāmyaham","english":"But those who always worship Me with exclusive devotion, meditating on My transcendental form—to them I carry what they lack, and I preserve what they have.","hindi":"अनन्य भाव से मेरा चिन्तन करते हुए जो भक्तजन मेरी ही उपासना करते हैं, उन नित्ययुक्त पुरुषों का योग और क्षेम मैं स्वयं वहन करता हूँ।","gujarati":"જેઓ અનન્ય ચિત્તે મારું ચિંતન કરીને મારી ઉપાસના કરે છે, તેવા નિરંતર મારામાં જોડાયેલા ભક્તોના યોગ અને ક્ષેમનું વહન હું સ્વયં કરું છું."},"9.23":{"chapter":9,"verse":23,"sloka":"येऽप्यन्यदेवता भक्ता यजन्ते श्रद्धयाऽन्विताः।\n\nतेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम्।।9.23।।","transliteration":"ye ’pyanya-devatā-bhaktā yajante śhraddhayānvitāḥ\nte ’pi mām eva kaunteya yajantyavidhi-pūrvakam","english":"Even those devotees who, endowed with faith, worship other gods, they worship Me alone, O Arjuna, but in an improper manner.","hindi":"हे कौन्तेय! जो भक्त श्रद्धा से युक्त होकर अन्य देवताओं की पूजा करते हैं, वे भी वास्तव में मुझे ही पूजते हैं, किंतु उनका वह पूजन अविधिपूर्वक है।","gujarati":"હે કૌન્તેય! જે ભક્તો શ્રદ્ધાથી યુક્ત થઈને અન્ય દેવતાઓની પૂજા કરે છે, તેઓ પણ વાસ્તવમાં મને જ પૂજે છે, પરંતુ તે પૂજન વિધિહીન છે."},"9.24":{"chapter":9,"verse":24,"sloka":"अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च।\n\nन तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते।।9.24।।","transliteration":"ahaṁ hi sarva-yajñānāṁ bhoktā cha prabhureva cha\nna tu mām abhijānanti tattvenātaśh chyavanti te","english":"For I alone am the enjoyer and the Lord of all sacrifices; but those who do not recognize My true transcendental nature fall away from the path of liberation.","hindi":"सब यज्ञों का भोक्ता और स्वामी केवल मैं ही हूँ, परन्तु जो भक्त मुझे तत्त्व से नहीं जानते, वे इस संसार के चक्र में पुनः गिरते हैं।","gujarati":"હું જ તમામ યજ્ઞોનો ભોક્તા અને સ્વામી છું, પરંતુ જેઓ મને તત્ત્વથી જાણતા નથી, તેઓ આ નશ્વર સંસારમાં પાછા ફરે છે."},"9.25":{"chapter":9,"verse":25,"sloka":"यान्ति देवव्रता देवान् पितृ़न्यान्ति पितृव्रताः।\n\nभूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम्।।9.25।।","transliteration":"yānti deva-vratā devān pitṝīn yānti pitṛi-vratāḥ\nbhūtāni yānti bhūtejyā yānti mad-yājino ’pi mām","english":"Those who worship the gods go to the gods; those who worship the ancestors go to the ancestors; those who worship the spirits go to the spirits; but those who worship Me come to Me, declares Lord Krishna.","hindi":"देवताओं के पूजक देवताओं को प्राप्त होते हैं, पितरों के पूजक पितरों को प्राप्त होते हैं, भूतों के पूजक भूतों को प्राप्त होते हैं और मेरे भक्त मुझे ही प्राप्त होते हैं, ऐसा भगवान श्रीकृष्ण कहते हैं।","gujarati":"દેવતાઓને પૂજનારા દેવતાઓને પામે છે, પિતૃઓને પૂજનારા પિતૃઓને પામે છે, ભૂતોને પૂજનારા ભૂતોને પામે છે, પરંતુ મારા ભક્તો મને જ પ્રાપ્ત થાય છે, એમ ભગવાન શ્રીકૃષ્ણ કહે છે."},"9.26":{"chapter":9,"verse":26,"sloka":"पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति।\n\nतदहं भक्त्युपहृतमश्नामि प्रयतात्मनः।।9.26।।","transliteration":"patraṁ puṣhpaṁ phalaṁ toyaṁ yo me bhaktyā prayachchhati\ntadahaṁ bhaktyupahṛitam aśhnāmi prayatātmanaḥ","english":"Whoever offers Me with devotion a leaf, a flower, a fruit, or a little water, that, so offered devotedly by the pure-minded, I accept.","hindi":"जो कोई भी भक्त मेरे लिए पत्र, पुष्प, फल, जल आदि भक्ति से अर्पण करता है, उस शुद्ध मन के भक्त का वह भक्तिपूर्वक अर्पण किया हुआ (पत्र पुष्पादि) मैं प्रेमपूर्वक स्वीकार करता हूँ।","gujarati":"જે કોઈ ભક્ત મને પ્રેમપૂર્વક પત્ર, પુષ્પ, ફળ અથવા જળ અર્પણ કરે છે, તે શુદ્ધ ભાવથી અર્પણ કરેલું ભેટ હું સ્વીકારું છું."},"9.27":{"chapter":9,"verse":27,"sloka":"यत्करोषि यदश्नासि यज्जुहोषि ददासि यत्।\n\nयत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम्।।9.27।।","transliteration":"yat karoṣhi yad aśhnāsi yaj juhoṣhi dadāsi yat\nyat tapasyasi kaunteya tat kuruṣhva mad-arpaṇam","english":"Whatever you do, whatever you eat, whatever you offer in sacrifice, whatever you give, and whatever austerity you perform, O Arjuna, do it all as an offering unto Me, Shri Krishna.","hindi":"हे अर्जुन! तुम जो कुछ भी कर्म करते हो, जो कुछ खाते हो, जो कुछ हवन करते हो, जो कुछ दान देते हो और जो कुछ तप करते हो, वह सब मुझ श्री कृष्ण को ही अर्पण करो।","gujarati":"હે અર્જુન! તું જે કંઈ કર્મ કરે છે, જે કંઈ ખાય છે, જે કંઈ હોમ કરે છે, જે કંઈ દાન આપે છે અને જે કંઈ તપ કરે છે, તે બધું મને, શ્રી કૃષ્ણને જ અર્પણ કર."},"9.28":{"chapter":9,"verse":28,"sloka":"शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः।\n\nसंन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि।।9.28।।","transliteration":"śhubhāśhubha-phalair evaṁ mokṣhyase karma-bandhanaiḥ\nsannyāsa-yoga-yuktātmā vimukto mām upaiṣhyasi","english":"Thus, you shall be liberated from the bondage of actions and their good and evil fruits; with your mind steadfast in the Yoga of renunciation, and being liberated, you shall come unto Me.","hindi":"इस प्रकार तुम शुभाशुभ फलों वाले कर्म-बंधनों से मुक्त हो जाओगे; संन्यास-योग से युक्तचित्त होकर तुम मुक्त हो जाओगे और मुझे ही प्राप्त करोगे।","gujarati":"આ રીતે તું શુભ અને અશુભ ફળવાળા કર્મબંધનોથી મુક્ત થઈ જઈશ; સંન્યાસયોગથી યુક્તચિત્ત થયેલો તું મુક્ત થઈને મને જ પ્રાપ્ત કરીશ."},"9.29":{"chapter":9,"verse":29,"sloka":"समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः।\n\nये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम्।।9.29।।","transliteration":"samo ’haṁ sarva-bhūteṣhu na me dveṣhyo ’sti na priyaḥ\nye bhajanti tu māṁ bhaktyā mayi te teṣhu chāpyaham","english":"Shri Krishna says: I am impartial to all living beings; there is no one hateful or dear to Me. But those who worship Me with devotion dwell in Me, and I am also in them.","hindi":"भगवान श्री कृष्ण कहते हैं: मैं सभी प्राणियों में समान भाव से स्थित हूँ; न तो कोई मुझे अप्रिय है और न ही प्रिय। किंतु जो भक्त श्रद्धा के साथ मेरा भजन करते हैं, वे मुझमें स्थित हैं और मैं भी उनमें स्थित हूँ।","gujarati":"શ્રી કૃષ્ણ કહે છે: હું સર્વ પ્રાણીઓમાં સમાન છું; કોઈ મને અપ્રિય નથી અને કોઈ પ્રિય નથી. પરંતુ જેઓ ભક્તિપૂર્વક મારું ભજન કરે છે, તેઓ મારામાં સ્થિત છે અને હું પણ તેમાં છું."},"9.30":{"chapter":9,"verse":30,"sloka":"अपि चेत्सुदुराचारो भजते मामनन्यभाक्।\n\nसाधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः।।9.30।।","transliteration":"api chet su-durāchāro bhajate mām ananya-bhāk\nsādhur eva sa mantavyaḥ samyag vyavasito hi saḥ","english":"Even if one of very evil conduct worships Me with single-minded devotion, he is to be regarded as righteous, for he has rightly resolved.","hindi":"यदि कोई अतिशय दुराचारी भी अनन्य भाव से मेरा भक्त होकर मुझे भजता है, तो उसे साधु ही मानने योग्य है, क्योंकि उसने यथार्थ निश्चय कर लिया है।","gujarati":"જો કોઈ અતિશય દુરાચારી પણ અનન્ય ભાવે મારું ભજન કરે છે, તો તેને સાધુ જ માનવો જોઈએ, કારણ કે તેણે સાચો નિશ્ચય કર્યો છે."},"9.31":{"chapter":9,"verse":31,"sloka":"क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति।\n\nकौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति।।9.31।।","transliteration":"kṣhipraṁ bhavati dharmātmā śhaśhvach-chhāntiṁ nigachchhati\nkaunteya pratijānīhi na me bhaktaḥ praṇaśhyati","english":"He quickly becomes righteous and attains lasting peace. O Arjuna, proclaim it boldly that My devotee never perishes.","hindi":"वह शीघ्र ही धर्मात्मा हो जाता है और सदा रहने वाली शान्ति को प्राप्त होता है। हे अर्जुन, तू निश्चयपूर्वक सत्य जान कि मेरे भक्त का कभी विनाश नहीं होता।","gujarati":"તે તત્કાલ ધર્માત્મા થઈ જાય છે અને શાશ્વત શાંતિને પ્રાપ્ત કરે છે. હે અર્જુન, તું નિશ્ચયપૂર્વક સત્ય જાણ કે મારા ભક્તનો ક્યારેય વિનાશ થતો નથી."},"9.32":{"chapter":9,"verse":32,"sloka":"मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः।\n\nस्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम्।।9.32।।","transliteration":"māṁ hi pārtha vyapāśhritya ye ’pi syuḥ pāpa-yonayaḥ\nstriyo vaiśhyās tathā śhūdrās te ’pi yānti parāṁ gatim","english":"O Arjuna, those who take refuge in Me, even if they be of sinful birth—such as women, Vaisyas, and Sudras—attain the Supreme Goal.","hindi":"हे अर्जुन! जो कोई भी मेरी शरण ग्रहण करते हैं, वे चाहे पाप योनि वाले स्त्री, वैश्य या शूद्र ही क्यों न हों, वे भी परम गति को प्राप्त कर लेते हैं।","gujarati":"હે અર્જુન! જે કોઈ પણ મારો આશ્રય લે છે, પછી ભલે તે સ્ત્રી, વૈશ્ય કે શૂદ્ર જેવા પાપમય યોનિમાં જન્મેલા હોય, તો પણ તેઓ પરમ ગતિને પ્રાપ્ત કરે છે."},"9.33":{"chapter":9,"verse":33,"sloka":"किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा।\n\nअनित्यमसुखं लोकमिमं प्राप्य भजस्व माम्।।9.33।।","transliteration":"kiṁ punar brāhmaṇāḥ puṇyā bhaktā rājarṣhayas tathā\nanityam asukhaṁ lokam imaṁ prāpya bhajasva mām","english":"How much more easily, then, do holy Brahmins and devoted royal sages attain the supreme goal? Having come to this impermanent and joyless world, O Arjuna, worship Me with devotion.","hindi":"फिर पुण्यशील ब्राह्मणों तथा राजर्षियों का तो कहना ही क्या, जो भक्त हैं! अतः इस अनित्य और दुखरूप संसार में आकर तुम मेरी ही भक्ति करो।","gujarati":"ત્યારે પવિત્ર બ્રાહ્મણો અને રાજર્ષિ ભક્તોનું તો કહેવું જ શું? તેથી આ અનિત્ય અને દુઃખદાયી સંસારમાં જન્મ પામીને તું મારી જ ભક્તિ કર."},"9.34":{"chapter":9,"verse":34,"sloka":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।\n\nमामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः।।9.34।।","transliteration":"man-manā bhava mad-bhakto mad-yājī māṁ namaskuru\nmām evaiṣhyasi yuktvaivam ātmānaṁ mat-parāyaṇaḥ","english":"Engage your mind always in thinking of Me, become My devotee, worship Me, and offer your homage unto Me. Being completely absorbed in Me, surely you will come to Me.","hindi":"मुझमें मन को लगाओ, मेरे भक्त बनो, मेरी पूजा करो और मुझे नमस्कार करो। इस प्रकार मुझमें ही पूर्णतया लीन होकर और मुझे ही अपना परम लक्ष्य मानकर, तुम निश्चित ही मुझे प्राप्त हो जाओगे।","gujarati":"તારા મનને મારામાં પરોવ, મારો ભક્ત થા, મારું પૂજન કર અને મને નમસ્કાર કર. આ રીતે મારામાં પૂર્ણપણે તલ્લીન થઈને અને મને જ પરમ લક્ષ્ય માનીને, તું નિશ્ચિતપણે મને જ પ્રાપ્ત કરીશ."},"10.1":{"chapter":10,"verse":1,"sloka":"श्री भगवानुवाच\n\nभूय एव महाबाहो श्रृणु मे परमं वचः।\n\nयत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया।।10.1।।","transliteration":"śhrī bhagavān uvācha\nbhūya eva mahā-bāho śhṛiṇu me paramaṁ vachaḥ\nyatte ’haṁ prīyamāṇāya vakṣhyāmi hita-kāmyayā","english":"The Blessed Lord Shri Krishna said: Once again, O mighty-armed Arjuna, listen to My supreme word, which I will speak to you for your welfare, because you are very dear to Me.","hindi":"श्रीभगवान् ने कहा—हे महाबाहो अर्जुन! मेरे इस परम रहस्यमय और कल्याणकारी वचन को पुनः सुनो, जिसे मैं तुम पर अत्यंत प्रेम होने के कारण तुम्हारे कल्याण के लिए कहूँगा।","gujarati":"શ્રી ભગવાન બોલ્યા— હે મહાબાહુ અર્જુન! ફરી પણ મારા પરમ વચનોને સાંભળ, જે હું તારા પર અત્યંત સ્નેહ હોવાને કારણે તારા કલ્યાણ માટે કહીશ."},"10.2":{"chapter":10,"verse":2,"sloka":"न मे विदुः सुरगणाः प्रभवं न महर्षयः।\n\nअहमादिर्हि देवानां महर्षीणां च सर्वशः।।10.2।।","transliteration":"na me viduḥ sura-gaṇāḥ prabhavaṁ na maharṣhayaḥ\naham ādir hi devānāṁ maharṣhīṇāṁ cha sarvaśhaḥ","english":"Neither the hosts of the demigods nor the great sages know My origin, for I am, in every respect, the source of all the demigods and the great sages.","hindi":"न तो देवताओं का समुदाय और न ही महर्षिगण मेरी उत्पत्ति को जानते हैं, क्योंकि मैं सब प्रकार से देवताओं और महर्षियों का भी आदिकारण हूँ।","gujarati":"મારો ઉદ્ભવ ન તો દેવતાઓ જાણે છે અને ન તો મહર્ષિઓ, કારણ કે હું સર્વ પ્રકારથી દેવતાઓ અને મહર્ષિઓનો પણ આદિકારણ છું."},"10.3":{"chapter":10,"verse":3,"sloka":"यो मामजमनादिं च वेत्ति लोकमहेश्वरम्।\n\nअसम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते।।10.3।।","transliteration":"yo māmajam anādiṁ cha vetti loka-maheśhvaram\nasammūḍhaḥ sa martyeṣhu sarva-pāpaiḥ pramuchyate","english":"He who knows Me as the unborn, as the beginningless, and as the Supreme Lord of all the worlds, he alone among mortals is undeluded and becomes liberated from all sins.","hindi":"जो मुझे अजन्मा, अनादि और समस्त लोकों का महान ईश्वर जानता है, वह मनुष्यों में संमोहरहित होकर समस्त पापों से मुक्त हो जाता है।","gujarati":"જે મને અજન્મા, અનાદિ અને સમગ્ર વિશ્વના મહાન ઈશ્વર તરીકે જાણે છે, તે મનુષ્યોમાં સંમોહરહિત થઈને સર્વ પાપોમાંથી મુક્ત થઈ જાય છે."},"10.4":{"chapter":10,"verse":4,"sloka":"बुद्धिर्ज्ञानमसंमोहः क्षमा सत्यं दमः शमः।\n\nसुखं दुःखं भवोऽभावो भयं चाभयमेव च।।10.4।।","transliteration":"buddhir jñānam asammohaḥ kṣhamā satyaṁ damaḥ śhamaḥ\nsukhaṁ duḥkhaṁ bhavo ’bhāvo bhayaṁ chābhayameva cha","english":"Intellect, knowledge, absence of delusion, forgiveness, truthfulness, self-control, and calmness, as well as pleasure and pain, birth and death, fear and fearlessness—all these varied states of beings are created by Me alone.","hindi":"बुद्धि, ज्ञान, मोह का अभाव, क्षमा, सत्य, इन्द्रिय-संयम, मन का निग्रह, सुख-दुःख, उत्पत्ति और प्रलय, भय और अभय—ये सभी प्राणियों के विविध भाव मेरे द्वारा ही रचे गए हैं।","gujarati":"બુદ્ધિ, જ્ઞાન, સંમોહનો અભાવ, ક્ષમા, સત્ય, ઇન્દ્રિય સંયમ, મનનું શાંતત્વ, સુખ-દુઃખ, જન્મ અને મૃત્યુ, તથા ભય અને અભય—આ તમામ ભિન્ન પ્રકારના ભાવો મારા દ્વારા જ નિર્મિત છે."},"10.5":{"chapter":10,"verse":5,"sloka":"अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः।\n\nभवन्ति भावा भूतानां मत्त एव पृथग्विधाः।।10.5।।","transliteration":"ahiṁsā   samatā  tuṣṭis tapo dānaṁ   yaśo    'yaśaḥ  bhavanti    bhāvā   bhūtānāṁ    matta   eva pṛthag-vidhāḥ","english":"Non-injury, truthfulness, equanimity, contentment, austerity, charity, fame, and infamy—these diverse qualities of living beings are created by Me alone.","hindi":"अहिंसा, समता, तुष्टि, तप, दान, यश और अपयश; प्राणियों के ये नाना प्रकार के भाव मेरे द्वारा ही उत्पन्न होते हैं।","gujarati":"અહિંસા, સમતા, સંતોષ, તપ, દાન, યશ અને અપયશ - જીવોના આ વિવિધ ભાવો મારામાંથી જ ઉત્પન્ન થાય છે."},"10.6":{"chapter":10,"verse":6,"sloka":"महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा।\n\nमद्भावा मानसा जाता येषां लोक इमाः प्रजाः।।10.6।।","transliteration":"maharṣhayaḥ sapta pūrve chatvāro manavas tathā\nmad-bhāvā mānasā jātā yeṣhāṁ loka imāḥ prajāḥ","english":"The seven great sages, the four ancient ones, and the Manus, all possessing powers like Mine, were born from My mind; from them, all the creatures in this world have descended.","hindi":"सात महर्षि, उनसे भी पहले के चार सनकादि ऋषि और चौदह मनु—ये सभी मेरे संकल्प (मन) से उत्पन्न हुए हैं और ये सभी शक्तियाँ मुझसे ही धारण करते हैं; इस संसार में जितनी भी प्रजा है, वह इन्हीं की संतान है।","gujarati":"સાત મહર્ષિઓ, તેમનાથી પણ પૂર્વે થયેલા ચાર સનકાદિ ઋષિઓ અને મનુઓ - આ બધા મારા મનમાંથી જ ઉત્પન્ન થયા છે અને તેમનામાં રહેલી શક્તિઓ પણ મારી જ છે; આ સંસારમાં જે કંઈ પણ જીવસૃષ્ટિ છે, તે આ સૌની જ સંતાન છે."},"10.7":{"chapter":10,"verse":7,"sloka":"एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः।\n\nसोऽविकम्पेन योगेन युज्यते नात्र संशयः।।10.7।।","transliteration":"etāṁ vibhūtiṁ yogaṁ cha mama yo vetti tattvataḥ\nso ’vikampena yogena yujyate nātra sanśhayaḥ","english":"He who knows in truth this glory and power of Yoga of Mine, becomes united with Me by unwavering Yoga; there is no doubt about it.","hindi":"जो पुरुष मेरी इस ऐश्वर्यमयी विभूति और योग-शक्ति को तत्त्व से जानता है, वह निश्चल योग से युक्त हो जाता है; इसमें तनिक भी संदेह नहीं है।","gujarati":"જે પુરુષ મારી આ વિભૂતિ અને યોગને તત્ત્વથી જાણે છે, તે અવિચલ યોગથી યુક્ત થઈ જાય છે; એમાં કોઈ સંશય નથી."},"10.8":{"chapter":10,"verse":8,"sloka":"अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते।\n\nइति मत्वा भजन्ते मां बुधा भावसमन्विताः।।10.8।।","transliteration":"ahaṁ sarvasya prabhavo mattaḥ sarvaṁ pravartate\niti matvā bhajante māṁ budhā bhāva-samanvitāḥ","english":"I am the source of all; from Me everything evolves; understanding this, the wise, endowed with meditation, worship Me with all their hearts.","hindi":"मैं ही सम्पूर्ण जगत का उत्पत्ति-स्थान हूँ; मुझसे ही सब कुछ प्रवृत्त होता है। ऐसा जानकर, बुद्धिमान भक्त भाव से युक्त होकर निरंतर मेरी ही उपासना करते हैं।","gujarati":"હું સર્વનો મૂળ સ્ત્રોત છું; મારાથી જ બધું ઉત્પન્ન થાય છે. એમ જાણીને, બુદ્ધિશાળી ભક્તો ભક્તિભાવથી યુક્ત થઈને મારી જ ઉપાસના કરે છે."},"10.9":{"chapter":10,"verse":9,"sloka":"मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम्।\n\nकथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च।।10.9।।","transliteration":"mach-chittā mad-gata-prāṇā bodhayantaḥ parasparam\nkathayantaśh cha māṁ nityaṁ tuṣhyanti cha ramanti cha","english":"My devotees, whose minds are fully absorbed in Me and whose lives are dedicated to Me, always enlighten one another and talk about My glories, thereby finding eternal satisfaction and bliss.","hindi":"मेरे भक्त, जिनके चित्त और प्राण मुझमें ही पूर्णतः समर्पित हैं, वे सदा एक-दूसरे को मेरा ज्ञान कराते हुए और मेरी लीलाओं व गुणों का वर्णन करते हुए सदैव सन्तुष्ट रहते हैं और परमानन्द का अनुभव करते हैं।","gujarati":"જેમના ચિત્ત અને પ્રાણ મુજમાં જ સંપૂર્ણપણે અર્પિત છે, તેવા ભક્તો હંમેશા પરસ્પર મારો જ બોધ કરાવતા અને મારા વિશે જ વાતો કરતા પરમ સંતોષ અને આનંદનો અનુભવ કરે છે."},"10.10":{"chapter":10,"verse":10,"sloka":"तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम्।\n\nददामि बुद्धियोगं तं येन मामुपयान्ति ते।।10.10।।","transliteration":"teṣhāṁ satata-yuktānāṁ bhajatāṁ prīti-pūrvakam\ndadāmi buddhi-yogaṁ taṁ yena mām upayānti te","english":"To those who are ever steadfast, worshipping me with love, I give the yoga of discrimination, by which they come to me.","hindi":"तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम् | ददामि बुद्धियोगं तं येन मामुपयान्ति ते ||","gujarati":"જેઓ સતત મારી સાથે જોડાયેલા રહીને પ્રેમપૂર્વક મારું ભજન કરે છે, તેવા ભક્તોને હું એવો 'બુદ્ધિયોગ' આપું છું જેના દ્વારા તેઓ મને પ્રાપ્ત કરે છે."},"10.11":{"chapter":10,"verse":11,"sloka":"तेषामेवानुकम्पार्थमहमज्ञानजं तमः।\n\nनाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता।।10.11।।","transliteration":"teṣhām evānukampārtham aham ajñāna-jaṁ tamaḥ\nnāśhayāmyātma-bhāva-stho jñāna-dīpena bhāsvatā","english":"Out of mere compassion for them, I, dwelling within their hearts, destroy the darkness born of ignorance by the shining lamp of knowledge.","hindi":"उनके ऊपर अनुग्रह करने के लिए ही, मैं उनके हृदय में स्थित होकर, अज्ञानजन्य अन्धकार को प्रकाशमय ज्ञान के दीपक द्वारा नष्ट कर देता हूँ।","gujarati":"તેમના પર અનુગ્રહ કરવા માટે, હું તેમના હૃદયમાં સ્થિત રહીને, જ્ઞાનરૂપી દીપક વડે અજ્ઞાનથી જન્મેલા અંધકારનો નાશ કરું છું."},"10.12":{"chapter":10,"verse":12,"sloka":"अर्जुन उवाच\n\nपरं ब्रह्म परं धाम पवित्रं परमं भवान्।\n\nपुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम्।।10.12।।","transliteration":"arjuna uvācha\nparaṁ brahma paraṁ dhāma pavitraṁ paramaṁ bhavān\npuruṣhaṁ śhāśhvataṁ divyam ādi-devam ajaṁ vibhum","english":"Arjuna said: You are the Supreme Brahman, the supreme abode, the ultimate purifier, the eternal, divine Person, the primeval God, the unborn, and the omnipresent.","hindi":"अर्जुन ने कहा: आप परम ब्रह्म, परम धाम और परम पवित्र हैं; आप सनातन दिव्य पुरुष, आदि देव, अजन्मा और सर्वव्यापी हैं।","gujarati":"અર્જુને કહ્યું: આપ પરમ બ્રહ્મ, પરમ ધામ અને પરમ પવિત્ર છો; આપ સનાતન દિવ્ય પુરુષ, આદિ દેવ, અજન્મા અને સર્વવ્યાપી છો."},"10.13":{"chapter":10,"verse":13,"sloka":"आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा।\n\nअसितो देवलो व्यासः स्वयं चैव ब्रवीषि मे।।10.13।।","transliteration":"āhus tvām ṛiṣhayaḥ sarve devarṣhir nāradas tathā\nasito devalo vyāsaḥ svayaṁ chaiva bravīṣhi me","english":"All the sages have thus declared Thee, as also the divine sage Narada; so also Asita, Devala, and Vyasa; and now Thou Thyself dost proclaim this to me.","hindi":"अर्जुन बोले- आपको समस्त ऋषिगण, देवर्षि नारद, असित, देवल और व्यास मुनि भी साक्षात् परम ब्रह्म और पुरुषोत्तम कहते हैं, और अब आप स्वयं भी मुझे यही कह रहे हैं।","gujarati":"અર્જુન બોલ્યા- આપને સર્વ ઋષિગણ, દેવર્ષિ નારદ, અસિત, દેવલ અને વ્યાસ મુનિ પણ પરબ્રહ્મ અને પરમેશ્વર કહે છે, અને હવે આપ સ્વયં પણ મને આ જ કહી રહ્યા છો."},"10.14":{"chapter":10,"verse":14,"sloka":"सर्वमेतदृतं मन्ये यन्मां वदसि केशव।\n\nन हि ते भगवन् व्यक्ितं विदुर्देवा न दानवाः।।10.14।।","transliteration":"sarvam etad ṛitaṁ manye yan māṁ vadasi keśhava\nna hi te bhagavan vyaktiṁ vidur devā na dānavāḥ","english":"Arjuna said: O Krishna, I accept all that You have spoken to me as the absolute truth. Neither the demigods nor the demons, O Lord, can comprehend Your eternal manifestation.","hindi":"अर्जुन ने कहा: हे कृष्ण! जो कुछ भी आपने मुझसे कहा है, उसे मैं सत्य मानता हूँ। हे भगवान! न तो देवता और न ही दानव ही आपके प्राकट्य को जानते हैं।","gujarati":"અર્જુને કહ્યું: હે કૃષ્ણ! તમે મને જે કંઈ પણ કહ્યું છે તે બધું જ હું સત્ય માનું છું. હે ભગવાન! ન તો દેવો કે ન તો દાનવો જ તમારા પ્રકટીકરણને જાણી શકે છે."},"10.15":{"chapter":10,"verse":15,"sloka":"स्वयमेवात्मनाऽत्मानं वेत्थ त्वं पुरुषोत्तम।\n\nभूतभावन भूतेश देवदेव जगत्पते।।10.15।।","transliteration":"swayam evātmanātmānaṁ vettha tvaṁ puruṣhottama\nbhūta-bhāvana bhūteśha deva-deva jagat-pate","english":"Verily, Thou Thyself knowest Thyself by Thyself, O Supreme Person (Purushottama), O source of all beings (Bhuta-bhavana), O Lord of all beings (Bhutesha), O God of gods (Devadeva), O Ruler of the universe (Jagat-pate)!","hindi":"हे पुरुषोत्तम! हे भूतभावन! हे भूतेश! हे देवों के देव! हे जगत् के स्वामी! आप स्वयं ही अपने आप को अपनी योगमाया से जानते हैं।","gujarati":"હે પુરુષોત્તમ! હે ભૂતભાવન! હે ભૂતેશ! હે દેવોના દેવ! હે જગતના સ્વામી! તમે પોતે જ તમારા સ્વરૂપને તમારાથી જાણો છો."},"10.16":{"chapter":10,"verse":16,"sloka":"वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः।\n\nयाभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि।।10.16।।","transliteration":"vaktum arhasyaśheṣheṇa divyā hyātma-vibhūtayaḥ\nyābhir vibhūtibhir lokān imāṁs tvaṁ vyāpya tiṣhṭhasi","english":"Please describe to me without reserve Your divine glories, by which You pervade all these worlds and exist within them.","hindi":"आप अपनी उन दिव्य विभूतियों को विस्तारपूर्वक कहने में समर्थ हैं, जिनके द्वारा आप इन सब लोकों को व्याप्त करके स्थित हैं।","gujarati":"તમે જ તમારી એ દિવ્ય વિભૂતિઓને સંપૂર્ણ રીતે કહેવાને યોગ્ય છો, જેના દ્વારા તમે આ તમામ લોકોમાં વ્યાપ્ત થઈને સ્થિત છો."},"10.17":{"chapter":10,"verse":17,"sloka":"कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन्।\n\nकेषु केषु च भावेषु चिन्त्योऽसि भगवन्मया।।10.17।।","transliteration":"kathaṁ vidyām ahaṁ yogins tvāṁ sadā parichintayan\nkeṣhu keṣhu cha bhāveṣhu chintyo ’si bhagavan mayā","english":"How shall I, ever meditating, know You, O Yogin? In what various aspects and forms, O Blessed Lord, should I meditate upon You?","hindi":"हे योगेश्वर! मैं किस प्रकार निरंतर चिंतन करता हुआ आपको जानूँ? और हे भगवन! आप किन-किन रूपों में मेरे द्वारा चिंतन करने योग्य हैं?","gujarati":"હે યોગેશ્વર! હું કઈ રીતે સતત ધ્યાન ધરતો રહીને તમને જાણી શકું? અને હે ભગવાન! કયા કયા સ્વરૂપોમાં તમારું ચિંતન કરવું જોઈએ?"},"10.18":{"chapter":10,"verse":18,"sloka":"विस्तरेणात्मनो योगं विभूतिं च जनार्दन।\n\nभूयः कथय तृप्तिर्हि श्रृण्वतो नास्ति मेऽमृतम्।।10.18।।","transliteration":"vistareṇātmano yogaṁ vibhūtiṁ cha janārdana\nbhūyaḥ kathaya tṛiptir hi śhṛiṇvato nāsti me ’mṛitam","english":"Arjuna said: O Krishna, please tell me again in detail of Your yogic powers and glories, for I am never satiated with hearing Your nectar-like words, which give life to the soul.","hindi":"अर्जुन ने कहा: हे कृष्ण! अपनी योग-शक्ति और विभूतियों का पुनः विस्तार से वर्णन कीजिये, क्योंकि आपके अमृततुल्य वचनों को सुनते हुए मुझे तृप्ति नहीं होती, वे तो मेरे प्राणों को जीवन प्रदान करने वाले हैं।","gujarati":"અર્જુને કહ્યું: હે કૃષ્ણ! તમારી યોગશક્તિ અને વિભૂતિઓનું ફરીથી વિસ્તારપૂર્વક વર્ણન કરો, કારણ કે તમારા અમૃતમય વચનો સાંભળવાથી મને તૃપ્તિ થતી નથી."},"10.19":{"chapter":10,"verse":19,"sloka":"श्री भगवानुवाच\n\nहन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः।\n\nप्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे।।10.19।।","transliteration":"śhrī bhagavān uvācha\nhanta te kathayiṣhyāmi divyā hyātma-vibhūtayaḥ\nprādhānyataḥ kuru-śhreṣhṭha nāstyanto vistarasya me","english":"The Blessed Lord Krishna said: 'Very well, I shall now declare to you My divine glories, O Arjuna, but only those which are prominent; for there is no end to My infinite expansion.'","hindi":"श्रीभगवान् ने कहा - हन्त! अब मैं तुमसे अपनी दिव्य विभूतियों को प्रधानता से कहूँगा, हे अर्जुन! क्योंकि मेरे विस्तार का कोई अन्त नहीं है।","gujarati":"શ્રી ભગવાન બોલ્યા: 'હે અર્જુન! હવે હું તને મારી દિવ્ય વિભૂતિઓનું વર્ણન સંભળાવીશ, જે મુખ્ય છે; કારણ કે મારા અનંત વિસ્તારનો કોઈ અંત નથી.'"},"10.20":{"chapter":10,"verse":20,"sloka":"अहमात्मा गुडाकेश सर्वभूताशयस्थितः।\n\nअहमादिश्च मध्यं च भूतानामन्त एव च।।10.20।।","transliteration":"aham ātmā guḍākeśha sarva-bhūtāśhaya-sthitaḥ\naham ādiśh cha madhyaṁ cha bhūtānām anta eva cha","english":"I am the Self, O Gudakesa, seated in the hearts of all beings; I am the beginning, the middle, and the end of all beings.","hindi":"हे गुडाकेश! मैं समस्त भूतों के हृदय में स्थित सबकी आत्मा हूँ तथा सम्पूर्ण भूतों का आदि, मध्य और अन्त भी मैं ही हूँ।","gujarati":"હે ગુડાકેશ! હું સર્વ પ્રાણીઓના હૃદયમાં સ્થિત આત્મા છું અને હું જ બધા પ્રાણીઓનો આદિ, મધ્ય તથા અંત પણ છું."},"10.21":{"chapter":10,"verse":21,"sloka":"आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान्।\n\nमरीचिर्मरुतामस्मि नक्षत्राणामहं शशी।।10.21।।","transliteration":"ādityānām ahaṁ viṣhṇur jyotiṣhāṁ ravir anśhumān\nmarīchir marutām asmi nakṣhatrāṇām ahaṁ śhaśhī","english":"Among the twelve Adityas, I am Vishnu; among luminaries, the radiant sun; among the Maruts, I am Marichi; and among the stars, I am the moon.","hindi":"मैं बारह आदित्यों में विष्णु हूँ और प्रकाशमानों में सूर्य हूँ। मैं मरुतों में मरीचि हूँ और नक्षत्रों में चंद्रमा हूँ।","gujarati":"હું બાર આદિત્યોમાં વિષ્ણુ છું, અને પ્રકાશમાન પદાર્થોમાં કિરણોવાળો સૂર્ય છું. હું મરુતોમાં મરીચિ છું અને નક્ષત્રોમાં ચંદ્ર છું."},"10.22":{"chapter":10,"verse":22,"sloka":"वेदानां सामवेदोऽस्मि देवानामस्मि वासवः।\n\nइन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना।।10.22।।","transliteration":"vedānāṁ sāma-vedo ’smi devānām asmi vāsavaḥ\nindriyāṇāṁ manaśh chāsmi bhūtānām asmi chetanā","english":"Among the Vedas, I am the Sama-Veda; among the gods, I am Vasava; among the senses, I am the mind; and among living beings, I am the consciousness that dwells within.","hindi":"मैं वेदों में सामवेद हूँ, देवताओं में इन्द्र हूँ; मैं इन्द्रियों में मन और प्राणियों में चेतना (ज्ञानशक्ति) हूँ।","gujarati":"વેદોમાં હું સામવેદ છું, દેવોમાં ઇન્દ્ર છું, ઇન્દ્રિયોમાં હું મન છું અને પ્રાણીઓમાં હું ચેતના છું."},"10.23":{"chapter":10,"verse":23,"sloka":"रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम्।\n\nवसूनां पावकश्चास्मि मेरुः शिखरिणामहम्।।10.23।।","transliteration":"rudrāṇāṁ śhaṅkaraśh chāsmi vitteśho yakṣha-rakṣhasām\nvasūnāṁ pāvakaśh chāsmi meruḥ śhikhariṇām aham","english":"Among the Rudras, I am Shankara; among the Yakshas and Rakshasas, I am Kubera, the Lord of Wealth; among the Vasus, I am Pavaka (Fire); and among the mountains, I am Meru.","hindi":"रुद्राणां शंकरश्चास्मि वित्तेशो यक्षरक्षसाम् | वसूनां पावकश्चास्मि मेरुः शिखरिणामहम् || (मैं रुद्रों में शंकर हूँ, यक्ष और राक्षसों में धन का स्वामी कुबेर हूँ, वसुओं में मैं अग्नि हूँ और ऊँचे पर्वतों में मेरु पर्वत हूँ।)","gujarati":"રૂદ્રોમાં હું શંકર છું, યક્ષ અને રાક્ષસોમાં ધનનો સ્વામી કુબેર છું, વસુઓમાં હું અગ્નિ છું અને પર્વતોમાં હું મેરુ છું."},"10.24":{"chapter":10,"verse":24,"sloka":"पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम्।\n\nसेनानीनामहं स्कन्दः सरसामस्मि सागरः।।10.24।।","transliteration":"purodhasāṁ cha mukhyaṁ māṁ viddhi pārtha bṛihaspatim\nsenānīnām ahaṁ skandaḥ sarasām asmi sāgaraḥ","english":"Among the household priests, O Arjuna, know Me to be the chief, Brihaspati; among army generals, I am Skanda, and among water reservoirs, I am the ocean.","hindi":"हे अर्जुन! पुरोहितों में तुम मुझे मुख्य बृहस्पति जानो, सेनापतियों में मैं स्कन्द हूँ और जलाशयों में मैं समुद्र हूँ।","gujarati":"હે અર્જુન! પુરોહિતોમાં તું મને મુખ્ય બૃહસ્પતિ જાણ, સેનાપતિઓમાં હું સ્કંદ છું અને જળાશયોમાં હું સમુદ્ર છું."},"10.25":{"chapter":10,"verse":25,"sloka":"महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम्।\n\nयज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः।।10.25।।","transliteration":"maharṣhīṇāṁ bhṛigur ahaṁ girām asmyekam akṣharam\nyajñānāṁ japa-yajño ’smi sthāvarāṇāṁ himālayaḥ","english":"Among the great sages I am Bhrigu; among words I am the one-syllable Om; among sacrifices I am the sacrifice of silent repetition (Japa-yajna); among immovable things I am the Himalayas.","hindi":"महर्षियों में मैं भृगु हूँ, शब्दों में मैं एकाक्षर ओंकार हूँ। यज्ञों में मैं जपयज्ञ हूँ और स्थावर (अचल) वस्तुओं में मैं हिमालय हूँ।","gujarati":"મહર્ષિઓમાં હું ભૃગુ છું, શબ્દોમાં હું એકાક્ષર ઓમકાર છું. યજ્ઞોમાં હું જપયજ્ઞ છું અને સ્થાવર વસ્તુઓમાં હું હિમાલય છું."},"10.26":{"chapter":10,"verse":26,"sloka":"अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः।\n\nगन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः।।10.26।।","transliteration":"aśhvatthaḥ sarva-vṛikṣhāṇāṁ devarṣhīṇāṁ cha nāradaḥ\ngandharvāṇāṁ chitrarathaḥ siddhānāṁ kapilo muniḥ","english":"Among all the trees, I am the Peepul; among the divine sages, I am Narada; among the Gandharvas, I am Chitraratha; and among the perfected beings, I am the sage Kapila.","hindi":"मैं समस्त वृक्षों में अश्वत्थ (पीपल) हूँ, देवर्षियों में नारद हूँ, गन्धर्वों में चित्ररथ हूँ और सिद्धों में कपिल मुनि हूँ।","gujarati":"વૃક્ષોમાં હું અશ્વત્થ (પીપળો) છું, દેવર્ષિઓમાં નારદ છું, ગંધર્વોમાં ચિત્રરથ છું અને સિદ્ધ પુરુષોમાં કપિલ મુનિ છું."},"10.27":{"chapter":10,"verse":27,"sloka":"उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम्।\n\nऐरावतं गजेन्द्राणां नराणां च नराधिपम्।।10.27।।","transliteration":"uchchaiḥśhravasam aśhvānāṁ viddhi mām amṛitodbhavam\nairāvataṁ gajendrāṇāṁ narāṇāṁ cha narādhipam","english":"Know Me to be Ucchaisravas, born of nectar, among horses; Airavata among lordly elephants; and the king among men.","hindi":"उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम् । ऐरावतं गजेन्द्राणां नराणां च नराधिपम् ॥","gujarati":"અશ્વોમાં મને અમૃતમાંથી ઉત્પન્ન થયેલા ઉચ્ચૈઃશ્રવા, હાથીઓમાં ઐરાવત અને મનુષ્યોમાં રાજા જાણો."},"10.28":{"chapter":10,"verse":28,"sloka":"आयुधानामहं वज्रं धेनूनामस्मि कामधुक्।\n\nप्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः।।10.28।।","transliteration":"āyudhānām ahaṁ vajraṁ dhenūnām asmi kāmadhuk\nprajanaśh chāsmi kandarpaḥ sarpāṇām asmi vāsukiḥ","english":"Of weapons I am the thunderbolt, and among cows I am Kamadhenu. I am Kandarpa, the cause of procreation, and among serpents I am Vasuki.","hindi":"मैं शस्त्रों में वज्र हूँ, धेनुओं में कामधेनु हूँ, संतान उत्पन्न करने का कारण कामदेव मैं हूँ और सर्पों में वासुकि हूँ।","gujarati":"હું શસ્ત્રોમાં વજ્ર છું, ગાયોમાં કામધેનુ છું, પ્રજા ઉત્પત્તિનું કારણ કામદેવ હું છું અને સર્પોમાં વાસુકી છું."},"10.29":{"chapter":10,"verse":29,"sloka":"अनन्तश्चास्मि नागानां वरुणो यादसामहम्।\n\nपितृ़णामर्यमा चास्मि यमः संयमतामहम्।।10.29।।","transliteration":"anantaśh chāsmi nāgānāṁ varuṇo yādasām aham\npitṝīṇām aryamā chāsmi yamaḥ sanyamatām aham","english":"I am Ananta among the Nagas; I am Varuna among water-deities; Aryaman among the Manes; and among the regulators, I am Yama.","hindi":"मैं नागों में अनन्त (शेषनाग) हूँ, जल के देवताओं में वरुण हूँ, पितरों में अर्यमा हूँ और शासन करने वालों में यमराज हूँ।","gujarati":"હું નાગોમાં અનંત (શેષનાગ) છું, જળના દેવતાઓમાં વરુણ છું, પિતૃઓમાં અર્ચમા છું અને શાસન કરનારાઓમાં યમરાજ છું."},"10.30":{"chapter":10,"verse":30,"sloka":"प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम्।\n\nमृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम्।।10.30।।","transliteration":"prahlādaśh chāsmi daityānāṁ kālaḥ kalayatām aham\nmṛigāṇāṁ cha mṛigendro ’haṁ vainateyaśh cha pakṣhiṇām","english":"I am Prahlada among the demons, and I am Time among the reckoners; among beasts I am the lion, and I am Vainateya (Garuda) among birds.","hindi":"मैं दैत्यों में प्रह्लाद और गणना करने वालों में काल हूँ, मैं पशुओं में सिंह हूँ और पक्षियों में गरुड़ हूँ।","gujarati":"હું દૈત્યોમાં પ્રહ્લાદ અને ગણતરી કરનારાઓમાં કાળ છું; પશુઓમાં હું સિંહ છું અને પક્ષીઓમાં ગરુડ છું."},"10.31":{"chapter":10,"verse":31,"sloka":"पवनः पवतामस्मि रामः शस्त्रभृतामहम्।\n\nझषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी।।10.31।।","transliteration":"pavanaḥ pavatām asmi rāmaḥ śhastra-bhṛitām aham\njhaṣhāṇāṁ makaraśh chāsmi srotasām asmi jāhnavī","english":"Among those who purify, I am the wind; among the wielders of weapons, I am Rama; among the fishes, I am the shark, and among the rivers, I am the Ganga.","hindi":"पवित्र करने वालों में मैं वायु हूँ, शस्त्रधारियों में मैं राम हूँ, जलचरों में मैं मगरमच्छ हूँ और नदियों में मैं गंगा हूँ।","gujarati":"પવિત્ર કરનારાઓમાં હું પવન છું, શસ્ત્રધારીઓમાં હું રામ છું, જળચરોમાં હું મગરમચ્છ છું અને નદીઓમાં હું ગંગા છું."},"10.32":{"chapter":10,"verse":32,"sloka":"सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन।\n\nअध्यात्मविद्या विद्यानां वादः प्रवदतामहम्।।10.32।।","transliteration":"sargāṇām ādir antaśh cha madhyaṁ chaivāham arjuna\nadhyātma-vidyā vidyānāṁ vādaḥ pravadatām aham","english":"Of all creations, I am the beginning, the end, and also the middle, O Arjuna. Of all sciences, I am the science of the Self (Adhyatma-vidya), and of those who engage in debate, I am the conclusive truth.","hindi":"हे अर्जुन! सृष्टियों का आदि, अन्त और मध्य भी मैं ही हूँ। समस्त विद्याओं में मैं अध्यात्म-विद्या हूँ और परस्पर विवाद करने वालों में मैं तत्व-निर्णायक वाद हूँ।","gujarati":"હે અર્જુન! હું સૃષ્ટિઓનું આદિ, મધ્ય અને અંત પણ છું. હું વિદ્યાઓમાં આત્મવિદ્યા છું અને વાદ-વિવાદ કરનારાઓમાં હું તત્વનો નિર્ણય કરનાર સંવાદ છું."},"10.33":{"chapter":10,"verse":33,"sloka":"अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च।\n\nअहमेवाक्षयः कालो धाताऽहं विश्वतोमुखः।।10.33।।","transliteration":"अहमेवाक्षय: कालो धाताहं विश्वतोमुख: || 33||\n\nakṣharāṇām a-kāro ’smi dvandvaḥ sāmāsikasya cha\naham evākṣhayaḥ kālo dhātāhaṁ viśhvato-mukhaḥ","english":"Among the letters of the alphabet, I am the letter 'A' and the dual among compounds. I am verily the inexhaustible and everlasting time; I am the dispenser of the fruits of actions, having faces in all directions.","hindi":"मैं अक्षरों में 'अ' हूँ और समासों में द्वन्द्व समास हूँ; मैं ही अक्षय काल हूँ और मैं ही सब ओर मुख वाला सबका धारण-पोषण करने वाला विधाता हूँ।","gujarati":"અક્ષરોમાં હું 'અ'કાર છું અને સમાસોમાં દ્વન્દ્વ સમાસ છું. હું જ અવિનાશી કાળ છું અને હું જ સર્વ દિશાઓમાં મુખવાળો, સૌનું પાલન-પોષણ કરનાર વિધાતા છું."},"10.34":{"chapter":10,"verse":34,"sloka":"मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम्।\n\nकीर्तिः श्रीर्वाक्च नारीणां स्मृतिर्मेधा धृतिः क्षमा।।10.34।।","transliteration":"mṛityuḥ sarva-haraśh chāham udbhavaśh cha bhaviṣhyatām\nkīrtiḥ śhrīr vāk cha nārīṇāṁ smṛitir medhā dhṛitiḥ kṣhamā","english":"I am all-devouring death, and I am the origin of all things that are yet to be. Among feminine qualities, I am fame, prosperity, speech, memory, intelligence, steadfastness, and forgiveness.","hindi":"मैं सबका नाश करने वाली मृत्यु हूँ और जो आगे होने वाले हैं, उनकी उत्पत्ति का कारण भी मैं ही हूँ। स्त्रियों में मैं कीर्ति, श्री, वाणी, स्मृति, मेधा, धृति और क्षमा हूँ।","gujarati":"હું સર્વનો નાશ કરનાર મૃત્યુ છું અને જેઓ ભવિષ્યમાં થનારા છે તેમનું ઉત્પત્તિનું કારણ પણ હું જ છું. સ્ત્રીઓમાં હું કીર્તિ, શ્રી, વાણી, સ્મૃતિ, મેધા, ધૃતિ અને ક્ષમા છું."},"10.35":{"chapter":10,"verse":35,"sloka":"बृहत्साम तथा साम्नां गायत्री छन्दसामहम्।\n\nमासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः।।10.35।।","transliteration":"bṛihat-sāma tathā sāmnāṁ gāyatrī chhandasām aham\nmāsānāṁ mārga-śhīrṣho ’ham ṛitūnāṁ kusumākaraḥ","english":"Among the hymns, I am the Brihat-saman; among the meters, I am the Gayatri; among the months, I am Margashirsha; and among the seasons, I am the flowery spring.","hindi":"मैं सामवेदों में बृहत्साम हूँ और छन्दों में गायत्री छन्द हूँ; मैं महीनों में मार्गशीर्ष हूँ और ऋतुओं में वसन्त हूँ।","gujarati":"હું સામવેદના મંત્રોમાં બૃહત્સામ છું અને છંદોમાં ગાયત્રી છંદ છું; મહિનાઓમાં હું માગશર મહિનો છું અને ઋતુઓમાં વસંત છું."},"10.36":{"chapter":10,"verse":36,"sloka":"द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम्।\n\nजयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम्।।10.36।।","transliteration":"dyūtaṁ chhalayatām asmi tejas tejasvinām aham\njayo ’smi vyavasāyo ’smi sattvaṁ sattvavatām aham","english":"I am the gambling of the deceitful, the splendor of the splendid, I am victory, I am the resolve of the resolute, and I am the goodness of the good.","hindi":"मैं छल करने वालों का द्यूत (जुआ) हूँ, मैं तेजस्वियों का तेज हूँ, मैं विजय हूँ, मैं निश्चय करने वालों का निश्चय हूँ और मैं सात्विक पुरुषों का सात्विक भाव हूँ।","gujarati":"હું કપટ કરનારાઓનો જુગાર છું, હું તેજસ્વીઓનું તેજ છું, હું વિજય છું, હું નિશ્ચય કરનારાઓનો નિશ્ચય છું અને હું સાત્વિક પુરુષોનો સાત્વિક ભાવ છું."},"10.37":{"chapter":10,"verse":37,"sloka":"वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनंजयः।\n\nमुनीनामप्यहं व्यासः कवीनामुशना कविः।।10.37।।","transliteration":"vṛiṣhṇīnāṁ vāsudevo ’smi pāṇḍavānāṁ dhanañjayaḥ\nmunīnām apyahaṁ vyāsaḥ kavīnām uśhanā kaviḥ","english":"Among the Vrishnis I am Vaasudeva, among the Pandavas I am Arjuna, among the sages I am Vyasa, and among the poets I am Usanas, the sage-poet.","hindi":"वृष्णियों में मैं वासुदेव हूँ, पाण्डवों में अर्जुन हूँ, मुनियों में व्यास हूँ और कवियों में उशना कवि हूँ।","gujarati":"વૃષ્ણિઓમાં હું વાસુદેવ છું, પાંડવોમાં અર્જુન છું, મુનિઓમાં વ્યાસ છું અને કવિઓમાં ઉશના કવિ છું."},"10.38":{"chapter":10,"verse":38,"sloka":"दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम्।\n\nमौनं चैवास्मि गुह्यानां ज्ञानं ज्ञानवतामहम्।।10.38।।","transliteration":"daṇḍo damayatām asmi nītir asmi jigīṣhatām\nmaunaṁ chaivāsmi guhyānāṁ jñānaṁ jñānavatām aham","english":"Of those who punish, I am the scepter; among those who seek victory, I am statesmanship; and among secrets, I am silence; I am knowledge among knowers.","hindi":"दमन करने वालों में मैं दण्ड हूँ, विजय चाहने वालों में मैं नीति हूँ, गुप्त रखने योग्य वस्तुओं में मैं मौन हूँ और ज्ञानवानों में मैं ज्ञान हूँ।","gujarati":"દમન કરનારાઓમાં હું દંડ છું અને વિજયની ઈચ્છા રાખનારાઓમાં હું નીતિ છું; ગુપ્ત રાખવા જેવી વસ્તુઓમાં હું મૌન છું અને જ્ઞાનીઓમાં હું જ્ઞાન છું."},"10.39":{"chapter":10,"verse":39,"sloka":"यच्चापि सर्वभूतानां बीजं तदहमर्जुन।\n\nन तदस्ति विना यत्स्यान्मया भूतं चराचरम्।।10.39।।","transliteration":"yach chāpi sarva-bhūtānāṁ bījaṁ tad aham arjuna\nna tad asti vinā yat syān mayā bhūtaṁ charācharam","english":"And whatever is the seed of all beings, that too am I, O Arjuna; there is no being, whether moving or non-moving, that can exist without Me.","hindi":"हे अर्जुन! जो समस्त भूतों की उत्पत्ति का बीज है, वह भी मैं ही हूँ; क्योंकि ऐसा कोई भी चर या अचर प्राणी नहीं है, जो मुझसे रहित होकर अस्तित्व में रह सके।","gujarati":"અને હે અર્જુન! જે સર્વ ભૂતોનું બીજ (કારણ) છે, તે પણ હું જ છું, કારણ કે એવું કોઈ ચર કે અચર ભૂત નથી, જે મારા વિના અસ્તિત્વ ધરાવી શકે."},"10.40":{"chapter":10,"verse":40,"sloka":"नान्तोऽस्ति मम दिव्यानां विभूतीनां परंतप।\n\nएष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया।।10.40।।","transliteration":"nānto ’sti mama divyānāṁ vibhūtīnāṁ parantapa\neṣha tūddeśhataḥ prokto vibhūter vistaro mayā","english":"There is no end to My divine glories, O Arjuna, but what I have declared to you is but a brief summary of their expanse.","hindi":"हे परन्तप अर्जुन! मेरी दिव्य विभूतियों का कोई अन्त नहीं है; मैंने अपनी विभूतियों का जो वर्णन किया है, वह तो केवल एक संक्षिप्त संकेत मात्र है।","gujarati":"હે અર્જુન! મારી દિવ્ય વિભૂતિઓનો કોઈ અંત નથી; મેં મારી વિભૂતિઓનું જે વર્ણન કર્યું છે તે તો માત્ર એક સંક્ષિપ્ત નિર્દેશ છે."},"10.41":{"chapter":10,"verse":41,"sloka":"यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा।\n\nतत्तदेवावगच्छ त्वं मम तेजोंऽशसंभवम्।।10.41।।","transliteration":"yad yad vibhūtimat sattvaṁ śhrīmad ūrjitam eva vā\ntat tad evāvagachchha tvaṁ mama tejo ’nśha-sambhavam","english":"Know that all that is glorious, beautiful, or powerful exists only as a spark of My divine splendor.","hindi":"जो कुछ भी विभूतिवान, श्रीयुक्त और बलवान है, उसे तुम मेरे तेज के एक अंश से ही उत्पन्न समझो।","gujarati":"જે કઈ પણ ઐશ્વર્યવાન, શ્રીયુક્ત અને બળવાન છે, તેને તું મારા તેજના એક અંશમાંથી જ ઉત્પન્ન થયેલું જાણ."},"10.42":{"chapter":10,"verse":42,"sloka":"अथवा बहुनैतेन किं ज्ञातेन तवार्जुन।\n\nविष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत्।।10.42।।","transliteration":"atha vā bahunaitena kiṁ jñātena tavārjuna\nviṣhṭabhyāham idaṁ kṛitsnam ekānśhena sthito jagat","english":"But what is the need for all this detailed knowledge, O Arjuna? I exist, sustaining this entire universe by a mere fragment of Myself.","hindi":"अथवा हे अर्जुन! बहुत जानने से तुम्हारा क्या प्रयोजन है? मैं इस सम्पूर्ण जगत् को अपने एक अंश मात्र से धारण करके स्थित हूँ।","gujarati":"અથવા હે અર્જુન! આ બધું વિસ્તારપૂર્વક જાણવાથી તારે શું કામ છે? હું તો આ સમગ્ર જગતને મારા એક અંશ માત્રથી ધારણ કરીને સ્થિત છું."},"11.1":{"chapter":11,"verse":1,"sloka":"अर्जुन उवाच\n\nमदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम्।\n\nयत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम।।11.1।।","transliteration":"arjuna uvācha\nmad-anugrahāya paramaṁ guhyam adhyātma-sanjñitam\nyat tvayoktaṁ vachas tena moho ’yaṁ vigato mama","english":"Arjuna said, 'By this discourse on the supreme secret concerning the Self, which You have spoken out of compassion for me, my delusion has been dispelled.'","hindi":"अर्जुन ने कहा, 'मुझ पर कृपा करने के लिए आपने जो यह परम गोपनीय अध्यात्म-विषयक उपदेश दिया है, उससे मेरा मोह नष्ट हो गया है।'","gujarati":"અર્જુને કહ્યું, 'મારા પર અનુગ્રહ કરવા માટે આપે આત્મા સંબંધી જે પરમ ગોપનીય વચન કહ્યું, તેનાથી મારો મોહ દૂર થઈ ગયો છે.'"},"11.2":{"chapter":11,"verse":2,"sloka":"भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया।\n\nत्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम्।।11.2।।","transliteration":"bhavāpyayau hi bhūtānāṁ śhrutau vistaraśho mayā\ntvattaḥ kamala-patrākṣha māhātmyam api chāvyayam","english":"The origin and destruction of beings have been heard in detail from You, O lotus-eyed Lord, and also Your inexhaustible greatness.","hindi":"हे कमलनयन ! मैंने भूतों की उत्पत्ति और प्रलय आपसे विस्तारपूर्वक सुने हैं तथा आपका अव्यय माहात्म्य भी सुना है।।","gujarati":"હે કમલનયન ! તમારી પાસેથી મેં ભૂતોની ઉત્પત્તિ અને પ્રલય વિસ્તારપૂર્વક સાંભળ્યા છે અને તમારું અવિનાશી માહાત્મ્ય પણ સાંભળ્યું છે."},"11.3":{"chapter":11,"verse":3,"sloka":"एवमेतद्यथात्थ त्वमात्मानं परमेश्वर।\n\nद्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम।।11.3।।","transliteration":"evam etad yathāttha tvam ātmānaṁ parameśhvara\ndraṣhṭum ichchhāmi te rūpam aiśhwaraṁ puruṣhottama","english":"O Supreme Lord, O Purushottama, as You have described Yourself to be, I now wish to see Your divine and transcendental form.","hindi":"हे परमेश्वर! हे पुरुषोत्तम! जैसा आप स्वयं को बता रहे हैं, मैं आपके उस ऐश्वर्यपूर्ण दिव्य रूप के दर्शन करना चाहता हूँ।","gujarati":"હે પરમેશ્વર! હે પુરુષોત્તમ! તમે જે રીતે તમારા સ્વરૂપનું વર્ણન કર્યું છે, તે મુજબ હું તમારા તે દિવ્ય અને ઐશ્વર્યવાન રૂપને પ્રત્યક્ષ જોવા ઈચ્છું છું."},"11.4":{"chapter":11,"verse":4,"sloka":"मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो।\n\nयोगेश्वर ततो मे त्वं दर्शयाऽत्मानमव्ययम्।।11.4।।","transliteration":"manyase yadi tach chhakyaṁ mayā draṣhṭum iti prabho\nyogeśhvara tato me tvaṁ darśhayātmānam avyayam","english":"If Thou, O Lord, thinkest it possible for me to see it, do Thou, then, O Lord of Yogis, show me Thy imperishable Self.","hindi":"हे प्रभो! यदि आप ऐसा समझते हैं कि मैं उसे देखने में समर्थ हूँ, तो हे योगेश्वर! आप मुझे अपने उस अविनाशी स्वरूप का दर्शन कराइये।","gujarati":"હે પ્રભુ! જો આપ એમ માનતા હોવ કે હું તેને જોવા માટે સમર્થ છું, તો હે યોગેશ્વર! આપ મને તમારા તે અવિનાશી સ્વરૂપના દર્શન કરાવો."},"11.5":{"chapter":11,"verse":5,"sloka":"श्री भगवानुवाच\n\nपश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः।\n\nनानाविधानि दिव्यानि नानावर्णाकृतीनि च।।11.5।।","transliteration":"śhrī-bhagavān uvācha\npaśhya me pārtha rūpāṇi śhataśho ’tha sahasraśhaḥ\nnānā-vidhāni divyāni nānā-varṇākṛitīni cha","english":"The Blessed Lord Krishna said: Behold, O Arjuna, My forms by the hundreds and thousands—divine, of various colors and shapes.","hindi":"श्रीभगवान् ने कहा—हे अर्जुन! मेरे सैकड़ों और हजारों दिव्य रूपों को देखो, जो अनेक प्रकार के हैं तथा नाना वर्ण और आकृतियों वाले हैं।","gujarati":"શ્રી ભગવાન બોલ્યા—હે અર્જુન! મારા સેંકડો અને હજારો વિવિધ પ્રકારના દિવ્ય રૂપોને જુઓ, જે અનેક વર્ણ અને આકૃતિઓવાળા છે."},"11.6":{"chapter":11,"verse":6,"sloka":"पश्यादित्यान्वसून्रुद्रानश्िवनौ मरुतस्तथा।\n\nबहून्यदृष्टपूर्वाणि पश्याऽश्चर्याणि भारत।।11.6।।","transliteration":"paśhyādityān vasūn rudrān aśhvinau marutas tathā\nbahūny adṛiṣhṭa-pūrvāṇi paśhyāśhcharyāṇi bhārata","english":"Behold the Adityas, the Vasus, the Rudras, the two Asvins, and the Maruts; behold many wonders never before seen, O Arjuna.","hindi":"हे भारत! मुझमें आदित्यों को, वसुओं को, रुद्रों को, दोनों अश्विनीकुमारों को और मरुद्गणों को देखो। हे अर्जुन! और भी बहुत से पहले न देखे हुए आश्चर्यों को देखो।","gujarati":"હે ભારત! મારામાં આદિત્યો, વસુઓ, રુદ્રો, બંને અશ્વિનીકુમારો અને મરુદ્ગણોને જો. હે અર્જુન! આ સિવાય પણ અનેક અદ્ભુત દ્રશ્યો જો જે તેં પહેલાં ક્યારેય જોયા નથી."},"11.7":{"chapter":11,"verse":7,"sloka":"इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम्।\n\nमम देहे गुडाकेश यच्चान्यद्द्रष्टुमिच्छसि।।11.7।।","transliteration":"ihaika-sthaṁ jagat kṛitsnaṁ paśhyādya sa-charācharam\nmama dehe guḍākeśha yach chānyad draṣhṭum ichchhasi","english":"Behold now, O Arjuna, the entire universe, with all that is moving and stationary, centered in one place within this My body, and whatever else you desire to see.","hindi":"हे अर्जुन! अब मेरे इस शरीर में एक जगह स्थित चराचर जगत् को देखो, तथा इसके अलावा जो कुछ भी तुम देखना चाहते हो, उसे भी यहीं देखो।","gujarati":"હે અર્જુન! હવે મારા આ શરીરમાં એક જ જગ્યાએ સ્થિત આખું જગત, ચરાચર સહિત, જુઓ અને બીજું જે કંઈ પણ તમે જોવા ઈચ્છતા હોવ તે પણ અહીં જુઓ."},"11.8":{"chapter":11,"verse":8,"sloka":"न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा।\n\nदिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम्।।11.8।।","transliteration":"na tu māṁ śhakyase draṣhṭum anenaiva sva-chakṣhuṣhā\ndivyaṁ dadāmi te chakṣhuḥ paśhya me yogam aiśhwaram","english":"But you are not able to behold Me with these your own eyes; I bestow upon you the divine eye; behold My lordly Yoga.","hindi":"परन्तु तुम अपने इन प्राकृत नेत्रों से मुझे देखने में समर्थ नहीं हो, इसलिए मैं तुम्हें दिव्य दृष्टि प्रदान करता हूँ; तुम मेरे इस ईश्वरीय योग का दर्शन करो।","gujarati":"પરંતુ તું મને તારા આ પ્રાકૃત નેત્રોથી જોવા માટે સમર્થ નથી, તેથી હું તને દિવ્ય ચક્ષુ આપું છું; તું મારા આ ઐશ્વર્યમય યોગનું દર્શન કર."},"11.9":{"chapter":11,"verse":9,"sloka":"सञ्जय उवाच\n\nएवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः।\n\nदर्शयामास पार्थाय परमं रूपमैश्वरम्।।11.9।।","transliteration":"sañjaya uvācha\nevam uktvā tato rājan mahā-yogeśhvaro hariḥ\ndarśhayām āsa pārthāya paramaṁ rūpam aiśhwaram","english":"Sanjaya said: Having spoken thus, O King, Shri Krishna, the great Master of all Yoga, revealed unto Arjuna His supreme, divine form as the Lord of the Universe.","hindi":"संजय ने कहा: हे राजन्! महायोगेश्वर भगवान श्रीकृष्ण ने इस प्रकार कहकर फिर अर्जुन को अपना परम ऐश्वर्ययुक्त दिव्य रूप दिखाया।","gujarati":"સંજયે કહ્યું: હે રાજન્! મહાયોગેશ્વર ભગવાન શ્રીકૃષ્ણે આમ કહીને અર્જુનને પોતાનું પરમ ઐશ્વર્યયુક્ત દિવ્ય સ્વરૂપ બતાવ્યું."},"11.10":{"chapter":11,"verse":10,"sloka":"अनेकवक्त्रनयनमनेकाद्भुतदर्शनम्।\n\nअनेकदिव्याभरणं दिव्यानेकोद्यतायुधम्।।11.10।।","transliteration":"aneka-vaktra-nayanam anekādbhuta-darśhanam\naneka-divyābharaṇaṁ divyānekodyatāyudham","english":"Possessing numerous mouths and eyes, displaying numerous wondrous visions, adorned with numerous divine ornaments, and holding aloft numerous divine weapons, He revealed that stupendous form.","hindi":"अनेक मुख और नेत्रों से युक्त, अनेक अद्भुत दर्शनों वाले, बहुत से दिव्य भूषणों से सुसज्जित और अनेक दिव्य शस्त्रों को हाथों में धारण किए हुए, भगवान श्रीकृष्ण ने वह विराट स्वरूप प्रदर्शित किया।","gujarati":"અનેક મુખ અને નેત્રોથી યુક્ત, અનેક અદભુત દર્શનો વાળા, ઘણા બધા દિવ્ય આભૂષણોથી સજ્જ અને અનેક દિવ્ય શસ્ત્રો હાથમાં ઉઠાવેલા, ભગવાન શ્રીકૃષ્ણએ તે વિરાટ સ્વરૂપ પ્રદર્શિત કર્યું."},"11.11":{"chapter":11,"verse":11,"sloka":"दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम्।\n\nसर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम्।।11.11।।","transliteration":"divya-mālyāmbara-dharaṁ divya-gandhānulepanam\nsarvāśhcharya-mayaṁ devam anantaṁ viśhvato-mukham","english":"Wearing divine garlands and garments, anointed with divine scents, the all-wonderful, resplendent Supreme Lord, who is infinite and possesses faces in all directions, manifested before Arjuna.","hindi":"दिव्य माला और वस्त्रों को धारण किए हुए, दिव्य गंधों से सुसज्जित, वे सर्वशक्तिमान और अद्भुत, अनंत परमेश्वर, जिनके मुख सर्वत्र हैं, अर्जुन के समक्ष प्रकट हुए।","gujarati":"દિવ્ય માળાઓ અને વસ્ત્રો ધારણ કરેલા, દિવ્ય ગંધોથી સુસજ્જ, સર્વ-આશ્ચર્યજનક, તેજસ્વી અને અનંત એવા પરમેશ્વર, જેઓ સર્વ દિશાઓમાં મુખ ધરાવે છે, તે અર્જુને નિહાળ્યા."},"11.12":{"chapter":11,"verse":12,"sloka":"दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता।\n\nयदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः।।11.12।।","transliteration":"divi sūrya-sahasrasya bhaved yugapad utthitā\nyadi bhāḥ sadṛiśhī sā syād bhāsas tasya mahātmanaḥ","english":"If the splendour of a thousand suns were to blaze out simultaneously in the sky, that would be the splendour of that mighty being.","hindi":"यदि आकाश में एक साथ हजार सूर्यों का प्रकाश प्रकट हो जाए, तो वह उस महान परमात्मा के प्रकाश के सदृश होगा।","gujarati":"જો આકાશમાં એકસાથે હજારો સૂર્યોનો પ્રકાશ પ્રગટ થાય, તો તે તે મહાન પરમાત્માના પ્રકાશ સમાન હશે."},"11.13":{"chapter":11,"verse":13,"sloka":"तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा।\n\nअपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा।।11.13।।","transliteration":"tatraika-sthaṁ jagat kṛitsnaṁ pravibhaktam anekadhā\napaśhyad deva-devasya śharīre pāṇḍavas tadā","english":"At that time, Arjuna, the son of Pandu, beheld the entire universe, with its infinite divisions, unified and resting within the body of the Supreme Lord Krishna, the God of gods.","hindi":"उस समय पाण्डुपुत्र अर्जुन ने अनेक प्रकार से विभक्त सम्पूर्ण जगत् को देवों के देव भगवान श्रीकृष्ण के शरीर में एक ही स्थान पर स्थित देखा।","gujarati":"ત્યારે પાંડુપુત્ર અર્જુને તે સમયે અનેક પ્રકારથી વિભક્ત થયેલા સંપૂર્ણ જગતને દેવોના દેવ ભગવાન શ્રીકૃષ્ણના શરીરના એક ભાગમાં સ્થિત જોયું."},"11.14":{"chapter":11,"verse":14,"sloka":"ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः।\n\nप्रणम्य शिरसा देवं कृताञ्जलिरभाषत।।11.14।।","transliteration":"tataḥ sa vismayāviṣhṭo hṛiṣhṭa-romā dhanañjayaḥ\npraṇamya śhirasā devaṁ kṛitāñjalir abhāṣhata","english":"Then, Arjuna, filled with wonder and his hair standing on end, bowed his head to the Supreme Lord Krishna and, with folded palms, began to speak.","hindi":"तदनन्तर, विस्मय से भर गए और रोमांचित शरीर वाले अर्जुन ने उन देवों के देव श्री कृष्ण को मस्तक झुकाकर प्रणाम किया और हाथ जोड़कर उनसे प्रार्थना की।","gujarati":"ત્યારબાદ, વિસ્મયથી ભરાઈ ગયેલા અને રોમાંચિત શરીરવાળા અર્જુને શ્રી કૃષ્ણ ભગવાનને મસ્તક નમાવીને પ્રણામ કર્યા અને હાથ જોડીને બોલવા લાગ્યા."},"11.15":{"chapter":11,"verse":15,"sloka":"अर्जुन उवाच\n\nपश्यामि देवांस्तव देव देहे\n\nसर्वांस्तथा भूतविशेषसङ्घान्।\n\nब्रह्माणमीशं कमलासनस्थ\n\nमृषींश्च सर्वानुरगांश्च दिव्यान्।।11.15।।","transliteration":"arjuna uvācha\npaśhyāmi devāns tava deva dehe\nsarvāns tathā bhūta-viśheṣha-saṅghān\nbrahmāṇam īśhaṁ kamalāsana-stham\nṛiṣhīnśh cha sarvān uragānśh cha divyān","english":"Arjuna said: O Lord Krishna, I behold within Your body all the demigods and hosts of various classes of living entities, Lord Brahma seated on the lotus flower, all the great sages, and the celestial serpents.","hindi":"अर्जुन ने कहा - हे भगवान श्री कृष्ण! मैं आपके शरीर में समस्त देवताओं को और अनेक प्रकार के प्राणियों के समुदायों को, कमल के आसन पर विराजमान ब्रह्माजी को, समस्त ऋषियों को और दिव्य सर्पों को देख रहा हूँ।","gujarati":"અર્જુને કહ્યું - હે ભગવાન શ્રી કૃષ્ણ! હું તમારા શરીરમાં તમામ દેવોને અને વિવિધ પ્રાણીઓના સમૂહોને, કમળ પર બિરાજમાન બ્રહ્માજીને, તમામ ઋષિઓને અને દિવ્ય સર્પોને જોઈ રહ્યો છું."},"11.16":{"chapter":11,"verse":16,"sloka":"अनेकबाहूदरवक्त्रनेत्रं\n\nपश्यामि त्वां सर्वतोऽनन्तरूपम्।\n\nनान्तं न मध्यं न पुनस्तवादिं\n\nपश्यामि विश्वेश्वर विश्वरूप।।11.16।।","transliteration":"aneka-bāhūdara-vaktra-netraṁ\npaśhyāmi tvāṁ sarvato ’nanta-rūpam\nnāntaṁ na madhyaṁ na punas tavādiṁ\npaśhyāmi viśhveśhvara viśhva-rūpa","english":"I see You with boundless form on every side, with many arms, stomachs, mouths, and eyes; neither the end, nor the middle, nor the beginning do I see, O Lord of the Universe, O Universal Form.","hindi":"हे विश्वेश्वर! मैं आपको अनेक भुजाओं, उदर, मुख और नेत्रों वाले तथा सब ओर से अनंत रूपों में देखता हूँ। हे विश्वरूप! मैं न आपके अंत को देखता हूँ, न मध्य को और न ही आदि को।","gujarati":"હે વિશ્વેશ્વર! હું તમને અનેક હાથ, પેટ, મુખ અને નેત્રોવાળા તથા સર્વ તરફથી અનંત રૂપોમાં જોઉં છું. હે વિશ્વરૂપ! હું ન તમારા અંતને જોઉં છું, ન મધ્યને અને ન આદિને."},"11.17":{"chapter":11,"verse":17,"sloka":"किरीटिनं गदिनं चक्रिणं च\n\nतेजोराशिं सर्वतोदीप्तिमन्तम्।\n\nपश्यामि त्वां दुर्निरीक्ष्यं समन्ता\n\nद्दीप्तानलार्कद्युतिमप्रमेयम्।।11.17।।","transliteration":"kirīṭinaṁ gadinaṁ chakriṇaṁ cha\ntejo-rāśhiṁ sarvato dīptimantam\npaśhyāmi tvāṁ durnirīkṣhyaṁ samantād\ndīptānalārka-dyutim aprameyam","english":"I see You possessing a diadem, a club, and a discus, a mass of radiance shining everywhere, difficult to behold, blazing all around like a burning fire and the sun, and immeasurable in Your form.","hindi":"मैं आपको मुकुट, गदा और चक्र धारण किए हुए, सब ओर प्रकाशमान तेज के पुंज के रूप में देखता हूँ, जिसे देख पाना अति कठिन है, जो जलती हुई अग्नि और सूर्य के समान चारों ओर देदीप्यमान है, और जिसका कोई आदि-अंत नहीं है।","gujarati":"હું આપને મુકુટ, ગદા અને ચક્ર ધારણ કરેલા, ચારે તરફ ફેલાયેલા તેજપુંજ સ્વરૂપે જોઉં છું, જેનું દર્શન કરવું અત્યંત કઠિન છે, જે પ્રજ્વલિત અગ્નિ અને સૂર્ય સમાન પ્રકાશમાન છે અને જેનું માપ કાઢી શકાય તેમ નથી."},"11.18":{"chapter":11,"verse":18,"sloka":"त्वमक्षरं परमं वेदितव्यं\n\nत्वमस्य विश्वस्य परं निधानम्।\n\nत्वमव्ययः शाश्वतधर्मगोप्ता\n\nसनातनस्त्वं पुरुषो मतो मे।।11.18।।","transliteration":"tvam akṣharaṁ paramaṁ veditavyaṁ\ntvam asya viśhvasya paraṁ nidhānam\ntvam avyayaḥ śhāśhvata-dharma-goptā\nsanātanas tvaṁ puruṣho mato me","english":"You are the Imperishable, the Supreme Being to be known. You are the ultimate refuge of this universe; You are the immutable protector of the eternal Dharma; You are the Primal Person, such is my conviction.","hindi":"आप ही जानने योग्य परम अक्षर ब्रह्म हैं; आप ही इस ब्रह्मांड के परम आश्रय हैं; आप ही शाश्वत धर्म के अविनाशी रक्षक हैं; आप ही अनादि पुरुष हैं, ऐसा मेरा दृढ़ मत है।","gujarati":"આપ જ જાણવા યોગ્ય પરમ અક્ષર છો; આપ આ વિશ્વના પરમ આશ્રય છો; આપ શાશ્વત ધર્મના અવિનાશી રક્ષક છો અને આપ જ સનાતન પુરુષ છો, એવો મારો દ્રઢ મત છે."},"11.19":{"chapter":11,"verse":19,"sloka":"अनादिमध्यान्तमनन्तवीर्य\n\nमनन्तबाहुं शशिसूर्यनेत्रम्।\n\nपश्यामि त्वां दीप्तहुताशवक्त्रम्\n\nस्वतेजसा विश्वमिदं तपन्तम्।।11.19।।","transliteration":"स्वतेजसा विश्वमिदं तपन्तम् || 19||","english":"I behold You as without beginning, middle, or end, possessed of infinite power, with innumerable arms; the sun and moon are Your eyes, and Your mouth is a blazing fire, heating the entire universe with Your own radiance.","hindi":"मैं आपको आदि, मध्य और अंत से रहित, अनंत सामर्थ्य से युक्त और अनंत भुजाओं वाले रूप में देखता हूँ; सूर्य और चंद्रमा आपके नेत्र हैं, और प्रज्वलित अग्नि आपका मुख है, जो अपने तेज से इस संपूर्ण ब्रह्मांड को तप्त कर रहे हैं।","gujarati":"હું આપને આદિ, મધ્ય અને અંતથી રહિત, અનંત સામર્થ્યવાન અને અસંખ્ય ભુજાઓ ધરાવતા સ્વરૂપમાં જોઉં છું; સૂર્ય અને ચંદ્ર આપના નેત્રો છે અને પ્રજ્વલિત અગ્નિ આપનું મુખ છે, જે પોતાના તેજથી આ સમગ્ર વિશ્વને તપાવી રહ્યા છે."},"11.20":{"chapter":11,"verse":20,"sloka":"द्यावापृथिव्योरिदमन्तरं हि\n\nव्याप्तं त्वयैकेन दिशश्च सर्वाः।\n\nदृष्ट्वाऽद्भुतं रूपमुग्रं तवेदं\n\nलोकत्रयं प्रव्यथितं महात्मन्।।11.20।।","transliteration":"dyāv ā-pṛithivyor idam antaraṁ hi\nvyāptaṁ tvayaikena diśhaśh cha sarvāḥ\ndṛiṣhṭvādbhutaṁ rūpam ugraṁ tavedaṁ\nloka-trayaṁ pravyathitaṁ mahātman","english":"O Great-Souled One! This space between the heavens and the earth and all the directions are pervaded by You alone; seeing this Your wondrous and terrible form, the three worlds are trembling with fear.","hindi":"हे महात्मन्! स्वर्ग और पृथ्वी के बीच का यह आकाश तथा समस्त दिशाएं अकेले आप ही से व्याप्त हैं; आपके इस अद्भुत और उग्र रूप को देखकर तीनों लोक अतिव्यथा को प्राप्त हो रहे हैं।","gujarati":"હે મહાત્મન! સ્વર્ગ અને પૃથ્વીની વચ્ચેનું આ આકાશ અને તમામ દિશાઓ એકલા આપનાથી જ વ્યાપ્ત છે; આપના આ અદ્ભુત અને ઉગ્ર રૂપને જોઈને ત્રણેય લોક અત્યંત ભયભીત થઈ રહ્યા છે."},"11.21":{"chapter":11,"verse":21,"sloka":"अमी हि त्वां सुरसङ्घाः विशन्ति\n\nकेचिद्भीताः प्राञ्जलयो गृणन्ति।\n\nस्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः\n\nस्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः।।11.21।।","transliteration":"amī hi tvāṁ sura-saṅghā viśhanti\nkechid bhītāḥ prāñjalayo gṛiṇanti\nsvastīty uktvā maharṣhi-siddha-saṅghāḥ\nstuvanti tvāṁ stutibhiḥ puṣhkalābhiḥ","english":"These hosts of celestials enter into You; some in fear, with joined palms, invoke Your grace. Companies of great sages and perfected souls praise You with auspicious hymns of glorification.","hindi":"ये देवताओं के समूह आपमें ही प्रवेश कर रहे हैं, और कई एक भयभीत होकर हाथ जोड़े हुए आपकी स्तुति करते हैं। महर्षि और सिद्धों के समुदाय 'कल्याण हो' ऐसा कहकर उत्तम स्तोत्रों द्वारा आपकी स्तुति कर रहे हैं।","gujarati":"દેવોના સમૂહો આપમાં પ્રવેશ કરી રહ્યા છે અને કેટલાક ભયભીત થઈને હાથ જોડી આપની સ્તુતિ કરી રહ્યા છે; મહર્ષિઓ અને સિદ્ધોના સમુદાયો 'કલ્યાણ હો' એમ કહીને ઉત્તમ સ્તોત્રો દ્વારા આપની સ્તુતિ કરી રહ્યા છે."},"11.22":{"chapter":11,"verse":22,"sloka":"रुद्रादित्या वसवो ये च साध्या\n\nविश्वेऽश्िवनौ मरुतश्चोष्मपाश्च।\n\nगन्धर्वयक्षासुरसिद्धसङ्घा\n\nवीक्षन्ते त्वां विस्मिताश्चैव सर्वे।।11.22।।","transliteration":"rudrādityā vasavo ye cha sādhyā\nviśhve ’śhvinau marutaśh choṣhmapāśh cha\ngandharva-yakṣhāsura-siddha-saṅghā\nvīkṣhante tvāṁ vismitāśh chaiva sarve","english":"The Rudras, the Adityas, the Vasus, the Sadhyas, the Visvedevas, the two Asvins, the Maruts, the Manus, and the hosts of celestial singers, the Yakshas, the demons, and the perfected ones—all of them gaze upon Thee, O Shri Krishna, with great amazement.","hindi":"रुद्र, आदित्य, वसु, साध्य, विश्वेदेव, दोनों अश्विनीकुमार, मरुद्गण, पितरों का समुदाय, गन्धर्व, यक्ष, असुर और सिद्धों के समुदाय—ये सभी विस्मित होकर आपको देख रहे हैं, हे श्री कृष्ण।","gujarati":"રૂદ્રો, આદિત્યો, વસુઓ, સાધ્યગણો, વિશ્વદેવો, બે અશ્વિનીકુમારો, મરુદગણો, ઉષ્મપાઓ, ગંધર્વો, યક્ષો, અસુરો અને સિદ્ધગણોના સમુદાયો—આ સર્વે આપને વિસ્મયપૂર્વક નિહાળી રહ્યા છે, હે શ્રી કૃષ્ણ."},"11.23":{"chapter":11,"verse":23,"sloka":"रूपं महत्ते बहुवक्त्रनेत्रं\n\nमहाबाहो बहुबाहूरुपादम्।\n\nबहूदरं बहुदंष्ट्राकरालं\n\nदृष्ट्वा लोकाः प्रव्यथितास्तथाऽहम्।।11.23।।","transliteration":"rūpaṁ mahat te bahu-vaktra-netraṁ\nmahā-bāho bahu-bāhūru-pādam\nbahūdaraṁ bahu-danṣhṭrā-karālaṁ\ndṛiṣhṭvā lokāḥ pravyathitās tathāham","english":"Seeing Your immeasurable form with many mouths and eyes, O mighty-armed one, with many arms, thighs, and feet, with many stomachs and fearsome with many tusks, the worlds are terrified, and so am I.","hindi":"हे महाबाहो! आपके बहुत मुख और नेत्रों वाले, बहुत भुजाओं, जंघाओं और चरणों वाले, बहुत उदरों वाले तथा बहुत सी विकराल दाढ़ों वाले महान रूप को देखकर सब लोक भयभीत हो रहे हैं और मैं भी व्याकुल हो रहा हूँ।","gujarati":"હે મહાબાહુ! તમારા અનેક મુખ અને નેત્રોવાળા, અનેક હાથ, જાંઘ અને ચરણોવાળા, ઘણા ઉદર અને અનેક વિકરાળ દાઢોવાળા મહાન સ્વરૂપને જોઈને બધા લોકો ભયભીત થઈ રહ્યા છે અને હું પણ વ્યાકુળ થઈ રહ્યો છું."},"11.24":{"chapter":11,"verse":24,"sloka":"नभःस्पृशं दीप्तमनेकवर्णं\n\nव्यात्ताननं दीप्तविशालनेत्रम्।\n\nदृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा\n\nधृतिं न विन्दामि शमं च विष्णो।।11.24।।","transliteration":"nabhaḥ-spṛiśhaṁ dīptam aneka-varṇaṁ\nvyāttānanaṁ dīpta-viśhāla-netram\ndṛiṣhṭvā hi tvāṁ pravyathitāntar-ātmā\ndhṛitiṁ na vindāmi śhamaṁ cha viṣhṇo","english":"Seeing Thee touching the sky, effulgent in many colors, with mouths wide open and large fiery eyes, I am terrified at heart, O Vishnu, and find neither courage nor peace.","hindi":"हे विष्णो! आकाश को स्पर्श करते हुए, अनेक रंगों में देदीप्यमान, खुले हुए मुख और विशाल अग्नि के समान नेत्रों वाले आपको देखकर मेरा हृदय भय से व्याकुल हो रहा है; मैं न तो धैर्य रख पा रहा हूँ और न ही मुझे शांति मिल रही है।","gujarati":"હે વિષ્ણુ! આકાશને સ્પર્શી રહેલા, અનેક રંગોમાં ઝળહળતા, વિકરાળ મુખ અને અગ્નિ જેવા તેજસ્વી વિશાળ નેત્રોવાળા તમને જોઈને હું ભયભીત થયો છું; મારું હૃદય ધ્રૂજી રહ્યું છે અને મને ન તો ધૈર્ય મળે છે કે ન તો શાંતિ."},"11.25":{"chapter":11,"verse":25,"sloka":"दंष्ट्राकरालानि च ते मुखानि\n\nदृष्ट्वैव कालानलसन्निभानि।\n\nदिशो न जाने न लभे च शर्म\n\nप्रसीद देवेश जगन्निवास।।11.25।।","transliteration":"danṣhṭrā-karālāni cha te mukhāni\ndṛiṣhṭvaiva kālānala-sannibhāni\ndiśho na jāne na labhe cha śharma\nprasīda deveśha jagan-nivāsa","english":"Seeing Your mouths, terrifying with their tusks and blazing like the fires of cosmic dissolution, I have lost my sense of direction and find no peace. Be merciful, O Lord of all Lords, O Abode of the Universe.","hindi":"आपकी प्रलयाग्नि के समान प्रज्वलित और विकराल दाढ़ों वाले मुखों को देखकर, मैं दिशाओं को नहीं पहचान पा रहा हूँ और मुझे कहीं भी शान्ति नहीं मिल रही है। हे देवेश! हे जगन्निवास! आप मुझ पर कृपा कीजिए।","gujarati":"તમારા પ્રલયાગ્નિ જેવા પ્રજ્વલિત અને વિકરાળ દાઢોવાળા મુખોને જોઈને, હું દિશાઓનું ભાન ગુમાવી રહ્યો છું અને મને ક્યાંય શાંતિ મળતી નથી. હે દેવેશ! હે જગન્નિવાસ! તમે પ્રસન્ન થાઓ."},"11.26":{"chapter":11,"verse":26,"sloka":"अमी च त्वां धृतराष्ट्रस्य पुत्राः\n\nसर्वे सहैवावनिपालसङ्घैः।\n\nभीष्मो द्रोणः सूतपुत्रस्तथाऽसौ\n\nसहास्मदीयैरपि योधमुख्यैः।।11.26।।","transliteration":"amī cha tvāṁ dhṛitarāśhtrasya putrāḥ\nsarve sahaivāvani-pāla-saṅghaiḥ\nbhīṣhmo droṇaḥ sūta-putras tathāsau\nsahāsmadīyair api yodha-mukhyaiḥ\n vaktrāṇi te tvaramāṇā viśhanti\ndanṣhṭrā-karālāni bhayānakāni\nkechid vilagnā daśhanāntareṣhu\nsandṛiśhyante chūrṇitair uttamāṅgaiḥ","english":"All the sons of Dhritarashtra, along with the hosts of kings of the earth, Bhishma, Drona, and Karna, as well as the chief among our warriors, are rushing headlong into Your terrible mouths.","hindi":"धृतराष्ट्र के वे सभी पुत्र, राजाओं के उस समुदाय के साथ, भीष्म, द्रोण, कर्ण और हमारे पक्ष के अन्य प्रमुख योद्धा भी—ये सभी आपके विकराल मुखों में प्रवेश कर रहे हैं।","gujarati":"ધૃતરાષ્ટ્રના પુત્રો, રાજાઓના સમુદાયો સહિત, ભીષ્મ, દ્રોણ અને કર્ણ, તેમજ આપણા પક્ષના મુખ્ય યોદ્ધાઓ પણ આપના ભયાનક મુખમાં પ્રવેશી રહ્યા છે."},"11.27":{"chapter":11,"verse":27,"sloka":"वक्त्राणि ते त्वरमाणा विशन्ति\n\nदंष्ट्राकरालानि भयानकानि।\n\nकेचिद्विलग्ना दशनान्तरेषु\n\nसंदृश्यन्ते चूर्णितैरुत्तमाङ्गैः।।11.27।।","transliteration":"vaktrāṇi te  tvaramāṇā   viśanti daṁṣṭrā-karālāni    bhayānakāni kecid   vilagnā daśanāntareṣu   sandṛśyante cūrṇitair   uttamāṅgaiḥ","english":"Some hurry into Your mouths with their terrible teeth, fearful to behold. Some are found stuck in the gaps between the teeth, their heads crushed to powder.","hindi":"वे सब ही तीव्रता से आपके विकराल दाढ़ों वाले डरावने मुखों में प्रवेश कर रहे हैं और कई एक चूर्णित शिरों सहित आपके दांतों के बीच में फँसे हुए दिख रहे हैं।","gujarati":"ઘણા બધા લોકો વેગપૂર્વક તમારા ભયાનક દાંતોવાળા મુખમાં પ્રવેશ કરી રહ્યા છે અને કેટલાક તો તમારા દાંતોની વચ્ચે ફસાયેલા, તેમના મસ્તક ચૂર્ણ થયેલા દેખાઈ રહ્યા છે."},"11.28":{"chapter":11,"verse":28,"sloka":"यथा नदीनां बहवोऽम्बुवेगाः\n\nसमुद्रमेवाभिमुखाः द्रवन्ति।\n\nतथा तवामी नरलोकवीरा\n\nविशन्ति वक्त्राण्यभिविज्वलन्ति।।11.28।।","transliteration":"yathā nadīnāṁ bahavo ’mbu-vegāḥ\nsamudram evābhimukhā dravanti\ntathā tavāmī nara-loka-vīrā\nviśhanti vaktrāṇy abhivijvalanti","english":"Just as the many rushing torrents of rivers flow towards the ocean, so do these heroes of the human world enter Your flaming mouths.","hindi":"जैसे नदियों के बहुत से जलप्रवाह समुद्र की ओर वेग से बहते हैं, वैसे ही मनुष्यलोक के ये वीर योद्धागण आपके प्रज्वलित मुखों में प्रवेश करते हैं।।","gujarati":"જેમ નદીઓના ઘણા જળપ્રવાહ વેગથી સમુદ્ર તરફ વહે છે, તેમ જ મનુષ્યલોકના આ વીર યોદ્ધાઓ તમારા પ્રજ્વલિત મુખમાં પ્રવેશ કરે છે."},"11.29":{"chapter":11,"verse":29,"sloka":"यथा प्रदीप्तं ज्वलनं पतङ्गा\n\nविशन्ति नाशाय समृद्धवेगाः।\n\nतथैव नाशाय विशन्ति लोका\n\nस्तवापि वक्त्राणि समृद्धवेगाः।।11.29।।","transliteration":"yathā pradīptaṁ jvalanaṁ pataṅgā\nviśhanti nāśhāya samṛiddha-vegāḥ\ntathaiva nāśhāya viśhanti lokās\ntavāpi vaktrāṇi samṛiddha-vegāḥ","english":"As moths hurriedly rush into a blazing fire, leading to their own destruction, so too these creatures hurry into Your mouths, leading to their own destruction.","hindi":"जैसे पतंगे अपने नाश के लिए प्रज्वलित अग्नि में अतिवेग से प्रवेश करते हैं, वैसे ही ये लोग भी अपने नाश के लिए आपके मुखों में अतिवेग से प्रवेश करते हैं।।","gujarati":"જેમ પતંગિયા પોતાના વિનાશ માટે પ્રજ્વલિત અગ્નિમાં અતિવેગથી પ્રવેશ કરે છે, તેમ જ આ લોકો પણ પોતાના વિનાશ માટે તમારા મુખમાં અતિવેગથી પ્રવેશ કરે છે."},"11.30":{"chapter":11,"verse":30,"sloka":"लेलिह्यसे ग्रसमानः समन्ता\n\nल्लोकान्समग्रान्वदनैर्ज्वलद्भिः।\n\nतेजोभिरापूर्य जगत्समग्रं\n\nभासस्तवोग्राः प्रतपन्ति विष्णो।।11.30।।","transliteration":"lelihyase grasamānaḥ samantāl\nlokān samagrān vadanair jvaladbhiḥ\ntejobhir āpūrya jagat samagraṁ\nbhāsas tavogrāḥ pratapanti viṣhṇo","english":"You are licking up and devouring all the worlds on every side with Your flaming mouths. Your fierce rays, filling the entire universe with radiance, are scorching it, O Vishnu!","hindi":"हे विष्णो! आप प्रज्वलित मुखों के द्वारा इन समस्त लोकों का ग्रसन करते हुए आस्वाद ले रहे हैं। आपकी उग्र किरणें सम्पूर्ण जगत् को अपने प्रचंड तेज से भर कर तपा रही हैं।","gujarati":"હે વિષ્ણુ! આપ પ્રજ્વલિત મુખ વડે ચારે બાજુથી બધા લોકોને ગળી રહ્યા છો અને ચાટી રહ્યા છો. તમારી ઉગ્ર કિરણો સમગ્ર જગતને તેજથી ભરીને તપાવી રહી છે."},"11.31":{"chapter":11,"verse":31,"sloka":"आख्याहि मे को भवानुग्ररूपो\n\nनमोऽस्तु ते देववर प्रसीद।\n\nविज्ञातुमिच्छामि भवन्तमाद्यं\n\nन हि प्रजानामि तव प्रवृत्तिम्।।11.31।।","transliteration":"ākhyāhi me ko bhavān ugra-rūpo\nnamo ’stu te deva-vara prasīda\nvijñātum ichchhāmi bhavantam ādyaṁ\nna hi prajānāmi tava pravṛittim","english":"Tell me, who You are, so fierce of form. I offer my salutations to You, O God Supreme; have mercy on me. I desire to know You, the original Being. I do not indeed know Your workings.","hindi":"हे उग्र रूप वाले! आप कौन हैं, मुझे बतलाइये। हे देवश्रेष्ठ! आपको नमस्कार है, आप मुझ पर प्रसन्न होइये। मैं आपको आदि पुरुष को तत्त्व से जानना चाहता हूँ, क्योंकि आपकी इस प्रवृत्तिको मैं नहीं जानता।","gujarati":"હે ઉગ્ર સ્વરૂપવાળા! આપ કોણ છો, તે મને કહો. હે દેવશ્રેષ્ઠ! તમને મારા નમસ્કાર છે, આપ પ્રસન્ન થાઓ. હું આપ આદિ પુરુષને જાણવા ઇચ્છું છું, કારણ કે હું આપની પ્રવૃત્તિને સમજી શકતો નથી."},"11.32":{"chapter":11,"verse":32,"sloka":"श्री भगवानुवाच\n\nकालोऽस्मि लोकक्षयकृत्प्रवृद्धो\n\nलोकान्समाहर्तुमिह प्रवृत्तः।\n\nऋतेऽपि त्वां न भविष्यन्ति सर्वे\n\nयेऽवस्थिताः प्रत्यनीकेषु योधाः।।11.32।।","transliteration":"śhrī-bhagavān uvācha\nkālo ’smi loka-kṣhaya-kṛit pravṛiddho\nlokān samāhartum iha pravṛittaḥ\nṛite ’pi tvāṁ na bhaviṣhyanti sarve\nye ’vasthitāḥ pratyanīkeṣhu yodhāḥ","english":"Shri Krishna, the Supreme Personality of Godhead, said: I am Time, the great destroyer of worlds, and I have come here to annihilate all people. With the exception of you, all the soldiers here on both sides will be slain.","hindi":"श्री भगवान ने कहा: मैं लोकों का विनाश करने वाला साक्षात् महाकाल हूँ। इस समय मैं इन लोकों को नष्ट करने के लिए प्रवृत्त हुआ हूँ। तुम्हारे बिना भी, विपक्ष की सेना में खड़े हुए ये योद्धा जीवित नहीं रहेंगे।","gujarati":"શ્રી ભગવાન બોલ્યા: હું જગતનો વિનાશ કરનાર પ્રવૃદ્ધ કાળ છું અને અત્યારે આ સર્વ લોકોનો સંહાર કરવા માટે પ્રવૃત્ત થયો છું. પ્રતિપક્ષીઓની સેનામાં રહેલા જે યોદ્ધાઓ છે, તે તારા વિના પણ જીવતા નહીં રહે."},"11.33":{"chapter":11,"verse":33,"sloka":"तस्मात्त्वमुत्तिष्ठ यशो लभस्व\n\nजित्वा शत्रून् भुङ्क्ष्व राज्यं समृद्धम्।\n\nमयैवैते निहताः पूर्वमेव\n\nनिमित्तमात्रं भव सव्यसाचिन्।।11.33।।","transliteration":"tasmāt tvam uttiṣhṭha yaśho labhasva\njitvā śhatrūn bhuṅkṣhva rājyaṁ samṛiddham\nmayaivaite nihatāḥ pūrvam eva\nnimitta-mātraṁ bhava savya-sāchin","english":"Therefore, arise and attain glory. Conquer your enemies and enjoy the prosperous kingdom. Truly, by Me, they have already been slain; be you merely an instrument, O Arjuna.","hindi":"इसलिए तुम उठ खड़े हो जाओ और यश प्राप्त करो; शत्रुओं को जीतकर समृद्ध राज्य का भोग करो। ये सब पहले ही मेरे द्वारा मारे जा चुके हैं; हे अर्जुन! तुम तो केवल निमित्तमात्र बन जाओ।","gujarati":"તેથી તું ઉઠ અને યશ પ્રાપ્ત કર; શત્રુઓને જીતીને સમૃદ્ધ રાજ્યનો ભોગ કર. આ બધા તો મારા દ્વારા પહેલેથી જ મારી નાખવામાં આવ્યા છે; હે અર્જુન! તું તો માત્ર નિમિત્ત માત્ર બની જા."},"11.34":{"chapter":11,"verse":34,"sloka":"द्रोणं च भीष्मं च जयद्रथं च\n\nकर्णं तथाऽन्यानपि योधवीरान्।\n\nमया हतांस्त्वं जहि मा व्यथिष्ठा\n\nयुध्यस्व जेतासि रणे सपत्नान्।।11.34।।","transliteration":"droṇaṁ cha bhīṣhmaṁ cha jayadrathaṁ cha\nkarṇaṁ tathānyān api yodha-vīrān\nmayā hatāṁs tvaṁ jahi mā vyathiṣhṭhā\nyudhyasva jetāsi raṇe sapatnān","english":"Drona, Bhishma, Jayadratha, Karna, and many other heroic warriors have already been destroyed by Me; do not tremble, O Arjuna; fight, and you shall surely conquer your enemies in the battle.","hindi":"द्रोण, भीष्म, जयद्रथ, कर्ण तथा अन्य वीर योद्धा पहले ही मेरे द्वारा मारे जा चुके हैं; अतः तुम भयभीत मत हो, हे अर्जुन! तुम युद्ध करो; तुम निश्चय ही युद्ध में अपने शत्रुओं को पराजित करोगे।","gujarati":"દ્રોણ, ભીષ્મ, જયદ્રથ, કર્ણ તથા અન્ય શૂરવીર યોદ્ધાઓ તો મારા દ્વારા પહેલેથી જ હણાઈ ચૂક્યા છે; તેથી હે અર્જુન, તું ભય પામીશ નહીં; તું યુદ્ધ કર, તું આ સંગ્રામમાં ચોક્કસપણે તારા શત્રુઓને જીતીશ."},"11.35":{"chapter":11,"verse":35,"sloka":"सञ्जय उवाच\n\nएतच्छ्रुत्वा वचनं केशवस्य\n\nकृताञ्जलिर्वेपमानः किरीटी।\n\nनमस्कृत्वा भूय एवाह कृष्णं\n\nसगद्गदं भीतभीतः प्रणम्य।।11.35।।","transliteration":"sañjaya uvācha\netach chhrutvā vachanaṁ keśhavasya\nkṛitāñjalir vepamānaḥ kirīṭī\nnamaskṛitvā bhūya evāha kṛiṣhṇaṁ\nsa-gadgadaṁ bhīta-bhītaḥ praṇamya","english":"Sanjaya said: Having heard these words of Lord Krishna, the diadem-wearing Arjuna, with joined palms, trembling and bowing down, addressed Lord Krishna again in a choked voice, filled with awe and fear.","hindi":"संजय ने कहा: श्रीकृष्ण के इन वचनों को सुनकर मुकुटधारी अर्जुन ने हाथ जोड़कर, कांपते हुए और प्रणाम करके अत्यंत भयभीत होकर पुनः गदगद वाणी में श्रीकृष्ण से कहा।","gujarati":"સંજયે કહ્યું: શ્રીકૃષ્ણના આ વચનો સાંભળીને મુકુટધારી અર્જુન હાથ જોડીને, ધ્રૂજતા અને પ્રણામ કરીને, અત્યંત ભયભીત થઈને ફરીથી ગદગદ વાણીમાં શ્રીકૃષ્ણને કહેવા લાગ્યા."},"11.36":{"chapter":11,"verse":36,"sloka":"अर्जुन उवाच\n\nस्थाने हृषीकेश तव प्रकीर्त्या\n\nजगत् प्रहृष्यत्यनुरज्यते च।\n\nरक्षांसि भीतानि दिशो द्रवन्ति\n\nसर्वे नमस्यन्ति च सिद्धसङ्घाः।।11.36।।","transliteration":"arjuna uvācha\nsthāne hṛiṣhīkeśha tava prakīrtyā\njagat prahṛiṣhyaty anurajyate cha\nrakṣhānsi bhītāni diśho dravanti\nsarve namasyanti cha siddha-saṅghāḥ","english":"Arjuna said: 'O Hrishikesha, it is fitting that the world rejoices and delights in Your glory; the demons are struck with terror and flee in all directions, while all the hosts of the perfected beings bow down before You.'","hindi":"अर्जुन ने कहा -- हे हृषीकेश! यह उचित ही है कि आपके नाम, गुण और प्रभाव के कीर्तन से यह संसार हर्षित होता है और अनुराग करता है। भयभीत राक्षसगण सब दिशाओं में भाग रहे हैं और सिद्धों के समुदाय आपको नमस्कार कर रहे हैं।","gujarati":"અર્જુને કહ્યું: 'હે હૃષીકેશ! એ યોગ્ય જ છે કે આપના મહિમાના કીર્તનથી આ જગત આનંદિત થાય છે અને આપનામાં અનુરાગ રાખે છે. ભયભીત રાક્ષસો બધી દિશાઓમાં નાસી જાય છે અને સિદ્ધ પુરુષોના સમુદાયો આપને નમસ્કાર કરે છે.'"},"11.37":{"chapter":11,"verse":37,"sloka":"कस्माच्च ते न नमेरन्महात्मन्\n\nगरीयसे ब्रह्मणोऽप्यादिकर्त्रे।\n\nअनन्त देवेश जगन्निवास\n\nत्वमक्षरं सदसत्तत्परं यत्।।11.37।।","transliteration":"kasmāch cha te na nameran mahātman\ngarīyase brahmaṇo ’py ādi-kartre\nananta deveśha jagan-nivāsa\ntvam akṣharaṁ sad-asat tat paraṁ yat","english":"And why should they not bow to You, O Great Soul, who are even greater than Brahma, the original creator? O Infinite One, O Lord of the gods, O Abode of the universe, You are the imperishable source, the manifest and the unmanifest, and that which is beyond both, the Supreme Reality.","hindi":"हे महात्मन्! ब्रह्मा के भी आदि कर्ता और सबसे श्रेष्ठ आपके लिए वे क्यों न नमस्कार करें? हे अनन्त! हे देवेश! हे जगन्निवास! जो सत्-असत् और इन दोनों से परे अक्षरतत्त्व है, वह आप ही हैं।","gujarati":"હે મહાત્મન! આદિ કર્તા બ્રહ્માના પણ તમે કર્તા છો અને સૌથી શ્રેષ્ઠ છો, તો પછી તેઓ તમને કેમ નમસ્કાર ન કરે? હે અનંત! હે દેવેશ! હે જગન્નિવાસ! જે સત, અસત અને તે બંનેથી પર અક્ષર તત્વ છે, તે તમે જ છો."},"11.38":{"chapter":11,"verse":38,"sloka":"त्वमादिदेवः पुरुषः पुराण\n\nस्त्वमस्य विश्वस्य परं निधानम्।\n\nवेत्तासि वेद्यं च परं च धाम\n\nत्वया ततं विश्वमनन्तरूप।।11.38।।","transliteration":"tvam ādi-devaḥ puruṣhaḥ purāṇas\ntvam asya viśhvasya paraṁ nidhānam\nvettāsi vedyaṁ cha paraṁ cha dhāma\ntvayā tataṁ viśhvam ananta-rūpa","english":"You are the primal God, the ancient Purusha, and the supreme refuge of this universe. You are the knower, the knowable, and the supreme Abode. O Being of infinite forms, by You alone is this universe pervaded.","hindi":"आप आदिदेव और सनातन पुरुष हैं। आप इस जगत के परम आश्रय, ज्ञाता, ज्ञेय और परम धाम हैं। हे अनन्त रूप, आपसे ही यह सारा विश्व व्याप्त है।","gujarati":"તમે આદિદેવ અને સનાતન પુરુષ છો. તમે આ જગતનો પરમ આશ્રય, જ્ઞાતા, જ્ઞેય અને પરમ ધામ છો. હે અનંત રૂપ, તમારા દ્વારા જ આ વિશ્વ વ્યાપ્ત છે."},"11.39":{"chapter":11,"verse":39,"sloka":"वायुर्यमोऽग्निर्वरुणः शशाङ्कः\n\nप्रजापतिस्त्वं प्रपितामहश्च।\n\nनमो नमस्तेऽस्तु सहस्रकृत्वः\n\nपुनश्च भूयोऽपि नमो नमस्ते।।11.39।।","transliteration":"vāyur yamo ’gnir varuṇaḥ śhaśhāṅkaḥ\nprajāpatis tvaṁ prapitāmahaśh cha\nnamo namas te ’stu sahasra-kṛitvaḥ\npunaśh cha bhūyo ’pi namo namas te","english":"You are Vayu, Yama, Agni, Varuna, the Moon, the Creator, and the great-grandfather. Salutations to You a thousand times, and again and again, salutations to You.","hindi":"आप वायु, यम, अग्नि, वरुण, चन्द्रमा, प्रजापति और प्रपितामह हैं। आपके लिए सहस्र बार नमस्कार, नमस्कार है, पुनः आपको बारम्बार नमस्कार, नमस्कार है।","gujarati":"તમે વાયુ, યમ, અગ્નિ, વરુણ, ચંદ્રમા, પ્રજાપતિ અને પ્રપિતામહ છો. તમારા માટે સહસ્ત્ર વાર નમસ્કાર, નમસ્કાર છે, ફરી તમને વારંવાર નમસ્કાર, નમસ્કાર છે."},"11.40":{"chapter":11,"verse":40,"sloka":"नमः पुरस्तादथ पृष्ठतस्ते\n\nनमोऽस्तु ते सर्वत एव सर्व।\n\nअनन्तवीर्यामितविक्रमस्त्वं\n\nसर्वं समाप्नोषि ततोऽसि सर्वः।।11.40।।","transliteration":"namaḥ purastād atha pṛiṣhṭhatas te\nnamo ’stu te sarvata eva sarva\nananta-vīryāmita-vikramas tvaṁ\nsarvaṁ samāpnoṣhi tato ’si sarvaḥ","english":"Salutations to You in front and behind! Salutations to You on every side! O All! You, infinite in power and prowess, pervade all; therefore You are all.","hindi":"हे अनन्त सामर्थ्य वाले भगवन्! आपको आगे से और पीछे से भी नमस्कार है! हे सर्वात्मन्! आपको सब ओर से ही नमस्कार है। आप अमित विक्रमशाली हैं और आप ही सबको व्याप्त किये हुए हैं, इसलिए आप ही सब कुछ हैं।","gujarati":"હે અનંત સામર્થ્યવાળા પ્રભુ! તમને આગળથી અને પાછળથી નમસ્કાર હો! હે સર્વાત્મન! તમને બધી દિશાઓમાંથી નમસ્કાર હો! આપ અમિત પરાક્રમશાળી છો અને આપ જ આ બધું વ્યાપ્ત કરીને રહેલા છો, માટે આપ જ સર્વરૂપ છો."},"11.41":{"chapter":11,"verse":41,"sloka":"सखेति मत्वा प्रसभं यदुक्तं\n\nहे कृष्ण हे यादव हे सखेति।\n\nअजानता महिमानं तवेदं\n\nमया प्रमादात्प्रणयेन वापि।।11.41।।","transliteration":"sakheti matvā prasabhaṁ yad uktaṁ\nhe kṛiṣhṇa he yādava he sakheti\najānatā mahimānaṁ tavedaṁ\nmayā pramādāt praṇayena vāpi","english":"Whatever I have rashly said out of carelessness or affection, calling You 'O Krishna', 'O Yadava', or 'O Friend', considering You merely as a friend, not knowing Your greatness, O Achyuta.","hindi":"हे अच्युत! आपमें मेरी महिमा को न जानते हुए, लापरवाही से या प्रेम के वश में, मैंने आपको 'हे कृष्ण', 'हे यादव', 'हे सखा' कहकर जो कुछ भी कहा है, वह सब मेरी अज्ञानता थी।","gujarati":"હે અચ્યુત! આપની આ મહિમાને ન જાણતા, મેં આપને મિત્ર માનીને જે કંઈ પણ 'હે કૃષ્ણ', 'હે યાદવ', 'હે સખા' કહીને બેદરકારી કે પ્રેમથી અપમાન કર્યું હોય, તે માટે મને ક્ષમા કરો."},"11.42":{"chapter":11,"verse":42,"sloka":"यच्चावहासार्थमसत्कृतोऽसि\n\nविहारशय्यासनभोजनेषु।\n\nएकोऽथवाप्यच्युत तत्समक्षं\n\nतत्क्षामये त्वामहमप्रमेयम्।।11.42।।","transliteration":"yach chāvahāsārtham asat-kṛito ’si\nvihāra-śhayyāsana-bhojaneṣhu\neko ’tha vāpy achyuta tat-samakṣhaṁ\ntat kṣhāmaye tvām aham aprameyam","english":"In whatever way I may have insulted You out of carelessness or love, while at play, reclining, sitting, or dining, whether alone or in the presence of others, O Achyuta, I implore You, the immeasurable Lord Krishna, to forgive me.","hindi":"हे अच्युत! जो कुछ भी मैंने हँसी-मज़ाक में, खेल-कूद में, सोते, बैठते या भोजन करते समय अकेले में या सबके सामने आपका अपमान किया हो, उस सबके लिए मैं आप से, हे अप्रमेय भगवान श्रीकृष्ण, क्षमा माँगता हूँ।","gujarati":"હે અચ્યુત! મેં જે કંઈ પણ મજાકમાં, રમતમાં, સૂતી વખતે, બેસતી વખતે કે ભોજન કરતી વખતે, એકાંતમાં અથવા અન્યોની હાજરીમાં આપનું અપમાન કર્યું હોય, તે બધા માટે હું આપની, હે અપરિમિત ભગવાન શ્રીકૃષ્ણ, ક્ષમા માંગું છું."},"11.43":{"chapter":11,"verse":43,"sloka":"पितासि लोकस्य चराचरस्य\n\nत्वमस्य पूज्यश्च गुरुर्गरीयान्।\n\nन त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो\n\nलोकत्रयेऽप्यप्रतिमप्रभाव।।11.43।।","transliteration":"pitāsi lokasya charācharasya\ntvam asya pūjyaśh cha gurur garīyān\nna tvat-samo ’sty abhyadhikaḥ kuto ’nyo\nloka-traye ’py apratima-prabhāva","english":"You are the Father of the entire world, of all that moves and remains stationary. You are the worthy object of adoration, the supreme Guru. O Lord of incomparable power, there is none equal to You in all the three worlds; how, then, could anyone be greater than You?","hindi":"आप इस चराचर जगत् के पिता और परम पूजनीय गुरु हैं। हे अतुलनीय प्रभाव वाले भगवन्! तीनों लोकों में आपके समान भी कोई नहीं है, तो फिर आपसे अधिक श्रेष्ठ कैसे हो सकता है?","gujarati":"તમે આ સ્થાવર અને જંગમ વિશ્વના પિતા અને પરમ પૂજનીય ગુરુ છો. હે અતુલનીય પ્રભાવવાળા ભગવાન! ત્રણેય લોકમાં તમારા સમાન પણ કોઈ નથી, તો પછી તમારાથી ચડિયાતું બીજું કોણ હોઈ શકે?"},"11.44":{"chapter":11,"verse":44,"sloka":"तस्मात्प्रणम्य प्रणिधाय कायं\n\nप्रसादये त्वामहमीशमीड्यम्।\n\nपितेव पुत्रस्य सखेव सख्युः\n\nप्रियः प्रियायार्हसि देव सोढुम्।।11.44।।","transliteration":"tasmāt praṇamya praṇidhāya kāyaṁ\nprasādaye tvām aham īśham īḍyam\npiteva putrasya sakheva sakhyuḥ\npriyaḥ priyāyārhasi deva soḍhum","english":"Therefore, bowing down and prostrating my body, I crave Thy forgiveness, O adorable Lord. As a father forgives his son, a friend his dear friend, a lover his beloved, even so may Thou forgive me, O God.","hindi":"अतः हे पूजनीय प्रभु! मैं अपने शरीर को साष्टांग प्रणाम करते हुए आप भगवान् से क्षमा याचना करता हूँ। जैसे पिता अपने पुत्र के, मित्र अपने मित्र के और प्रेमी अपनी प्रिया के अपराधों को क्षमा कर देते हैं, उसी प्रकार हे भगवन् श्री कृष्ण! आप भी मेरे अपराधों को क्षमा करने की कृपा करें।","gujarati":"તેથી, હે પૂજનીય પ્રભુ! હું મારા શરીરને સાષ્ટાંગ દંડવત્ પ્રણામ કરીને આપની ક્ષમા માંગુ છું. જેમ પિતા પોતાના પુત્રના, મિત્ર પોતાના મિત્રના અને પ્રેમી પોતાની પ્રેમિકાના અપરાધને ક્ષમા કરે છે, તેવી જ રીતે હે શ્રી કૃષ્ણ! આપ પણ મારા અપરાધોને ક્ષમા કરો."},"11.45":{"chapter":11,"verse":45,"sloka":"अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा\n\nभयेन च प्रव्यथितं मनो मे।\n\nतदेव मे दर्शय देव रूपं\n\nप्रसीद देवेश जगन्निवास।।11.45।।","transliteration":"adṛiṣhṭa-pūrvaṁ hṛiṣhito ’smi dṛiṣhṭvā\nbhayena cha pravyathitaṁ mano me\ntad eva me darśhaya deva rūpaṁ\nprasīda deveśha jagan-nivāsa","english":"Arjuna said: I am delighted to have seen that which has never been seen before, yet my mind is disturbed by fear. O Lord Krishna, please show me Your previous form; have mercy, O God of gods, O Abode of the universe.","hindi":"अर्जुन ने कहा: मैं पहले न देखे हुए इस अद्भुत रूप को देखकर हर्षित हो रहा हूँ, परन्तु मेरा मन भय से व्याकुल हो रहा है। हे श्री कृष्ण! आप मुझे अपना वह पूर्व का रूप ही दिखाएँ। हे देवेश! हे जगन्निवास! मुझ पर प्रसन्न होइये।","gujarati":"અર્જુને કહ્યું: મેં જે કદી જોયું નથી તે જોઈને હું આનંદિત થયો છું, પરંતુ મારું મન ભયથી વ્યાકુળ પણ થઈ રહ્યું છે. હે શ્રીકૃષ્ણ! મને આપનું તે પૂર્વેનું રૂપ જ દર્શાવો. હે દેવેશ! હે જગન્નિવાસ! આપ પ્રસન્ન થાઓ."},"11.46":{"chapter":11,"verse":46,"sloka":"किरीटिनं गदिनं चक्रहस्त\n\nमिच्छामि त्वां द्रष्टुमहं तथैव।\n\nतेनैव रूपेण चतुर्भुजेन\n\nसहस्रबाहो भव विश्वमूर्ते।।11.46।।","transliteration":"kirīṭinaṁ gadinaṁ chakra-hastam\nichchhāmi tvāṁ draṣhṭum ahaṁ tathaiva\ntenaiva rūpeṇa chatur-bhujena\nsahasra-bāho bhava viśhva-mūrte","english":"I wish to see You as before, wearing a crown and holding a mace and a discus; O thousand-armed one, O Cosmic Form, please appear again in Your four-armed form.","hindi":"मैं आपको पहले की तरह मुकुट धारण किए हुए, गदा और चक्र हाथ में लिए हुए देखना चाहता हूँ। हे सहस्र भुजाओं वाले! हे विश्वरूप! आप पुनः अपने चतुर्भुज रूप में प्रकट हो जाइए।","gujarati":"હું આપને પહેલાની જેમ મુગટ ધારણ કરેલા, ગદા અને ચક્ર હાથમાં લીધેલા જોવા ઈચ્છું છું. હે સહસ્ત્રબાહુ! હે વિશ્વરૂપ! આપ ફરીથી આપના ચતુર્ભુજ સ્વરૂપમાં પ્રગટ થાઓ."},"11.47":{"chapter":11,"verse":47,"sloka":"श्री भगवानुवाच\n\nमया प्रसन्नेन तवार्जुनेदं\n\nरूपं परं दर्शितमात्मयोगात्।\n\nतेजोमयं विश्वमनन्तमाद्यं\n\nयन्मे त्वदन्येन न दृष्टपूर्वम्।।11.47।।","transliteration":"śhrī-bhagavān uvācha\nmayā prasannena tavārjunedaṁ\nrūpaṁ paraṁ darśhitam ātma-yogāt\ntejo-mayaṁ viśhvam anantam ādyaṁ\nyan me tvad anyena na dṛiṣhṭa-pūrvam","english":"The Blessed Lord Shri Krishna said: 'O Arjuna, being pleased with you, I have shown you through My own divine Yogic power this supreme, brilliant, universal, primal, and infinite Cosmic Form, which has not been seen by anyone else before you.'","hindi":"भगवान श्रीकृष्ण ने कहा: 'हे अर्जुन! तुम पर प्रसन्न होकर मैंने अपनी योगशक्ति के प्रभाव से तुम्हें यह मेरा परम तेजोमय, सबका आदि और अनंत विश्वरूप दिखाया है, जिसे तुम्हारे अतिरिक्त पूर्व में किसी ने नहीं देखा है।'","gujarati":"ભગવાન શ્રીકૃષ્ણે કહ્યું: 'હે અર્જુન! તારા પર પ્રસન્ન થઈને મેં મારી પોતાની યોગશક્તિથી તને આ મારું પરમ તેજોમય, અનાદિ અને અનંત વિશ્વરૂપ દર્શાવ્યું છે, જે તારા સિવાય અન્ય કોઈએ ક્યારેય જોયું નથી.'"},"11.48":{"chapter":11,"verse":48,"sloka":"न वेदयज्ञाध्ययनैर्न दानै\n\nर्न च क्रियाभिर्न तपोभिरुग्रैः।\n\nएवंरूपः शक्य अहं नृलोके\n\nद्रष्टुं त्वदन्येन कुरुप्रवीर।।11.48।।","transliteration":"na veda-yajñādhyayanair na dānair\nna cha kriyābhir na tapobhir ugraiḥ\nevaṁ-rūpaḥ śhakya ahaṁ nṛi-loke\ndraṣhṭuṁ tvad anyena kuru-pravīra","english":"Neither by study of the Vedas, nor by penance, nor by charity, nor by ritual sacrifices, can I be seen in this form in the material world by anyone other than you, O Arjuna, the best of the Kurus.","hindi":"हे अर्जुन, न तो वेदों के अध्ययन से, न दान से, न यज्ञों से और न ही कठोर तपस्याओं से, मनुष्य लोक में मेरे इस विश्वरूप को तुम्हारे अतिरिक्त अन्य कोई देख सकता है।","gujarati":"હે અર્જુન, ન તો વેદોના અધ્યયનથી, ન દાનથી, ન યજ્ઞોથી અને ન તો કઠોર તપસ્યાઓથી, આ મનુષ્યલોકમાં મારા આ વિશ્વરૂપને તમારા સિવાય અન્ય કોઈ જોઈ શકતું નથી."},"11.49":{"chapter":11,"verse":49,"sloka":"मा ते व्यथा मा च विमूढभावो\n\nदृष्ट्वा रूपं घोरमीदृङ्ममेदम्।\n\nव्यपेतभीः प्रीतमनाः पुनस्त्वं\n\nतदेव मे रूपमिदं प्रपश्य।।11.49।।","transliteration":"mā te vyathā mā cha vimūḍha-bhāvo\ndṛiṣhṭvā rūpaṁ ghoram īdṛiṅ mamedam\nvyapeta-bhīḥ prīta-manāḥ punas tvaṁ\ntad eva me rūpam idaṁ prapaśhya","english":"Be not afraid nor bewildered by seeing this terrible form of Mine. With all fear dispelled and with a gladdened heart, behold again this former familiar form of Mine.","hindi":"मेरे इस विकराल रूप को देखकर तुम्हें भयभीत नहीं होना चाहिए और न ही भ्रमित होना चाहिए। अब अपने भय को दूर कर और प्रसन्नचित्त होकर, तुम पुनः मेरे उसी सौम्य पूर्व रूप को देखो।","gujarati":"મારા આ વિકરાળ સ્વરૂપને જોઈને તારે ગભરાવું કે મોહિત થવું જોઈએ નહીં. હવે તારા મનમાંથી ભય દૂર કરીને અને પ્રસન્ન ચિત્તે, તું ફરીથી મારા તે જ પૂર્વના સૌમ્ય સ્વરૂપને નિહાળ."},"11.50":{"chapter":11,"verse":50,"sloka":"सञ्जय उवाच\n\nइत्यर्जुनं वासुदेवस्तथोक्त्वा\n\nस्वकं रूपं दर्शयामास भूयः।\n\nआश्वासयामास च भीतमेनं\n\nभूत्वा पुनः सौम्यवपुर्महात्मा।।11.50।।","transliteration":"sañjaya uvācha\nity arjunaṁ vāsudevas tathoktvā\nsvakaṁ rūpaṁ darśhayām āsa bhūyaḥ\nāśhvāsayām āsa cha bhītam enaṁ\nbhūtvā punaḥ saumya-vapur mahātmā","english":"Sanjaya said: Having spoken thus to Arjuna, Krishna displayed His own form again. The Supreme Soul, assuming His gentle form, then consoled the terrified Arjuna.","hindi":"संजय ने कहा: अर्जुन से इस प्रकार कहकर श्रीकृष्ण ने पुनः अपना सौम्य रूप प्रकट किया। महात्मा ने अपने उस मनमोहक रूप को धारण कर भयभीत अर्जुन को धीरज बंधाया।","gujarati":"સંજયે કહ્યું: અર્જુનને આ પ્રમાણે કહીને શ્રીકૃષ્ણે ફરીથી પોતાનું સૌમ્ય સ્વરૂપ ધારણ કર્યું. તે મહાત્માએ પોતાના મનોહર રૂપમાં આવીને ભયભીત થયેલા અર્જુનને આશ્વાસન આપ્યું."},"11.51":{"chapter":11,"verse":51,"sloka":"अर्जुन उवाच\n\nदृष्ट्वेदं मानुषं रूपं तवसौम्यं जनार्दन।\n\nइदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः।।11.51।।","transliteration":"arjuna uvācha\ndṛiṣhṭvedaṁ mānuṣhaṁ rūpaṁ tava saumyaṁ janārdana\nidānīm asmi saṁvṛittaḥ sa-chetāḥ prakṛitiṁ gataḥ","english":"Arjuna said: 'O Janardana, seeing this gentle human form of Yours, I have now become composed and am restored to my own nature.'","hindi":"अर्जुन ने कहा - हे जनार्दन! आपके इस सौम्य मनुष्य रूप को देखकर अब मैं शांतचित्त हुआ और अपने स्वभाव को प्राप्त हो गया हूँ।","gujarati":"અર્જુને કહ્યું - હે જનાર્દન! તમારા આ સૌમ્ય મનુષ્ય રૂપને જોઈને હવે હું શાંતચિત્ત થયો છું અને પોતાના સ્વભાવને પ્રાપ્ત થઈ ગયો છું."},"11.52":{"chapter":11,"verse":52,"sloka":"श्री भगवानुवाच\n\nसुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम।\n\nदेवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः।।11.52।।","transliteration":"śhrī-bhagavān uvācha\nsu-durdarśham idaṁ rūpaṁ dṛiṣhṭavān asi yan mama\ndevā apy asya rūpasya nityaṁ darśhana-kāṅkṣhiṇaḥ","english":"The Supreme Lord Shri Krishna said: This form of Mine, which you have seen, is very difficult to perceive; even the celestial beings are always longing to behold this vision.","hindi":"श्रीभगवान् ने कहा: मेरा यह रूप, जिसे तुमने अभी देखा है, अत्यंत दुर्लभ है; देवता भी सदा इस रूप के दर्शन के लिए लालायित रहते हैं।","gujarati":"શ્રી ભગવાન બોલ્યા: મારું જે આ સ્વરૂપ તેં જોયું છે, તે જોવું અત્યંત દુર્લભ છે; દેવતાઓ પણ સદા આ સ્વરૂપના દર્શન માટે તરસતા હોય છે."},"11.53":{"chapter":11,"verse":53,"sloka":"नाहं वेदैर्न तपसा न दानेन न चेज्यया।\n\nशक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा।।11.53।।","transliteration":"nāhaṁ vedair na tapasā na dānena na chejyayā\nśhakya evaṁ-vidho draṣhṭuṁ dṛiṣhṭavān asi māṁ yathā","english":"Neither by the study of the Vedas, nor by austerities, nor by charity, nor by ritual sacrifices can I be seen in this form as you have seen Me, O Arjuna.","hindi":"न तो वेदों के अध्ययन से, न तप से, न दान से और न ही यज्ञों के अनुष्ठान से मैं उस रूप में देखा जा सकता हूँ, जिस प्रकार तुमने मुझे देखा है।","gujarati":"ન તો વેદો દ્વારા, ન તો તપ દ્વારા, ન તો દાન દ્વારા અને ન તો યજ્ઞ દ્વારા જ હું આ રૂપે જોવા મળી શકું છું, જે રીતે તેં મને જોયો છે."},"11.54":{"chapter":11,"verse":54,"sloka":"भक्त्या त्वनन्यया शक्यमहमेवंविधोऽर्जुन।\n\nज्ञातुं दृष्टुं च तत्त्वेन प्रवेष्टुं च परंतप।।11.54।।","transliteration":"bhaktyā tv ananyayā śhakya aham evaṁ-vidho ’rjuna\njñātuṁ draṣhṭuṁ cha tattvena praveṣhṭuṁ cha parantapa","english":"But by unalloyed devotion alone, I can be known, seen, and entered into in reality, O Arjuna.","hindi":"किंतु हे अर्जुन! अनन्य भक्ति के द्वारा मुझे इस प्रकार प्रत्यक्ष तत्व से जानने के लिए, देखने के लिए और मुझमें प्रवेश करने के लिए भी मैं सुलभ हूँ।","gujarati":"પરંતુ હે અર્જુન! અનન્ય ભક્તિ દ્વારા જ મને તત્ત્વથી જાણી શકાય છે, જોઈ શકાય છે અને મારામાં પ્રવેશ કરી શકાય છે."},"11.55":{"chapter":11,"verse":55,"sloka":"मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः।\n\nनिर्वैरः सर्वभूतेषु यः स मामेति पाण्डव।।11.55।।","transliteration":"mat-karma-kṛin mat-paramo mad-bhaktaḥ saṅga-varjitaḥ\nnirvairaḥ sarva-bhūteṣhu yaḥ sa mām eti pāṇḍava","english":"He who performs all actions for My sake, who considers Me the Supreme, who is My devotee, free from attachment and devoid of enmity towards any living being—that soul, O Arjuna, comes to Me.","hindi":"हे अर्जुन! जो पुरुष मेरे लिए ही कर्म करने वाला है, और मुझे ही परम लक्ष्य मानता है, जो मेरा भक्त है तथा संगरहित है, जो भूतमात्र के प्रति निर्वैर है, वह मुझे ही प्राप्त होता है।","gujarati":"હે અર્જુન! જે મનુષ્ય મારા માટે જ કર્મ કરનારો છે, જે મને જ સર્વોપરી માને છે, જે મારો ભક્ત છે અને સંગરહિત છે, જે સર્વ પ્રાણીઓ પ્રત્યે વેરભાવ રહિત છે, તે મને જ પ્રાપ્ત થાય છે."},"12.1":{"chapter":12,"verse":1,"sloka":"अर्जुन उवाचएवं सततयुक्ता ये भक्तास्त्वां पर्युपासते।येचाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः।।12.1।।","transliteration":"arjuna uvācha\nevaṁ satata-yuktā ye bhaktās tvāṁ paryupāsate\nye chāpy akṣharam avyaktaṁ teṣhāṁ ke yoga-vittamāḥ","english":"Arjuna said, 'Those devotees who thus, ever steadfast, worship You, and those who worship the Imperishable and the Unmanifested—which of these are the better knowers of Yoga?'","hindi":"अर्जुन ने कहा - 'जो भक्तगण इस प्रकार निरंतर आपकी उपासना करते हैं, और जो भक्त उस अक्षर (विनाशरहित) एवं अव्यक्त (निराकार) की उपासना करते हैं, उन दोनों में से योग को जानने वाले श्रेष्ठ कौन हैं?'","gujarati":"અર્જુને પૂછ્યું - 'જે ભક્તો સતત તમારી આ રીતે ભક્તિ કરે છે, અને જેઓ અક્ષર અને અવ્યક્તની ઉપાસના કરે છે, તે બંનેમાંથી યોગના જાણકારોમાં કોણ શ્રેષ્ઠ છે?'"},"12.2":{"chapter":12,"verse":2,"sloka":"श्री भगवानुवाचमय्यावेश्य मनो ये मां नित्ययुक्ता उपासते।श्रद्धया परयोपेतास्ते मे युक्ततमा मताः।।12.2।।","transliteration":"śhrī-bhagavān uvācha\nmayy āveśhya mano ye māṁ nitya-yuktā upāsate\nśhraddhayā parayopetās te me yuktatamā matāḥ","english":"The Supreme Lord Shri Krishna said: Those who, fixing their minds on Me, worship Me with supreme faith and are always united with Me in devotion, are considered by Me to be the most perfect in the practice of Yoga.","hindi":"श्रीभगवान् ने कहा: मुझमें मन को एकाग्र करके, निरंतर मुझमें युक्त हुए जो भक्तजन परम श्रद्धा से युक्त होकर मेरी उपासना करते हैं, वे मेरे मत में योगियों में सर्वश्रेष्ठ हैं।","gujarati":"શ્રી ભગવાન બોલ્યા: જેઓ મારામાં મન એકાગ્ર કરીને, નિત્ય મુજમાં જોડાયેલા રહીને, પરમ શ્રદ્ધા સાથે મારી ઉપાસના કરે છે, તેમને હું સર્વ યોગીઓમાં શ્રેષ્ઠ માનું છું."},"12.3":{"chapter":12,"verse":3,"sloka":"ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते।सर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम्।।12.3।।","transliteration":"ye tv akṣharam anirdeśhyam avyaktaṁ paryupāsate\nsarvatra-gam achintyañcha kūṭa-stham achalandhruvam\n sanniyamyendriya-grāmaṁ sarvatra sama-buddhayaḥ\nte prāpnuvanti mām eva sarva-bhūta-hite ratāḥ","english":"But those who fully worship the imperishable, the indefinable, the unmanifest, the all-pervading, the unthinkable, the unchanging, the immovable, and the eternal.","hindi":"परन्तु जो लोग उस अक्षर, अनिर्देश्य, अव्यक्त, सर्वव्यापी, अचिन्त्य, कूटस्थ, अचल और ध्रुव की उपासना करते हैं।","gujarati":"પરંતુ જે ભક્તો અક્ષર, અનિર્દેશ્ય, અવ્યક્ત, સર્વવ્યાપી, અચિંત્ય, કૂટસ્થ, અચળ અને નિત્ય એવા પરબ્રહ્મની ઉપાસના કરે છે."},"12.4":{"chapter":12,"verse":4,"sloka":"संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः।ते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः।।12.4।।","transliteration":"sanniyamyendriya-grāmaṁ  sarvatra    sama-buddhayaḥ  te  prāpnuvanti mām eva sarva-bhūta-hite    ratāḥ","english":"Those who have fully subdued their senses, who remain even-minded in all circumstances, and who are constantly engaged in the welfare of all living beings, they verily attain Me.","hindi":"जो सम्पूर्ण इन्द्रिय-समुदाय को वश में करके, सर्वत्र समभाव रखने वाले और समस्त प्राणियों के हित में लगे हुए हैं, वे भक्त मुझे ही प्राप्त होते हैं।","gujarati":"જેઓ સંપૂર્ણ ઇન્દ્રિયોને વશમાં રાખીને, સર્વત્ર સમભાવ રાખનારા અને તમામ પ્રાણીઓના કલ્યાણમાં રચ્યાપચ્યા રહેલા છે, તેવા ભક્તો મને જ પ્રાપ્ત થાય છે."},"12.5":{"chapter":12,"verse":5,"sloka":"क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।\n\nअव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते।।12.5।।","transliteration":"kleśho ’dhikataras teṣhām avyaktāsakta-chetasām\navyaktā hi gatir duḥkhaṁ dehavadbhir avāpyate","english":"For those whose minds are attached to the unmanifested, the struggle is greater, for the path toward the unmanifested is difficult for those who possess a physical body, O Arjuna.","hindi":"जिनका मन अव्यक्त (निराकार) में आसक्त है, उनके लिए क्लेश अधिक है, क्योंकि देहधारी जीवों के लिए अव्यक्त की प्राप्ति अत्यंत कठिन है।","gujarati":"જેમનું ચિત્ત અવ્યક્ત (નિરાકાર)માં આસક્ત છે, તેમના માટે ક્લેશ અધિક છે, કારણ કે દેહધારી જીવો માટે અવ્યક્ત તત્વની પ્રાપ્તિ અત્યંત કઠિન છે."},"12.6":{"chapter":12,"verse":6,"sloka":"ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः।अनन्येनैव योगेन मां ध्यायन्त उपासते।।12.6।।","transliteration":"ye tu sarvāṇi karmāṇi mayi sannyasya mat-paraḥ\nananyenaiva yogena māṁ dhyāyanta upāsate","english":"But those who worship Me, renouncing all actions unto Me, regarding Me as their supreme goal, and meditating upon Me with single-minded devotion through yoga—them, I swiftly deliver.","hindi":"परंतु जो भक्तजन समस्त कर्मों को मुझमें अर्पण करके, मुझे ही अपना परम लक्ष्य मानकर, अनन्ययोग के द्वारा मेरा ही ध्यान करते हुए मेरी उपासना करते हैं, उन्हें मैं शीघ्र ही भवसागर से मुक्त कर देता हूँ।","gujarati":"પરંતુ જે ભક્તો મને જ પરમ લક્ષ્ય ગણીને, સર્વ કર્મોને મારામાં અર્પણ કરી, અનન્ય યોગ દ્વારા મારું જ ધ્યાન ધરે છે, તેઓને હું શીઘ્ર ભવસાગરમાંથી મુક્ત કરું છું."},"12.7":{"chapter":12,"verse":7,"sloka":"तेषामहं समुद्धर्ता मृत्युसंसारसागरात्।भवामि नचिरात्पार्थ मय्यावेशितचेतसाम्।।12.7।।","transliteration":"teṣhām ahaṁ samuddhartā mṛityu-saṁsāra-sāgarāt\nbhavāmi na chirāt pārtha mayy āveśhita-chetasām","english":"For those whose minds are fixed upon Me, O Arjuna, I verily become the savior from the ocean of birth and death, which is the ocean of Samsara, before long.","hindi":"हे अर्जुन! जो मुझमें ही अपना मन स्थिर कर लेते हैं, उन भक्तों का मैं इस मृत्युरूप संसार-सागर से शीघ्र ही उद्धार करने वाला बन जाता हूँ।","gujarati":"હે અર્જુન! જેઓ પોતાનું ચિત્ત મારામાં સ્થિર કરે છે, તેવા ભક્તોનો હું આ મૃત્યુરૂપ સંસાર-સાગરમાંથી શીઘ્ર ઉદ્ધાર કરનાર બનું છું."},"12.8":{"chapter":12,"verse":8,"sloka":"मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः।।12.8।।","transliteration":"mayy eva mana ādhatsva mayi buddhiṁ niveśhaya\nnivasiṣhyasi mayy eva ata ūrdhvaṁ na sanśhayaḥ","english":"Fix your mind on Me, and let your intellect dwell in Me; thus, you shall undoubtedly live in Me alone hereafter.","hindi":"मुझमें ही अपने मन को लगाओ और मुझमें ही अपनी बुद्धि को स्थिर करो, इसके उपरांत तुम मुझमें ही निवास करोगे, इसमें कोई संशय नहीं है।","gujarati":"મારામાં જ મનને સ્થિર કર અને મારામાં જ બુદ્ધિને પરોવ; આ રીતે તું નિશ્ચિતપણે મારામાં જ નિવાસ કરીશ, તેમાં કોઈ સંશય નથી."},"12.9":{"chapter":12,"verse":9,"sloka":"अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।अभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय।।12.9।।","transliteration":"atha chittaṁ samādhātuṁ na śhaknoṣhi mayi sthiram\nabhyāsa-yogena tato mām ichchhāptuṁ dhanañjaya","english":"If you are unable to fix your mind steadily upon Me, O Dhananjaya, then seek to reach Me through the yoga of constant practice.","hindi":"हे धनंजय! यदि तुम अपने मन को मुझमें स्थिर करने में समर्थ नहीं हो, तो अभ्यासयोग के द्वारा तुम मुझे प्राप्त करने का प्रयत्न करो।","gujarati":"હે ધનંજય! જો તું તારા મનને મારામાં સ્થિર કરવા માટે સમર્થ ન હોય, તો અભ્યાસયોગ દ્વારા મને પ્રાપ્ત કરવાની ઈચ્છા કર."},"12.10":{"chapter":12,"verse":10,"sloka":"अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।मदर्थमपि कर्माणि कुर्वन् सिद्धिमवाप्स्यसि।।12.10।।","transliteration":"abhyāse ’py asamartho ’si mat-karma-paramo bhava\nmad-artham api karmāṇi kurvan siddhim avāpsyasi","english":"If you are unable even to practice Abhyasa Yoga, then be intent on performing all your actions for My sake; for even by working for My sake, you shall attain the ultimate perfection.","hindi":"यदि तुम अभ्यास योग में भी असमर्थ हो, तो केवल मेरे लिए कर्म करने के प्रति समर्पित हो जाओ; इस प्रकार मेरे लिए कर्म करते हुए भी तुम सिद्धि को प्राप्त करोगे।","gujarati":"જો તું આ અભ્યાસ યોગમાં પણ અસમર્થ હોય, તો મારા માટે જ કર્મ કરવાને પરાયણ થા; આ રીતે મારા માટે કર્મો કરતો રહીને પણ તું સિદ્ધિને પ્રાપ્ત કરીશ."},"12.11":{"chapter":12,"verse":11,"sloka":"अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः।सर्वकर्मफलत्यागं ततः कुरु यतात्मवान्।।12.11।।","transliteration":"athaitad apy aśhakto ’si kartuṁ mad-yogam āśhritaḥ\nsarva-karma-phala-tyāgaṁ tataḥ kuru yatātmavān","english":"If you are unable to do even this, then take refuge in union with Me, and while possessing self-control, renounce the fruits of all actions.","hindi":"यदि तू इसको भी करने में असमर्थ है, तो मेरे परायण होकर, आत्मसंयम से युक्त होकर समस्त कर्मों के फल का त्याग कर दे।","gujarati":"જો તું આ કરવા માટે પણ અસમર્થ હોય, તો મારામાં સ્થિત થઈને, આત્મસંયમથી યુક્ત થઈને સર્વ કર્મોના ફળનો ત્યાગ કર."},"12.12":{"chapter":12,"verse":12,"sloka":"श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्।।12.12।।","transliteration":"śhreyo hi jñānam abhyāsāj jñānād dhyānaṁ viśhiṣhyate\ndhyānāt karma-phala-tyāgas tyāgāch chhāntir anantaram","english":"Better indeed is knowledge than mechanical practice; better than knowledge is meditation; better than meditation is the renunciation of the fruits of actions, for peace immediately follows such renunciation.","hindi":"अभ्यास से ज्ञान श्रेष्ठ है, ज्ञान से श्रेष्ठ ध्यान है और ध्यान से भी श्रेष्ठ कर्मफल का त्याग है, क्योंकि त्याग से तत्काल ही परम शांति प्राप्त होती है।","gujarati":"અભ્યાસ કરતાં જ્ઞાન શ્રેષ્ઠ છે, જ્ઞાન કરતાં ધ્યાન શ્રેષ્ઠ છે અને ધ્યાન કરતાં પણ કર્મફળનો ત્યાગ શ્રેષ્ઠ છે; ત્યાગથી તત્કાળ શાંતિ પ્રાપ્ત થાય છે."},"12.13":{"chapter":12,"verse":13,"sloka":"अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।निर्ममो निरहङ्कारः समदुःखसुखः क्षमी।।12.13।।","transliteration":"adveṣhṭā sarva-bhūtānāṁ maitraḥ karuṇa eva cha\nnirmamo nirahankāraḥ sama-duḥkha-sukhaḥ kṣhamī","english":"He who bears no hatred toward any creature, who is a friend and compassionate to all, who is free from the sense of 'mine' and 'I', who is equipoised in pleasure and pain, and who is ever-forgiving.","hindi":"जो समस्त प्राणियों के प्रति द्वेष से रहित है, जो सबका मित्र और करुणावान है, जो ममता और अहंकार से मुक्त है, जो सुख और दुःख में समान रहता है और जो सदा क्षमाशील है।","gujarati":"જે કોઈ પણ પ્રાણી પ્રત્યે દ્વેષ રાખતો નથી, જે સૌનો મિત્ર અને દયાળુ છે, જે મમતા અને અહંકારથી મુક્ત છે, જે સુખ અને દુઃખમાં સમાન છે અને જે હંમેશા ક્ષમાશીલ છે."},"12.14":{"chapter":12,"verse":14,"sloka":"सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः।मय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः।।12.14।।","transliteration":"santuṣhṭaḥ satataṁ yogī yatātmā dṛiḍha-niśhchayaḥ\nmayy arpita-mano-buddhir yo mad-bhaktaḥ sa me priyaḥ","english":"Always content, steady in meditation, self-controlled, possessing firm conviction, with mind and intelligence dedicated to Me, such a devotee is dear to Lord Krishna.","hindi":"जो सदा सन्तुष्ट, निरंतर योग में स्थित, संयमित, दृढ़ निश्चयी है और जिसने अपना मन तथा बुद्धि मुझमें समर्पित कर दिए हैं, ऐसा मेरा भक्त श्री कृष्ण को अत्यंत प्रिय है।","gujarati":"જે સદા સંતુષ્ટ, યોગમાં સ્થિર, આત્મસંયમી અને દ્રઢ નિશ્ચયી છે, તથા જેણે પોતાનું મન અને બુદ્ધિ મારામાં અર્પણ કરી દીધા છે, તેવો મારો ભક્ત શ્રીકૃષ્ણને પ્રિય છે."},"12.15":{"chapter":12,"verse":15,"sloka":"यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः।हर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः।।12.15।।","transliteration":"yasmān nodvijate loko lokān nodvijate cha yaḥ\nharṣhāmarṣha-bhayodvegair mukto yaḥ sa cha me priyaḥ","english":"He by whom the world is not agitated, and who is not agitated by the world, who is freed from joy, anger, fear, and anxiety—he is dear to Me.","hindi":"जिससे संसार को उद्वेग नहीं होता और जो स्वयं भी संसार से उद्विग्न नहीं होता, तथा जो हर्ष, क्रोध, भय और उद्वेग से मुक्त है, वह भक्त मुझे प्रिय है।","gujarati":"જેનાથી જગત ઉદ્વેગ પામતું નથી અને જે પોતે પણ જગતથી ઉદ્વેગ પામતો નથી, તથા જે હર્ષ, અમર્ષ, ભય અને ઉદ્વેગથી મુક્ત છે, તે મને પ્રિય છે."},"12.16":{"chapter":12,"verse":16,"sloka":"अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः।सर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः।।12.16।।","transliteration":"anapekṣhaḥ śhuchir dakṣha udāsīno gata-vyathaḥ\nsarvārambha-parityāgī yo mad-bhaktaḥ sa me priyaḥ","english":"He who is free from wants, pure, expert, unconcerned, and free from pain, renouncing all undertakings and commencements, he who is devoted to Me is dear to Me.","hindi":"जो अपेक्षारहित, शुद्ध, दक्ष, उदासीन, व्यथारहित और सर्वकर्मों के आरंभ का त्यागी है, वह मेरा भक्त मुझे अति प्रिय है।","gujarati":"જે આકાંક્ષારહિત, શુદ્ધ, દક્ષ, ઉદાસીન, વ્યથારહિત અને સર્વ કર્મોના આરંભનો ત્યાગી છે, તેવો મારો ભક્ત મને પ્રિય છે."},"12.17":{"chapter":12,"verse":17,"sloka":"यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति।शुभाशुभपरित्यागी भक्ितमान्यः स मे प्रियः।।12.17।।","transliteration":"yo na hṛiṣhyati na dveṣhṭi na śhochati na kāṅkṣhati\nśhubhāśhubha-parityāgī bhaktimān yaḥ sa me priyaḥ","english":"He who neither rejoices nor hates, neither grieves nor desires, who renounces both the auspicious and the inauspicious, and is full of devotion—such a devotee is dear to Shri Krishna.","hindi":"जो न कभी हर्षित होता है, न द्वेष करता है, न शोक करता है और न ही कोई कामना करता है; जो शुभ और अशुभ दोनों प्रकार के कर्म-फल का त्याग करके अनन्य भक्ति में लीन है, वह भक्त भगवान् श्रीकृष्ण को अति प्रिय है।","gujarati":"જે ન કદી હર્ષિત થાય છે, ન દ્વેષ કરે છે, ન શોક કરે છે અને ન આકાંક્ષા રાખે છે; જે શુભ અને અશુભ બંનેના ત્યાગ કરીને ભક્તિમાં લીન છે, તેવો ભક્ત ભગવાન શ્રીકૃષ્ણને અતિ પ્રિય છે."},"12.18":{"chapter":12,"verse":18,"sloka":"समः शत्रौ च मित्रे च तथा मानापमानयोः।शीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः।।12.18।।","transliteration":"samaḥ śhatrau cha mitre cha tathā mānāpamānayoḥ\nśhītoṣhṇa-sukha-duḥkheṣhu samaḥ saṅga-vivarjitaḥ","english":"He who is the same to foe and friend, and also in honor and dishonor, who is the same in cold and heat, in pleasure and pain, and who is free from attachment.","hindi":"जो पुरुष शत्रु और मित्र में तथा मान और अपमान में सम है; जो शीत-उष्ण व सुख-दु:खादिक द्वन्द्वों में सम है और आसक्ति से रहित है।","gujarati":"જે પુરુષ શત્રુ અને મિત્રમાં તથા માન અને અપમાનમાં સમાન છે, જે શીત-ઉષ્ણ અને સુખ-દુઃખાદિ દ્વંદ્વોમાં સમાન છે અને આસક્તિથી રહિત છે."},"12.19":{"chapter":12,"verse":19,"sloka":"तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येनकेनचित्।अनिकेतः स्थिरमतिर्भक्ितमान्मे प्रियो नरः।।12.19।।","transliteration":"tulya-nindā-stutir maunī santuṣhṭo yena kenachit\naniketaḥ sthira-matir bhaktimān me priyo naraḥ","english":"He to whom censure and praise are equal, who is silent, content with anything, homeless, of a steady mind, and full of devotion; that man is dear to Me.","hindi":"जिसके लिए निन्दा और स्तुति समान हैं, जो मौन रहता है, जो किसी भी परिस्थिति में सन्तुष्ट रहता है, जिसका कोई निश्चित घर नहीं है, जिसकी बुद्धि स्थिर है और जो भक्ति से परिपूर्ण है; वह भक्त मुझे अत्यन्त प्रिय है।","gujarati":"જેને નિંદા અને સ્તુતિ સમાન છે, જે મૌની છે, જે કોઈ પણ વસ્તુમાં સંતુષ્ટ રહે છે, જે અનિકેત છે, જેની બુદ્ધિ સ્થિર છે અને જે ભક્તિથી ભરપૂર છે, તે ભક્ત મને અત્યંત પ્રિય છે."},"12.20":{"chapter":12,"verse":20,"sloka":"ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते।श्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः।।12.20।।","transliteration":"ye tu dharmyāmṛitam idaṁ yathoktaṁ paryupāsate\nśhraddadhānā mat-paramā bhaktās te ’tīva me priyāḥ","english":"Those who follow this immortal Dharma as described, endowed with faith, and regarding Me alone as their supreme goal, are exceedingly dear to Me, Shri Krishna.","hindi":"जो भक्त श्रद्धावान् होकर और मुझे ही परम लक्ष्य मानकर इस धर्ममय अमृत का पालन करते हैं, वे श्री कृष्ण को अतिशय प्रिय हैं।","gujarati":"જેઓ શ્રદ્ધાવાન થઈને અને મને જ પરમ લક્ષ્ય માનીને આ ધર્મમય અમૃતનું પાલન કરે છે, તે ભક્તો શ્રી કૃષ્ણને અત્યંત પ્રિય છે."},"13.1":{"chapter":13,"verse":1,"sloka":"अर्जुन उवाच\n\nप्रकृतिं पुरुषं चैव क्षेत्रं क्षेत्रज्ञमेव च।\n\nएतद्वेदितुमिच्छामि ज्ञानं ज्ञेयं च केशव।।13.1।।","transliteration":"arjuna uvācha\nprakṛitiṁ puruṣhaṁ chaiva kṣhetraṁ kṣhetra-jñam eva cha\netad veditum ichchhāmi jñānaṁ jñeyaṁ cha keśhava","english":"Arjuna said: O Keshava, I wish to understand the nature of Prakriti (Nature) and Purusha (the Enjoyer), the Kshetra (the field) and the Kshetrajna (the knower of the field), as well as true Jnana (knowledge) and the ultimate Jneya (the object of knowledge).","hindi":"अर्जुन ने कहा: हे केशव! मैं प्रकृति और पुरुष को, क्षेत्र और क्षेत्रज्ञ को, तथा ज्ञान और ज्ञेय को यथार्थ रूप से जानना चाहता हूँ।","gujarati":"અર્જુને કહ્યું: હે કેશવ! હું પ્રકૃતિ અને પુરુષને, ક્ષેત્ર અને ક્ષેત્રજ્ઞને, તથા જ્ઞાન અને જ્ઞેયને યથાર્થ રીતે જાણવાની ઈચ્છા રાખું છું."},"13.2":{"chapter":13,"verse":2,"sloka":"श्री भगवानुवाचइदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते।एतद्यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः।।13.2।।","transliteration":"śhrī-bhagavān uvācha\nidaṁ śharīraṁ kaunteya kṣhetram ity abhidhīyate\netad yo vetti taṁ prāhuḥ kṣhetra-jña iti tad-vidaḥ","english":"Shri Krishna said: O Arjuna, this body is known as the field, and those who know it are called the knower of the field by the sages who understand the truth.","hindi":"श्रीभगवान् ने कहा—हे अर्जुन! यह शरीर 'क्षेत्र' कहा जाता है, और जो इसे जानता है, उसे तत्त्वज्ञानी जन 'क्षेत्रज्ञ' कहते हैं।","gujarati":"શ્રી ભગવાન બોલ્યા—હે અર્જુન! આ શરીરને 'ક્ષેત્ર' કહેવામાં આવે છે, અને જે આને જાણે છે, તેને તત્ત્વજ્ઞાની પુરુષો 'ક્ષેત્રજ્ઞ' કહે છે."},"13.3":{"chapter":13,"verse":3,"sloka":"क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत।\n\nक्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम।।13.3।।","transliteration":"kṣhetra-jñaṁ chāpi māṁ viddhi sarva-kṣhetreṣhu bhārata\nkṣhetra-kṣhetrajñayor jñānaṁ yat taj jñānaṁ mataṁ mama","english":"O descendant of Bharata, understand that I am the Knower of the field within all fields; and the knowledge of both the field and the Knower of the field is what I consider true knowledge.","hindi":"हे भरतवंशी अर्जुन! तू समस्त क्षेत्रों (शरीरों) में क्षेत्रज्ञ अर्थात् मुझे ही जान। क्षेत्र और क्षेत्रज्ञ का जो तत्व से जानना है, वही वास्तव में ज्ञान है, ऐसा मेरा मत है।","gujarati":"હે ભારતવંશી અર્જુન! તું તમામ ક્ષેત્રોમાં ક્ષેત્રજ્ઞ (આત્મા અને પરમાત્મા) મને જ જાણ. ક્ષેત્ર અને ક્ષેત્રજ્ઞનું જે જ્ઞાન છે, તેને જ હું સાચું જ્ઞાન માનું છું."},"13.4":{"chapter":13,"verse":4,"sloka":"तत्क्षेत्रं यच्च यादृक् च यद्विकारि यतश्च यत्।स च यो यत्प्रभावश्च तत्समासेन मे श्रृणु।।13.4।।","transliteration":"tat kṣhetraṁ yach cha yādṛik cha yad-vikāri yataśh cha yat\nsa cha yo yat-prabhāvaśh cha tat samāsena me śhṛiṇu","english":"Hear from Me in brief what the field is, what its nature is, what its modifications are, where it originates from, who the knower of the field is, and what His powers are.","hindi":"वह क्षेत्र क्या है और कैसा है, उसके विकार क्या हैं, वह कहाँ से उत्पन्न हुआ है, वह क्षेत्रज्ञ कौन है और उसकी क्या शक्तियाँ हैं, यह सब मुझसे संक्षेप में सुनो।","gujarati":"તે ક્ષેત્ર શું છે અને કેવું છે, તેના વિકારો કયા છે, તે ક્યાંથી ઉત્પન્ન થયું છે, તે ક્ષેત્રજ્ઞ કોણ છે અને તેની શક્તિઓ શું છે, તે બધું મારી પાસેથી સંક્ષેપમાં સાંભળ."},"13.5":{"chapter":13,"verse":5,"sloka":"ऋषिभिर्बहुधा गीतं छन्दोभिर्विविधैः पृथक्।ब्रह्मसूत्रपदैश्चैव हेतुमद्भिर्विनिश्िचतैः।।13.5।।","transliteration":"ṛiṣhibhir bahudhā gītaṁ chhandobhir vividhaiḥ pṛithak\nbrahma-sūtra-padaiśh chaiva hetumadbhir viniśhchitaiḥ","english":"Rishis have sung of this in many ways, in various distinct chants, and also through aphoristic words indicative of the Absolute, full of reasoning and decisive.","hindi":"ऋषियों द्वारा इसके विषय में अनेक प्रकार से बहुत-से छन्दों में और ब्रह्म के सूचक युक्तियुक्त तथा निश्चयकारी ब्रह्मसूत्रों के पदों द्वारा भी अलग-अलग गाया गया है।","gujarati":"ઋષિઓએ આ વિષયમાં અનેક પ્રકારના છંદો દ્વારા અનેક રીતે ગાન કર્યું છે, તેમજ બ્રહ્મના સૂચક એવા યુક્તિપૂર્ણ અને નિશ્ચયાત્મક બ્રહ્મસૂત્રો દ્વારા પણ આ જ વાત કહેવામાં આવી છે."},"13.6":{"chapter":13,"verse":6,"sloka":"महाभूतान्यहङ्कारो बुद्धिरव्यक्तमेव च।इन्द्रियाणि दशैकं च पञ्च चेन्द्रियगोचराः।।13.6।।","transliteration":"mahā-bhūtāny ahankāro buddhir avyaktam eva cha\nindriyāṇi daśhaikaṁ cha pañcha chendriya-gocharāḥ","english":"The great elements, egoism, intellect, and also the Unmanifested Nature, the ten senses, and one mind, and the five objects of the senses.","hindi":"पाँच महाभूत, अहंकार, बुद्धि और अव्यक्त प्रकृति, तथा दस इन्द्रियाँ, एक मन और इन्द्रियों के पाँच विषय।","gujarati":"પંચ મહાભૂતો, અહંકાર, બુદ્ધિ અને અવ્યક્ત પ્રકૃતિ, તેમજ દસ ઇન્દ્રિયો, એક મન અને ઇન્દ્રિયોના પાંચ વિષયો."},"13.7":{"chapter":13,"verse":7,"sloka":"इच्छा द्वेषः सुखं दुःखं सङ्घातश्चेतनाधृतिः।एतत्क्षेत्रं समासेन सविकारमुदाहृतम्।।13.7।।","transliteration":"ichchhā dveṣhaḥ sukhaṁ duḥkhaṁ saṅghātaśh chetanā dhṛitiḥ\netat kṣhetraṁ samāsena sa-vikāram udāhṛitam","english":"Desire, hatred, pleasure, pain, the aggregate (the physical body), intelligence, and fortitude—the field has thus been briefly described along with its modifications.","hindi":"इच्छा, द्वेष, सुख, दुख, संघात (स्थूल शरीर), चेतना और धृति - इस प्रकार यह क्षेत्र अपने विकारों के सहित संक्षेप में कहा गया है।","gujarati":"ઈચ્છા, દ્વેષ, સુખ, દુઃખ, સંઘાત (સ્થૂળ શરીર), ચેતના અને ધૃતિ - આ પ્રમાણે વિકારો સહિત ક્ષેત્રનું સંક્ષેપમાં વર્ણન કરવામાં આવ્યું છે."},"13.8":{"chapter":13,"verse":8,"sloka":"अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम्।आचार्योपासनं शौचं स्थैर्यमात्मविनिग्रहः।।13.8।।","transliteration":"amānitvam adambhitvam ahinsā kṣhāntir ārjavam\nāchāryopāsanaṁ śhauchaṁ sthairyam ātma-vinigrahaḥ","english":"Humility, unpretentiousness, non-violence, forgiveness, uprightness, service to the spiritual master, purity, steadfastness, and self-control.","hindi":"अमानित्व, अदम्भित्व, अहिंसा, क्षमा, सरलता, गुरु की सेवा, शुद्धि, स्थिरता और आत्मसंयम।","gujarati":"નમ્રતા, દંભરહિતતા, અહિંસા, ક્ષમા, સરળતા, ગુરુની સેવા, શુદ્ધિ, દ્રઢતા અને આત્મસંયમ."},"13.9":{"chapter":13,"verse":9,"sloka":"इन्द्रियार्थेषु वैराग्यमनहङ्कार एव च।जन्ममृत्युजराव्याधिदुःखदोषानुदर्शनम्।।13.9।।","transliteration":"indriyārtheṣhu vairāgyam anahankāra eva cha\njanma-mṛityu-jarā-vyādhi-duḥkha-doṣhānudarśhanam","english":"Indifference to the objects of the senses and also absence of egoism; perceiving the evil in birth, death, old age, sickness, and pain.","hindi":"इन्द्रियों के विषयों में वैराग्य और अहंकार का अभाव; जन्म, मृत्यु, जरा, व्याधि और दुखों में दोषों का दर्शन करना।","gujarati":"ઇન્દ્રિયોના વિષયોમાં વૈરાગ્ય અને અહંકારનો અભાવ; જન્મ, મૃત્યુ, વૃદ્ધાવસ્થા, રોગ અને દુઃખમાં દોષોનું દર્શન કરવું."},"13.10":{"chapter":13,"verse":10,"sloka":"असक्ितरनभिष्वङ्गः पुत्रदारगृहादिषु।नित्यं च समचित्तत्वमिष्टानिष्टोपपत्तिषु।।13.10।।","transliteration":"asaktir anabhiṣhvaṅgaḥ putra-dāra-gṛihādiṣhu\nnityaṁ cha sama-chittatvam iṣhṭāniṣhṭopapattiṣhu","english":"Absence of attachment, absence of identification of the Self with son, wife, home and such, and constant even-mindedness in the attainment of the desirable and the undesirable.","hindi":"आसक्ति का अभाव, पुत्र, पत्नी, घर आदि में आत्मबुद्धि का न होना तथा इष्ट और अनिष्ट की प्राप्ति में सदैव समभाव रहना।","gujarati":"પુત્ર, સ્ત્રી, ઘર આદિમાં આસક્તિનો અભાવ, મમતાનો ત્યાગ અને ઇષ્ટ કે અનિષ્ટ વસ્તુઓની પ્રાપ્તિમાં હંમેશા સમભાવ રાખવો."},"13.11":{"chapter":13,"verse":11,"sloka":"मयि चानन्ययोगेन भक्ितरव्यभिचारिणी।विविक्तदेशसेवित्वमरतिर्जनसंसदि।।13.11।।","transliteration":"mayi chānanya-yogena bhaktir avyabhichāriṇī\nvivikta-deśha-sevitvam aratir jana-sansadi","english":"Unswerving devotion to Me through the Yoga of non-separation, resorting to solitary places, and a distaste for the company of people.","hindi":"अनन्ययोग के द्वारा मुझमें अव्यभिचारिणी भक्ति, एकान्त स्थान में रहने का स्वभाव और असंस्कृत जनों के समुदाय में अरुचि।","gujarati":"મારામાં અનન્ય યોગ વડે અવ્યભિચારી ભક્તિ, એકાંત સ્થળમાં રહેવાનો સ્વભાવ અને સંસારના લોકોના સમૂહમાં અરૂચિ."},"13.12":{"chapter":13,"verse":12,"sloka":"अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम्।एतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोन्यथा।।13.12।।","transliteration":"adhyātma-jñāna-nityatvaṁ tattva-jñānārtha-darśhanam\netaj jñānam iti proktam ajñānaṁ yad ato ’nyathā","english":"Constancy in Self-knowledge, and the perception of the goal of true knowledge—this is declared to be knowledge; all that is contrary to this is ignorance.","hindi":"अध्यात्मज्ञान में नित्य स्थित रहना और तत्त्वज्ञान के अर्थ स्वरूप परमात्मा का भली-भांति दर्शन करना—यह सब तो ज्ञान है, और जो इसके विपरीत है, वह अज्ञान है।","gujarati":"આત્મજ્ઞાનમાં નિરંતર સ્થિત રહેવું અને તત્વજ્ઞાનના અર્થરૂપ પરમાત્માનો સાક્ષાત્કાર કરવો—આને જ જ્ઞાન કહેવામાં આવ્યું છે, અને આનાથી વિપરીત જે કંઈ છે તે અજ્ઞાન છે."},"13.13":{"chapter":13,"verse":13,"sloka":"ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वाऽमृतमश्नुते।अनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते।।13.13।।","transliteration":"jñeyaṁ yat tat pravakṣhyāmi yaj jñātvāmṛitam aśhnute\nanādi mat-paraṁ brahma na sat tan nāsad uchyate","english":"I shall declare that which is to be known, through which one attains immortality; the beginningless Supreme Brahman, who is spoken of as neither being nor non-being.","hindi":"मैं उस ज्ञेय वस्तु को अच्छी प्रकार कहूँगा, जिसे जानकर मनुष्य अमृतत्व को प्राप्त करता है। वह अनादि परम ब्रह्म न सत् कहा जाता है और न असत् ही।","gujarati":"હવે હું તે જ્ઞેય વસ્તુ જણાવીશ, જેને જાણીને મનુષ્ય અમરત્વ પ્રાપ્ત કરે છે। તે અનાદિ પરબ્રહ્મ ન તો સત્ કહેવાય છે અને ન તો અસત્ જ."},"13.14":{"chapter":13,"verse":14,"sloka":"सर्वतः पाणिपादं तत्सर्वतोऽक्षिशिरोमुखम्।सर्वतः श्रुतिमल्लोके सर्वमावृत्य तिष्ठति।।13.14।।","transliteration":"sarvataḥ pāṇi-pādaṁ tat sarvato ’kṣhi-śhiro-mukham\nsarvataḥ śhrutimal loke sarvam āvṛitya tiṣhṭhati","english":"Everywhere are His hands and feet, everywhere His eyes, heads, and faces; His ears are everywhere. In this way, Lord Krishna exists pervading all in the universe.","hindi":"उस परमात्मा के सब ओर हाथ और पैर हैं, सब ओर नेत्र, सिर और मुख हैं तथा सब ओर कान हैं; वह संसार में सबको व्याप्त करके स्थित है।","gujarati":"તે ભગવાન બધે જ હાથ અને પગવાળા છે, બધે જ નેત્ર, મસ્તક અને મુખવાળા છે તથા બધે જ કાનવાળા છે; તે જગતમાં સર્વત્ર વ્યાપ્ત થઈને રહેલા છે."},"13.15":{"chapter":13,"verse":15,"sloka":"सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम्।असक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च।।13.15।।","transliteration":"sarvendriya-guṇābhāsaṁ sarvendriya-vivarjitam\nasaktaṁ sarva-bhṛich chaiva nirguṇaṁ guṇa-bhoktṛi cha","english":"Shri Krishna says: He shines by the functions of all the senses, yet He is devoid of the senses. He is unattached, yet He sustains all; He is devoid of the Gunas, yet He is the enjoyer of them.","hindi":"श्रीकृष्ण कहते हैं: वह समस्त इन्द्रियों के कार्यों द्वारा प्रकाशित होने वाला है, किन्तु वास्तव में इन्द्रियों से रहित है। वह अनासक्त होकर भी सबका धारण-पोषण करने वाला है और गुणों से रहित होकर भी गुणों का भोक्ता है।","gujarati":"શ્રીકૃષ્ણ કહે છે: તે તમામ ઇન્દ્રિયોના કાર્યો દ્વારા પ્રકાશિત થાય છે, પરંતુ વાસ્તવમાં તે ઇન્દ્રિયોથી રહિત છે. તે અનાસક્ત હોવા છતાં બધાનું ધારણ-પોષણ કરનાર છે, અને ગુણોથી રહિત હોવા છતાં તે ગુણોનો ભોક્તા છે."},"13.16":{"chapter":13,"verse":16,"sloka":"बहिरन्तश्च भूतानामचरं चरमेव च।सूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत्।।13.16।।","transliteration":"bahir antaśh cha bhūtānām acharaṁ charam eva cha\nsūkṣhmatvāt tad avijñeyaṁ dūra-sthaṁ chāntike cha tat","english":"It exists both within and outside all beings, among the moving and the non-moving. Because it is subtle, it is incomprehensible; and though it is far away, it is also near.","hindi":"वह परमात्मा सब प्राणियों के भीतर और बाहर स्थित है, वही चर और अचर भी है। वह सूक्ष्म होने के कारण अविज्ञेय है; वही सुदूर और अत्यन्त समीप भी है।","gujarati":"તે પરમાત્મા સર્વ પ્રાણીઓની અંદર અને બહાર સ્થિત છે, તે ચર અને અચર પણ છે. તે સૂક્ષ્મ હોવાને કારણે અવિજ્ઞેય છે; તે અત્યંત દૂર અને ખૂબ જ નજીક પણ છે."},"13.17":{"chapter":13,"verse":17,"sloka":"अविभक्तं च भूतेषु विभक्तमिव च स्थितम्।भूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च।।13.17।।","transliteration":"avibhaktaṁ cha bhūteṣhu vibhaktam iva cha sthitam\nbhūta-bhartṛi cha taj jñeyaṁ grasiṣhṇu prabhaviṣhṇu cha","english":"It is undivided, yet It appears to be divided among beings; It is to be known as the sustainer of all beings; It is the devourer and the generator of all.","hindi":"वह अविभक्त है, तथापि वह सब प्राणियों में विभक्त के समान स्थित है; वह परमात्मा ही प्राणियों को धारण करने वाला, संहार करने वाला और उत्पन्न करने वाला है।","gujarati":"તે અવિભાજ્ય છે, છતાં પ્રાણીઓમાં વિભાજિત હોય તેવું લાગે છે; તે પરબ્રહ્મ જાણવા યોગ્ય છે, જે સર્વ ભૂતોનું ધારણપોષણ કરનાર, સંહાર કરનાર અને ઉત્પન્ન કરનાર છે."},"13.18":{"chapter":13,"verse":18,"sloka":"ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते।ज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम्।।13.18।।","transliteration":"jyotiṣhām api taj jyotis tamasaḥ param uchyate\njñānaṁ jñeyaṁ jñāna-gamyaṁ hṛidi sarvasya viṣhṭhitam","english":"He is the Light of all lights, said to be beyond the darkness of ignorance. He is the knowledge, the object of knowledge, and the goal of knowledge, residing eternally within the hearts of all.","hindi":"वह ज्योतियों की भी ज्योति है और अज्ञान रूपी अंधकार से परे कहा जाता है। वह स्वयं ज्ञान है, ज्ञेय है और ज्ञान के द्वारा प्राप्त करने योग्य लक्ष्य भी वही है; वह सबके हृदय में स्थित है।","gujarati":"તે જ્યોતિઓની પણ જ્યોતિ છે અને અજ્ઞાનરૂપી અંધકારથી પર છે. તે જ્ઞાન, જ્ઞેય અને જ્ઞાન દ્વારા પ્રાપ્ત કરવા યોગ્ય લક્ષ્ય છે; તે સર્વના હૃદયમાં સ્થિત છે."},"13.19":{"chapter":13,"verse":19,"sloka":"इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः।मद्भक्त एतद्विज्ञाय मद्भावायोपपद्यते।।13.19।।","transliteration":"iti kṣhetraṁ tathā jñānaṁ jñeyaṁ choktaṁ samāsataḥ\nmad-bhakta etad vijñāya mad-bhāvāyopapadyate","english":"Thus the field of activities, as well as the process of knowledge and the object of knowledge, have been briefly described by Me. Only My devotee, having understood this thoroughly, attains My divine nature.","hindi":"इस प्रकार क्षेत्र, ज्ञान और ज्ञेय का संक्षेप में वर्णन किया गया। मेरा भक्त ही इसे तत्त्व से जानकर मेरे स्वरूप को प्राप्त होता है।","gujarati":"આ પ્રકારે ક્ષેત્ર, જ્ઞાન અને જ્ઞેયનું સંક્ષેપમાં વર્ણન કરવામાં આવ્યું છે. મારો ભક્ત આ તત્વને જાણીને મારા સ્વરૂપને પ્રાપ્ત કરે છે."},"13.20":{"chapter":13,"verse":20,"sloka":"प्रकृतिं पुरुषं चैव विद्ध्यनादी उभावपि।विकारांश्च गुणांश्चैव विद्धि प्रकृतिसंभवान्।।13.20।।","transliteration":"prakṛitiṁ puruṣhaṁ chaiva viddhy anādī ubhāv api\nvikārānśh cha guṇānśh chaiva viddhi prakṛiti-sambhavān","english":"Know that Nature (Prakriti) and the individual soul (Purusha) are both beginningless; and know also that all transformations and qualities are born of Nature.","hindi":"प्रकृति और पुरुष को तुम अनादि जानो। और यह भी समझो कि सभी विकार और गुण प्रकृति से ही उत्पन्न हुए हैं।","gujarati":"તું પ્રકૃતિ અને પુરુષ બંનેને અનાદિ જાણ. અને એ પણ જાણ કે તમામ વિકારો અને ગુણો પ્રકૃતિમાંથી જ ઉત્પન્ન થાય છે."},"13.21":{"chapter":13,"verse":21,"sloka":"कार्यकारणकर्तृत्वे हेतुः प्रकृतिरुच्यते।पुरुषः सुखदुःखानां भोक्तृत्वे हेतुरुच्यते।।13.21।।","transliteration":"kārya-kāraṇa-kartṛitve hetuḥ prakṛitir uchyate\npuruṣhaḥ sukha-duḥkhānāṁ bhoktṛitve hetur uchyate","english":"Nature is said to be the cause of all physical effects and causes, while the individual soul is said to be the cause of the experience of pleasures and pains.","hindi":"कार्य और कारण को उत्पन्न करने में प्रकृति हेतु कही जाती है और पुरुष सुख-दुख के भोक्तापन में हेतु कहा जाता है।","gujarati":"કાર્ય અને કારણને ઉત્પન્ન કરવામાં પ્રકૃતિ કારણભૂત કહેવાય છે અને જીવાત્મા સુખ-દુઃખના ભોગવટામાં કારણભૂત કહેવાય છે."},"13.22":{"chapter":13,"verse":22,"sloka":"पुरुषः प्रकृतिस्थो हि भुङ्क्ते प्रकृतिजान्गुणान्।कारणं गुणसङ्गोऽस्य सदसद्योनिजन्मसु।।13.22।।","transliteration":"puruṣhaḥ prakṛiti-stho hi bhuṅkte prakṛiti-jān guṇān\nkāraṇaṁ guṇa-saṅgo ’sya sad-asad-yoni-janmasu","english":"The soul seated in Nature experiences the qualities born of Nature; attachment to the qualities is the cause of its birth in good and evil wombs.","hindi":"प्रकृति में स्थित पुरुष प्रकृति से उत्पन्न गुणों को भोगता है। इन गुणों का संग ही इस पुरुष जीव के शुभ और अशुभ योनियों में जन्म लेने का कारण है।","gujarati":"પ્રકૃતિમાં સ્થિત પુરુષ પ્રકૃતિથી ઉત્પન્ન ગુણોને ભોગવે છે. આ ગુણોનો સંગ જ આ જીવના શુભ અને અશુભ યોનિઓમાં જન્મ લેવાનું કારણ છે."},"13.23":{"chapter":13,"verse":23,"sloka":"उपद्रष्टाऽनुमन्ता च भर्ता भोक्ता महेश्वरः।परमात्मेति चाप्युक्तो देहेऽस्मिन्पुरुषः परः।।13.23।।","transliteration":"upadraṣhṭānumantā cha bhartā bhoktā maheśhvaraḥ\nparamātmeti chāpy ukto dehe ’smin puruṣhaḥ paraḥ","english":"The Supreme Lord Krishna says: 'The Supreme Soul within this body is also known as the Witness, the Permitter, the Sustainer, the Enjoyer, the Great Lord, and the Supreme Self.'","hindi":"भगवान श्रीकृष्ण कहते हैं: 'इस देह में स्थित यह परमात्मा ही वास्तव में उपद्रष्टा (साक्षी), अनुमन्ता (अनुमति देने वाला), भर्ता (धारण करने वाला), भोक्ता (भोगने वाला), महेश्वर (महान ईश्वर) और परमात्मा के नाम से जाना जाता है।'","gujarati":"ભગવાન શ્રીકૃષ્ણ કહે છે: 'આ દેહમાં રહેલા પરમાત્મા જ વાસ્તવમાં ઉપદ્રષ્ટા (સાક્ષી), અનુમન્તા (અનુમતિ આપનાર), ભર્તા (ધારણ કરનાર), ભોક્તા (ભોગવનાર), મહેશ્વર (મહાન ઈશ્વર) અને પરમાત્મા તરીકે ઓળખાય છે.'"},"13.24":{"chapter":13,"verse":24,"sloka":"य एवं वेत्ति पुरुषं प्रकृतिं च गुणैःसह।सर्वथा वर्तमानोऽपि न स भूयोऽभिजायते।।13.24।।","transliteration":"ya evaṁ vetti puruṣhaṁ prakṛitiṁ cha guṇaiḥ saha\nsarvathā vartamāno ’pi na sa bhūyo ’bhijāyate","english":"He who thus realizes the Spirit (Purusha) and Matter (Prakriti) together with its modes (gunas), though he may be living in any condition whatsoever, is not born again.","hindi":"जो पुरुष इस प्रकार पुरुष और गुणों के सहित प्रकृति को तत्व से जानता है, वह सब प्रकार से वर्तमान होता हुआ भी पुन: जन्म को प्राप्त नहीं होता।","gujarati":"જે મનુષ્ય આ પ્રકારે પુરુષને અને ગુણો સહિત પ્રકૃતિને તત્ત્વથી જાણે છે, તે સર્વ પ્રકારના વર્તમાન હોવા છતાં ફરી જન્મ ધારણ કરતો નથી."},"13.25":{"chapter":13,"verse":25,"sloka":"ध्यानेनात्मनि पश्यन्ति केचिदात्मानमात्मना।अन्ये सांख्येन योगेन कर्मयोगेन चापरे।।13.25।।","transliteration":"dhyānenātmani paśhyanti kechid ātmānam ātmanā\nanye sānkhyena yogena karma-yogena chāpare","english":"Some perceive the Supreme Self within their hearts through the practice of meditation, others through the Yoga of knowledge, and still others through the Yoga of selfless action.","hindi":"कुछ लोग ध्यान के द्वारा आत्मा को अपने भीतर ही देखते हैं, अन्य लोग ज्ञानयोग के द्वारा और कुछ अन्य कर्मयोग के मार्ग से परमात्मा का साक्षात्कार करते हैं।","gujarati":"કોઈ પુરુષ ધ્યાન દ્વારા આત્માને પોતાના હૃદયમાં જુએ છે, બીજા લોકો જ્ઞાનયોગ દ્વારા અને અન્ય સાધકો કર્મયોગ દ્વારા તે પરમાત્માને નિહાળે છે."},"13.26":{"chapter":13,"verse":26,"sloka":"अन्ये त्वेवमजानन्तः श्रुत्वाऽन्येभ्य उपासते।तेऽपि चातितरन्त्येव मृत्युं श्रुतिपरायणाः।।13.26।।","transliteration":"anye tv evam ajānantaḥ śhrutvānyebhya upāsate\nte ’pi chātitaranty eva mṛityuṁ śhruti-parāyaṇāḥ","english":"Others, who do not possess this direct knowledge, worship by hearing from others; having taken refuge in what they have heard, they too transcend the cycle of death.","hindi":"अन्य जो दूसरे लोग इस प्रकार स्वयं नहीं जानते, वे दूसरों से सुनकर उपासना करते हैं; वे भी श्रवण के परायण होकर मृत्यु के पार हो जाते हैं।","gujarati":"બીજા ઘણા એવા લોકો છે જેઓ પોતે આ જ્ઞાન નથી જાણતા, પરંતુ અન્ય લોકો પાસેથી સાંભળીને જ ઉપાસના કરે છે; તેઓ પણ શ્રવણપરાયણ થઈને મૃત્યુને તરી જાય છે."},"13.27":{"chapter":13,"verse":27,"sloka":"यावत्सञ्जायते किञ्चित्सत्त्वं स्थावरजङ्गमम्।क्षेत्रक्षेत्रज्ञसंयोगात्तद्विद्धि भरतर्षभ।।13.27।।","transliteration":"yāvat sañjāyate kiñchit sattvaṁ sthāvara-jaṅgamam\nkṣhetra-kṣhetrajña-sanyogāt tad viddhi bharatarṣhabha","english":"O best of the Bharatas, know that whatever being is born, whether moving or unmoving, it arises from the union of the field (kshetra) and the knower of the field (kshetrajna).","hindi":"हे भरतश्रेष्ठ! जो कुछ भी स्थावर (जड़) और जंगम (चेतन) वस्तु उत्पन्न होती है, उसे तुम क्षेत्र और क्षेत्रज्ञ के संयोग से ही उत्पन्न हुई जानो।","gujarati":"હે ભરતશ્રેષ્ઠ અર્જુન! જે કંઈ પણ સ્થાવર કે જંગમ વસ્તુઓ ઉત્પન્ન થાય છે, તે સર્વને તું ક્ષેત્ર અને ક્ષેત્રજ્ઞના સંયોગથી જ ઉત્પન્ન થયેલી જાણ."},"13.28":{"chapter":13,"verse":28,"sloka":"समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम्।विनश्यत्स्वविनश्यन्तं यः पश्यति स पश्यति।।13.28।।","transliteration":"samaṁ sarveṣhu bhūteṣhu tiṣhṭhantaṁ parameśhvaram\nvinaśhyatsv avinaśhyantaṁ yaḥ paśhyati sa paśhyati","english":"He who perceives the Supreme Lord Krishna residing equally in all beings, the Imperishable within the perishable, he truly sees.","hindi":"जो पुरुष समस्त नश्वर प्राणियों में स्थित अविनाशी परमेश्वर श्रीकृष्ण को समभाव से देखता है, वही वास्तव में देखता है।","gujarati":"જે પુરુષ સમસ્ત વિનાશી પ્રાણીઓમાં અવિનાશી પરમેશ્વર શ્રીકૃષ્ણને સમભાવથી સ્થિત જુએ છે, તે જ ખરેખર જુએ છે."},"13.29":{"chapter":13,"verse":29,"sloka":"समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम्।न हिनस्त्यात्मनाऽऽत्मानं ततो याति परां गतिम्।।13.29।।","transliteration":"samaṁ paśhyan hi sarvatra samavasthitam īśhvaram\nna hinasty ātmanātmānaṁ tato yāti parāṁ gatim","english":"He who perceives the Supreme Lord existing equally in all beings, dwelling everywhere, does not degrade the self by the self; thus, he attains the supreme destination.","hindi":"जो पुरुष सभी प्राणियों में समान रूप से स्थित परमेश्वर को देखता है, वह अपने आप द्वारा अपनी आत्मा का अहित नहीं करता है; इस प्रकार वह परम गति को प्राप्त होता है।","gujarati":"જે મનુષ્ય સર્વત્ર સમાન ભાવે રહેલા પરમેશ્વરને જુએ છે, તે પોતાની જાતે પોતાની આત્માનો વિનાશ કરતો નથી; આમ, તે પરમ ગતિને પામે છે."},"13.30":{"chapter":13,"verse":30,"sloka":"प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः।यः पश्यति तथाऽऽत्मानमकर्तारं स पश्यति।।13.30।।","transliteration":"prakṛityaiva cha karmāṇi kriyamāṇāni sarvaśhaḥ\nyaḥ paśhyati tathātmānam akartāraṁ sa paśhyati","english":"He truly sees, who perceives that all actions are performed by material Nature (Prakriti) alone and that the eternal Self (Atman) is the non-doer.","hindi":"जो पुरुष यह देखता है कि समस्त कर्म केवल प्रकृति द्वारा ही किए जाते हैं और आत्मा वास्तव में अकर्ता है, वही वास्तव में देखता है।","gujarati":"જે પુરુષ એવું જુએ છે કે બધાં કર્મ કેવળ પ્રકૃતિ દ્વારા જ કરવામાં આવે છે અને આત્મા અકર્તા છે, તે જ ખરેખર જુએ છે."},"13.31":{"chapter":13,"verse":31,"sloka":"यदा भूतपृथग्भावमेकस्थमनुपश्यति।तत एव च विस्तारं ब्रह्म सम्पद्यते तदा।।13.31।।","transliteration":"yadā bhūta-pṛithag-bhāvam eka-stham anupaśhyati\ntata eva cha vistāraṁ brahma sampadyate tadā","english":"When a seeker perceives the diverse existence of all beings as established in the One and witnesses how they all emanate from that same Source, they attain Brahman.","hindi":"जब मनुष्य समस्त प्राणियों की विविधता को एक परमात्मा में ही स्थित देखता है और यह जानता है कि सभी का विस्तार उन्हीं से हुआ है, तब वह ब्रह्म को प्राप्त कर लेता है।","gujarati":"જ્યારે પુરુષ ભૂતોના પૃથક-પૃથક ભાવને એક પરમાત્મામાં જ સ્થિત જુએ છે અને તે પરમાત્માથી જ આ બધાનું વિસ્તરણ થયું છે તેમ જાણે છે, ત્યારે તે બ્રહ્મને પ્રાપ્ત થાય છે."},"13.32":{"chapter":13,"verse":32,"sloka":"अनादित्वान्निर्गुणत्वात्परमात्मायमव्ययः।शरीरस्थोऽपि कौन्तेय न करोति न लिप्यते।।13.32।।","transliteration":"anāditvān nirguṇatvāt paramātmāyam avyayaḥ\nśharīra-stho ’pi kaunteya na karoti na lipyate","english":"O Arjuna, being beginningless and devoid of any material qualities, this Supreme Self is imperishable. Though dwelling within the body, Shri Krishna reveals that the Self neither acts nor is tainted by the actions of the material world.","hindi":"हे अर्जुन! यह अनादि और निर्गुण होने के कारण अविनाशी परमात्मा है। शरीर में स्थित होने पर भी, स्वयं भगवान श्री कृष्ण के अनुसार, यह आत्मा न तो कुछ करती है और न ही कर्मों से लिप्त होती है।","gujarati":"હે અર્જુન! અનાદિ અને નિર્ગુણ હોવાને લીધે આ પરમાત્મા અવ્યય છે. શરીરમાં સ્થિત હોવા છતાં, ભગવાન શ્રી કૃષ્ણ જણાવે છે કે તે આત્મા ન તો કંઈ કરે છે અને ન તો કર્મોના ફળથી લિપ્ત થાય છે."},"13.33":{"chapter":13,"verse":33,"sloka":"यथा सर्वगतं सौक्ष्म्यादाकाशं नोपलिप्यते।सर्वत्रावस्थितो देहे तथाऽऽत्मा नोपलिप्यते।।13.33।।","transliteration":"yathā sarva-gataṁ saukṣhmyād ākāśhaṁ nopalipyate\nsarvatrāvasthito dehe tathātmā nopalipyate","english":"As the all-pervading ether, due to its subtle nature, does not mix with anything, so the Self, though situated within the body, remains untainted.","hindi":"जैसे सर्वव्यापी आकाश सूक्ष्म होने के कारण किसी भी वस्तु के गुणों से लिप्त नहीं होता, वैसे ही शरीर में स्थित आत्मा शरीर के गुणों से लिप्त नहीं होता।","gujarati":"જેમ સર્વવ્યાપી આકાશ સૂક્ષ્મ હોવાને કારણે કોઈ પણ વસ્તુના ગુણોથી લિપ્ત થતું નથી, તેમ શરીરમાં રહેલો આત્મા પણ શરીરના ગુણોથી લિપ્ત થતો નથી."},"13.34":{"chapter":13,"verse":34,"sloka":"यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः।क्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति भारत।।13.34।।","transliteration":"yathā prakāśhayaty ekaḥ kṛitsnaṁ lokam imaṁ raviḥ\nkṣhetraṁ kṣhetrī tathā kṛitsnaṁ prakāśhayati bhārata","english":"Just as the one sun illuminates the entire world, so too does the Lord of the field, the Supreme Self, illuminate the entire field of the body, O Arjuna.","hindi":"हे अर्जुन! जिस प्रकार एक ही सूर्य इस संपूर्ण संसार को प्रकाशित करता है, उसी प्रकार आत्मा रूपी क्षेत्रज्ञ इस संपूर्ण शरीर (क्षेत्र) को प्रकाशित करता है।","gujarati":"હે અર્જુન! જેવી રીતે એક જ સૂર્ય સમગ્ર વિશ્વને પ્રકાશિત કરે છે, તેવી જ રીતે ક્ષેત્રનો સ્વામી (પરમાત્મા) આ સમગ્ર ક્ષેત્રને પ્રકાશિત કરે છે."},"13.35":{"chapter":13,"verse":35,"sloka":"क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा।भूतप्रकृतिमोक्षं च ये विदुर्यान्ति ते परम्।।13.35।।","transliteration":"kṣhetra-kṣhetrajñayor evam antaraṁ jñāna-chakṣhuṣhā\nbhūta-prakṛiti-mokṣhaṁ cha ye vidur yānti te param","english":"Those who perceive with the eye of knowledge the distinction between the field and the knower of the field, and also the liberation from the nature of being, attain the Supreme.","hindi":"जो पुरुष ज्ञानरूपी नेत्रों के द्वारा क्षेत्र और क्षेत्रज्ञ के भेद को तथा प्रकृति से जीवों की मुक्ति के उपाय को भली-भांति जानते हैं, वे परम ब्रह्म श्री कृष्ण को प्राप्त होते हैं।","gujarati":"જે પુરુષો જ્ઞાનરૂપી નેત્રો દ્વારા ક્ષેત્ર અને ક્ષેત્રજ્ઞના ભેદને તથા પ્રકૃતિના વિકારોમાંથી જીવની મુક્તિને જાણે છે, તેઓ પરમ પદને પામે છે."},"14.1":{"chapter":14,"verse":1,"sloka":"श्री भगवानुवाचपरं भूयः प्रवक्ष्यामि ज्ञानानां ज्ञानमुत्तमम्।यज्ज्ञात्वा मुनयः सर्वे परां सिद्धिमितो गताः।।14.1।।","transliteration":"śhrī-bhagavān uvācha\nparaṁ bhūyaḥ pravakṣhyāmi jñānānāṁ jñānam uttamam\nyaj jñātvā munayaḥ sarve parāṁ siddhim ito gatāḥ","english":"The Blessed Lord Shri Krishna said: I shall further declare unto you that supreme knowledge, the best of all knowledge, by knowing which all the sages have attained the highest perfection after departing from this world.","hindi":"श्री भगवान् ने कहा: मैं तुम्हें उस परम ज्ञान को फिर से बताऊंगा, जो समस्त ज्ञानों में सर्वोत्तम है, जिसे जानकर सभी मुनियों ने इस संसार से मुक्त होकर परम सिद्धि को प्राप्त किया है।","gujarati":"શ્રી ભગવાન બોલ્યા: હું તને ફરીથી એ પરમ જ્ઞાન કહીશ, જે સર્વ જ્ઞાનોમાં શ્રેષ્ઠ છે; જેને જાણીને તમામ મુનિઓ આ સંસારમાંથી મુક્ત થઈને પરમ સિદ્ધિને પ્રાપ્ત થયા છે."},"14.2":{"chapter":14,"verse":2,"sloka":"इदं ज्ञानमुपाश्रित्य मम साधर्म्यमागताः।सर्गेऽपि नोपजायन्ते प्रलये न व्यथन्ति च।।14.2।।","transliteration":"idaṁ jñānam upāśhritya mama sādharmyam āgatāḥ\nsarge ’pi nopajāyante pralaye na vyathanti cha","english":"Those who, having taken refuge in this knowledge, have attained a state of oneness with Me, are neither born at the time of creation nor disturbed at the time of dissolution.","hindi":"जो इस ज्ञान का आश्रय लेकर मेरे स्वरूप (साधर्म्य) को प्राप्त हो गए हैं, वे सृष्टि के आदि में न तो जन्म लेते हैं और न ही प्रलयकाल में व्याकुल होते हैं।","gujarati":"જેઓ આ જ્ઞાનનો આશ્રય લઈને મારા સ્વરૂપ (સાધર્મ્ય) ને પ્રાપ્ત થયા છે, તેઓ સૃષ્ટિના આરંભ સમયે જન્મ લેતા નથી અને પ્રલયકાળમાં પણ વ્યાકુળ થતા નથી."},"14.3":{"chapter":14,"verse":3,"sloka":"मम योनिर्महद्ब्रह्म तस्मिन् गर्भं दधाम्यहम्।संभवः सर्वभूतानां ततो भवति भारत।।14.3।।","transliteration":"mama yonir mahad brahma tasmin garbhaṁ dadhāmy aham\nsambhavaḥ sarva-bhūtānāṁ tato bhavati bhārata","english":"My womb is the great Brahman (Prakriti); in it I place the seed of all living entities, and from that union, O Arjuna, occurs the birth of all beings.","hindi":"हे अर्जुन! मेरी महद् ब्रह्मरूपा प्रकृति ही समस्त भूतों की योनि (गर्भ) है, जिसमें मैं गर्भाधान करता हूँ और उसी से समस्त प्राणियों की उत्पत्ति होती है।","gujarati":"હે અર્જુન! મારી મહદ્ બ્રહ્મરૂપ પ્રકૃતિ એ જ સમસ્ત જીવોની યોનિ છે, જેમાં હું ગર્ભાધાન કરું છું અને તેથી જ સર્વ ભૂતોની ઉત્પત્તિ થાય છે."},"14.4":{"chapter":14,"verse":4,"sloka":"सर्वयोनिषु कौन्तेय मूर्तयः सम्भवन्ति याः।तासां ब्रह्म महद्योनिरहं बीजप्रदः पिता।।14.4।।","transliteration":"sarva-yoniṣhu kaunteya mūrtayaḥ sambhavanti yāḥ\ntāsāṁ brahma mahad yonir ahaṁ bīja-pradaḥ pitā","english":"O son of Kunti, know that in all forms of life that are born from various wombs, the material nature is the mother who conceives them, and I, Shri Krishna, am the seed-giving father.","hindi":"हे कौन्तेय! समस्त योनियों में जो-जो भी मूर्तियाँ उत्पन्न होती हैं, उन सबकी योनि अर्थात् गर्भ-धारण करने वाली तो प्रकृति है और मैं बीज स्थापित करने वाला पिता हूँ।","gujarati":"હે અર્જુન! તમામ યોનિઓમાં જે જે શરીર ધારણ થાય છે, તે બધા માટે પ્રકૃતિ ગર્ભસ્થાન છે અને હું બીજ આપનાર પિતા છું."},"14.5":{"chapter":14,"verse":5,"sloka":"सत्त्वं रजस्तम इति गुणाः प्रकृतिसंभवाः।निबध्नन्ति महाबाहो देहे देहिनमव्ययम्।।14.5।।","transliteration":"sattvaṁ rajas tama iti guṇāḥ prakṛiti-sambhavāḥ\nnibadhnanti mahā-bāho dehe dehinam avyayam","english":"Sattva, Rajas, and Tamas — these three modes born of material nature, O mighty-armed Arjuna, bind the eternal soul to the physical body.","hindi":"हे महाबाहो अर्जुन! सत्त्व, रज और तम - प्रकृति से उत्पन्न ये तीनों गुण अविनाशी आत्मा को शरीर में बांध देते हैं।","gujarati":"હે મહાબાહો અર્જુન! સત્ત્વ, રજ અને તમ - પ્રકૃતિથી ઉત્પન્ન થયેલા આ ત્રણ ગુણો અવિનાશી આત્માને શરીરમાં જકડી રાખે છે."},"14.6":{"chapter":14,"verse":6,"sloka":"तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम्।सुखसङ्गेन बध्नाति ज्ञानसङ्गेन चानघ।।14.6।।","transliteration":"tatra sattvaṁ nirmalatvāt prakāśhakam anāmayam\nsukha-saṅgena badhnāti jñāna-saṅgena chānagha","english":"O sinless Arjuna, of these three modes, the mode of goodness (sattva-guna), being purer than the others, is illuminating and free from all vice; it binds the soul by attachment to happiness and attachment to knowledge.","hindi":"हे निष्पाप अर्जुन! इन तीनों गुणों में, सत्त्वगुण निर्मल होने के कारण प्रकाशक और निर्दोष है; वह जीव को सुख की आसक्ति और ज्ञान की आसक्ति से बांध लेता है।","gujarati":"હે નિષ્પાપ અર્જુન! આ ત્રણ ગુણોમાં, સત્વગુણ અત્યંત નિર્મળ હોવાથી પ્રકાશક અને દોષરહિત છે; તે જીવાત્માને સુખની આસક્તિ અને જ્ઞાનની આસક્તિ દ્વારા બાંધી લે છે."},"14.7":{"chapter":14,"verse":7,"sloka":"रजो रागात्मकं विद्धि तृष्णासङ्गसमुद्भवम्।तन्निबध्नाति कौन्तेय कर्मसङ्गेन देहिनम्।।14.7।।","transliteration":"rajo rāgātmakaṁ viddhi tṛiṣhṇā-saṅga-samudbhavam\ntan nibadhnāti kaunteya karma-saṅgena dehinam","english":"Know, O Arjuna, that the mode of passion, Rajas, is born of unlimited desires and longings, and because of this, the embodied soul is bound to material fruitive activities.","hindi":"हे अर्जुन! तुम रजोगुण को रागस्वरूप जानो, जो तृष्णा और आसक्ति से उत्पन्न होता है। यह देही आत्मा को कर्म और उनके फलों की आसक्ति से बांध देता है।","gujarati":"હે અર્જુન! તું રજોગુણને રાગસ્વરૂપ જાણ, જે તૃષ્ણા અને આસક્તિમાંથી જન્મે છે. તે દેહધારી આત્માને કર્મ અને તેના ફળની આસક્તિ દ્વારા બાંધી લે છે."},"14.8":{"chapter":14,"verse":8,"sloka":"तमस्त्वज्ञानजं विद्धि मोहनं सर्वदेहिनाम्।प्रमादालस्यनिद्राभिस्तन्निबध्नाति भारत।।14.8।।","transliteration":"tamas tv ajñāna-jaṁ viddhi mohanaṁ sarva-dehinām\npramādālasya-nidrābhis tan nibadhnāti bhārata","english":"But know, O Arjuna, that Tamas is born of ignorance and deludes all embodied beings. It binds the soul fast through heedlessness, indolence, and sleep.","hindi":"हे अर्जुन! तू तमोगुण को अज्ञान से उत्पन्न जान; यह समस्त देहधारियों को मोहित करने वाला है। वह प्रमाद, आलस्य और निद्रा के द्वारा जीव को बांधता है।","gujarati":"હે અર્જુન! તમોગુણને અજ્ઞાનમાંથી ઉત્પન્ન થયેલો જાણ; જે તમામ દેહધારીઓને મોહિત કરનારો છે. તે પ્રમાદ, આળસ અને નિદ્રા દ્વારા જીવને બાંધે છે."},"14.9":{"chapter":14,"verse":9,"sloka":"सत्त्वं सुखे सञ्जयति रजः कर्मणि भारत।ज्ञानमावृत्य तु तमः प्रमादे सञ्जयत्युत।।14.9।।","transliteration":"sattvaṁ sukhe sañjayati rajaḥ karmaṇi bhārata\njñānam āvṛitya tu tamaḥ pramāde sañjayaty uta","english":"Sattva binds one to happiness, Rajas to action, O Arjuna, while Tamas, verily shrouding knowledge, attaches one to heedlessness.","hindi":"हे अर्जुन! सत्त्वगुण सुख में आसक्त करता है और रजोगुण कर्म में, किन्तु तमोगुण ज्ञान को ढंककर प्रमाद में आसक्त कर देता है।","gujarati":"હે અર્જુન! સત્વગુણ સુખમાં આસક્ત કરે છે અને રજોગુણ કર્મના ફળમાં, પરંતુ તમોગુણ જ્ઞાનને ઢાંકીને પ્રમાદમાં આસક્ત કરી દે છે."},"14.10":{"chapter":14,"verse":10,"sloka":"रजस्तमश्चाभिभूय सत्त्वं भवति भारत।रजः सत्त्वं तमश्चैव तमः सत्त्वं रजस्तथा।।14.10।।","transliteration":"rajas tamaśh chābhibhūya sattvaṁ bhavati bhārata\nrajaḥ sattvaṁ tamaśh chaiva tamaḥ sattvaṁ rajas tathā","english":"O descendant of Bharata, sometimes goodness (Sattva) prevails, having conquered passion (Rajas) and ignorance (Tamas); at other times passion (Rajas) prevails, having conquered goodness (Sattva) and ignorance (Tamas); and at other times ignorance (Tamas) prevails, having conquered goodness (Sattva) and passion (Rajas).","hindi":"हे भरतवंशी अर्जुन! कभी सत्त्वगुण रजोगुण और तमोगुण को दबाकर प्रबल हो जाता है, कभी रजोगुण सत्त्वगुण और तमोगुण को दबाकर प्रबल हो जाता है, और कभी तमोगुण सत्त्वगुण और रजोगुण को दबाकर प्रबल हो जाता है।","gujarati":"હે ભરતવંશી અર્જુન! ક્યારેક રજોગુણ અને તમોગુણને દબાવીને સત્ત્વગુણની વૃદ્ધિ થાય છે, ક્યારેક સત્ત્વગુણ અને તમોગુણને દબાવીને રજોગુણની વૃદ્ધિ થાય છે, અને ક્યારેક સત્ત્વગુણ અને રજોગુણને દબાવીને તમોગુણની વૃદ્ધિ થાય છે."},"14.11":{"chapter":14,"verse":11,"sloka":"सर्वद्वारेषु देहेऽस्मिन्प्रकाश उपजायते।ज्ञानं यदा तदा विद्याद्विवृद्धं सत्त्वमित्युत।।14.11।।","transliteration":"sarva-dvāreṣhu dehe ’smin prakāśha upajāyate\njñānaṁ yadā tadā vidyād vivṛiddhaṁ sattvam ity uta","english":"When the light of wisdom shines through all the gates of this body, then it should be known that the quality of goodness, Sattva, is predominant.","hindi":"जब इस देह के द्वारों अर्थात् समस्त इन्द्रियों में ज्ञानरूप प्रकाश उत्पन्न होता है, तब सत्त्वगुण को प्रवृद्ध हुआ जानो।","gujarati":"જ્યારે આ દેહના સર્વ દ્વારોમાં જ્ઞાનરૂપી પ્રકાશ પ્રગટ થાય છે, ત્યારે સમજવું કે સત્ત્વગુણ પ્રબળ થયો છે."},"14.12":{"chapter":14,"verse":12,"sloka":"लोभः प्रवृत्तिरारम्भः कर्मणामशमः स्पृहा।रजस्येतानि जायन्ते विवृद्धे भरतर्षभ।।14.12।।","transliteration":"lobhaḥ pravṛittir ārambhaḥ karmaṇām aśhamaḥ spṛihā\nrajasy etāni jāyante vivṛiddhe bharatarṣhabha","english":"Greed, intense activity, the undertaking of worldly projects, restlessness, and deep longing—these symptoms manifest when the mode of passion, Rajas, becomes predominant, O best of the Bharatas, Arjuna.","hindi":"हे भरतवंशी अर्जुन! रजोगुण के बढ़ने पर लोभ, कर्मों में अत्यधिक प्रवृत्ति, सांसारिक कार्यों का आरम्भ, अशांति और विषयों के प्रति लालसा—ये सब उत्पन्न होते हैं।","gujarati":"હે અર્જુન! રજોગુણની વૃદ્ધિ થતાં લોભ, કાર્ય કરવામાં પ્રવૃત્તિ, નવાં કર્મોનો આરંભ, અશાંતિ અને કામનાઓ - આ બધું ઉત્પન્ન થાય છે."},"14.13":{"chapter":14,"verse":13,"sloka":"अप्रकाशोऽप्रवृत्तिश्च प्रमादो मोह एव च।तमस्येतानि जायन्ते विवृद्धे कुरुनन्दन।।14.13।।","transliteration":"aprakāśho ’pravṛittiśh cha pramādo moha eva cha\ntamasy etāni jāyante vivṛiddhe kuru-nandana","english":"Lord Krishna says: 'Darkness, inertia, negligence, and delusion—these occur when the mode of ignorance (Tamas) is predominant, O descendant of Kuru.'","hindi":"भगवान श्रीकृष्ण कहते हैं: 'हे कुरुनन्दन! तमोगुण की वृद्धि होने पर अप्रकाश (अज्ञान), अप्रवृत्ति (आलस्य), प्रमाद (सावधानी का अभाव) और मोह उत्पन्न होते हैं।'","gujarati":"ભગવાન શ્રીકૃષ્ણ કહે છે: 'હે કુરુનંદન! જ્યારે તમોગુણની વૃદ્ધિ થાય છે, ત્યારે અજ્ઞાનતા, આળસ, પ્રમાદ અને મોહ ઉત્પન્ન થાય છે.'"},"14.14":{"chapter":14,"verse":14,"sloka":"यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत्।तदोत्तमविदां लोकानमलान्प्रतिपद्यते।।14.14।।","transliteration":"yadā sattve pravṛiddhe tu pralayaṁ yāti deha-bhṛit\ntadottama-vidāṁ lokān amalān pratipadyate","english":"When the embodied soul departs while the mode of goodness (Sattva) is predominant, it attains the stainless, elevated realms of those who are knowers of the Highest.","hindi":"जब यह देहधारी जीव सत्त्वगुण की प्रबलता में मृत्यु को प्राप्त होता है, तब वह उन निर्मल लोकों को प्राप्त होता है जो श्रेष्ठ ज्ञानियों के लिए आरक्षित हैं।","gujarati":"જ્યારે આ દેહધારી જીવ સત્ત્વગુણની પ્રબળતામાં મૃત્યુ પામે છે, ત્યારે તે ઉત્તમ કર્મ કરનારા જ્ઞાનીઓના નિર્મળ લોકને પ્રાપ્ત કરે છે."},"14.15":{"chapter":14,"verse":15,"sloka":"रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते।तथा प्रलीनस्तमसि मूढयोनिषु जायते।।14.15।।","transliteration":"rajasi pralayaṁ gatvā karma-saṅgiṣhu jāyate\ntathā pralīnas tamasi mūḍha-yoniṣhu jāyate","english":"If one meets death while Rajas is predominant, one is born among those attached to fruitive actions; and if one meets death while Tamas is predominant, one is born in the wombs of the thoughtless.","hindi":"रजोगुण की वृद्धि के समय मृत्यु को प्राप्त होने वाला पुरुष कर्मों में आसक्त होने वालों के मध्य जन्म लेता है, और तमोगुण की वृद्धि में मृत्यु को प्राप्त होने वाला मूढ़ योनियों (पशु-पक्षी आदि) में जन्म लेता है।","gujarati":"જો રજોગુણ વધેલો હોય ત્યારે મનુષ્ય મૃત્યુ પામે, તો તે કર્મોમાં આસક્ત લોકોમાં જન્મ લે છે; અને જો તમોગુણ વધેલો હોય ત્યારે મૃત્યુ પામે, તો તે મૂઢ યોનિઓમાં જન્મ લે છે."},"14.16":{"chapter":14,"verse":16,"sloka":"कर्मणः सुकृतस्याहुः सात्त्विकं निर्मलं फलम्।रजसस्तु फलं दुःखमज्ञानं तमसः फलम्।।14.16।।","transliteration":"karmaṇaḥ sukṛitasyāhuḥ sāttvikaṁ nirmalaṁ phalam\nrajasas tu phalaṁ duḥkham ajñānaṁ tamasaḥ phalam","english":"The result of a virtuous act is said to be Sattvic and pure; the result of passion is misery, and the result of ignorance is darkness.","hindi":"शुभ कर्म का फल सात्विक और निर्मल कहा गया है; रजोगुण का फल दुःख और तमोगुण का फल अज्ञान है।","gujarati":"સત્કર્મનું ફળ સાત્વિક અને નિર્મળ કહેવાયું છે; રજોગુણનું ફળ દુઃખ અને તમોગુણનું ફળ અજ્ઞાન છે."},"14.17":{"chapter":14,"verse":17,"sloka":"सत्त्वात्सञ्जायते ज्ञानं रजसो लोभ एव च।प्रमादमोहौ तमसो भवतोऽज्ञानमेव च।।14.17।।","transliteration":"sattvāt sañjāyate jñānaṁ rajaso lobha eva cha\npramāda-mohau tamaso bhavato ’jñānam eva cha","english":"From Sattva arises knowledge, from Rajas arises greed, and from Tamas arise heedlessness, delusion, and also ignorance.","hindi":"सत्त्वगुण से ज्ञान उत्पन्न होता है, रजोगुण से लोभ उत्पन्न होता है, और तमोगुण से प्रमाद, मोह तथा अज्ञान उत्पन्न होता है।","gujarati":"સત્વગુણથી જ્ઞાન ઉત્પન્ન થાય છે, રજોગુણથી લોભ ઉત્પન્ન થાય છે, અને તમોગુણથી પ્રમાદ, મોહ તથા અજ્ઞાન ઉત્પન્ન થાય છે."},"14.18":{"chapter":14,"verse":18,"sloka":"ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः।जघन्यगुणवृत्तिस्था अधो गच्छन्ति तामसाः।।14.18।।","transliteration":"ūrdhvaṁ gachchhanti sattva-sthā madhye tiṣhṭhanti rājasāḥ\njaghanya-guṇa-vṛitti-sthā adho gachchhanti tāmasāḥ","english":"Those established in Sattva ascend to higher realms, those governed by Rajas remain in the middle sphere, and those immersed in the functions of Tamas descend to lower states.","hindi":"सत्त्वगुण में स्थित पुरुष ऊर्ध्व लोकों को जाते हैं, रजोगुणी पुरुष मध्य में स्थित रहते हैं और तमोगुण के कार्यों में लीन तामस लोग अधोगति को प्राप्त होते हैं।","gujarati":"સત્વગુણમાં સ્થિત પુરુષો ઉર્ધ્વ લોકને પામે છે, રજોગુણી પુરુષો મધ્યમાં રહે છે અને તમોગુણની હીન વૃત્તિઓમાં સ્થિત તામસ લોકો અધોગતિને પ્રાપ્ત થાય છે."},"14.19":{"chapter":14,"verse":19,"sloka":"नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति।गुणेभ्यश्च परं वेत्ति मद्भावं सोऽधिगच्छति।।14.19।।","transliteration":"nānyaṁ guṇebhyaḥ kartāraṁ yadā draṣhṭānupaśhyati\nguṇebhyaśh cha paraṁ vetti mad-bhāvaṁ so ’dhigachchhati","english":"When the seer perceives no agent of action other than the three modes of material nature (Gunas), and knows the Supreme Lord Krishna who is transcendental to these modes, he attains My divine nature.","hindi":"जब द्रष्टा यह अनुभव करता है कि तीनों गुणों के अतिरिक्त अन्य कोई कर्ता नहीं है और वह उन गुणों से परे स्थित भगवान श्री कृष्ण के दिव्य स्वरूप को जान लेता है, तब वह मेरे दिव्य धाम को प्राप्त होता है।","gujarati":"જ્યારે દ્રષ્ટા ત્રણેય ગુણો સિવાય અન્ય કોઈને કર્તા તરીકે જોતો નથી અને તે ગુણોથી પર એવા પરમ પુરુષોત્તમ શ્રી કૃષ્ણને જાણી લે છે, ત્યારે તે મારા દિવ્ય સ્વરૂપને પ્રાપ્ત કરે છે."},"14.20":{"chapter":14,"verse":20,"sloka":"गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान्।जन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते।।14.20।।","transliteration":"guṇān etān atītya trīn dehī deha-samudbhavān\njanma-mṛityu-jarā-duḥkhair vimukto ’mṛitam aśhnute","english":"When the embodied soul transcends these three modes of material nature that originate the body, it becomes free from the distresses of birth, death, old age, and their attendant suffering, and thus attains the nectar of immortality.","hindi":"जब यह देही पुरुष शरीर को उत्पन्न करने वाले इन तीनों गुणों का उल्लंघन कर जाता है, तब वह जन्म, मृत्यु, वृद्धावस्था और दुखों से मुक्त होकर अमृतत्व को प्राप्त कर लेता है।","gujarati":"જ્યારે દેહધારી આ ત્રણેય ગુણોને ઓળંગી જાય છે જેમાંથી શરીર ઉત્પન્ન થયું છે, ત્યારે તે જન્મ, મૃત્યુ, વૃદ્ધાવસ્થા અને દુઃખોથી મુક્ત થઈને અમૃતત્વને પ્રાપ્ત કરે છે."},"14.21":{"chapter":14,"verse":21,"sloka":"अर्जुन उवाचकैर्लिंगैस्त्रीन्गुणानेतानतीतो भवति प्रभो।किमाचारः कथं चैतांस्त्रीन्गुणानतिवर्तते।।14.21।।","transliteration":"arjuna uvācha\nkair liṅgais trīn guṇān etān atīto bhavati prabho\nkim āchāraḥ kathaṁ chaitāns trīn guṇān ativartate","english":"Arjuna asked: O Lord, what are the characteristics of one who has transcended these three modes of material nature? How does such a person conduct themselves, and by what means do they transcend these modes?","hindi":"अर्जुन ने पूछा: हे प्रभो! इन तीनों गुणों से अतीत हुआ पुरुष किन लक्षणों से युक्त होता है? उसका आचरण कैसा होता है और वह किस उपाय से इन तीनों गुणों से परे जाता है?","gujarati":"અર્જુને પૂછ્યું: હે પ્રભો! આ ત્રણ ગુણોથી પર થયેલા પુરુષના લક્ષણો કયા છે? તેનું આચરણ કેવું હોય છે અને તે કયા ઉપાયથી આ ત્રણ ગુણોને ઓળંગી જાય છે?"},"14.22":{"chapter":14,"verse":22,"sloka":"श्री भगवानुवाचप्रकाशं च प्रवृत्तिं च मोहमेव च पाण्डव।न द्वेष्टि सम्प्रवृत्तानि न निवृत्तानि काङ्क्षति।।14.22।।","transliteration":"śhrī-bhagavān uvācha\nprakāśhaṁ cha pravṛittiṁ cha moham eva cha pāṇḍava\nna dveṣhṭi sampravṛittāni na nivṛittāni kāṅkṣhati","english":"Shri Krishna said: He who does not abhor illumination, activity, and delusion when they are manifest, nor desires them when they are absent.","hindi":"श्रीभगवान् ने कहा—हे अर्जुन! जो प्रकाश (सत्त्वगुण), प्रवृत्ति (रजोगुण) और मोह (तमोगुण) के प्रकट होने पर उनसे द्वेष नहीं करता और उनके निवृत्त होने पर उनकी आकांक्षा नहीं करता।","gujarati":"શ્રી ભગવાન બોલ્યા—હે અર્જુન! જે પ્રકાશ, પ્રવૃત્તિ અને મોહરૂપી ગુણો પ્રગટ થાય ત્યારે તેનો દ્વેષ કરતો નથી, અને જ્યારે તે નિવૃત્ત થાય ત્યારે તેની આકાંક્ષા પણ કરતો નથી."},"14.23":{"chapter":14,"verse":23,"sloka":"उदासीनवदासीनो गुणैर्यो न विचाल्यते।गुणा वर्तन्त इत्येव योऽवतिष्ठति नेङ्गते।।14.23।।","transliteration":"udāsīna-vad āsīno guṇair yo na vichālyate\nguṇā vartanta ity evaṁ yo ’vatiṣhṭhati neṅgate","english":"He who remains like one unconcerned, undisturbed by the modes of material nature, and who, knowing that the modes are solely acting, remains fixed and does not waver—such a person is situated in the transcendental state.","hindi":"जो उदासीन के समान स्थित है और गुणों के द्वारा विचलित नहीं होता, जो यह जानकर कि 'केवल गुण ही गुणों में बरत रहे हैं', अडिग रहता है और स्वयं विचलित नहीं होता।","gujarati":"જે ઉદાસીનની જેમ સ્થિત રહીને ગુણો દ્વારા વિચલિત થતો નથી અને જે એવું જાણીને કે 'કેવળ ગુણો જ ગુણોમાં કાર્ય કરી રહ્યા છે', સ્થિર રહે છે અને ડગમગતો નથી."},"14.24":{"chapter":14,"verse":24,"sloka":"समदुःखसुखः स्वस्थः समलोष्टाश्मकाञ्चनः।तुल्यप्रियाप्रियो धीरस्तुल्यनिन्दात्मसंस्तुतिः।।14.24।।","transliteration":"sama-duḥkha-sukhaḥ sva-sthaḥ sama-loṣhṭāśhma-kāñchanaḥ\ntulya-priyāpriyo dhīras tulya-nindātma-sanstutiḥ","english":"He who is alike in pleasure and pain, who is established in the Self, to whom a clod of earth, a stone, and gold are the same, who is equal to the dear and the unfriendly, who is firm, and to whom censure and praise are the same.","hindi":"जो सुख-दु:ख को समान समझने वाला है, जो अपने स्वरूप में स्थित है, जिसके लिए मिट्टी, पत्थर और स्वर्ण समान हैं, जो प्रिय और अप्रिय को एक समान देखता है, जो धीर है और जिसे निन्दा तथा स्तुति समान हैं।","gujarati":"જે સુખ-દુઃખમાં સમાન રહેનારો છે, જે પોતાના સ્વરૂપમાં સ્થિત છે, જેના માટે માટી, પથ્થર અને સોનું સમાન છે, જે પ્રિય અને અપ્રિયને સમાન ગણે છે, જે ધીર છે અને જેને નિંદા તથા સ્તુતિ સમાન છે."},"14.25":{"chapter":14,"verse":25,"sloka":"मानापमानयोस्तुल्यस्तुल्यो मित्रारिपक्षयोः।सर्वारम्भपरित्यागी गुणातीतः स उच्यते।।14.25।।","transliteration":"mānāpamānayos tulyas tulyo mitrāri-pakṣhayoḥ\nsarvārambha-parityāgī guṇātītaḥ sa uchyate","english":"He who is the same in honor and dishonor, the same to friend and foe, having abandoned all undertakings, is said to have transcended the modes of material nature.","hindi":"जो मान और अपमान में समान है, मित्र और शत्रु के प्रति भी समान भाव रखता है, और जिसने समस्त सांसारिक कार्यों का कर्तापन त्याग दिया है, ऐसे पुरुष को गुणातीत कहा गया है।","gujarati":"જે માન અને અપમાનમાં સમાન છે, મિત્ર અને શત્રુ પક્ષમાં પણ સમાન છે, અને જેણે તમામ કર્મોના કર્તાપણાનો ત્યાગ કર્યો છે, તેવા પુરુષને ગુણાતીત કહેવામાં આવે છે."},"14.26":{"chapter":14,"verse":26,"sloka":"मां च योऽव्यभिचारेण भक्ितयोगेन सेवते।स गुणान्समतीत्यैतान् ब्रह्मभूयाय कल्पते।।14.26।।","transliteration":"māṁ cha yo ’vyabhichāreṇa bhakti-yogena sevate\nsa guṇān samatītyaitān brahma-bhūyāya kalpate","english":"And he who serves Me with unwavering devotion, transcending these three modes of material nature, at once becomes eligible for realization of the Brahman.","hindi":"और जो पुरुष अव्यभिचारी भक्तियोग के द्वारा निरंतर मेरी सेवा करता है, वह इन तीनों गुणों को भली-भांति लांघकर सच्चिदानंदघन ब्रह्म को प्राप्त करने के योग्य हो जाता है।","gujarati":"અને જે કોઈ અનન્ય ભક્તિ દ્વારા મારી સેવા કરે છે, તે પ્રકૃતિના આ ત્રણેય ગુણોને ઓળંગીને બ્રહ્મરૂપ થવાને યોગ્ય બને છે."},"14.27":{"chapter":14,"verse":27,"sloka":"ब्रह्मणो हि प्रतिष्ठाऽहममृतस्याव्ययस्य च।शाश्वतस्य च धर्मस्य सुखस्यैकान्तिकस्य च।।14.27।।","transliteration":"brahmaṇo hi pratiṣhṭhāham amṛitasyāvyayasya cha\nśhāśhvatasya cha dharmasya sukhasyaikāntikasya cha","english":"For I am the foundation of the impersonal Brahman, of immortality, of imperishability, of eternal Dharma, and of absolute bliss.","hindi":"क्योंकि मैं अविनाशी ब्रह्म का, अमृत का, अक्षय धर्म का और अनन्य परमानंद का आश्रय हूँ।","gujarati":"કારણ કે હું અમર, અવિનાશી બ્રહ્મ, શાશ્વત ધર્મ અને પરમ આનંદનો આશ્રય છું."},"15.1":{"chapter":15,"verse":1,"sloka":"श्री भगवानुवाचऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम्।छन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित्।।15.1।।","transliteration":"śhrī-bhagavān uvācha\nūrdhva-mūlam adhaḥ-śhākham aśhvatthaṁ prāhur avyayam\nchhandānsi yasya parṇāni yas taṁ veda sa veda-vit","english":"Shri Krishna, the Supreme Personality of Godhead, said: They speak of an eternal banyan tree that has its roots above and its branches below, whose leaves are the Vedic hymns. One who understands this tree is the knower of the Vedas.","hindi":"श्री भगवान् ने कहा: (ज्ञानी जन) ऊर्ध्वमूल और अधःशाखा वाले उस अविनाशी अश्वत्थ वृक्ष को संसार का स्वरूप बताते हैं, जिसके पत्ते वैदिक छंद हैं; जो पुरुष इस संसार-वृक्ष को तत्व से जानता है, वह वास्तव में वेद का ज्ञाता है।","gujarati":"શ્રી ભગવાન બોલ્યા: (જ્ઞાનીઓ) ઊર્ધ્વમૂળ અને અધઃશાખાવાળા અવિનાશી અશ્વત્થ વૃક્ષને સંસારનું સ્વરૂપ કહે છે, જેના પાન વૈદિક છંદો છે; જે મનુષ્ય આ સંસાર-વૃક્ષને તત્વથી જાણે છે, તે જ સાચો વેદવેત્તા છે."},"15.2":{"chapter":15,"verse":2,"sloka":"अधश्चोर्ध्वं प्रसृतास्तस्य शाखा     गुणप्रवृद्धा विषयप्रवालाः।अधश्च मूलान्यनुसन्ततानि     कर्मानुबन्धीनि मनुष्यलोके।।15.2।।","transliteration":"adhaśh chordhvaṁ prasṛitās tasya śhākhā\nguṇa-pravṛiddhā viṣhaya-pravālāḥ\nadhaśh cha mūlāny anusantatāni\nkarmānubandhīni manuṣhya-loke","english":"Its branches extend both downward and upward, nourished by the Gunas; its buds are the sense-objects. Below, in the human world, the roots spread out, causing the bonds of Karma.","hindi":"उस संसार रूपी अश्वत्थ वृक्ष की शाखाएं तीनों गुणों द्वारा पोषित होकर ऊपर और नीचे फैली हुई हैं; विषयों के अंकुर इसके कोमल पत्ते हैं। मनुष्य लोक में कर्मों को उत्पन्न करने वाली इसकी जड़ें नीचे की ओर फैली हुई हैं।","gujarati":"તે સંસારરૂપી અશ્વત્થ વૃક્ષની શાખાઓ ત્રણેય ગુણો દ્વારા પોષાઈને નીચે અને ઉપર ફેલાયેલી છે; વિષયો તેના અંકુર છે, અને મનુષ્યલોકમાં કર્મોનું બંધન પેદા કરતી તેની મૂળ નીચેની તરફ પ્રસરેલી છે."},"15.3":{"chapter":15,"verse":3,"sloka":"न रूपमस्येह तथोपलभ्यते    नान्तो न चादिर्न च संप्रतिष्ठा।अश्वत्थमेनं सुविरूढमूल    मसङ्गशस्त्रेण दृढेन छित्त्वा।।15.3।।","transliteration":"na rūpam asyeha tathopalabhyate\nnānto na chādir na cha sampratiṣhṭhā\naśhvattham enaṁ su-virūḍha-mūlam\nasaṅga-śhastreṇa dṛiḍhena chhittvā","english":"The true nature of this worldly tree is not perceived here, neither its beginning nor its end, nor its foundation. Having cut down this firmly rooted Ashvattha tree with the powerful weapon of detachment, one must seek the supreme goal.","hindi":"इस संसार रूपी वृक्ष का स्वरूप जैसा कहा गया है, वैसा यहाँ (इस लोक में) नहीं देखा जाता, न तो इसका आदि है, न अंत और न ही कोई सुदृढ़ आधार है। इस अत्यंत दृढ़ मूल वाले अश्वत्थ वृक्ष को वैराग्य रूपी शस्त्र से काटकर, परम पद की खोज करनी चाहिए।","gujarati":"આ સંસાર રૂપી વૃક્ષનું સ્વરૂપ જેવું કહેવામાં આવ્યું છે તેવું અહીં જોવા મળતું નથી, કારણ કે ન તો તેનો કોઈ આદિ છે, ન અંત છે અને ન કોઈ સ્થાયી આધાર છે. આ અત્યંત દ્રઢ મૂળવાળા અશ્વત્થ વૃક્ષને અનાસક્તિરૂપી શસ્ત્ર વડે કાપીને, પરમ પદની શોધ કરવી જોઈએ."},"15.4":{"chapter":15,"verse":4,"sloka":"ततः पदं तत्परिमार्गितव्य    यस्मिन्गता न निवर्तन्ति भूयः।तमेव चाद्यं पुरुषं प्रपद्ये    यतः प्रवृत्तिः प्रसृता पुराणी।।15.4।।","transliteration":"tataḥ padaṁ tat parimārgitavyaṁ\nyasmin gatā na nivartanti bhūyaḥ\ntam eva chādyaṁ puruṣhaṁ prapadye\nyataḥ pravṛittiḥ prasṛitā purāṇī","english":"Then, that goal should be sought for, to which, having gone, they do not return. I seek refuge in that Primeval Purusha from whom the eternal process of creation has streamed forth.","hindi":"तत्पश्चात उस परम पद को खोजना चाहिए जहाँ पहुँचकर जीव पुनः संसार में नहीं लौटते। मैं उस आदि पुरुष की शरण में हूँ, जिनसे यह पुरातन संसार-प्रवृत्ति प्रसृत हुई है।","gujarati":"ત્યારબાદ તે પરમ પદની શોધ કરવી જોઈએ કે જ્યાં ગયા પછી જીવ ફરી આ સંસારમાં પાછો આવતો નથી. હું તે આદિ પુરુષના શરણમાં છું, જેમાંથી આ પુરાતન સૃષ્ટિ-પ્રવૃત્તિનો વિસ્તાર થયો છે."},"15.5":{"chapter":15,"verse":5,"sloka":"निर्मानमोहा जितसङ्गदोषा    अध्यात्मनित्या विनिवृत्तकामाः।द्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञै    र्गच्छन्त्यमूढाः पदमव्ययं तत्।।15.5।।","transliteration":"nirmāna-mohā jita-saṅga-doṣhā\nadhyātma-nityā vinivṛitta-kāmāḥ\ndvandvair vimuktāḥ sukha-duḥkha-sanjñair\ngachchhanty amūḍhāḥ padam avyayaṁ tat","english":"Those who are free from pride and delusion, who have conquered the evil of attachment, who dwell constantly in the Self, whose desires have completely ceased, and who are liberated from the dualities known as pleasure and pain—such undeluded souls attain My eternal abode.","hindi":"जिनका मान और मोह नष्ट हो गया है, जिन्होंने संगदोष को जीत लिया है, जो नित्य परमात्मा के स्वरूप में स्थित हैं, जिनकी कामनाएं पूर्णतः शांत हो गई हैं और जो सुख-दुःख जैसे द्वंद्वों से मुक्त हैं, वे मोह-रहित पुरुष उस अविनाशी परम पद को प्राप्त होते हैं।","gujarati":"જેમનું માન અને મોહ નષ્ટ થઈ ગયા છે, જેમણે સંગદોષને જીતી લીધો છે, જેઓ પરમાત્મામાં સ્થિત છે, જેની કામનાઓ સંપૂર્ણપણે શાંત થઈ ગઈ છે અને જેઓ સુખ-દુઃખ નામના દ્વંદ્વોથી મુક્ત થઈ ગયા છે, તેવા મોહરહિત જ્ઞાનીજન તે અવિનાશી પરમ પદને પ્રાપ્ત કરે છે."},"15.6":{"chapter":15,"verse":6,"sloka":"न तद्भासयते सूर्यो न शशाङ्को न पावकः।यद्गत्वा न निवर्तन्ते तद्धाम परमं मम।।15.6।।","transliteration":"na tad bhāsayate sūryo na śhaśhāṅko na pāvakaḥ\nyad gatvā na nivartante tad dhāma paramaṁ mama","english":"Neither the sun illuminates there, nor the moon, nor the fire; having reached that state, one does not return. That is My supreme abode, declares Bhagwan Shri Krishna.","hindi":"न वहाँ सूर्य प्रकाशित कर सकता है, न चंद्रमा और न ही अग्नि। उस परम धाम को प्राप्त करके जीव पुन: संसार में नहीं लौटते हैं। वह मेरा परम धाम है, ऐसा भगवान श्री कृष्ण का वचन है।","gujarati":"ત્યાં ન તો સૂર્ય પ્રકાશિત કરી શકે છે, ન ચંદ્રમા અને ન અગ્નિ। જેને પ્રાપ્ત કરીને મનુષ્ય ફરી આ સંસારમાં પાછા ફરતા નથી, તે મારું પરમ ધામ છે, એમ ભગવાન શ્રી કૃષ્ણ કહે છે."},"15.7":{"chapter":15,"verse":7,"sloka":"ममैवांशो जीवलोके जीवभूतः सनातनः।मनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति।।15.7।।","transliteration":"mamaivānśho jīva-loke jīva-bhūtaḥ sanātanaḥ\nmanaḥ-ṣhaṣhṭhānīndriyāṇi prakṛiti-sthāni karṣhati","english":"An eternal portion of Myself, having become a living soul in the world of life, draws to itself the five senses, with the mind as the sixth, abiding in Nature.","hindi":"इस जीव-लोक में मेरा ही एक सनातन अंश जीव-रूप धारण करता है और प्रकृति में स्थित छह इन्द्रियों (पाँच ज्ञानेन्द्रियाँ और मन) को अपनी ओर आकर्षित करता है।","gujarati":"આ જીવલોકમાં મારો જ એક સનાતન અંશ જીવ બનીને પ્રકૃતિમાં સ્થિત પાંચ ઇન્દ્રિયો અને છઠ્ઠા મનને પોતાની તરફ આકર્ષે છે."},"15.8":{"chapter":15,"verse":8,"sloka":"शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः।गृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात्।।15.8।।","transliteration":"śharīraṁ yad avāpnoti yach chāpy utkrāmatīśhvaraḥ\ngṛihītvaitāni sanyāti vāyur gandhān ivāśhayāt","english":"When the Lord, who is the individual soul (Jiva), acquires a body or departs from one, He carries with Him the senses and the mind, just as the wind carries scents away from their source.","hindi":"जब जीव रूपी ईश्वर शरीर को धारण करता है और जब वह इसे छोड़ता है, तब वह इन इन्द्रियों और मन को वैसे ही साथ ले जाता है, जैसे वायु फूलों के स्थान से गन्ध को ले जाती है।","gujarati":"જ્યારે ભગવાન જીવના રૂપમાં શરીર ધારણ કરે છે અને જ્યારે તેને છોડે છે, ત્યારે તે આ ઇન્દ્રિયો અને મનને એવી જ રીતે પોતાની સાથે લઈ જાય છે, જેમ વાયુ ફૂલોના સ્થાનમાંથી સુગંધને લઈ જાય છે."},"15.9":{"chapter":15,"verse":9,"sloka":"श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च।अधिष्ठाय मनश्चायं विषयानुपसेवते।।15.9।।","transliteration":"śhrotraṁ chakṣhuḥ sparśhanaṁ cha rasanaṁ ghrāṇam eva cha\nadhiṣhṭhāya manaśh chāyaṁ viṣhayān upasevate","english":"Presiding over the ears, eyes, touch, taste, smell, and the mind, the embodied soul enjoys the objects of the senses.","hindi":"यह जीव श्रोत्र, चक्षु, त्वचा, रसना, घ्राण और मन को आश्रय देकर विषयों का सेवन करता है।","gujarati":"આ જીવ કાન, આંખ, ત્વચા, જીભ, નાક અને મનને આશ્રય આપીને વિષયોનો ભોગ કરે છે."},"15.10":{"chapter":15,"verse":10,"sloka":"उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।विमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः।।15.10।।","transliteration":"utkrāmantaṁ sthitaṁ vāpi bhuñjānaṁ vā guṇānvitam\nvimūḍhā nānupaśhyanti paśhyanti jñāna-chakṣhuṣhaḥ","english":"The deluded do not perceive the soul as it leaves the body, remains within it, or enjoys sense objects under the influence of the modes of nature; only those whose eyes are opened by the light of knowledge can behold Him.","hindi":"शरीर से निकलते हुए, शरीर में स्थित रहते हुए या गुणों के अधीन होकर विषयों को भोगते हुए भी, मूढ़ लोग इस आत्मा को नहीं देख पाते; परन्तु ज्ञानचक्षु वाले ज्ञानी पुरुष ही उसे देख पाते हैं।","gujarati":"શરીરનો ત્યાગ કરતી વખતે, શરીરમાં સ્થિત હોય ત્યારે અથવા ગુણોના આધીન થઈને વિષયોનો ભોગ કરતી વખતે પણ, મૂઢ લોકો આ આત્માને જોઈ શકતા નથી; પરંતુ જ્ઞાનરૂપી ચક્ષુ ધરાવનારા પુરુષો જ તેને જોઈ શકે છે."},"15.11":{"chapter":15,"verse":11,"sloka":"यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।यतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः।।15.11।।","transliteration":"yatanto yoginaśh chainaṁ paśhyanty ātmany avasthitam\nyatanto ‘py akṛitātmāno nainaṁ paśhyanty achetasaḥ","english":"Yogis who strive for perfection perceive Him dwelling within the Self, but the unrefined and unintelligent, despite their efforts, do not see Him.","hindi":"प्रयत्नशील योगी जन अपने हृदय में स्थित आत्मा को साक्षात देखते हैं, परन्तु जिनका अन्तःकरण शुद्ध नहीं है और जो अविवेकी हैं, वे यत्न करते हुए भी भगवान् श्रीकृष्ण को नहीं देख पाते।","gujarati":"પ્રયત્નશીલ યોગીઓ પોતાના હૃદયમાં સ્થિત આત્માને જુએ છે, પરંતુ જેમનું અંતઃકરણ અશુદ્ધ છે અને જેઓ અવिवेકી છે, તેઓ પ્રયત્ન કરવા છતાં પણ ભગવાન શ્રી કૃષ્ણને જોઈ શકતા નથી."},"15.12":{"chapter":15,"verse":12,"sloka":"यदादित्यगतं तेजो जगद्भासयतेऽखिलम्।यच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम्।।15.12।।","transliteration":"yad āditya-gataṁ tejo jagad bhāsayate ’khilam\nyach chandramasi yach chāgnau tat tejo viddhi māmakam","english":"The splendor that dwells in the sun, illuminating the entire universe; and that which is in the moon, and that which is in the fire—know that all such effulgence belongs to Me, Lord Krishna.","hindi":"जो तेज सूर्य में स्थित होकर सम्पूर्ण जगत् को प्रकाशित करता है, तथा जो चन्द्रमा में है और जो अग्नि में है, उस तेज को तुम भगवान् श्रीकृष्ण का ही जानो।","gujarati":"જે તેજ સૂર્યમાં સ્થિત થઈને સમગ્ર જગતને પ્રકાશિત કરે છે, તથા જે તેજ ચંદ્રમામાં છે અને અગ્નિમાં છે, તે તેજને તું ભગવાન શ્રીકૃષ્ણનું જ જાણ."},"15.13":{"chapter":15,"verse":13,"sloka":"गामाविश्य च भूतानि धारयाम्यहमोजसा।पुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः।।15.13।।","transliteration":"gām āviśhya cha bhūtāni dhārayāmy aham ojasā\npuṣhṇāmi chauṣhadhīḥ sarvāḥ somo bhūtvā rasātmakaḥ","english":"Entering into the earth, I support all beings by My energy; and becoming the nectar-filled moon, I nourish all medicinal herbs.","hindi":"मैं पृथ्वी में प्रविष्ट होकर अपनी शक्ति से समस्त प्राणियों को धारण करता हूँ और रसस्वरूप चन्द्रमा होकर सब औषधियों अर्थात् वनस्पतियों को पुष्ट करता हूँ।","gujarati":"હું પૃથ્વીમાં પ્રવેશ કરીને મારી શક્તિ વડે સર્વ ભૂતોને ધારણ કરું છું અને રસસ્વરૂપ ચંદ્ર બનીને તમામ ઔષધિઓનું પોષણ કરું છું."},"15.14":{"chapter":15,"verse":14,"sloka":"अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः।प्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम्।।15.14।।","transliteration":"ahaṁ vaiśhvānaro bhūtvā prāṇināṁ deham āśhritaḥ\nprāṇāpāna-samāyuktaḥ pachāmy annaṁ chatur-vidham","english":"Having become the fire Vaisvanara, I abide in the bodies of living beings and, associated with the Prana and the Apana, digest the fourfold food.","hindi":"मैं ही समस्त प्राणियों के देह में स्थित वैश्वानर अग्निरूप होकर प्राण और अपान से युक्त चार प्रकार के अन्न को पचाता हूँ।","gujarati":"હું વૈશ્વાનર અગ્નિરૂપે સર્વ પ્રાણીઓના શરીરમાં રહીને પ્રાણ તથા અપાન વાયુના સહયોગથી ચાર પ્રકારના અન્નને પચાવું છું."},"15.15":{"chapter":15,"verse":15,"sloka":"सर्वस्य चाहं हृदि सन्निविष्टो    मत्तः स्मृतिर्ज्ञानमपोहनं च।वेदैश्च सर्वैरहमेव वेद्यो    वेदान्तकृद्वेदविदेव चाहम्।।15.15।।","transliteration":"sarvasya chāhaṁ hṛidi sanniviṣhṭo\nmattaḥ smṛitir jñānam apohanaṁ cha\nvedaiśh cha sarvair aham eva vedyo\nvedānta-kṛid veda-vid eva chāham","english":"I am seated in the hearts of all living beings, and from Me proceed memory, knowledge, and forgetfulness. I am the One to be known by all the Vedas; I am the author of the Vedanta and the knower of the Vedas.","hindi":"मैं सभी प्राणियों के हृदय में स्थित हूँ, और मुझसे ही स्मृति, ज्ञान तथा उनका अभाव होता है। मैं ही समस्त वेदों द्वारा जानने योग्य हूँ, वेदान्त का रचयिता और वेदों का ज्ञाता भी मैं ही हूँ।","gujarati":"હું સર્વ પ્રાણીઓના હૃદયમાં સ્થિત છું, અને મારાથી જ સ્મૃતિ, જ્ઞાન તથા તેમનો અભાવ થાય છે. હું જ સર્વ વેદો દ્વારા જાણવા યોગ્ય છું; હું જ વેદાંતનો રચયિતા અને વેદોનો જ્ઞાતા છું."},"15.16":{"chapter":15,"verse":16,"sloka":"द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।क्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते।।15.16।।","transliteration":"dvāv imau puruṣhau loke kṣharaśh chākṣhara eva cha\nkṣharaḥ sarvāṇi bhūtāni kūṭa-stho ’kṣhara uchyate","english":"There are two kinds of beings in this world: the perishable and the imperishable. All beings are said to be perishable, and the one who is unchanging is called the imperishable.","hindi":"इस संसार में दो प्रकार के पुरुष हैं: एक 'क्षर' यानी नश्वर और दूसरा 'अक्षर' यानी अनश्वर। समस्त प्राणियों के शरीर क्षर कहलाते हैं और 'कूटस्थ' यानी विकाररहित आत्मा अक्षर कही जाती है।","gujarati":"આ સંસારમાં બે પ્રકારના પુરુષો છે: ક્ષર (નાશવંત) અને અક્ષર (અવિનાશી). તમામ જીવો ક્ષર કહેવાય છે અને જે કૂટસ્થ છે, તેને અક્ષર કહેવામાં આવે છે."},"15.17":{"chapter":15,"verse":17,"sloka":"उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः।यो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः।।15.17।।","transliteration":"uttamaḥ puruṣhas tv anyaḥ paramātmety udāhṛitaḥ\nyo loka-trayam āviśhya bibharty avyaya īśhvaraḥ","english":"But the Supreme Purusha is distinct; He is known as the highest Self, the imperishable Lord, who enters into the three worlds and sustains them all.","hindi":"परन्तु उत्तम पुरुष तो अन्य ही है, जो परमात्मा कहलाता है और जो तीनों लोकों में प्रवेश करके सबका धारण करने वाला अविनाशी ईश्वर है।","gujarati":"પરંતુ ઉત્તમ પુરુષ તો અન્ય જ છે, જે પરમાત્મા કહેવાય છે અને જે ત્રણેય લોકમાં પ્રવેશ કરીને સૌનું ધારણ-પોષણ કરનાર અવિનાશી ઈશ્વર છે."},"15.18":{"chapter":15,"verse":18,"sloka":"यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः।अतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः।।15.18।।","transliteration":"yasmāt kṣharam atīto ’ham akṣharād api chottamaḥ\nato ’smi loke vede cha prathitaḥ puruṣhottamaḥ","english":"Because I transcend the perishable and am even higher than the imperishable, I am celebrated in the world and in the Vedas as the Supreme Person, Purushottama.","hindi":"क्योंकि मैं नश्वर से परे हूँ और अविनाशी से भी उत्तम हूँ, इसीलिए संसार और वेद में मुझे पुरुषोत्तम के नाम से प्रख्यात किया गया है।","gujarati":"કારણ કે હું ક્ષર (નાશવંત) થી પર છું અને અક્ષર (અવિનાશી) થી પણ સર્વોત્તમ છું, તેથી લોકમાં અને વેદોમાં હું 'પુરુષોત્તમ' તરીકે પ્રસિદ્ધ છું."},"15.19":{"chapter":15,"verse":19,"sloka":"यो मामेवमसम्मूढो जानाति पुरुषोत्तमम्।स सर्वविद्भजति मां सर्वभावेन भारत।।15.19।।","transliteration":"yo mām evam asammūḍho jānāti puruṣhottamam\nsa sarva-vid bhajati māṁ sarva-bhāvena bhārata","english":"He who, being free from delusion, knows Me as the Supreme Person, he, knowing all, worships Me with his whole being, O Arjuna.","hindi":"हे भारत! जो संशयरहित होकर मुझे पुरुषोत्तम के रूप में जानता है, वह सर्वज्ञ पुरुष सम्पूर्ण भाव से मेरी भक्ति करता है।","gujarati":"હે ભારત! જે નિર્મોહી થઈને મને પુરુષોત્તમ તરીકે જાણે છે, તે સર્વજ્ઞ પુરુષ સર્વભાવે કરીને મારું જ ભજન-પૂજન કરે છે."},"15.20":{"chapter":15,"verse":20,"sloka":"इति गुह्यतमं शास्त्रमिदमुक्तं मयाऽनघ।एतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत।।15.20।।","transliteration":"iti guhyatamaṁ śhāstram idam uktaṁ mayānagha\netad buddhvā buddhimān syāt kṛita-kṛityaśh cha bhārata","english":"Thus, O sinless Arjuna, I have imparted this most confidential doctrine; by understanding this, one becomes truly wise, and all one's duties are fulfilled.","hindi":"हे निष्पाप अर्जुन! इस प्रकार मेरे द्वारा यह अत्यंत गोपनीय शास्त्र कहा गया है; इसे जानकर मनुष्य बुद्धिमान हो जाता है और उसके समस्त कर्तव्य पूर्ण हो जाते हैं।","gujarati":"હે નિષ્પાપ અર્જુન! આ રીતે મારા દ્વારા આ અત્યંત ગુપ્ત શાસ્ત્ર કહેવામાં આવ્યું છે; જેને જાણીને મનુષ્ય જ્ઞાની અને કૃતકૃત્ય થઈ જાય છે."},"16.1":{"chapter":16,"verse":1,"sloka":"श्री भगवानुवाच\n\nअभयं सत्त्वसंशुद्धिः ज्ञानयोगव्यवस्थितिः।\n\nदानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम्।।16.1।।","transliteration":"śhrī-bhagavān uvācha\nabhayaṁ sattva-sanśhuddhir jñāna-yoga-vyavasthitiḥ\ndānaṁ damaśh cha yajñaśh cha svādhyāyas tapa ārjavam","english":"The Blessed Lord Krishna said: Fearlessness, purity of heart, steadfastness in knowledge and yoga, almsgiving, control of the senses, sacrifice, study of scriptures, austerity, and straightforwardness.","hindi":"श्री भगवान् श्रीकृष्ण ने कहा: निर्भयता, अन्तःकरण की शुद्धि, ज्ञानयोग में दृढ़ स्थिति, दान, इन्द्रिय-निग्रह, यज्ञ, शास्त्रों का अध्ययन, तप और सरलता।","gujarati":"શ્રી ભગવાન શ્રીકૃષ્ણે કહ્યું: અભયતા, અંતઃકરણની શુદ્ધિ, જ્ઞાનયોગમાં દ્રઢ સ્થિતિ, દાન, ઇન્દ્રિય-નિગ્રહ, યજ્ઞ, શાસ્ત્રોનું અધ્યયન, તપ અને સરળતા."},"16.2":{"chapter":16,"verse":2,"sloka":"अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम्।दया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम्।।16.2।।","transliteration":"ahinsā satyam akrodhas tyāgaḥ śhāntir apaiśhunam\ndayā bhūteṣhv aloluptvaṁ mārdavaṁ hrīr achāpalam","english":"Non-violence, truthfulness, absence of anger, renunciation, peacefulness, avoidance of fault-finding, compassion for all living beings, freedom from covetousness, gentleness, modesty, and steady determination.","hindi":"अहिंसा, सत्य, क्रोध का न होना, त्याग, शांति, चुगली न करना, समस्त प्राणियों के प्रति दया, लोभ का अभाव, कोमलता, लज्जा और स्थिरता।","gujarati":"અહિંસા, સત્ય, ક્રોધનો અભાવ, ત્યાગ, શાંતિ, નિંદા ન કરવી, સર્વ જીવો પ્રત્યે દયા, લોભનો અભાવ, મૃદુતા, લજ્જા અને અચંચળતા."},"16.3":{"chapter":16,"verse":3,"sloka":"तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता।\n\nभवन्ति सम्पदं दैवीमभिजातस्य भारत।।16.3।।","transliteration":"tejaḥ kṣhamā dhṛitiḥ śhaucham adroho nāti-mānitā\nbhavanti sampadaṁ daivīm abhijātasya bhārata","english":"Vigor, forgiveness, fortitude, purity, absence of hatred, and absence of pride—these qualities, O Arjuna, belong to one born for a divine state.","hindi":"तेज, क्षमा, धैर्य, बाहर-भीतर की शुद्धि, किसी से भी शत्रुता न रखना और अपने में पूज्यता के अभिमान का न होना—हे अर्जुन, ये दैवी संपदा लेकर उत्पन्न हुए पुरुष के लक्षण हैं।","gujarati":"તેજ, ક્ષમા, ધીરજ, બાહ્ય તથા આંતરિક શુદ્ધિ, દ્રોહનો અભાવ અને ગર્વનો અભાવ—હે અર્જુન, આ દૈવી સંપત્તિ લઈને જન્મેલા પુરુષના લક્ષણો છે."},"16.4":{"chapter":16,"verse":4,"sloka":"दम्भो दर्पोऽभिमानश्च क्रोधः पारुष्यमेव च।अज्ञानं चाभिजातस्य पार्थ सम्पदमासुरीम्।।16.4।।","transliteration":"dambho darpo ’bhimānaśh cha krodhaḥ pāruṣhyam eva cha\najñānaṁ chābhijātasya pārtha sampadam āsurīm","english":"Hypocrisy, arrogance, and conceit, anger, harshness, and ignorance—these qualities belong to one who is born for a demoniacal state, O Partha.","hindi":"दम्भ, दर्प, अभिमान, क्रोध, कठोरता और अज्ञान—हे पार्थ! ये सब आसुरी स्वभाव वाले मनुष्य के लक्षण हैं।","gujarati":"દંભ, ગર્વ, અભિમાન, ક્રોધ, કઠોરતા અને અજ્ઞાન—હે પાર્થ! આ તમામ ગુણો આસુરી સંપત્તિ ધરાવતા મનુષ્યના લક્ષણો છે."},"16.5":{"chapter":16,"verse":5,"sloka":"दैवी सम्पद्विमोक्षाय निबन्धायासुरी मता।मा शुचः सम्पदं दैवीमभिजातोऽसि पाण्डव।।16.5।।","transliteration":"daivī sampad vimokṣhāya nibandhāyāsurī matā\nmā śhuchaḥ sampadaṁ daivīm abhijāto ’si pāṇḍava","english":"The divine nature is considered conducive to liberation, whereas the demonic nature is deemed to lead to bondage. Do not grieve, O Arjuna, for you are born with divine endowments.","hindi":"दैवी सम्पदा मोक्ष के लिए और आसुरी सम्पदा बन्धन के लिए मानी गई है। हे अर्जुन, तुम शोक मत करो, क्योंकि तुम दैवी गुणों के साथ उत्पन्न हुए हो।","gujarati":"દૈવી સંપત્તિ મોક્ષ માટે અને આસુરી સંપત્તિ બંધન માટે માનવામાં આવે છે. હે અર્જુન, તું શોક ન કર, કારણ કે તું દૈવી ગુણો સાથે જન્મેલો છે."},"16.6":{"chapter":16,"verse":6,"sloka":"द्वौ भूतसर्गौ लोकेऽस्मिन् दैव आसुर एव च।दैवो विस्तरशः प्रोक्त आसुरं पार्थ मे श्रृणु।।16.6।।","transliteration":"dvau bhūta-sargau loke ’smin daiva āsura eva cha\ndaivo vistaraśhaḥ prokta āsuraṁ pārtha me śhṛiṇu","english":"O Arjuna, in this world there are two types of created beings: the divine and the demoniacal. I have already described the divine at length; now, hear from Me, O son of Pritha, regarding the demoniacal.","hindi":"हे पार्थ! इस संसार में भूतों की दो ही प्रकार की सृष्टि है- एक दैवी और दूसरी आसुरी। दैवी सम्पदा के विषय में मैंने विस्तारपूर्वक वर्णन किया है; अब तुम आसुरी स्वभाव के विषय में मुझसे विस्तार से सुनो।","gujarati":"હે અર્જુન! આ સંસારમાં ભૂતોની બે પ્રકારની સૃષ્ટિ છે, એક દૈવી અને બીજી આસુરી. દૈવી સંપત્તિ વિશે મેં વિસ્તારપૂર્વક વર્ણન કર્યું છે; હવે તું આસુરી સ્વભાવ વિશે મારી પાસેથી વિસ્તારથી સાંભળ."},"16.7":{"chapter":16,"verse":7,"sloka":"प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः।न शौचं नापि चाचारो न सत्यं तेषु विद्यते।।16.7।।","transliteration":"pravṛittiṁ cha nivṛittiṁ cha janā na vidur āsurāḥ\nna śhauchaṁ nāpi chāchāro na satyaṁ teṣhu vidyate","english":"Those who possess a demoniac nature do not know what ought to be done and what ought not to be done. Neither purity, nor righteous conduct, nor truth is found in them.","hindi":"आसुरी स्वभाव वाले लोग यह नहीं जानते कि क्या करना चाहिए और क्या नहीं करना चाहिए। उनमें न तो बाहर-भीतर की शुद्धि है, न सदाचार है और न ही सत्य का कोई स्थान है।","gujarati":"આસુરી સ્વભાવના લોકો શું કરવું જોઈએ અને શું ન કરવું જોઈએ તે જાણતા નથી. તેમનામાં ન તો પવિત્રતા હોય છે, ન સદાચાર હોય છે અને ન તો સત્ય જ હોય છે."},"16.8":{"chapter":16,"verse":8,"sloka":"असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम्।अपरस्परसम्भूतं किमन्यत्कामहैतुकम्।।16.8।।","transliteration":"asatyam apratiṣhṭhaṁ te jagad āhur anīśhvaram\naparaspara-sambhūtaṁ kim anyat kāma-haitukam","english":"They say, 'This universe is without truth, without a moral basis, without a God, brought about by mutual union, with lust as its cause; what else?'","hindi":"वे कहते हैं कि यह जगत् आश्रयरहित, असत्य और ईश्वर रहित है, यह परस्पर कामुक संबंध से ही उत्पन्न हुआ है, और क्या हो सकता है?","gujarati":"તેઓ કહે છે કે આ જગત આશ્રયરહિત, સત્યહીન અને ઈશ્વર વગરનું છે, આ તો માત્ર સ્ત્રી-પુરુષના પરસ્પર કામુક સંબધથી ઉત્પન્ન થયું છે, અને આનું બીજું કારણ શું હોઈ શકે?"},"16.9":{"chapter":16,"verse":9,"sloka":"एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः।प्रभवन्त्युग्रकर्माणः क्षयाय जगतोऽहिताः।।16.9।।","transliteration":"etāṁ dṛiṣhṭim avaṣhṭabhya naṣhṭātmāno ’lpa-buddhayaḥ\nprabhavanty ugra-karmāṇaḥ kṣhayāya jagato ’hitāḥ","english":"Holding fast to this vision, these lost souls of meager intellect and cruel actions manifest as enemies of the world, driven by a desire for its destruction.","hindi":"इस दृष्टि का आश्रय लेकर, नष्टस्वभाव वाले, अल्प बुद्धि के वे लोग घोर कर्म करने वाले और जगत् के शत्रु के रूप में उसके विनाश के लिए ही उत्पन्न होते हैं।","gujarati":"આ દ્રષ્ટિનો આશ્રય લઈને, નષ્ટ સ્વભાવવાળા, અલ્પ બુદ્ધિના તે લોકો ઘોર કર્મ કરનારા અને જગતના શત્રુ તરીકે તેના વિનાશ માટે જ ઉત્પન્ન થાય છે."},"16.10":{"chapter":16,"verse":10,"sloka":"काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः।मोहाद्गृहीत्वासद्ग्राहान्प्रवर्तन्तेऽशुचिव्रताः।।16.10।।","transliteration":"kāmam āśhritya duṣhpūraṁ dambha-māna-madānvitāḥ\nmohād gṛihītvāsad-grāhān pravartante ’śhuchi-vratāḥ","english":"Giving themselves up to insatiable desires, possessed of hypocrisy, pride, and arrogance, holding false views through delusion, they act with impure resolves.","hindi":"कभी न पूर्ण होने वाली कामनाओं का आश्रय लेकर, दम्भ, मान और मद से युक्त होकर, मोहवश मिथ्या धारणाओं को धारण किए हुए ये अशुद्ध संकल्पों वाले लोग संसार में कार्य करते हैं।","gujarati":"કદી પણ તૃપ્ત ન થતી કામનાઓનો આશ્રય લઈને, દંભ, માન અને મદથી યુક્ત, મોહવશ મિથ્યા ધારણાઓ ધારણ કરીને, આ અશુદ્ધ સંકલ્પવાળા લોકો જગતમાં કાર્ય કરે છે."},"16.11":{"chapter":16,"verse":11,"sloka":"चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः।कामोपभोगपरमा एतावदिति निश्िचताः।।16.11।।","transliteration":"chintām aparimeyāṁ cha pralayāntām upāśhritāḥ\nkāmopabhoga-paramā etāvad iti niśhchitāḥ","english":"Giving themselves over to immeasurable cares that end only with death, regarding the gratification of lust as their highest aim, and feeling sure that that is all.","hindi":"मरणपर्यन्त रहने वाली अपरिमित चिन्ताओं से ग्रस्त और विषयोपभोग को ही परम लक्ष्य मानने वाले वे लोग, यह दृढ़ निश्चय किए रहते हैं कि इतना ही (सत्य) है।","gujarati":"મૃત્યુપર્યંત રહેતી અપરિમિત ચિંતાઓથી ગ્રસ્ત અને વિષયોપભોગને જ પરમ લક્ષ્ય માનનારા એવા તે લોકો એવો દ્રઢ નિશ્ચય કરી લે છે કે આટલું જ સત્ય છે."},"16.12":{"chapter":16,"verse":12,"sloka":"आशापाशशतैर्बद्धाः कामक्रोधपरायणाः।ईहन्ते कामभोगार्थमन्यायेनार्थसञ्चयान्।।16.12।।","transliteration":"āśhā-pāśha-śhatair baddhāḥ kāma-krodha-parāyaṇāḥ\nīhante kāma-bhogārtham anyāyenārtha-sañchayān","english":"Bound by a hundred ties of hope, given over to lust and anger, they strive to obtain hoards of wealth by unlawful means for the sake of sensual enjoyment.","hindi":"सैकड़ों आशापाशों से बंधे हुए, काम और क्रोध के वश में होकर, ये लोग विषय-भोगों को प्राप्त करने के लिए अन्यायपूर्ण तरीके से धन का संचय करने की चेष्टा करते हैं।","gujarati":"સોએક આશાઓના પાશમાં બંધાયેલા, કામ અને ક્રોધને વશ થયેલા આવા લોકો વિષયભોગો પૂરા કરવા માટે અન્યાયી માર્ગે ધનનો સંગ્રહ કરવા પ્રયત્ન કરે છે."},"16.13":{"chapter":16,"verse":13,"sloka":"इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम्।इदमस्तीदमपि मे भविष्यति पुनर्धनम्।।16.13।।","transliteration":"idam adya mayā labdham imaṁ prāpsye manoratham\nidam astīdam api me bhaviṣhyati punar dhanam","english":"\"I have gained this today, and I will fulfill this desire of mine. This is mine, and this wealth will be mine in the future.\"","hindi":"“मैंने आज यह प्राप्त कर लिया है और अब मैं इस मनोरथ को भी पूरा करूँगा। यह मेरा है, और भविष्य में भी यह और अधिक धन मेरा ही होगा।”","gujarati":"\"મેં આજે આ પ્રાપ્ત કર્યું છે અને હવે હું આ મનોરથ પણ પૂરો કરીશ. આ મારું છે, અને ભવિષ્યમાં આટલું ધન પણ મારું જ થશે.\""},"16.14":{"chapter":16,"verse":14,"sloka":"असौ मया हतः शत्रुर्हनिष्ये चापरानपि।ईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान्सुखी।।16.14।।","transliteration":"asau mayā hataḥ śhatrur haniṣhye chāparān api\nīśhvaro ’ham ahaṁ bhogī siddho ’haṁ balavān sukhī","english":"“I have slain this enemy, and others also I shall slay. I am the lord, I am the enjoyer, I am accomplished, powerful and happy.”","hindi":"“मैंने इस शत्रु को मार दिया है और अन्य शत्रुओं को भी मैं मार डालूँगा। मैं ही ईश्वर हूँ, मैं ही भोक्ता हूँ, मैं ही सिद्ध, बलवान और सुखी हूँ।”","gujarati":"“મેં આ શત્રુને મારી નાખ્યો છે અને બીજા શત્રુઓને પણ હું મારી નાખીશ. હું જ ઈશ્વર છું, હું જ ભોક્તા છું, હું જ સિદ્ધ, બળવાન અને સુખી છું.”"},"16.15":{"chapter":16,"verse":15,"sloka":"आढ्योऽभिजनवानस्मि कोऽन्योऽस्ति सदृशो मया।यक्ष्ये दास्यामि मोदिष्य इत्यज्ञानविमोहिताः।।16.15।।","transliteration":"āḍhyo ’bhijanavān asmi ko ’nyo ’sti sadṛiśho mayā\nyakṣhye dāsyāmi modiṣhya ity ajñāna-vimohitāḥ\n aneka-chitta-vibhrāntā moha-jāla-samāvṛitāḥ\nprasaktāḥ kāma-bhogeṣhu patanti narake ’śhuchau","english":"\"I am wealthy and born into a noble family. Who else is like me? I shall perform sacrifices, give charity, and rejoice.\" Thus, they are deluded by ignorance.","hindi":"\"मैं धनवान और उत्तम कुल में उत्पन्न हुआ हूँ। मेरे समान और कौन है? मैं यज्ञ करूँगा, मैं दान दूँगा, मैं हर्ष करूँगा\" - इस प्रकार वे अज्ञान से मोहित रहते हैं।","gujarati":"\"હું ધનવાન અને ઉચ્ચ કુળમાં જન્મેલો છું. મારા જેવું બીજું કોણ છે? હું યજ્ઞ કરીશ, હું દાન આપીશ અને મોજ કરીશ\" - આ રીતે તેઓ અજ્ઞાનથી મોહિત થયેલા હોય છે."},"16.16":{"chapter":16,"verse":16,"sloka":"अनेकचित्तविभ्रान्ता मोहजालसमावृताः।प्रसक्ताः कामभोगेषु पतन्ति नरकेऽशुचौ।।16.16।।","transliteration":"aneka-citta-vibhrāntā    moha-jāla-samāvṛtāḥ prasaktāḥ   kāma-bhogeṣu    patanti narake  'śucau","english":"Bewildered by many fancies, entangled in the snare of delusion, addicted to the gratification of lust, they fall into a foul hell.","hindi":"अनेक प्रकार से भ्रमित चित्त वाले, मोह के जाल में फँसे हुए तथा विषय-भोगों की प्राप्ति में ही आसक्त ये लोग घोर, अपवित्र नरक में गिरते हैं।","gujarati":"અનેક પ્રકારના સંકલ્પોથી ભ્રમિત થયેલા, મોહજાળમાં ફસાયેલા અને વિષયભોગોમાં અત્યંત આસક્ત એવા લોકો ગંદા અને ભયાનક નરકમાં પડે છે."},"16.17":{"chapter":16,"verse":17,"sloka":"आत्मसम्भाविताः स्तब्धा धनमानमदान्विताः।यजन्ते नामयज्ञैस्ते दम्भेनाविधिपूर्वकम्।।16.17।।","transliteration":"ātma-sambhāvitāḥ stabdhā dhana-māna-madānvitāḥ\nyajante nāma-yajñais te dambhenāvidhi-pūrvakam","english":"Self-conceited, stubborn, filled with the pride and intoxication of wealth, they perform sacrifices in name only for the sake of ostentation, contrary to the ordinances of the scriptures.","hindi":"अपने आप को ही श्रेष्ठ मानने वाले, हठी, धन और मान के मद में चूर होकर वे लोग केवल नाममात्र के यज्ञों को दम्भपूर्वक करते हैं, जो शास्त्रविधि के विरुद्ध हैं।","gujarati":"સ્વયંને જ શ્રેષ્ઠ માનનારા, હઠીલા, ધન અને માનના મદથી યુક્ત એવા લોકો, શાસ્ત્રવિધિની વિરુદ્ધ જઈને માત્ર દેખાડા માટે નામમાત્રના યજ્ઞો કરે છે."},"16.18":{"chapter":16,"verse":18,"sloka":"अहङ्कारं बलं दर्पं कामं क्रोधं च संश्रिताः।मामात्मपरदेहेषु प्रद्विषन्तोऽभ्यसूयकाः।।16.18।।","transliteration":"ahankāraṁ balaṁ darpaṁ kāmaṁ krodhaṁ cha sanśhritāḥ\nmām ātma-para-deheṣhu pradviṣhanto ’bhyasūyakāḥ","english":"Given over to egoism, power, haughtiness, lust, and anger, these malicious people hate Me in their own bodies and in the bodies of others.","hindi":"अहंकार, बल, दर्प, काम और क्रोध के वशीभूत हुए ये आसुरी स्वभाव वाले लोग अपने और दूसरों के शरीर में स्थित मुझ (श्री कृष्ण) से द्वेष करने वाले होते हैं।","gujarati":"અહંકાર, બળ, દર્પ, કામ અને ક્રોધના વશમાં થયેલા એવા દુષ્ટ લોકો પોતાના અને બીજાના શરીરમાં રહેલા મુજ (શ્રી કૃષ્ણ) નો દ્વેષ કરે છે."},"16.19":{"chapter":16,"verse":19,"sloka":"तानहं द्विषतः क्रूरान्संसारेषु नराधमान्।क्षिपाम्यजस्रमशुभानासुरीष्वेव योनिषु।।16.19।।","transliteration":"tān ahaṁ dviṣhataḥ krūrān sansāreṣhu narādhamān\nkṣhipāmy ajasram aśhubhān āsurīṣhv eva yoniṣhu","english":"These cruel and hateful ones, the lowest among men, I incessantly cast into the wombs of demons within this world of repeated births and deaths.","hindi":"उन द्वेषी, क्रूर और नराधमों को मैं इस संसार में बारम्बार आसुरी योनियों में ही डालता हूँ।","gujarati":"તે દ્વેષી, ક્રૂર અને મનુષ્યોમાં અધમ એવા પાપીઓને હું આ સંસારમાં વારંવાર આસુરી યોનિઓમાં જ નાખું છું."},"16.20":{"chapter":16,"verse":20,"sloka":"असुरीं योनिमापन्ना मूढा जन्मनि जन्मनि।मामप्राप्यैव कौन्तेय ततो यान्त्यधमां गतिम्।।16.20।।","transliteration":"āsurīṁ yonim āpannā mūḍhā janmani janmani\nmām aprāpyaiva kaunteya tato yānty adhamāṁ gatim","english":"Attaining demoniac births, birth after birth, these deluded ones, not reaching Me, O son of Kunti, sink into still lower states.","hindi":"हे अर्जुन! बार-बार आसुरी योनियों में जन्म लेकर वे मूढ़ पुरुष मुझे प्राप्त न होकर उससे भी अधम गति को ही प्राप्त होते हैं।","gujarati":"હે અર્જુન! જન્મ-જન્માંતરમાં આસુરી યોનિઓને પ્રાપ્ત થતા એ મૂઢ પુરુષો મને પ્રાપ્ત ન કરીને તેનાથી પણ અધમ ગતિને પામે છે."},"16.21":{"chapter":16,"verse":21,"sloka":"त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः।कामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत्।।16.21।।","transliteration":"tri-vidhaṁ narakasyedaṁ dvāraṁ nāśhanam ātmanaḥ\nkāmaḥ krodhas tathā lobhas tasmād etat trayaṁ tyajet","english":"The Supreme Lord Krishna declares: There are three gates to this hell, which destroy the soul: lust, anger, and greed. Therefore, one must abandon these three.","hindi":"भगवान श्रीकृष्ण कहते हैं: काम, क्रोध और लोभ—ये नरक के तीन द्वार हैं, जो आत्मा का नाश करने वाले हैं। इसलिए, मनुष्य को इन तीनों का त्याग कर देना चाहिए।","gujarati":"ભગવાન શ્રીકૃષ્ણ કહે છે: કામ, ક્રોધ અને લોભ—આ ત્રણ નરકના દ્વાર છે, જે આત્માનો નાશ કરનારા છે. તેથી મનુષ્યએ આ ત્રણેયનો ત્યાગ કરવો જોઈએ."},"16.22":{"chapter":16,"verse":22,"sloka":"एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः।आचरत्यात्मनः श्रेयस्ततो याति परां गतिम्।।16.22।।","transliteration":"etair vimuktaḥ kaunteya tamo-dvārais tribhir naraḥ\nācharaty ātmanaḥ śhreyas tato yāti parāṁ gatim","english":"O son of Kunti, one who has escaped these three gates of hell acts for his own spiritual welfare and thus attains the Supreme Destination.","hindi":"हे कौन्तेय! जो मनुष्य नरक के इन तीनों द्वारों से मुक्त हो जाता है, वह अपने कल्याण का आचरण करता है और इस प्रकार परम गति को प्राप्त कर लेता है।","gujarati":"હે કૌન્તેય! જે મનુષ્ય નરકના આ ત્રણ દ્વારોથી મુક્ત થાય છે, તે પોતાના કલ્યાણના માર્ગ પર ચાલે છે અને અંતે પરમ ગતિ પ્રાપ્ત કરે છે."},"16.23":{"chapter":16,"verse":23,"sloka":"यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः।न स सिद्धिमवाप्नोति न सुखं न परां गतिम्।।16.23।।","transliteration":"yaḥ śhāstra-vidhim utsṛijya vartate kāma-kārataḥ\nna sa siddhim avāpnoti na sukhaṁ na parāṁ gatim","english":"He who, having cast aside the ordinances of the scriptures, acts under the impulse of desire, does not attain perfection, nor happiness, nor the Supreme Goal.","hindi":"जो शास्त्रविधि को त्यागकर मनमानी करते हैं और अपनी इच्छाओं के अनुसार चलते हैं, वे न तो जीवन में सिद्धि प्राप्त कर सकते हैं, न ही वास्तविक सुख, और न ही वे मेरी परम गति को प्राप्त होते हैं।","gujarati":"જે પુરુષ શાસ્ત્રવિધિને ત્યાગીને પોતાની કામનાથી પ્રેરાઈને કાર્ય કરે છે, તે ન તો પૂર્ણત્વની સિદ્ધિ પ્રાપ્ત કરે છે, ન સુખ અને ન તો પરમ ગતિને પામે છે."},"16.24":{"chapter":16,"verse":24,"sloka":"तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ।ज्ञात्वा शास्त्रविधानोक्तं कर्म कर्तुमिहार्हसि।।16.24।।","transliteration":"tasmāch chhāstraṁ pramāṇaṁ te kāryākārya-vyavasthitau\njñātvā śhāstra-vidhānoktaṁ karma kartum ihārhasi","english":"Therefore, let the scriptures be your authority in determining what should be done and what should not be done. Understanding the ordinances laid down by the scriptures, you should perform your actions in this world.","hindi":"इसलिए तुम्हारे लिए क्या कर्तव्य है और क्या अकर्तव्य, इसके निर्णय में शास्त्र ही प्रमाण हैं। शास्त्रों में बताए गए विधानों को जानकर, तुम्हें इस संसार में अपने कर्म करने चाहिए।","gujarati":"તેથી તારે શું કરવું અને શું ન કરવું તે નક્કી કરવામાં શાસ્ત્ર જ પ્રમાણ છે. શાસ્ત્રોમાં કહેલા વિધાનને જાણીને તે મુજબ જ તારે આ સંસારમાં કર્મ કરવા જોઈએ."},"17.1":{"chapter":17,"verse":1,"sloka":"अर्जुन उवाचये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयाऽन्विताः।तेषां निष्ठा तु का कृष्ण सत्त्वमाहो रजस्तमः।।17.1।।","transliteration":"arjuna uvācha\nye śhāstra-vidhim utsṛijya yajante śhraddhayānvitāḥ\nteṣhāṁ niṣhṭhā tu kā kṛiṣhṇa sattvam āho rajas tamaḥ","english":"Arjuna said: O Krishna, what is the situation of those who, disregarding the injunctions of the scriptures, perform sacrifice with faith? Is it Sattva, Rajas, or Tamas?","hindi":"अर्जुन ने कहा: हे कृष्ण! जो लोग शास्त्र-विधि को त्यागकर केवल श्रद्धा से युक्त होकर यज्ञ करते हैं, उनकी स्थिति क्या है? क्या वह सात्त्विक है, राजसिक है अथवा तामसिक?","gujarati":"અર્જુને પૂછ્યું: હે કૃષ્ણ! જેઓ શાસ્ત્રના નિયમોનો ત્યાગ કરીને કેવળ શ્રદ્ધાપૂર્વક યજ્ઞ કરે છે, તેમની નિષ્ઠા કેવી હોય છે? શું તે સાત્વિક, રાજસિક કે તામસિક હોય છે?"},"17.2":{"chapter":17,"verse":2,"sloka":"श्री भगवानुवाचत्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा।सात्त्विकी राजसी चैव तामसी चेति तां श्रृणु।।17.2।।","transliteration":"śhrī-bhagavān uvācha\ntri-vidhā bhavati śhraddhā dehināṁ sā svabhāva-jā\nsāttvikī rājasī chaiva tāmasī cheti tāṁ śhṛiṇu","english":"Shri Krishna said: The faith of the embodied souls is of three kinds, according to their nature—sattvic (pure), rajasic (passionate), and tamasic (dark). Hear of this from Me.","hindi":"श्री भगवान् ने कहा: देहधारियों की स्वाभाविक श्रद्धा सात्त्विक, राजसिक और तामसिक—इन तीन भेदों वाली होती है। तुम इसे मुझसे सुनो।","gujarati":"શ્રી ભગવાન બોલ્યા: દેહધારીઓની સ્વભાવજન્ય શ્રદ્ધા સાત્વિક, રાજસી અને તામસી એમ ત્રણ પ્રકારની હોય છે. તે મારા મુખેથી સાંભળ."},"17.3":{"chapter":17,"verse":3,"sloka":"सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत।श्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः।।17.3।।","transliteration":"sattvānurūpā sarvasya śhraddhā bhavati bhārata\nśhraddhā-mayo ‘yaṁ puruṣho yo yach-chhraddhaḥ sa eva saḥ","english":"O Arjuna, the faith of each individual is in accordance with their nature. A person is made of their faith; as their faith is, so they are.","hindi":"हे अर्जुन, प्रत्येक मनुष्य की श्रद्धा उसके अंतःकरण के अनुरूप होती है। पुरुष श्रद्धामय है, अतः जैसी जिसकी श्रद्धा है, वैसा ही वह स्वयं है।","gujarati":"હે અર્જુન, સૌ કોઈની શ્રદ્ધા તેમના સ્વભાવને અનુરૂપ હોય છે. મનુષ્ય શ્રદ્ધામય છે, તેથી જેવી જેની શ્રદ્ધા છે, તેવો જ તે પોતે છે."},"17.4":{"chapter":17,"verse":4,"sloka":"यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः।प्रेतान्भूतगणांश्चान्ये यजन्ते तामसा जनाः।।17.4।।","transliteration":"yajante sāttvikā devān yakṣha-rakṣhānsi rājasāḥ\npretān bhūta-gaṇānśh chānye yajante tāmasā janāḥ","english":"Shri Krishna says: Men of sattva (goodness) worship the devas (demigods); men of rajas (passion) worship the yakshas and rakshasas; and others, who are of tamas (ignorance), worship the pretas (ghosts) and the hosts of spirits.","hindi":"भगवान श्रीकृष्ण कहते हैं: सात्त्विक पुरुष देवताओं को पूजते हैं, राजस लोग यक्ष और राक्षसों को पूजते हैं, तथा दूसरे जो तामसी जन हैं, वे प्रेत और भूतगणों की पूजा करते हैं।","gujarati":"ભગવાન શ્રીકૃષ્ણ કહે છે: સાત્વિક પુરુષો દેવતાઓને પૂજે છે, રાજસી લોકો યક્ષો અને રાક્ષસોને પૂજે છે, અને બીજા જે તામસી લોકો છે, તેઓ પ્રેત અને ભૂતગણોની પૂજા કરે છે."},"17.5":{"chapter":17,"verse":5,"sloka":"अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः।दम्भाहङ्कारसंयुक्ताः कामरागबलान्विताः।।17.5।।","transliteration":"aśhāstra-vihitaṁ ghoraṁ tapyante ye tapo janāḥ\ndambhāhankāra-sanyuktāḥ kāma-rāga-balānvitāḥ","english":"Those who perform severe austerities not ordained by the scriptures, being deluded by hypocrisy and egoism, and impelled by the force of desire and attachment.","hindi":"जो मनुष्य शास्त्रविधि से रहित, घोर तप का आचरण करते हैं, वे दम्भ और अहंकार से युक्त तथा काम और आसक्ति के बल से प्रेरित होते हैं।","gujarati":"જે લોકો શાસ્ત્રવિધિથી રહિત ઘોર તપ કરે છે અને જેઓ દંભ, અહંકાર, કામ અને આસક્તિના વેગથી યુક્ત છે."},"17.6":{"chapter":17,"verse":6,"sloka":"कर्षयन्तः शरीरस्थं भूतग्राममचेतसः।मां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान्।।17.6।।","transliteration":"karṣhayantaḥ śharīra-sthaṁ bhūta-grāmam achetasaḥ\nmāṁ chaivāntaḥ śharīra-sthaṁ tān viddhy āsura-niśhchayān","english":"Know those individuals to be of demoniac resolves who senselessly torture the elements comprising the body, as well as Me, Shri Krishna, who dwell within that same body.","hindi":"जो लोग शरीर रूप से स्थित भूत-समुदाय को और शरीर के भीतर स्थित मुझ श्री कृष्ण को भी व्यर्थ में कष्ट पहुँचाते हैं, तुम उन मूर्ख व्यक्तियों को आसुरी स्वभाव का ही समझो।","gujarati":"જેઓ શરીરના ઘટકોને અને શરીરની અંદર વસતા મારા, શ્રી કૃષ્ણના સ્વરૂપને અતાર્કિક રીતે પીડા આપે છે, તેવા દુષ્ટ નિશ્ચયવાળા લોકોને તું આસુરી વૃત્તિના જાણજે."},"17.7":{"chapter":17,"verse":7,"sloka":"आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः।यज्ञस्तपस्तथा दानं तेषां भेदमिमं श्रृणु।।17.7।।","transliteration":"āhāras tv api sarvasya tri-vidho bhavati priyaḥ\nyajñas tapas tathā dānaṁ teṣhāṁ bhedam imaṁ śhṛiṇu","english":"The food that is dear to each is threefold, as well as sacrifice, austerity, and charity. Hear now the distinctions of these from Me.","hindi":"सब प्राणियों का भोजन भी अपनी-अपनी प्रकृति के अनुसार तीन प्रकार का प्रिय होता है; वैसे ही यज्ञ, तप और दान भी तीन प्रकार के होते हैं। उनके इन भेदों को तुम मुझसे सुनो।","gujarati":"દરેક પ્રાણીઓનો પ્રિય ખોરાક પણ ત્રણ પ્રકારનો હોય છે; તેમ જ યજ્ઞ, તપ અને દાન પણ ત્રણ પ્રકારના હોય છે. હવે તું તેમની આ ભિન્નતા મારા મુખેથી સાંભળ."},"17.8":{"chapter":17,"verse":8,"sloka":"आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः।रस्याः स्निग्धाः स्थिरा हृद्या आहाराः सात्त्विकप्रियाः।।17.8।।","transliteration":"āyuḥ-sattva-balārogya-sukha-prīti-vivardhanāḥ\nrasyāḥ snigdhāḥ sthirā hṛidyā āhārāḥ sāttvika-priyāḥ","english":"Foods that promote longevity, purity, strength, health, happiness, and satisfaction—foods that are succulent, unctuous, sustaining, and agreeable—are dear to those in the mode of goodness.","hindi":"आयु, सत्त्व (शुद्धि), बल, आरोग्य, सुख और प्रीति को प्रवृद्ध करने वाले, तथा रसयुक्त, स्निग्ध, स्थिर और मन को प्रसन्न करने वाले भोजन सात्त्विक मनुष्यों को प्रिय होते हैं।","gujarati":"આયુષ્ય, સત્વ (શુદ્ધિ), બળ, આરોગ્ય, સુખ અને પ્રીતિને વધારનારા, તેમજ રસયુક્ત, સ્નિગ્ધ, સ્થિર અને મનને પ્રસન્ન કરનારા આહાર સાત્વિક પુરુષોને પ્રિય હોય છે."},"17.9":{"chapter":17,"verse":9,"sloka":"कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः।आहारा राजसस्येष्टा दुःखशोकामयप्रदाः।।17.9।।","transliteration":"kaṭv-amla-lavaṇāty-uṣhṇa- tīkṣhṇa-rūkṣha-vidāhinaḥ\nāhārā rājasasyeṣhṭā duḥkha-śhokāmaya-pradāḥ","english":"Foods that are bitter, sour, salty, overly hot, pungent, dry, and burning are dear to those in the mode of passion (Rajas); such foods cause pain, grief, and disease.","hindi":"कड़वे, खट्टे, नमकीन, बहुत गर्म, तीखे, रूखे और दाह उत्पन्न करने वाले भोजन राजस व्यक्ति को प्रिय होते हैं, और ये भोजन दुःख, शोक तथा रोग को जन्म देने वाले हैं।","gujarati":"કડવા, ખાટા, ખારા, અતિશય ગરમ, તીખા, સૂકા અને દાહ ઉત્પન્ન કરનારા ભોજન રાજસી પુરુષોને પ્રિય હોય છે, અને આવા ખોરાક દુઃખ, શોક તથા રોગ ઉત્પન્ન કરનારા છે."},"17.10":{"chapter":17,"verse":10,"sloka":"यातयामं गतरसं पूति पर्युषितं च यत्।उच्छिष्टमपि चामेध्यं भोजनं तामसप्रियम्।।17.10।।","transliteration":"yāta-yāmaṁ gata-rasaṁ pūti paryuṣhitaṁ cha yat\nuchchhiṣhṭam api chāmedhyaṁ bhojanaṁ tāmasa-priyam","english":"Food that is stale, tasteless, putrid, rotten, refuse, and impure is dear to those who are in the mode of ignorance (Tamas).","hindi":"जो भोजन अधपका, रसरहित, दुर्गन्धयुक्त, बासी, उच्छिष्ट और अपवित्र है, वह तामसिक मनुष्यों को प्रिय होता है।","gujarati":"જે ખોરાક રાંધ્યા વગરનો, સ્વાદહીન, દુર્ગંધયુક્ત, વાસી, એઠો અને અપવિત્ર છે, તે તામસિક મનુષ્યોને પ્રિય હોય છે."},"17.11":{"chapter":17,"verse":11,"sloka":"अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते।यष्टव्यमेवेति मनः समाधाय स सात्त्विकः।।17.11।।","transliteration":"aphalākāṅkṣhibhir yajño vidhi-driṣhṭo ya ijyate\nyaṣhṭavyam eveti manaḥ samādhāya sa sāttvikaḥ","english":"That sacrifice which is performed by those who seek no reward, in accordance with scriptural injunctions, and with a firm conviction of the mind that it is a duty to be performed, is known as Sattvic.","hindi":"जो यज्ञ शास्त्रविधि के अनुसार नियत है, जिसे फल की इच्छा न रखने वाले पुरुषों द्वारा 'यह कर्तव्य है' ऐसा मन में निश्चय करके किया जाता है, वह यज्ञ सात्त्विक कहलाता है।","gujarati":"જે યજ્ઞ શાસ્ત્રવિધિ મુજબ નિયત છે અને જેને ફળની આકાંક્ષા વિનાના પુરુષો દ્વારા 'આ મારું કર્તવ્ય છે' એવો મનથી નિશ્ચય કરીને કરવામાં આવે છે, તે યજ્ઞ સાત્વિક છે."},"17.12":{"chapter":17,"verse":12,"sloka":"अभिसंधाय तु फलं दम्भार्थमपि चैव यत्।इज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम्।।17.12।।","transliteration":"abhisandhāya tu phalaṁ dambhārtham api chaiva yat\nijyate bharata-śhreṣhṭha taṁ yajñaṁ viddhi rājasam","english":"O Arjuna, know that the sacrifice which is performed for the sake of reward and with ostentation, is declared to be Rajasic.","hindi":"हे अर्जुन! जो यज्ञ फल की इच्छा से और केवल दिखावे के लिए किया जाता है, उसे तुम राजस यज्ञ जानो।","gujarati":"હે અર્જુન! જે યજ્ઞ ફળની ઈચ્છા રાખીને તથા દંભ માટે કરવામાં આવે છે, તે યજ્ઞને તું રાજસ જાણ."},"17.13":{"chapter":17,"verse":13,"sloka":"विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम्।श्रद्धाविरहितं यज्ञं तामसं परिचक्षते।।17.13।।","transliteration":"vidhi-hīnam asṛiṣhṭānnaṁ mantra-hīnam adakṣhiṇam\nśhraddhā-virahitaṁ yajñaṁ tāmasaṁ parichakṣhate","english":"Shri Krishna declares that sacrifice performed without adherence to scriptural ordinances, in which no food is distributed, and which is devoid of mantras, sacrificial gifts, and faith, is known as Tamasic.","hindi":"शास्त्रविधि से रहित, अन्नदान से रहित, बिना मन्त्रों, बिना दक्षिणा और बिना श्रद्धा के किये हुए यज्ञ को तामस यज्ञ कहते हैं।","gujarati":"શાસ્ત્રવિધિથી રહિત, અન્નદાનથી રહિત, મંત્રો વિના, દક્ષિણા વિના અને શ્રદ્ધા વિના કરવામાં આવેલા યજ્ઞને તામસ યજ્ઞ કહેવામાં આવે છે."},"17.14":{"chapter":17,"verse":14,"sloka":"देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम्।ब्रह्मचर्यमहिंसा च शारीरं तप उच्यते।।17.14।।","transliteration":"deva-dwija-guru-prājña- pūjanaṁ śhaucham ārjavam\nbrahmacharyam ahinsā cha śhārīraṁ tapa uchyate","english":"Worship of the gods, the twice-born, the teachers, and the wise; purity, straightforwardness, celibacy, and non-injury are all called the austerities of the body.","hindi":"देवता, द्विज, गुरु और ज्ञानी जनों का पूजन, पवित्रता, सरलता, ब्रह्मचर्य और अहिंसा - यह शारीरिक तप कहा जाता है।","gujarati":"દેવતા, બ્રાહ્મણ, ગુરુ અને જ્ઞાનીજનોનું પૂજન, પવિત્રતા, સરળતા, બ્રહ્મચર્ય અને અહિંસા - આ શરીર સંબંધી તપ કહેવાય છે."},"17.15":{"chapter":17,"verse":15,"sloka":"अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत्।स्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते।।17.15।।","transliteration":"anudvega-karaṁ vākyaṁ satyaṁ priya-hitaṁ cha yat\nsvādhyāyābhyasanaṁ chaiva vāṅ-mayaṁ tapa uchyate","english":"Speech that causes no agitation, is truthful, pleasant, and beneficial, and the regular recitation of the Vedas, is known as the austerity of speech.","hindi":"जो वाणी उद्वेग उत्पन्न करने वाली नहीं है, जो सत्य, प्रिय और हितकारक है तथा जो वेदों के स्वाध्याय का अभ्यास है—इसे ही वाणी का तप कहा गया है।","gujarati":"જે વાણી ઉદ્વેગ પેદા કરતી નથી, જે સત્ય, પ્રિય અને હિતકારક છે, અને વેદોનો સ્વાધ્યાય – આને વાણીનું તપ કહેવામાં આવે છે."},"17.16":{"chapter":17,"verse":16,"sloka":"मनःप्रसादः सौम्यत्वं मौनमात्मविनिग्रहः।भावसंशुद्धिरित्येतत्तपो मानसमुच्यते।।17.16।।","transliteration":"manaḥ-prasādaḥ saumyatvaṁ maunam ātma-vinigrahaḥ\nbhāva-sanśhuddhir ity etat tapo mānasam uchyate","english":"Serenity of mind, gentleness, silence, self-restraint, and purity of heart—this is declared to be the austerity of the mind.","hindi":"मन की प्रसन्नता, सौम्यभाव, भगवद्-चिन्तन (मौन), आत्मसंयम और अंतःकरण की शुद्धि—यह मानस तप कहा गया है।","gujarati":"મનની પ્રસન્નતા, સૌમ્યતા, મૌન, આત્મસંયમ અને અંતઃકરણની શુદ્ધિ—આને માનસિક તપ કહેવામાં આવે છે."},"17.17":{"chapter":17,"verse":17,"sloka":"श्रद्धया परया तप्तं तपस्तत्ित्रविधं नरैः।अफलाकाङ्क्षिभिर्युक्तैः सात्त्विकं परिचक्षते।।17.17।।","transliteration":"śhraddhayā parayā taptaṁ tapas tat tri-vidhaṁ naraiḥ\naphalākāṅkṣhibhir yuktaiḥ sāttvikaṁ parichakṣhate","english":"This threefold austerity, performed with utmost faith by men who are steadfast, without desire for any fruit, is declared to be Sattvic.","hindi":"फल की आकांक्षा न रखने वाले युक्त पुरुषों के द्वारा परम श्रद्धा से किये गये उस पूर्वोक्त त्रिविध तप को सात्त्विक कहते हैं।","gujarati":"ફળની આકાંક્ષા ન રાખનારા, યોગયુક્ત પુરુષો દ્વારા અત્યંત શ્રદ્ધાથી કરવામાં આવેલા તે પૂર્વોક્ત ત્રિવિધ તપને સાત્ત્વિક કહેવામાં આવે છે."},"17.18":{"chapter":17,"verse":18,"sloka":"सत्कारमानपूजार्थं तपो दम्भेन चैव यत्।क्रियते तदिह प्रोक्तं राजसं चलमध्रुवम्।।17.18।।","transliteration":"satkāra-māna-pūjārthaṁ tapo dambhena chaiva yat\nkriyate tad iha proktaṁ rājasaṁ chalam adhruvam","english":"Austerity that is performed to gain respect, honor, and adoration, and also out of hypocrisy, is declared to be Rajasic; it is unstable and transient.","hindi":"जो तप सत्कार, मान और पूजा के लिए अथवा केवल दम्भ (पाखण्ड) से ही किया जाता है, वह अनिश्चित और क्षणिक तप यहाँ राजस कहा गया है।","gujarati":"જે તપ સત્કાર, માન અને પૂજા પ્રાપ્ત કરવા માટે અથવા તો દંભથી કરવામાં આવે છે, તે રાજસિક તપ કહેવાય છે; તે અસ્થિર અને ક્ષણિક છે."},"17.19":{"chapter":17,"verse":19,"sloka":"मूढग्राहेणात्मनो यत्पीडया क्रियते तपः।परस्योत्सादनार्थं वा तत्तामसमुदाहृतम्।।17.19।।","transliteration":"mūḍha-grāheṇātmano yat pīḍayā kriyate tapaḥ\nparasyotsādanārthaṁ vā tat tāmasam udāhṛitam","english":"That austerity which is performed out of a foolish notion, with self-torture, or for the purpose of destroying another, is declared to be of the Tamasic nature.","hindi":"जो तप मूढ़तापूर्वक स्वयं को पीड़ित करते हुए अथवा अन्य लोगों के नाश के लिए किया जाता है, वह तप तामस कहा गया है।","gujarati":"જે તપ મૂઢતાપૂર્વક, પોતાના શરીરને પીડા આપીને અથવા અન્ય લોકોના વિનાશ માટે કરવામાં આવે છે, તે તપ તામસ કહેવાય છે."},"17.20":{"chapter":17,"verse":20,"sloka":"दातव्यमिति यद्दानं दीयतेऽनुपकारिणे।देशे काले च पात्रे च तद्दानं सात्त्विकं स्मृतम्।।17.20।।","transliteration":"dātavyam iti yad dānaṁ dīyate ‘nupakāriṇe\ndeśhe kāle cha pātre cha tad dānaṁ sāttvikaṁ smṛitam","english":"Charity given as a duty, to a worthy person, at a proper time and place, and to one who cannot return the favor, is considered Sattvic.","hindi":"जो दान देना कर्तव्य है—ऐसी भावना से, देश-काल और पात्र को देखकर, बिना किसी बदले की अपेक्षा के दिया जाता है, वह दान सात्त्विक कहा गया है।","gujarati":"દાન આપવું એ જ કર્તવ્ય છે - એવી ભાવનાથી જે દાન યોગ્ય દેશ, કાળ અને પાત્રને જોઈને, બદલામાં કંઈ પણ અપેક્ષા રાખ્યા વિના આપવામાં આવે છે, તે દાન સાત્ત્વિક માનવામાં આવે છે."},"17.21":{"chapter":17,"verse":21,"sloka":"यत्तु प्रत्युपकारार्थं फलमुद्दिश्य वा पुनः।दीयते च परिक्लिष्टं तद्दानं राजसं स्मृतम्।।17.21।।","transliteration":"yat tu pratyupakārārthaṁ phalam uddiśhya vā punaḥ\ndīyate cha parikliṣhṭaṁ tad dānaṁ rājasaṁ smṛitam","english":"But the gift that is given with the expectation of a return, or with a desire for a reward, or given begrudgingly, is declared to be of the nature of passion (Rajasic).","hindi":"जो दान प्रत्युपकार की भावना से, फल की इच्छा रखकर या क्लेशपूर्वक दिया जाता है, उसे राजस दान कहा गया है।","gujarati":"પરંતુ જે દાન બદલાની અપેક્ષા રાખીને, ફળની ઈચ્છાથી અથવા ક્લેશપૂર્વક આપવામાં આવે છે, તે દાન રાજસી ગણાય છે."},"17.22":{"chapter":17,"verse":22,"sloka":"अदेशकाले यद्दानमपात्रेभ्यश्च दीयते।असत्कृतमवज्ञातं तत्तामसमुदाहृतम्।।17.22।।","transliteration":"adeśha-kāle yad dānam apātrebhyaśh cha dīyate\nasat-kṛitam avajñātaṁ tat tāmasam udāhṛitam","english":"The gift that is given in the wrong place and at the wrong time, to unworthy persons, without respect or with insult, is declared to be of a Tamasic nature.","hindi":"जो दान बिना सत्कार के, तिरस्कारपूर्वक, अयोग्य स्थान और समय पर, तथा अयोग्य पात्रों को दिया जाता है, वह दान तामस कहा गया है।","gujarati":"જે દાન સત્કાર વિના અથવા તિરસ્કારપૂર્વક, અયોગ્ય સ્થળ-કાળમાં અને અપાત્ર વ્યક્તિઓને આપવામાં આવે છે, તે દાન તામસ ગણાય છે."},"17.23":{"chapter":17,"verse":23,"sloka":"तत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः।ब्राह्मणास्तेन वेदाश्च यज्ञाश्च विहिताः पुरा।।17.23।।","transliteration":"oṁ tat sad iti nirdeśho brahmaṇas tri-vidhaḥ smṛitaḥ\nbrāhmaṇās tena vedāśh cha yajñāśh cha vihitāḥ purā","english":"“Om Tat Sat”: this is declared to be the threefold designation of the Supreme Absolute, Brahman. By this, the brahmanas, the Vedas, and the sacrifices were ordained in the beginning of creation.","hindi":"'ॐ तत् सत्' - ऐसा यह ब्रह्म का त्रिविध निर्देश कहा गया है; उसी से आदिकाल में ब्राह्मण, वेद और यज्ञों की रचना हुई थी।","gujarati":"'ઓમ્ તત્ સત્' - આ પરબ્રહ્મનો ત્રિવિધ નિર્દેશ કહેવાયો છે. તેના દ્વારા જ આદિકાળમાં બ્રાહ્મણો, વેદો અને યજ્ઞોનું સર્જન થયું હતું."},"17.24":{"chapter":17,"verse":24,"sloka":"तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः।प्रवर्तन्ते विधानोक्ताः सततं ब्रह्मवादिनाम्।।17.24।।","transliteration":"tasmād oṁ ity udāhṛitya yajña-dāna-tapaḥ-kriyāḥ\npravartante vidhānoktāḥ satataṁ brahma-vādinām","english":"Therefore, with the utterance of 'Om,' the acts of sacrifice, charity, and austerity, as enjoined in the scriptures, are always begun by the students of the Brahman.","hindi":"इसलिए, शास्त्रोक्त यज्ञ, दान और तप की क्रियाएं ब्रह्म के उपासकों द्वारा सदैव ओंकार का उच्चारण करके ही आरम्भ की जाती हैं।","gujarati":"તેથી, શાસ્ત્રોક્ત યજ્ઞ, દાન અને તપની ક્રિયાઓ બ્રહ્મવેત્તાઓ દ્વારા હંમેશા ૐકારના ઉચ્ચારણ સાથે જ શરૂ કરવામાં આવે છે."},"17.25":{"chapter":17,"verse":25,"sloka":"तदित्यनभिसन्धाय फलं यज्ञतपःक्रियाः।दानक्रियाश्च विविधाः क्रियन्ते मोक्षकाङ्क्षि।।17.25।।","transliteration":"tad ity anabhisandhāya phalaṁ yajña-tapaḥ-kriyāḥ\ndāna-kriyāśh cha vividhāḥ kriyante mokṣha-kāṅkṣhibhiḥ","english":"Uttering the word 'Tat,' without desire for fruits, the various acts of sacrifice, austerity, and charity are performed by those seeking liberation.","hindi":"मुमुक्षुजन 'तत्' शब्द का उच्चारण करके फल की कामना से रहित होकर यज्ञ, तप और दान आदि विविध कर्मों का अनुष्ठान करते हैं।","gujarati":"મોક્ષની ઈચ્છા રાખનારાઓ 'તત્' શબ્દનો ઉચ્ચાર કરીને, ફળની આશા વગર વિવિધ પ્રકારના યજ્ઞ, તપ અને દાનરૂપી કર્મ કરે છે."},"17.26":{"chapter":17,"verse":26,"sloka":"सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते।प्रशस्ते कर्मणि तथा सच्छब्दः पार्थ युज्यते।।17.26।।","transliteration":"sad-bhāve sādhu-bhāve cha sad ity etat prayujyate\npraśhaste karmaṇi tathā sach-chhabdaḥ pārtha yujyate","english":"The word 'Sat' is used in the sense of reality and of goodness; and so also, O Arjuna, the word 'Sat' is used for an auspicious act.","hindi":"सद्भाव में और साधुभाव में 'सत्' शब्द का प्रयोग किया जाता है, तथा हे अर्जुन! प्रशस्त कर्म में भी 'सत्' शब्द का प्रयोग किया जाता है।","gujarati":"સદ્ભાવ અને સાધુભાવમાં 'સત્' શબ્દનો પ્રયોગ કરવામાં આવે છે, તથા હે અર્જુન! શ્રેષ્ઠ કે શુભ કર્મમાં પણ 'સત્' શબ્દનો પ્રયોગ થાય છે."},"17.27":{"chapter":17,"verse":27,"sloka":"यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते।कर्म चैव तदर्थीयं सदित्येवाभिधीयते।।17.27।।","transliteration":"yajñe tapasi dāne cha sthitiḥ sad iti chochyate\nkarma chaiva tad-arthīyaṁ sad ity evābhidhīyate","english":"Steadfastness in sacrifice, austerity, and charity is also called 'Sat', and likewise, any action performed for the sake of the Supreme is termed 'Sat'.","hindi":"यज्ञ, तप और दान में जो स्थिति है, उसे 'सत्' कहा जाता है, और उनके निमित्त किया गया कर्म भी 'सत्' ही कहलाता है।","gujarati":"યજ્ઞ, તપ અને દાનમાં જે સ્થિરતા છે તેને 'સત્' કહેવામાં આવે છે, અને તે (પરમાત્મા) ના નિમિત્તે કરવામાં આવેલું કર્મ પણ 'સત્' જ કહેવાય છે."},"17.28":{"chapter":17,"verse":28,"sloka":"अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत्।असदित्युच्यते पार्थ न च तत्प्रेत्य नो इह।।17.28।।","transliteration":"aśhraddhayā hutaṁ dattaṁ tapas taptaṁ kṛitaṁ cha yat\nasad ity uchyate pārtha na cha tat pretya no iha","english":"Whatever sacrifice, charity, or austerity is performed without faith, O son of Pritha, is declared to be 'Asat' (non-existent or false); it is of no use here in this life nor after death, O Arjuna.","hindi":"हे पार्थ! बिना श्रद्धा के किया गया यज्ञ, दान, तप और अन्य जो भी शुभ कर्म है, उसे 'असत्' कहा जाता है; वह न तो इस लोक में और न ही परलोक में फलदायक होता है।","gujarati":"હે અર્જુન! શ્રદ્ધા વિના જે કંઈ પણ યજ્ઞ, દાન, તપ કે બીજું કોઈ કર્મ કરવામાં આવે છે, તેને 'અસત્' કહેવામાં આવે છે; તે ન તો આ લોકમાં અને ન તો મરણ પછીના લોકમાં ફળદાયી થાય છે."},"18.1":{"chapter":18,"verse":1,"sloka":"अर्जुन उवाच\n\nसंन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम्।\n\nत्यागस्य च हृषीकेश पृथक्केशिनिषूदन।।18.1।।","transliteration":"arjuna uvācha\nsannyāsasya mahā-bāho tattvam ichchhāmi veditum\ntyāgasya cha hṛiṣhīkeśha pṛithak keśhi-niṣhūdana","english":"Arjuna said: O mighty-armed Hrishikesa, O slayer of Kesi, I wish to understand the true nature of renunciation (sannyasa) and of abandonment (tyaga) distinctly.","hindi":"अर्जुन ने कहा: हे महाबाहो! हे हृषीकेश! हे केशनिषूदन! मैं संन्यास और त्याग के तत्त्व को पृथक्-पृथक् यथार्थ रूप से जानना चाहता हूँ।","gujarati":"અર્જુને કહ્યું: હે મહાબાહો! હે હૃષીકેશ! હે કેશનિષૂદન! હું સંન્યાસ અને ત્યાગના તત્ત્વને અલગ-અલગ જાણવાની ઈચ્છા રાખું છું."},"18.2":{"chapter":18,"verse":2,"sloka":"श्री भगवानुवाच\n\nकाम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः।\n\nसर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः।।18.2।।","transliteration":"śhrī-bhagavān uvācha\nkāmyānāṁ karmaṇāṁ nyāsaṁ sannyāsaṁ kavayo viduḥ\nsarva-karma-phala-tyāgaṁ prāhus tyāgaṁ vichakṣhaṇāḥ","english":"Shri Krishna, the Supreme Personality of Godhead, said: The learned know that the renunciation of desire-prompted actions is called sannyasa; whereas the wise declare that the abandonment of the fruits of all actions is known as tyaga.","hindi":"श्री भगवान ने कहा: कुछ ज्ञानी पुरुष काम्य कर्मों के त्याग को 'संन्यास' कहते हैं और विद्वान पुरुष सब कर्मों के फल के त्याग को 'त्याग' कहते हैं।","gujarati":"શ્રી ભગવાન બોલ્યા: કેટલાંક જ્ઞાની પુરુષો કામ્ય કર્મોના ત્યાગને 'સંન્યાસ' કહે છે અને વિચક્ષણ પુરુષો સર્વ કર્મોના ફળના ત્યાગને 'ત્યાગ' કહે છે."},"18.3":{"chapter":18,"verse":3,"sloka":"त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः।\n\nयज्ञदानतपःकर्म न त्याज्यमिति चापरे।।18.3।।","transliteration":"tyājyaṁ doṣha-vad ity eke karma prāhur manīṣhiṇaḥ\nyajña-dāna-tapaḥ-karma na tyājyam iti chāpare","english":"Some philosophers declare that action is to be abandoned as an evil, while others maintain that the acts of sacrifice, charity, and penance should never be relinquished.","hindi":"कुछ विद्वान कहते हैं कि समस्त कर्म दोषयुक्त होने के कारण त्याग देने योग्य हैं, जबकि अन्य मनीषी कहते हैं कि यज्ञ, दान और तप रूपी कर्मों का त्याग कभी नहीं करना चाहिए।","gujarati":"કેટલાક જ્ઞાનીઓ કહે છે કે કર્મ દોષયુક્ત હોવાથી તે ત્યાજ્ય છે, જ્યારે અન્ય જ્ઞાનીઓ કહે છે કે યજ્ઞ, દાન અને તપરૂપી કર્મનો ક્યારેય ત્યાગ કરવો જોઈએ નહીં."},"18.4":{"chapter":18,"verse":4,"sloka":"निश्चयं श्रृणु मे तत्र त्यागे भरतसत्तम।त्यागो हि पुरुषव्याघ्र त्रिविधः संप्रकीर्तितः।।18.4।।","transliteration":"niśhchayaṁ śhṛiṇu me tatra tyāge bharata-sattama\ntyāgo hi puruṣha-vyāghra tri-vidhaḥ samprakīrtitaḥ","english":"Hear from Me the final conclusion regarding this renunciation, O best of the Bharatas; renunciation, O best of men, has been declared to be of three kinds.","hindi":"हे भरतश्रेष्ठ अर्जुन! इस त्याग के विषय में मेरे निश्चित मत को सुनो। हे पुरुषश्रेष्ठ! त्याग तीन प्रकार का कहा गया है।","gujarati":"હે ભરતશ્રેષ્ઠ! આ ત્યાગ વિષે મારા નિશ્ચિત મતને સાંભળ. હે પુરુષશ્રેષ્ઠ! ત્યાગ ત્રણ પ્રકારનો કહેવામાં આવ્યો છે."},"18.5":{"chapter":18,"verse":5,"sloka":"यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत्।यज्ञो दानं तपश्चैव पावनानि मनीषिणाम्।।18.5।।","transliteration":"yajña-dāna-tapaḥ-karma na tyājyaṁ kāryam eva tat\nyajño dānaṁ tapaśh chaiva pāvanāni manīṣhiṇām","english":"Acts of sacrifice, charity, and austerity should not be abandoned, but must be performed; for sacrifice, charity, and austerity are indeed the purifiers of the wise.","hindi":"यज्ञ, दान और तपरूप कर्म त्यागने योग्य नहीं हैं, बल्कि उन्हें अवश्य करना चाहिए; क्योंकि यज्ञ, दान और तप तो मनीषियों को पवित्र करने वाले हैं।","gujarati":"યજ્ઞ, દાન અને તપરૂપ કર્મ ત્યાગવા યોગ્ય નથી, પરંતુ તે અવશ્ય કરવા જોઈએ; કારણ કે યજ્ઞ, દાન અને તપ એ જ્ઞાનીઓને પવિત્ર કરનારા છે."},"18.6":{"chapter":18,"verse":6,"sloka":"एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च।कर्तव्यानीति मे पार्थ निश्िचतं मतमुत्तमम्।।18.6।।","transliteration":"etāny api tu karmāṇi saṅgaṁ tyaktvā phalāni cha\nkartavyānīti me pārtha niśhchitaṁ matam uttamam","english":"O Arjuna, even these actions must be performed, relinquishing all attachment and the desire for fruits; this is My definitive and supreme conviction, declares Lord Krishna.","hindi":"हे अर्जुन ! इन कर्मों को भी आसक्ति और फल की इच्छा का त्याग करके ही करना चाहिए, यह मेरा निश्चित और उत्तम मत है, ऐसा योगेश्वर श्रीकृष्ण का उपदेश है।","gujarati":"હે અર્જુન! આ કર્મોને પણ આસક્તિ અને ફળની ઈચ્છાનો ત્યાગ કરીને જ કરવા જોઈએ, આ મારો નિશ્ચિત અને ઉત્તમ મત છે, એમ ભગવાન શ્રીકૃષ્ણ જણાવે છે."},"18.7":{"chapter":18,"verse":7,"sloka":"नियतस्य तु संन्यासः कर्मणो नोपपद्यते।मोहात्तस्य परित्यागस्तामसः परिकीर्तितः।।18.7।।","transliteration":"niyatasya tu sannyāsaḥ karmaṇo nopapadyate\nmohāt tasya parityāgas tāmasaḥ parikīrtitaḥ","english":"Verily, the renunciation of prescribed duties is not proper. The abandonment of such duties out of delusion is declared to be Tamasic (of the nature of ignorance).","hindi":"नियत कर्म का त्याग करना उचित नहीं है। मोहवश उस कर्तव्य का परित्याग कर देना 'तामस' त्याग कहा गया है।","gujarati":"નિયત કર્મનો ત્યાગ કરવો ઉચિત નથી; મોહવશ થઈને કર્તવ્યનો ત્યાગ કરવો તે 'તામસ' ત્યાગ કહેવાય છે."},"18.8":{"chapter":18,"verse":8,"sloka":"दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत्।स कृत्वा राजसं त्यागं नैव त्यागफलं लभेत्।।18.8।।","transliteration":"duḥkham ity eva yat karma kāya-kleśha-bhayāt tyajet\nsa kṛitvā rājasaṁ tyāgaṁ naiva tyāga-phalaṁ labhet","english":"He who abandons prescribed duties because they are troublesome or out of fear of bodily discomfort, performs Rajasic renunciation and does not attain the fruit of true renunciation.","hindi":"जो मनुष्य, कर्म को कष्टकारक समझकर शारीरिक क्लेश के भय से छोड़ देता है, वह राजसिक त्याग करके कभी भी त्याग के फल को प्राप्त नहीं करता।","gujarati":"જે મનુષ્ય કર્મ દુઃખદાયક છે એમ સમજીને શારીરિક કષ્ટના ભયથી તેનો ત્યાગ કરે છે, તે રાજસિક ત્યાગ કરીને ક્યારેય ત્યાગના ફળને પ્રાપ્ત કરતો નથી."},"18.9":{"chapter":18,"verse":9,"sloka":"कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन।सङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः।।18.9।।","transliteration":"kāryam ity eva yat karma niyataṁ kriyate ‘rjuna\nsaṅgaṁ tyaktvā phalaṁ chaiva sa tyāgaḥ sāttviko mataḥ","english":"O Arjuna, when an obligatory duty is performed merely because it is one's duty, renouncing all attachment and the desire for reward, that renunciation is considered to be in the mode of goodness (sattvic).","hindi":"हे अर्जुन! जो नियत कर्म केवल 'कर्तव्य है' ऐसा मानकर आसक्ति और फल की इच्छा का त्याग करके किया जाता है, उस त्याग को सात्त्विक माना गया है।","gujarati":"હે અર્જુન! જે નિયત કર્મ કેવળ 'કર્તવ્ય છે' એમ સમજીને, આસક્તિ અને ફળની ઈચ્છાનો ત્યાગ કરીને કરવામાં આવે છે, તેવા ત્યાગને સાત્ત્વિક માનવામાં આવ્યો છે."},"18.10":{"chapter":18,"verse":10,"sloka":"न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते।त्यागी सत्त्वसमाविष्टो मेधावी छिन्नसंशयः।।18.10।।","transliteration":"na dveṣhṭy akuśhalaṁ karma kuśhale nānuṣhajjate\ntyāgī sattva-samāviṣhṭo medhāvī chhinna-sanśhayaḥ","english":"The person who is endowed with the quality of goodness (sattva), who is intelligent, and whose doubts have been severed, does not hate an unpleasant duty nor is he attached to a pleasant one.","hindi":"जो पुरुष सत्त्वगुण से सम्पन्न है, जिसकी बुद्धि संशयरहित हो गई है और जो मेधावी है, वह न तो अप्रिय कर्म से द्वेष करता है और न ही प्रिय कर्म में आसक्त होता है।","gujarati":"જે પુરુષ સત્વગુણથી સંપન્ન છે, જેની બુદ્ધિ સંશયથી મુક્ત છે અને જે જ્ઞાની છે, તે અપ્રિય કર્મથી દ્વેષ કરતો નથી અને પ્રિય કર્મમાં આસક્ત થતો નથી."},"18.11":{"chapter":18,"verse":11,"sloka":"न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः।यस्तु कर्मफलत्यागी स त्यागीत्यभिधीयते।।18.11।।","transliteration":"na hi deha-bhṛitā śhakyaṁ tyaktuṁ karmāṇy aśheṣhataḥ\nyas tu karma-phala-tyāgī sa tyāgīty abhidhīyate","english":"It is indeed impossible for one who possesses a body to relinquish all actions completely; however, he who renounces the fruits of his actions is regarded as one who has attained true renunciation.","hindi":"देहधारी जीव द्वारा समस्त कर्मों का पूर्णतः त्याग कर पाना संभव नहीं है; अतः जो कर्मफल का त्याग करता है, उसे ही वास्तव में त्यागी कहा जाता है।","gujarati":"શરીરધારી જીવ દ્વારા સંપૂર્ણપણે કર્મોનો ત્યાગ કરવો શક્ય નથી; પરંતુ જે કર્મફળનો ત્યાગ કરે છે, તેને જ સાચો ત્યાગી કહેવામાં આવે છે."},"18.12":{"chapter":18,"verse":12,"sloka":"अनिष्टमिष्टं मिश्रं च त्रिविधं कर्मणः फलम्।भवत्यत्यागिनां प्रेत्य न तु संन्यासिनां क्वचित्।।18.12।।","transliteration":"aniṣhṭam iṣhṭaṁ miśhraṁ cha tri-vidhaṁ karmaṇaḥ phalam\nbhavaty atyāgināṁ pretya na tu sannyāsināṁ kvachit","english":"The threefold fruit of action—evil, good, and mixed—accrues after death to those who do not renounce the fruit of their actions; but for those who are true renunciates, such results never exist.","hindi":"कर्मों के शुभ, अशुभ और मिश्र—ये तीन प्रकार के फल उन लोगों को मरणोपरान्त प्राप्त होते हैं, जिन्होंने कर्मफल का त्याग नहीं किया है; परन्तु त्यागियों (संन्यासियों) को ये फल कभी प्राप्त नहीं होते।","gujarati":"કર્મનું ત્રિવિધ ફળ—અશુભ, શુભ અને મિશ્ર—મરણ પછી તેવા લોકોને મળે છે જેમણે ત્યાગ નથી કર્યો, પરંતુ જેઓ સંન્યાસી છે તેમને આ ફળ ક્યારેય મળતા નથી."},"18.13":{"chapter":18,"verse":13,"sloka":"पञ्चैतानि महाबाहो कारणानि निबोध मे।सांख्ये कृतान्ते प्रोक्तानि सिद्धये सर्वकर्मणाम्।।18.13।।","transliteration":"pañchaitāni mahā-bāho kāraṇāni nibodha me\nsānkhye kṛitānte proktāni siddhaye sarva-karmaṇām","english":"Learn from Me, O mighty-armed Arjuna, these five causes, as declared in the Sankhya system, for the accomplishment of all actions.","hindi":"हे महाबाहो अर्जुन! समस्त कर्मों की सिद्धि के लिए सांख्य सिद्धांत में बताए गए इन पांच कारणों को तुम मुझसे समझो।","gujarati":"હે મહાબાહુ અર્જુન! સમસ્ત કર્મોની સિદ્ધિ માટે સાંખ્ય શાસ્ત્રમાં કહેલા આ પાંચ કારણોને તું મારી પાસેથી સારી રીતે જાણી લે."},"18.14":{"chapter":18,"verse":14,"sloka":"अधिष्ठानं तथा कर्ता करणं च पृथग्विधम्।विविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम्।।18.14।।","transliteration":"adhiṣhṭhānaṁ tathā kartā karaṇaṁ cha pṛithag-vidham\nvividhāśh cha pṛithak cheṣhṭā daivaṁ chaivātra pañchamam","english":"The seat of action (the body), the performer (the ego), the various senses, the different functions of many kinds, and the presiding deity—the fifth.","hindi":"अधिष्ठानं तथा कर्ता करणं च पृथग्विधम्। विविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम्।।","gujarati":"અધિષ્ઠાન (શરીર), કર્તા, વિવિધ કરણ (ઇન્દ્રિયો), અનેક પ્રકારની અલગ-અલગ ચેષ્ટાઓ તથા પાંચમું દૈવ (પ્રેરક દેવતાઓ) છે."},"18.15":{"chapter":18,"verse":15,"sloka":"शरीरवाङ्मनोभिर्यत्कर्म प्रारभते नरः।न्याय्यं वा विपरीतं वा पञ्चैते तस्य हेतवः।।18.15।।","transliteration":"śharīra-vāṅ-manobhir yat karma prārabhate naraḥ\nnyāyyaṁ vā viparītaṁ vā pañchaite tasya hetavaḥ","english":"Whatever action a person performs by their body, speech, and mind—whether it be right or wrong—these five are its causes.","hindi":"मनुष्य अपने शरीर, वाणी और मन के द्वारा जो कोई उचित या अनुचित कर्म करता है, उसके ये पाँच कारण ही हैं।","gujarati":"શરીર, વાણી અને મન દ્વારા મનુષ્ય જે કંઈ પણ યોગ્ય અથવા અયોગ્ય કર્મ કરે છે, તેના આ પાંચ કારણો જ છે."},"18.16":{"chapter":18,"verse":16,"sloka":"तत्रैवं सति कर्तारमात्मानं केवलं तु यः।पश्यत्यकृतबुद्धित्वान्न स पश्यति दुर्मतिः।।18.16।।","transliteration":"tatraivaṁ sati kartāram ātmānaṁ kevalaṁ tu yaḥ\npaśhyaty akṛita-buddhitvān na sa paśhyati durmatiḥ","english":"Therefore, he who, due to an untrained understanding, perceives his self—which is pure and isolated—as the sole agent of action, such a person of perverted intelligence does not perceive the truth.","hindi":"इसलिए, जो पुरुष असंस्कृत बुद्धि होने के कारण, स्वयं शुद्ध और असंग आत्मा को ही कर्ता मानता है, वह मंदबुद्धि पुरुष यथार्थ को नहीं देख पाता।","gujarati":"તેથી જે પુરુષ અશુદ્ધ બુદ્ધિને કારણે, એકલા શુદ્ધ આત્માને જ કર્તા માને છે, તે મંદબુદ્ધિ પુરુષ સત્યને જોતો નથી."},"18.17":{"chapter":18,"verse":17,"sloka":"यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते।हत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते।।18.17।।","transliteration":"yasya nāhankṛito bhāvo buddhir yasya na lipyate\nhatvā ‘pi sa imāl lokān na hanti na nibadhyate","english":"He who is free from the egoistic notion, whose intelligence is not tainted by good or evil, though he slays these people, he does not slay, nor is he bound by the action.","hindi":"जिस पुरुष में अहंकार का भाव नहीं है और जिसकी बुद्धि किसी भी प्रकार के पाप-पुण्य या गुण-दोष के द्वंद्व से लिप्त नहीं होती, वह पुरुष इन सब लोकों को मारकर भी वास्तव में न तो मारता है और न ही कर्मों के बंधन में बँधता है।","gujarati":"જે પુરુષમાં અહંકારનો ભાવ નથી અને જેની બુદ્ધિ કોઈ પણ કર્મના દોષ કે ગુણથી લિપ્ત થતી નથી, તે પુરુષ આ બધા લોકોને મારીને પણ વાસ્તવમાં ન તો મારતો નથી અને ન તો કર્મનાં બંધનમાં બંધાય છે."},"18.18":{"chapter":18,"verse":18,"sloka":"ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना।करणं कर्म कर्तेति त्रिविधः कर्मसंग्रहः।।18.18।।","transliteration":"jñānaṁ jñeyaṁ parijñātā tri-vidhā karma-chodanā\nkaraṇaṁ karma karteti tri-vidhaḥ karma-saṅgrahaḥ","english":"Knowledge, the object of knowledge, and the knower constitute the threefold impulse to action; the senses, the action, and the doer constitute the threefold basis of action.","hindi":"ज्ञान, ज्ञेय और परिज्ञाता - ये तीन प्रकार की कर्म की प्रेरणा हैं, और करण, कर्म तथा कर्ता - ये तीन प्रकार का कर्म-संग्रह (आधार) है।","gujarati":"જ્ઞાન, જ્ઞેય અને પરિજ્ઞાતા - આ ત્રણ પ્રકારની કર્મની પ્રેરણા છે, અને કરણ, કર્મ તથા કર્તા - આ ત્રણ પ્રકારનો કર્મનો સંગ્રહ છે."},"18.19":{"chapter":18,"verse":19,"sloka":"ज्ञानं कर्म च कर्ता च त्रिधैव गुणभेदतः।प्रोच्यते गुणसंख्याने यथावच्छृणु तान्यपि।।18.19।।","transliteration":"jñānaṁ karma cha kartā cha tridhaiva guṇa-bhedataḥ\nprochyate guṇa-saṅkhyāne yathāvach chhṛiṇu tāny api","english":"Knowledge, action, and the performer of action are declared in the science of the Gunas (Sankhya) to be of three types only, according to the distinction of the Gunas. Hear of them from Me as they truly are.","hindi":"ज्ञान, कर्म और कर्ता भी गुणों के भेद से सांख्यशास्त्र में तीन प्रकार के ही कहे गये हैं; उनको भी तुम मुझसे भली-भांति सुनो।","gujarati":"જ્ઞાન, કર્મ અને કર્તા પણ ગુણોના ભેદને કારણે સાંખ્યશાસ્ત્રમાં ત્રણ પ્રકારના જ કહ્યાં છે; તે પણ તું મારી પાસેથી યથાવત્ સાંભળ."},"18.20":{"chapter":18,"verse":20,"sloka":"सर्वभूतेषु येनैकं भावमव्ययमीक्षते।अविभक्तं विभक्तेषु तज्ज्ञानं विद्धि सात्त्विकम्।।18.20।।","transliteration":"sarva-bhūteṣhu yenaikaṁ bhāvam avyayam īkṣhate\navibhaktaṁ vibhakteṣhu taj jñānaṁ viddhi sāttvikam","english":"That knowledge by which one sees the one, undivided, and indestructible Reality in all beings, despite their apparent separation—know that knowledge to be Sattvic, O Arjuna.","hindi":"जिस ज्ञान के द्वारा मनुष्य समस्त पृथक-पृथक भूतों में एक अविभक्त और अविनाशी तत्त्व को देखता है, उस ज्ञान को तुम सात्त्विक जानो।","gujarati":"જે જ્ઞાન વડે મનુષ્ય સર્વ ભૂતોમાં વિભક્ત હોવા છતાં અવિભક્ત અને અવિનાશી પરમાત્માને જુએ છે, તે જ્ઞાનને તું સાત્વિક જાણ."},"18.21":{"chapter":18,"verse":21,"sloka":"पृथक्त्वेन तु यज्ज्ञानं नानाभावान्पृथग्विधान्।वेत्ति सर्वेषु भूतेषु तज्ज्ञानं विद्धि राजसम्।।18.21।।","transliteration":"pṛithaktvena tu yaj jñānaṁ nānā-bhāvān pṛithag-vidhān\nvetti sarveṣhu bhūteṣhu taj jñānaṁ viddhi rājasam","english":"But that knowledge which sees in all beings various entities of distinct kinds as being distinct from one another, know thou that knowledge to be Rajasic.","hindi":"जिस ज्ञान के द्वारा मनुष्य समस्त प्राणियों में अलग-अलग प्रकार के अनेक भावों को पृथक्-पृथक् जानता है, उस ज्ञान को तुम राजस जानो।","gujarati":"પરંતુ જે જ્ઞાન વડે મનુષ્ય તમામ પ્રાણીઓમાં વિવિધ પ્રકારના અસંખ્ય ભાવને જુદા જુદા સ્વરૂપે જુએ છે, તે જ્ઞાનને તું રાજસ જાણ."},"18.22":{"chapter":18,"verse":22,"sloka":"यत्तु कृत्स्नवदेकस्मिन्कार्ये सक्तमहैतुकम्।अतत्त्वार्थवदल्पं च तत्तामसमुदाहृतम्।।18.22।।","transliteration":"yat tu kṛitsna-vad ekasmin kārye saktam ahaitukam\natattvārtha-vad alpaṁ cha tat tāmasam udāhṛitam","english":"But that knowledge which clings to one single effect as if it were the whole, devoid of reason, without foundation in the ultimate Truth, and is trivial, is declared to be Tamasic.","hindi":"किंतु जो ज्ञान किसी एक कार्य (अपूर्ण शरीर) में ही ऐसे आसक्त रहता है मानो वही पूर्ण हो, जो तर्कहीन है, वास्तविक तत्त्व से रहित है और तुच्छ है, वह तामस कहा जाता है।","gujarati":"પરંતુ જે જ્ઞાન એક જ કાર્યમાં એવી રીતે ચોંટેલું રહે છે કે જાણે તે જ પૂર્ણ હોય, જે તર્કહીન છે, જે વાસ્તવિક તત્ત્વથી રહિત છે અને તુચ્છ છે, તેને તામસિક કહેવામાં આવે છે."},"18.23":{"chapter":18,"verse":23,"sloka":"नियतं सङ्गरहितमरागद्वेषतः कृतम्।अफलप्रेप्सुना कर्म यत्तत्सात्त्विकमुच्यते।।18.23।।","transliteration":"niyataṁ saṅga-rahitam arāga-dveṣhataḥ kṛitam\naphala-prepsunā karma yat tat sāttvikam uchyate","english":"An action that is ordained, free from attachment, performed without love or hatred, and devoid of any desire for the fruits of labor, is declared to be of the mode of goodness (Sattvic).","hindi":"जो कर्म शास्त्रविहित है, जो आसक्ति से रहित है, जिसे फल की इच्छा न रखने वाले पुरुष ने राग और द्वेष से दूर होकर किया है, उसे सात्त्विक कहा जाता है।","gujarati":"જે કર્મ શાસ્ત્રવિધિથી નિયત છે, જે આસક્તિરહિત છે, અને જે ફળની ઈચ્છા ન રાખનાર પુરુષ દ્વારા રાગ-દ્વેષ વગર કરવામાં આવ્યું છે, તેને સાત્વિક કહેવામાં આવે છે."},"18.24":{"chapter":18,"verse":24,"sloka":"यत्तु कामेप्सुना कर्म साहङ्कारेण वा पुनः।क्रियते बहुलायासं तद्राजसमुदाहृतम्।।18.24।।","transliteration":"yat tu kāmepsunā karma sāhankāreṇa vā punaḥ\nkriyate bahulāyāsaṁ tad rājasam udāhṛitam","english":"But that action which is performed by one seeking the fulfillment of desires, with a sense of egotism, and with much effort, is declared to be Rajasic.","hindi":"किन्तु जो कर्म बहुत परिश्रम से युक्त है तथा फल की कामना वाले, अहंकारयुक्त पुरुष के द्वारा किया जाता है, वह कर्म राजस कहा गया है।","gujarati":"પરંતુ જે કર્મ ખૂબ પરિશ્રમથી યુક્ત છે તથા ફળની કામનાવાળા અને અહંકારયુક્ત પુરુષ દ્વારા કરવામાં આવે છે, તે કર્મ રાજસ કહેવાય છે."},"18.25":{"chapter":18,"verse":25,"sloka":"अनुबन्धं क्षयं हिंसामनपेक्ष्य च पौरुषम्।मोहादारभ्यते कर्म यत्तत्तामसमुच्यते।।18.25।।","transliteration":"anubandhaṁ kṣhayaṁ hinsām anapekṣhya cha pauruṣham\nmohād ārabhyate karma yat tat tāmasam uchyate","english":"That action which is undertaken from delusion, without regard for the consequences, loss, injury, and one's own ability, is declared to be Tamasic.","hindi":"जो कर्म मोहवश, परिणाम, हानि, हिंसा और अपने सामर्थ्य का विचार किए बिना किया जाता है, वह तामस कहलाता है।","gujarati":"જે કર્મ પરિણામ, હાનિ, હિંસા અને પોતાના સામર્થ્યનો વિચાર કર્યા વગર માત્ર મોહને વશ થઈને કરવામાં આવે છે, તે તામસ કહેવાય છે."},"18.26":{"chapter":18,"verse":26,"sloka":"मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वितः।सिद्ध्यसिद्ध्योर्निर्विकारः कर्ता सात्त्विक उच्यते।।18.26।।","transliteration":"mukta-saṅgo ‘nahaṁ-vādī dhṛity-utsāha-samanvitaḥ\nsiddhy-asiddhyor nirvikāraḥ kartā sāttvika uchyate","english":"The agent who is free from attachment, devoid of egoism, endowed with fortitude and enthusiasm, and remains unaffected by success or failure, is declared to be of the Sattvic nature.","hindi":"जो कर्ता संगरहित, अहंमन्यता से रहित, धैर्य और उत्साह से युक्त तथा कार्य की सिद्धि और असिद्धि में निर्विकार रहता है, वह सात्त्विक कर्ता कहलाता है।","gujarati":"જે કર્તા સંગરહિત, અહંકારરહિત, ધૈર્ય અને ઉત્સાહથી યુક્ત તેમજ કાર્યની સફળતા કે નિષ્ફળતામાં નિર્વિકાર રહે છે, તે સાત્ત્વિક કર્તા કહેવાય છે."},"18.27":{"chapter":18,"verse":27,"sloka":"रागी कर्मफलप्रेप्सुर्लुब्धो हिंसात्मकोऽशुचिः।हर्षशोकान्वितः कर्ता राजसः परिकीर्तितः।।18.27।।","transliteration":"rāgī karma-phala-prepsur lubdho hinsātmako ‘śhuchiḥ\nharṣha-śhokānvitaḥ kartā rājasaḥ parikīrtitaḥ","english":"The agent who is passionate, desiring the fruits of actions, greedy, violent, impure, and moved by joy and sorrow is declared to be Rajasic.","hindi":"जो कर्ता आसक्त है, कर्मों के फल की इच्छा रखने वाला है, लोभी है, दूसरों को कष्ट पहुँचाने के स्वभाव वाला है, अशुद्ध है तथा हर्ष और शोक से ग्रस्त रहता है, वह राजस कर्ता कहा गया है।","gujarati":"જે કર્તા આસક્ત, કર્મના ફળની ઇચ્છા રાખનાર, લોભી, હિંસક સ્વભાવનો, અપવિત્ર અને હર્ષ-શોકથી યુક્ત છે, તેને રાજસ કર્તા કહેવામાં આવે છે."},"18.28":{"chapter":18,"verse":28,"sloka":"अयुक्तः प्राकृतः स्तब्धः शठो नैष्कृतिकोऽलसः।विषादी दीर्घसूत्री च कर्ता तामस उच्यते।।18.28।।","transliteration":"ayuktaḥ prākṛitaḥ stabdhaḥ śhaṭho naiṣhkṛitiko ‘lasaḥ\nviṣhādī dīrgha-sūtrī cha kartā tāmasa uchyate","english":"Unsteady, vulgar, inflexible, deceitful, malicious, lazy, despondent, and procrastinating—such an agent is called Tamasic.","hindi":"अयुक्त, प्राकृत, स्तब्ध, शठ, नैष्कृतिक, आलसी, विषादी और दीर्घसूत्री कर्ता तामस कहा जाता है।","gujarati":"અયુક્ત, પ્રાકૃત, સ્તબ્ધ, શઠ, નૈષ્કૃતિક, આળસુ, વિષાદી અને દીર્ઘસૂત્રી કર્તા તામસ કહેવાય છે."},"18.29":{"chapter":18,"verse":29,"sloka":"बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं श्रृणु।प्रोच्यमानमशेषेण पृथक्त्वेन धनञ्जय।।18.29।।","transliteration":"buddher bhedaṁ dhṛiteśh chaiva guṇatas tri-vidhaṁ śhṛiṇu\nprochyamānam aśheṣheṇa pṛithaktvena dhanañjaya","english":"O Arjuna, hear now the threefold classification of the intellect and the firmness according to the Gunas, as I declare them fully and distinctly unto you.","hindi":"हे अर्जुन! अब मेरे द्वारा गुणों के अनुसार किए गए बुद्धि और धृति के त्रिविध भेदों को पूर्णतः और पृथक रूप से सुनो, जैसा कि मैं उनका वर्णन कर रहा हूँ।","gujarati":"હે અર્જુન! હવે મારા દ્વારા ગુણોના આધારે વર્ણવેલા બુદ્ધિ અને ધૃતિના ત્રિવિધ ભેદોને તું સંપૂર્ણપણે અને સ્પષ્ટ રીતે સાંભળ."},"18.30":{"chapter":18,"verse":30,"sloka":"प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये।बन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी।।18.30।।","transliteration":"pravṛittiṁ cha nivṛittiṁ cha kāryākārye bhayābhaye\nbandhaṁ mokṣhaṁ cha yā vetti buddhiḥ sā pārtha sāttvikī","english":"The intellect which knows the path of work and renunciation, what ought to be done and what ought not to be done, fear and fearlessness, bondage and liberation—that intellect, O Arjuna, is Sattvic.","hindi":"हे पार्थ! जो बुद्धि प्रवृत्ति और निवृत्ति, कार्य और अकार्य, भय और अभय तथा बन्ध और मोक्ष को यथार्थ रूप से जानती है, वह बुद्धि सात्त्विकी है।","gujarati":"હે પાર્થ! જે બુદ્ધિ પ્રવૃત્તિ અને નિવૃત્તિ, કર્તવ્ય અને અકર્તવ્ય, ભય અને અભય તથા બંધન અને મોક્ષને યથાર્થ રીતે જાણે છે, તે બુદ્ધિ સાત્ત્વિક છે."},"18.31":{"chapter":18,"verse":31,"sloka":"यया धर्ममधर्मं च कार्यं चाकार्यमेव च।अयथावत्प्रजानाति बुद्धिः सा पार्थ राजसी।।18.31।।","transliteration":"yayā dharmam adharmaṁ cha kāryaṁ chākāryam eva cha\nayathāvat prajānāti buddhiḥ sā pārtha rājasī","english":"O Arjuna, that intellect by which one fails to correctly discern dharma and adharma, as well as what ought to be done and what ought not to be done, is known as rajasic.","hindi":"हे पार्थ! जिस बुद्धि के द्वारा मनुष्य धर्म और अधर्म को तथा कर्तव्य और अकर्तव्य को यथावत् नहीं जानता है, वह बुद्धि राजसी है।","gujarati":"હે પાર્થ! જે બુદ્ધિ દ્વારા મનુષ્ય ધર્મ અને અધર્મ તથા કર્તવ્ય અને અકર્તવ્યને યથાર્થ રીતે જાણતો નથી, તે બુદ્ધિ રાજસી છે."},"18.32":{"chapter":18,"verse":32,"sloka":"अधर्मं धर्ममिति या मन्यते तमसाऽऽवृता।सर्वार्थान्विपरीतांश्च बुद्धिः सा पार्थ तामसी।।18.32।।","transliteration":"adharmaṁ dharmam iti yā manyate tamasāvṛitā\nsarvārthān viparītānśh cha buddhiḥ sā pārtha tāmasī","english":"O Arjuna, that intellect which is shrouded in darkness, which perceives irreligion as religion and views all things in a perverted way, is of the nature of Tamas.","hindi":"हे अर्जुन! जो बुद्धि तमोगुण से ढकी हुई है, जो अधर्म को ही धर्म मानती है और सभी वस्तुओं को उनके वास्तविक स्वरूप से विपरीत देखती है, वह तामसी बुद्धि कहलाती है।","gujarati":"હે અર્જુન! જે બુદ્ધિ તમોગુણથી ઘેરાયેલી છે, જે અધર્મને ધર્મ માને છે અને દરેક વસ્તુને વિપરીત સ્વરૂપે જુએ છે, તે બુદ્ધિ તામસી છે."},"18.33":{"chapter":18,"verse":33,"sloka":"धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः।योगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी।।18.33।।","transliteration":"dhṛityā yayā dhārayate manaḥ-prāṇendriya-kriyāḥ\nyogenāvyabhichāriṇyā dhṛitiḥ sā pārtha sāttvikī","english":"The unwavering firmness, O Arjuna, by which the functions of the mind, the life-force, and the senses are restrained through the practice of Yoga, is known as Sattvic determination.","hindi":"हे अर्जुन! जिस अटूट धृति (दृढ़ता) के द्वारा मनुष्य योग के अभ्यास से मन, प्राण और इन्द्रियों की क्रियाओं को धारण करता है, वह सात्त्विकी धृति कहलाती है।","gujarati":"હે અર્જુન! જે અતૂટ દ્રઢતા દ્વારા મનુષ્ય યોગના અભ્યાસથી મન, પ્રાણ અને ઇન્દ્રિયોની ક્રિયાઓને ધારણ કરે છે, તે સાત્વિકી દ્રઢતા કહેવાય છે."},"18.34":{"chapter":18,"verse":34,"sloka":"यया तु धर्मकामार्थान् धृत्या धारयतेऽर्जुन।प्रसङ्गेन फलाकाङ्क्षी धृतिः सा पार्थ राजसी।।18.34।।","transliteration":"yayā tu dharma-kāmārthān dhṛityā dhārayate ‘rjuna\nprasaṅgena phalākāṅkṣhī dhṛitiḥ sā pārtha rājasī","english":"But that determination, O Arjuna, by which one holds fast to duty, pleasure, and wealth—being attached and desiring the fruits of these actions—that firmness is declared to be Rajasic.","hindi":"किंतु हे अर्जुन! जो फल की इच्छा रखने वाला पुरुष अत्यंत आसक्ति से धर्म, अर्थ और काम के फलों को धारण करता है, वह धृति राजसी मानी गई है।","gujarati":"પરંતુ હે અર્જુન! જે દ્રઢતા વડે ફળની ઈચ્છા રાખનાર પુરુષ અત્યંત આસક્તિથી ધર્મ, અર્થ અને કામને ધારણ કરે છે, તે દ્રઢતા રાજસી છે."},"18.35":{"chapter":18,"verse":35,"sloka":"यया स्वप्नं भयं शोकं विषादं मदमेव च।न विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी।।18.35।।","transliteration":"yayā svapnaṁ bhayaṁ śhokaṁ viṣhādaṁ madam eva cha\nna vimuñchati durmedhā dhṛitiḥ sā pārtha tāmasī","english":"O Arjuna, that determination by which a foolish person does not abandon sleep, fear, grief, despair, and arrogance, is declared to be Tamasic.","hindi":"हे अर्जुन! जिस धारणा के द्वारा दुर्बुद्धि मनुष्य स्वप्न (निद्रा), भय, शोक, विषाद और अहंकार का त्याग नहीं करता, वह धृति तामसी कहलाती है।","gujarati":"હે અર્જુન! જે ધારણા દ્વારા દુર્બુદ્ધિ મનુષ્ય ઊંઘ, ભય, શોક, વિષાદ અને અહંકારનો ત્યાગ નથી કરતો, તે ધૃતિ તામસી કહેવાય છે."},"18.36":{"chapter":18,"verse":36,"sloka":"सुखं त्विदानीं त्रिविधं श्रृणु मे भरतर्षभ।अभ्यासाद्रमते यत्र दुःखान्तं च निगच्छति।।18.36।।","transliteration":"sukhaṁ tv idānīṁ tri-vidhaṁ śhṛiṇu me bharatarṣhabha\nabhyāsād ramate yatra duḥkhāntaṁ cha nigachchhati\n yat tad agre viṣham iva pariṇāme ‘mṛitopamam\ntat sukhaṁ sāttvikaṁ proktam ātma-buddhi-prasāda-jam","english":"Now, O Arjuna, hear from Me regarding the three types of happiness in which one finds delight through practice, and by which one surely arrives at the end of all suffering.","hindi":"हे अर्जुन! अब तुम मुझसे उस तीन प्रकार के सुख के विषय में सुनो, जिसमें मनुष्य अभ्यास के द्वारा रम जाता है और दुखों के अंत को प्राप्त कर लेता है।","gujarati":"હે અર્જુન! હવે તું મારી પાસેથી તે ત્રણ પ્રકારના સુખ વિશે સાંભળ, જેમાં મનુષ્ય અભ્યાસ દ્વારા રમે છે અને દુઃખોના અંતને પ્રાપ્ત કરી લે છે."},"18.37":{"chapter":18,"verse":37,"sloka":"यत्तदग्रे विषमिव परिणामेऽमृतोपमम्।तत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम्।।18.37।।","transliteration":"yat  tad agre    viṣam   iva pariṇāme    'mṛtopamam  tat sukhaṁ  sāttvikaṁ   proktam ātma-buddhi-prasāda-jam","english":"That which in the beginning is like poison, but in the end is like nectar—that happiness is declared to be sattvic, born of the clarity of one’s own mind due to self-realization.","hindi":"जो सुख आरम्भ में विष के समान प्रतीत होता है, किन्तु परिणाम में अमृत के तुल्य है, वह आत्म-बोध की निर्मलता से उत्पन्न सात्त्विक सुख कहा गया है।","gujarati":"જે સુખ શરૂઆતમાં વિષ જેવું લાગે છે, પરંતુ પરિણામમાં અમૃત સમાન છે, તે આત્મ-બુદ્ધિના પ્રસાદથી ઉત્પન્ન થયેલું સુખ સાત્ત્વિક કહેવાય છે."},"18.38":{"chapter":18,"verse":38,"sloka":"विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम्।परिणामे विषमिव तत्सुखं राजसं स्मृतम्।।18.38।।","transliteration":"viṣhayendriya-sanyogād yat tad agre ’mṛitopamam\npariṇāme viṣham iva tat sukhaṁ rājasaṁ smṛitam","english":"That happiness which arises from the contact of the senses with their objects, which is like nectar at first but like poison in the end, is declared to be Rajasic.","hindi":"जो सुख विषयों और इन्द्रियों के संयोग से उत्पन्न होता है, वह आरम्भ में अमृत के समान प्रतीत होता है, परन्तु परिणाम में विष के तुल्य होता है, उस सुख को राजस कहा गया है।","gujarati":"જે સુખ વિષયો અને ઇન્દ્રિયોના સંયોગથી ઉત્પન્ન થાય છે, તે આરંભમાં અમૃત જેવું લાગે છે, પરંતુ પરિણામમાં વિષ સમાન છે, તે સુખ રાજસ કહેવાય છે."},"18.39":{"chapter":18,"verse":39,"sloka":"यदग्रे चानुबन्धे च सुखं मोहनमात्मनः।निद्रालस्यप्रमादोत्थं तत्तामसमुदाहृतम्।।18.39।।","transliteration":"yad agre chānubandhe cha sukhaṁ mohanam ātmanaḥ\nnidrālasya-pramādotthaṁ tat tāmasam udāhṛitam","english":"That happiness which both in the beginning and at the end is delusive to the self, arising from sleep, indolence, and heedlessness, is declared to be Tamasic.","hindi":"जो सुख आरम्भ में और परिणाम में भी आत्मा को मोहित करने वाला है, वह निद्रा, आलस्य और प्रमाद से उत्पन्न होने वाला सुख तामस कहा जाता है।","gujarati":"જે સુખ આરંભમાં અને પરિણામમાં પણ આત્માને મોહિત કરનારું છે, તે નિદ્રા, આળસ અને પ્રમાદથી ઉત્પન્ન થયેલું સુખ તામસ કહેવાય છે."},"18.40":{"chapter":18,"verse":40,"sloka":"न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः।सत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्ित्रभिर्गुणैः।।18.40।।","transliteration":"na tad asti pṛithivyāṁ vā divi deveṣhu vā punaḥ\nsattvaṁ prakṛiti-jair muktaṁ yad ebhiḥ syāt tribhir guṇaiḥ","english":"There is no being on earth or among the celestial gods in the higher realms who is free from these three modes born of material nature.","hindi":"पृथ्वी पर अथवा स्वर्ग में देवताओं के बीच भी ऐसा कोई प्राणी नहीं है, जो प्रकृति से उत्पन्न इन तीन गुणों से मुक्त हो।","gujarati":"પૃથ્વી પર કે સ્વર્ગમાં દેવતાઓમાં પણ એવું કોઈ પ્રાણી નથી જે પ્રકૃતિથી ઉત્પન્ન થયેલા આ ત્રણ ગુણોથી મુક્ત હોય."},"18.41":{"chapter":18,"verse":41,"sloka":"ब्राह्मणक्षत्रियविशां शूद्राणां च परंतप।कर्माणि प्रविभक्तानि स्वभावप्रभवैर्गुणैः।।18.41।।","transliteration":"brāhmaṇa-kṣhatriya-viśhāṁ śhūdrāṇāṁ cha parantapa\nkarmāṇi pravibhaktāni svabhāva-prabhavair guṇaiḥ","english":"The duties of Brahmanas, Kshatriyas, Vaisyas, and Sudras are distributed according to the qualities born of their own nature, O Arjuna.","hindi":"हे परन्तप! ब्राह्मणों, क्षत्रियों, वैश्यों और शूद्रों के कर्म, स्वभाव से उत्पन्न गुणों के अनुसार विभक्त किए गए हैं।","gujarati":"હે પરંતપ! બ્રાહ્મણો, ક્ષત્રિયો, વૈશ્યો અને શૂદ્રોના કર્મો તેમના સ્વભાવમાંથી જન્મેલા ગુણો અનુસાર વિભાજિત કરવામાં આવ્યા છે."},"18.42":{"chapter":18,"verse":42,"sloka":"शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च।ज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम्।।18.42।।","transliteration":"śhamo damas tapaḥ śhauchaṁ kṣhāntir ārjavam eva cha\njñānaṁ vijñānam āstikyaṁ brahma-karma svabhāva-jam","english":"Serenity, self-restraint, austerity, purity, forgiveness, and uprightness, as well as knowledge, realization, and belief in God, are the duties of Brahmanas, born of their own nature.","hindi":"शम, दम, तप, शौच, क्षान्ति, आर्जव, ज्ञान, विज्ञान और आस्तिक्य - ये ब्राह्मण के स्वाभाविक कर्म हैं।","gujarati":"શમ, દમ, તપ, શૌચ, ક્ષમા, સરલતા, જ્ઞાન, વિજ્ઞાન અને આસ્તિકતા - આ બ્રાહ્મણના સ્વાભાવિક કર્મ છે."},"18.43":{"chapter":18,"verse":43,"sloka":"शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम्।दानमीश्वरभावश्च क्षात्रं कर्म स्वभावजम्।।18.43।।","transliteration":"śhauryaṁ tejo dhṛitir dākṣhyaṁ yuddhe chāpy apalāyanam\ndānam īśhvara-bhāvaśh cha kṣhātraṁ karma svabhāva-jam","english":"Heroism, splendor, firmness, dexterity, and not fleeing from battle, generosity, and lordliness are the duties of the Kshatriyas, born of their own nature.","hindi":"शौर्य, तेज, धैर्य, चतुरता और युद्ध में न भागना, दान देना और स्वामी-भाव—ये क्षत्रिय के स्वाभाविक कर्म हैं।","gujarati":"શૌર્ય, તેજ, ધૈર્ય, દક્ષતા, યુદ્ધમાંથી પાછા ન હઠવું, દાન આપવું અને સ્વામીભાવ - આ ક્ષત્રિયોના સ્વભાવજન્ત કર્મ છે."},"18.44":{"chapter":18,"verse":44,"sloka":"कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम्।परिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम्।।18.44।।","transliteration":"kṛiṣhi-gau-rakṣhya-vāṇijyaṁ vaiśhya-karma svabhāva-jam\nparicharyātmakaṁ karma śhūdrasyāpi svabhāva-jam","english":"Agriculture, cattle-rearing, and trade are the natural duties of the Vaisya; and service is the natural duty of the Sudra, born of their own inherent qualities.","hindi":"कृषि, गौपालन और व्यापार वैश्य के स्वाभाविक कर्म हैं, और सेवा करना शूद्र का स्वाभाविक कर्म है, जो उनके स्वभाव से उत्पन्न हुए हैं।","gujarati":"ખેતી, ગૌપાલન અને વેપાર એ વૈશ્યના સ્વભાવગત કર્મો છે, અને સેવા કરવી એ શૂદ્રનું સ્વભાવગત કર્મ છે, જે તેમના પ્રકૃતિજન્ય ગુણોમાંથી જન્મે છે."},"18.45":{"chapter":18,"verse":45,"sloka":"स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः।स्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु।।18.45।।","transliteration":"sve sve karmaṇy abhirataḥ sansiddhiṁ labhate naraḥ\nsva-karma-nirataḥ siddhiṁ yathā vindati tach chhṛiṇu","english":"Devoted to one's own duty, man attains perfection. Now hear from Me how one engaged in his own duty attains such perfection, O Arjuna.","hindi":"अपने-अपने स्वाभाविक कर्मों में तत्पर मनुष्य भगवत्प्राप्ति रूप सिद्धि को प्राप्त कर लेता है। हे अर्जुन! अपने स्वाभाविक कर्म में लगा हुआ मनुष्य जिस प्रकार से कर्म करके सिद्धि को प्राप्त होता है, उसे तू मुझसे सुन।","gujarati":"પોતપોતાના સ્વાભાવિક કર્મોમાં નિષ્ઠાપૂર્વક લાગેલા મનુષ્યો સિદ્ધિને પ્રાપ્ત કરે છે. હે અર્જુન! પોતાના કર્મમાં રત રહીને મનુષ્ય કેવી રીતે સિદ્ધિ પ્રાપ્ત કરે છે, તે તું મારી પાસેથી સાંભળ."},"18.46":{"chapter":18,"verse":46,"sloka":"यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम्।स्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः।।18.46।।","transliteration":"yataḥ pravṛittir bhūtānāṁ yena sarvam idaṁ tatam\nsva-karmaṇā tam abhyarchya siddhiṁ vindati mānavaḥ","english":"By worshipping Shri Krishna, from whom all beings have emanated and by whom this entire universe is pervaded, through the performance of one's own prescribed duties, a human being attains perfection.","hindi":"जिस श्री कृष्ण से संपूर्ण प्राणियों की उत्पत्ति हुई है और जिनसे यह समस्त जगत व्याप्त है, उन श्री कृष्ण की अपने स्वाभाविक कर्मों के द्वारा पूजा करके मनुष्य परम सिद्धि को प्राप्त होता है।","gujarati":"જે શ્રી કૃષ્ણમાંથી સર્વ પ્રાણીઓની ઉત્પત્તિ થઈ છે અને જેના દ્વારા આ સમગ્ર જગત વ્યાપ્ત છે, તે શ્રી કૃષ્ણની પોતાના સ્વભાવજનિત કર્મો દ્વારા પૂજા કરીને મનુષ્ય સિદ્ધિને પ્રાપ્ત કરે છે."},"18.47":{"chapter":18,"verse":47,"sloka":"श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात्।स्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम्।।18.47।।","transliteration":"śhreyān swa-dharmo viguṇaḥ para-dharmāt sv-anuṣhṭhitāt\nsvabhāva-niyataṁ karma kurvan nāpnoti kilbiṣham","english":"Better is one's own duty (Svadharma), though imperfectly performed, than the duty of another well performed. By performing the duty ordained by one's own nature, a person incurs no sin.","hindi":"दूसरे के धर्म का भली-भांति पालन करने की अपेक्षा, अपने स्वयं के धर्म का पालन करना, भले ही वह गुणरहित हो, श्रेष्ठ है। अपने स्वभाव से नियत किए गए कर्म को करने वाला मनुष्य पाप का भागी नहीं होता।","gujarati":"બીજાના ધર્મનું સારી રીતે પાલન કરવા કરતાં, ગુણરહિત હોવા છતાં પોતાના સ્વધર્મનું પાલન કરવું શ્રેષ્ઠ છે. પોતાના સ્વભાવથી નિયત કરેલા કર્મ કરનાર મનુષ્ય પાપને પ્રાપ્ત કરતો નથી."},"18.48":{"chapter":18,"verse":48,"sloka":"सहजं कर्म कौन्तेय सदोषमपि न त्यजेत्।सर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः।।18.48।।","transliteration":"saha-jaṁ karma kaunteya sa-doṣham api na tyajet\nsarvārambhā hi doṣheṇa dhūmenāgnir ivāvṛitāḥ","english":"O Arjuna, one should not abandon the duty born of one's own nature, even if it has flaws; for all undertakings are covered by defects, as fire is covered by smoke, says Bhagwan Shri Krishna.","hindi":"हे अर्जुन, मनुष्य को अपने स्वभाव से उत्पन्न कर्म को दोषयुक्त होने पर भी त्यागना नहीं चाहिए, क्योंकि धुएँ से ढकी अग्नि के समान सभी कर्म किसी न किसी दोष से आवृत रहते हैं, ऐसा भगवान श्री कृष्ण का कथन है।","gujarati":"હે અર્જુન, મનુષ્યે પોતાનો સ્વભાવગત ધર્મ, ભલે તે દોષપૂર્ણ હોય, ક્યારેય ત્યાગવો જોઈએ નહીં; કારણ કે ધુમાડાથી અગ્નિની જેમ દરેક કર્મ કોઈ ને કોઈ દોષથી ઘેરાયેલું હોય છે, એમ ભગવાન શ્રી કૃષ્ણ કહે છે."},"18.49":{"chapter":18,"verse":49,"sloka":"असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः।नैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति।।18.49।।","transliteration":"asakta-buddhiḥ sarvatra jitātmā vigata-spṛihaḥ\nnaiṣhkarmya-siddhiṁ paramāṁ sannyāsenādhigachchhati","english":"One whose intellect is unattached everywhere, who has subdued the self, and from whom all desires have fled, attains through renunciation the supreme state of freedom from the bondage of action.","hindi":"जिसकी बुद्धि सर्वत्र आसक्ति से रहित है, जो अपने मन और इंद्रियों को जीतने वाला है, और जिसकी समस्त इच्छाएं नष्ट हो चुकी हैं, वह पुरुष संन्यास के द्वारा परम नैर्ष्कम्य सिद्धि को प्राप्त करता है।","gujarati":"જેની બુદ્ધિ સર્વત્ર આસક્તિ વિનાની છે, જેણે પોતાનું મન જીતી લીધું છે અને જેની તમામ ઈચ્છાઓ નાશ પામી છે, તે પુરુષ સંન્યાસ દ્વારા પરમ નૈષ્કર્મ્ય સિદ્ધિને પ્રાપ્ત કરે છે."},"18.50":{"chapter":18,"verse":50,"sloka":"सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे।समासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा।।18.50।।","transliteration":"siddhiṁ prāpto yathā brahma tathāpnoti nibodha me\nsamāsenaiva kaunteya niṣhṭhā jñānasya yā parā","english":"Learn from Me, O Arjuna, in brief how one who has attained perfection reaches Brahman—the Eternal, the supreme goal of knowledge.","hindi":"हे अर्जुन! सिद्धि प्राप्त करने वाला पुरुष जिस प्रकार ब्रह्म को प्राप्त होता है, और जो ज्ञान की सर्वोच्च निष्ठा है, उसे तुम मुझसे संक्षेप में समझो।","gujarati":"હે અર્જુન! સિદ્ધિને પ્રાપ્ત પુરુષ જે રીતે બ્રહ્મને પામે છે, અને જે જ્ઞાનની પરાકાષ્ઠા છે, તે તું મારી પાસેથી સંક્ષેપમાં જાણ."},"18.51":{"chapter":18,"verse":51,"sloka":"बुद्ध्या विशुद्धया युक्तो धृत्याऽऽत्मानं नियम्य च।शब्दादीन् विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च।।18.51।।","transliteration":"buddhyā viśhuddhayā yukto dhṛityātmānaṁ niyamya cha\nśhabdādīn viṣhayāns tyaktvā rāga-dveṣhau vyudasya cha","english":"Endowed with a pure intellect, controlling the self with firm resolve, abandoning the objects of the senses such as sound, and casting aside attraction and hatred.","hindi":"विशुद्ध बुद्धि से युक्त होकर, धैर्यपूर्वक अन्तःकरण को वश में करके, शब्दादि विषयों को त्यागकर तथा राग-द्वेष का परित्याग करके (साधक स्थितप्रज्ञ होता है)।","gujarati":"વિશુદ્ધ બુદ્ધિથી યુક્ત, ધૈર્યથી અંતઃકરણને વશ કરીને, શબ્દાદિ વિષયોનો ત્યાગ કરીને તથા રાગ-દ્વેષને દૂર કરીને (સાધક સ્થિર થાય છે)."},"18.52":{"chapter":18,"verse":52,"sloka":"विविक्तसेवी लघ्वाशी यतवाक्कायमानसः।ध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः।।18.52।।","transliteration":"vivikta-sevī laghv-āśhī yata-vāk-kāya-mānasaḥ\ndhyāna-yoga-paro nityaṁ vairāgyaṁ samupāśhritaḥ","english":"Dwelling in solitude, eating sparingly, with speech, body, and mind subdued, always engaged in meditation and concentration, and resorting to dispassion.","hindi":"एकान्त में निवास, अल्प आहार, वाणी, शरीर और मन का संयम, सदा ध्यान और समाधि में लगे रहना और वैराग्य का आश्रय लेना।","gujarati":"એકાંતમાં નિવાસ, અલ્પ આહાર, વાણી, શરીર અને મનનો સંયમ, સદા ધ્યાન અને સમાધિમાં તત્પર રહેવું અને વૈરાગ્યનો આશ્રય લેવો."},"18.53":{"chapter":18,"verse":53,"sloka":"अहङ्कारं बलं दर्पं कामं क्रोधं परिग्रहम्।विमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते।।18.53।।","transliteration":"ahankāraṁ balaṁ darpaṁ kāmaṁ krodhaṁ parigraham\nvimuchya nirmamaḥ śhānto brahma-bhūyāya kalpate","english":"Having abandoned egoism, strength, arrogance, desire, anger, and covetousness, and being free from the notion of 'mine' and peaceful, he is fit for becoming Brahman.","hindi":"अहंकार, बल, दर्प, काम, क्रोध और परिग्रह का त्याग करके, ममता से रहित और शांत हुआ मनुष्य ब्रह्म को प्राप्त करने के योग्य हो जाता है।","gujarati":"અહંકાર, બળ, દર્પ, કામ, ક્રોધ અને પરિગ્રહનો ત્યાગ કરીને, મમત્વભાવથી રહિત અને શાંત થયેલો પુરુષ બ્રહ્મત્વને પ્રાપ્ત કરવા યોગ્ય બને છે."},"18.54":{"chapter":18,"verse":54,"sloka":"ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति।समः सर्वेषु भूतेषु मद्भक्तिं लभते पराम्।।18.54।।","transliteration":"brahma-bhūtaḥ prasannātmā na śhochati na kāṅkṣhati\nsamaḥ sarveṣhu bhūteṣhu mad-bhaktiṁ labhate parām","english":"One who has attained the state of Brahman, being serene in the Self, neither grieves nor desires; being equal to all living beings, he attains supreme devotion unto Me, Shri Krishna.","hindi":"ब्रह्म में स्थित होकर, प्रसन्न चित्त वाला पुरुष न तो कभी किसी का शोक करता है और न ही किसी वस्तु की इच्छा करता है। वह समस्त प्राणियों के प्रति समभाव रखता हुआ, मेरी, अर्थात भगवान श्री कृष्ण की परा भक्ति को प्राप्त कर लेता है।","gujarati":"બ્રહ્મભૂત (બ્રહ્મમાં સ્થિત) અને પ્રસન્ન મનવાળો તે પુરુષ ન તો કોઈનો શોક કરે છે અને ન તો કોઈની ઈચ્છા રાખે છે; તે સમસ્ત ભૂતોમાં સમાનભાવ રાખીને મારી, એટલે કે ભગવાન શ્રી કૃષ્ણની પરા ભક્તિને પ્રાપ્ત કરે છે."},"18.55":{"chapter":18,"verse":55,"sloka":"भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः।ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम्।।18.55।।","transliteration":"bhaktyā mām abhijānāti yāvān yaśh chāsmi tattvataḥ\ntato māṁ tattvato jñātvā viśhate tad-anantaram","english":"Through pure devotion, one realizes Shri Krishna in His absolute truth—who He is and what He is. Having attained this direct realization of His divine nature, the devotee immediately enters into the Supreme Being.","hindi":"भक्ति के द्वारा वह मुझे तत्त्व से जान लेता है कि मैं कौन हूँ और कैसा हूँ। तत्पश्चात, मुझे तत्त्व से जानकर वह तत्काल ही मुझमें प्रविष्ट हो जाता है।","gujarati":"ભક્તિ દ્વારા તે મને તત્વથી જાણી લે છે કે હું કોણ છું અને શું છું. ત્યારબાદ, મને તત્વથી જાણીને તે તત્કાલ મારામાં પ્રવેશ કરે છે."},"18.56":{"chapter":18,"verse":56,"sloka":"सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः।मत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम्।।18.56।।","transliteration":"sarva-karmāṇy api sadā kurvāṇo mad-vyapāśhrayaḥ\nmat-prasādād avāpnoti śhāśhvataṁ padam avyayam","english":"Always performing all actions, taking refuge in Me alone, by My grace one attains the eternal, imperishable abode.","hindi":"सर्वदा सब कर्मों को करता हुआ भी जो मेरे परायण होकर मेरे शरण में रहता है, वह मेरे प्रसाद से शाश्वत और अविनाशी पद को प्राप्त कर लेता है।","gujarati":"સર્વ કર્મો હંમેશા કરતો હોવા છતાં પણ મારા આશ્રિત થઈને, મારી કૃપાથી તે શાશ્વત અને અવિનાશી પદને પામે છે."},"18.57":{"chapter":18,"verse":57,"sloka":"चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः।बुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव।।18.57।।","transliteration":"chetasā sarva-karmāṇi mayi sannyasya mat-paraḥ\nbuddhi-yogam upāśhritya mach-chittaḥ satataṁ bhava","english":"Mentally renouncing all actions unto Me, holding Me as the supreme goal, and resorting to the yoga of discernment, fix your consciousness ever upon Me.","hindi":"मन से समस्त कर्मों का मुझमें अर्पण करके, मुझे ही परम लक्ष्य मानकर तथा बुद्धियोग का आश्रय लेकर, तुम निरंतर मुझमें ही चित्त लगाओ।","gujarati":"સર્વ કર્મોને મનથી મારામાં સમર્પિત કરીને, મને જ પરમ લક્ષ્ય માનીને અને બુદ્ધિયોગનો આશ્રય લઈને, તું હંમેશા મારામાં જ ચિત્ત પરોવી રાખ."},"18.58":{"chapter":18,"verse":58,"sloka":"मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि।अथ चेत्त्वमहङ्कारान्न श्रोष्यसि विनङ्क्ष्यसि।।18.58।।","transliteration":"mach-chittaḥ sarva-durgāṇi mat-prasādāt tariṣhyasi\natha chet tvam ahankārān na śhroṣhyasi vinaṅkṣhyasi","english":"If you fix your consciousness upon Me, you will, by My grace, overcome all obstacles. But if, due to ego, you do not heed My words, you will be lost.","hindi":"यदि तू मुझमें चित्त लगाएगा, तो तू मेरी कृपा से समस्त कठिनाइयों को सहज ही पार कर लेगा। किन्तु यदि अहंकार के वश में होकर तू मेरे वचनों की उपेक्षा करेगा, तो तू विनष्ट हो जाएगा।","gujarati":"જો તું તારું ચિત્ત મારામાં પરોવીશ, તો મારી કૃપાથી તું તમામ સંકટોને પાર કરી જઈશ. પરંતુ જો અહંકારવશ તું મારા આ ઉપદેશને નહીં સાંભળે, તો તારો વિનાશ થશે."},"18.59":{"chapter":18,"verse":59,"sloka":"यदहङ्कारमाश्रित्य न योत्स्य इति मन्यसे।मिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति।।18.59।।","transliteration":"yad ahankāram āśhritya na yotsya iti manyase\nmithyaiṣha vyavasāyas te prakṛitis tvāṁ niyokṣhyati","english":"If, filled with egoism, thou thinkest, 'I will not fight,' then thy resolve is vain; nature will compel thee.","hindi":"यदि अहंकार से भरकर तुम यह सोचते हो कि 'मैं युद्ध नहीं करूँगा', तो तुम्हारा यह निश्चय व्यर्थ है; क्योंकि प्रकृति ही तुम्हें बलपूर्वक युद्ध में प्रवृत्त कर देगी।","gujarati":"જો અહંકારથી ભરાઈને તું એમ વિચારી રહ્યો છે કે 'હું યુદ્ધ નહીં કરું', તો તારો આ નિશ્ચય વ્યર્થ છે, કારણ કે પ્રકૃતિ તને બળપૂર્વક યુદ્ધમાં જોતરી દેશે."},"18.60":{"chapter":18,"verse":60,"sloka":"स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा।कर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत्।।18.60।।","transliteration":"swbhāva-jena kaunteya nibaddhaḥ svena karmaṇā\nkartuṁ nechchhasi yan mohāt kariṣhyasy avaśho ’pi tat","english":"O Arjuna, bound by your own karma born of your own nature, that which from delusion you do not wish to do, even that you shall do helplessly.","hindi":"हे अर्जुन! अपने स्वभाव से उत्पन्न कर्मों द्वारा तुम बंधे हुए हो, और मोहवश जिस कार्य को तुम करना नहीं चाहते, उसे भी तुम परवश होकर करोगे।","gujarati":"હે અર્જુન! તારા પોતાના સ્વભાવથી ઉત્પન્ન થયેલા કર્મો દ્વારા તું બંધાયેલો છે, અને જે કર્મને તું મોહને વશ થઈને કરવા નથી ઈચ્છતો, તેને પણ તું લાચાર થઈને કરીશ."},"18.61":{"chapter":18,"verse":61,"sloka":"ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति।भ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया।।18.61।।","transliteration":"īśhvaraḥ sarva-bhūtānāṁ hṛid-deśhe ‘rjuna tiṣhṭhati\nbhrāmayan sarva-bhūtāni yantrārūḍhāni māyayā","english":"The Supreme Lord Krishna dwells within the hearts of all living beings, O Arjuna, and by His divine illusory power (Maya), He causes all beings to revolve as if mounted on a mechanical device.","hindi":"हे अर्जुन! भगवान श्रीकृष्ण समस्त प्राणियों के हृदय में स्थित हैं और अपनी मायाशक्ति द्वारा समस्त प्राणियों को यन्त्र पर सवार हुए के समान घुमा रहे हैं।","gujarati":"હે અર્જુન! ભગવાન શ્રીકૃષ્ણ સર્વ પ્રાણીઓના હૃદયમાં બિરાજમાન છે અને પોતાની માયાશક્તિ વડે બધા જ પ્રાણીઓને યંત્ર પર બેઠેલાની જેમ ભ્રમણ કરાવી રહ્યા છે."},"18.62":{"chapter":18,"verse":62,"sloka":"तमेव शरणं गच्छ सर्वभावेन भारत।तत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम्।।18.62।।","transliteration":"tam eva śharaṇaṁ gachchha sarva-bhāvena bhārata\ntat-prasādāt parāṁ śhāntiṁ sthānaṁ prāpsyasi śhāśhvatam","english":"Surrender yourself unto Him alone with all your being, O Arjuna. By His grace, you will attain supreme peace and the eternal, imperishable abode.","hindi":"हे अर्जुन! तुम सर्वभाव से उसी भगवान श्री कृष्ण की शरण में जाओ। उनकी कृपा से ही तुम परम शान्ति और सनातन धाम को प्राप्त करोगे।","gujarati":"હે અર્જુન! તું સર્વભાવથી એકમાત્ર ભગવાન શ્રીકૃષ્ણની શરણમાં જા. તેમની કૃપાથી જ તું પરમ શાંતિ અને શાશ્વત ધામને પ્રાપ્ત કરીશ."},"18.63":{"chapter":18,"verse":63,"sloka":"इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया।विमृश्यैतदशेषेण यथेच्छसि तथा कुरु।।18.63।।","transliteration":"iti te jñānam ākhyātaṁ guhyād guhyataraṁ mayā\nvimṛiśhyaitad aśheṣheṇa yathechchhasi tathā kuru","english":"Thus, the knowledge most secret of all secrets has been declared to you by Me, Shri Krishna; having reflected upon this completely, do as you wish.","hindi":"इस प्रकार मैंने तुमसे वह ज्ञान कहा है, जो समस्त गोपनीय रहस्यों से भी अधिक गुह्य है; इस पर भली-भांति विचार करके, तुम जैसा चाहो वैसा करो।","gujarati":"આ પ્રકારે, મેં તને તે જ્ઞાન કહ્યું છે જે સર્વ ગુપ્ત રહસ્યોથી પણ અત્યંત ગુપ્ત છે; તેના પર સંપૂર્ણ વિચાર કરીને તારી ઈચ્છા મુજબ કર."},"18.64":{"chapter":18,"verse":64,"sloka":"सर्वगुह्यतमं भूयः श्रृणु मे परमं वचः।इष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम्।।18.64।।","transliteration":"sarva-guhyatamaṁ bhūyaḥ śhṛiṇu me paramaṁ vachaḥ\niṣhṭo ‘si me dṛiḍham iti tato vakṣhyāmi te hitam","english":"Hear again My supreme word, the most confidential of all secrets; because you are My dear friend, I shall speak to you for your own benefit.","hindi":"हे अर्जुन! मेरे परम गोपनीय, समस्त गुह्यों में अति उत्तम वचन को पुन: सुनो। तुम मुझे अतिशय प्रिय हो, इसलिए मैं तुम्हारे कल्याण के लिए यह हितकारी बात कहूंगा।","gujarati":"હવે મારા પરમ ગુપ્ત, સર્વ ગુહ્યોમાં સૌથી શ્રેષ્ઠ વચનને ફરીથી સાંભળ. તું મને અત્યંત પ્રિય હોવાથી હું તારા કલ્યાણ માટે આ હિતની વાત કહીશ."},"18.65":{"chapter":18,"verse":65,"sloka":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु।मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे।।18.65।।","transliteration":"man-manā bhava mad-bhakto mad-yājī māṁ namaskuru\nmām evaiṣhyasi satyaṁ te pratijāne priyo ‘si me","english":"Fix your mind on Me, be devoted to Me, worship Me, and bow down to Me. Thus, you will surely come to Me. I promise you this truly, for you are dear to Me.","hindi":"मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु | मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे ||","gujarati":"મારામાં મન પરોવ, મારા ભક્ત બન, મારી પૂજા કર અને મને નમસ્કાર કર; આ રીતે તું મને જ પ્રાપ્ત કરીશ. હું તને સત્ય પ્રતિજ્ઞા આપું છું, કારણ કે તું મારો અત્યંત પ્રિય છે."},"18.66":{"chapter":18,"verse":66,"sloka":"सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज।अहं त्वा सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः।।18.66।।","transliteration":"sarva-dharmān parityajya mām ekaṁ śharaṇaṁ vraja\nahaṁ tvāṁ sarva-pāpebhyo mokṣhayiṣhyāmi mā śhuchaḥ","english":"Abandon all varieties of religion and surrender unto Me alone. I will deliver you from all sinful reactions. Do not fear.","hindi":"सब प्रकार के धर्मों का परित्याग करके केवल मेरी ही शरण में आओ। मैं तुम्हें समस्त पापों से मुक्त कर दूँगा, तुम शोक मत करो।","gujarati":"સર્વ ધર્મોનો ત્યાગ કરીને તું અનન્ય ભાવે માત્ર મારી જ શરણમાં આવ. હું તને સર્વ પાપોમાંથી મુક્ત કરી દઈશ, તું શોક ન કર."},"18.67":{"chapter":18,"verse":67,"sloka":"इदं ते नातपस्काय नाभक्ताय कदाचन।न चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति।।18.67।।","transliteration":"idaṁ te nātapaskyāya nābhaktāya kadāchana\nna chāśhuśhruṣhave vāchyaṁ na cha māṁ yo ‘bhyasūtayi","english":"Never impart this knowledge to one who is devoid of austerities, nor to one who lacks devotion, nor to one who refuses to render service, nor to one who speaks ill of Me, Shri Krishna.","hindi":"यह ज्ञान कभी भी ऐसे व्यक्ति को नहीं देना चाहिए जो तपहीन है, जो भक्त नहीं है, जो सेवा के भाव से रहित है, अथवा जो मुझ श्री कृष्ण में दोष दृष्टि रखता है।","gujarati":"આ જ્ઞાન એવા વ્યક્તિને ક્યારેય ન કહેવું જે તપ વિનાનો છે, જે ભક્તિહીન છે, જે સેવા કરવા માટે ઉત્સુક નથી, અથવા જે મારામાં, એટલે કે શ્રી કૃષ્ણમાં દોષ શોધે છે."},"18.68":{"chapter":18,"verse":68,"sloka":"य इमं परमं गुह्यं मद्भक्तेष्वभिधास्यति।भक्ितं मयि परां कृत्वा मामेवैष्यत्यसंशयः।।18.68।।","transliteration":"ya idaṁ paramaṁ guhyaṁ mad-bhakteṣhv abhidhāsyati\nbhaktiṁ mayi parāṁ kṛitvā mām evaiṣhyaty asanśhayaḥ","english":"He who, having offered supreme devotion unto Me, imparts this supreme secret to My devotees, shall undoubtedly attain Me.","hindi":"जो पुरुष मुझमें परम प्रेम करके, इस परम गोपनीय रहस्य को मेरे भक्तों को सुनाता है, वह नि:संदेह मुझको ही प्राप्त होगा।","gujarati":"જે પુરુષ મારામાં પરમ પ્રેમ રાખીને, આ પરમ ગુહ્ય જ્ઞાન મારા ભક્તોને કહે છે, તે નિઃસંદેહ મને જ પ્રાપ્ત થાય છે."},"18.69":{"chapter":18,"verse":69,"sloka":"न च तस्मान्मनुष्येषु कश्िचन्मे प्रियकृत्तमः।भविता न च मे तस्मादन्यः प्रियतरो भुवि।।18.69।।","transliteration":"na cha tasmān manuṣhyeṣhu kaśhchin me priya-kṛittamaḥ\nbhavitā na cha me tasmād anyaḥ priyataro bhuvi","english":"There is no one among men who does service more pleasing to Me than him, nor shall there be anyone on earth dearer to Me than him.","hindi":"मनुष्यों में कोई भी ऐसा नहीं है, जो मेरा इससे बढ़कर प्रिय कार्य करने वाला हो और पृथ्वी पर इससे बढ़कर मेरा प्रिय दूसरा कोई होगा भी नहीं।","gujarati":"મનુષ્યોમાં કોઈ પણ એવો નથી જે મારા માટે આનાથી વધુ પ્રિય કાર્ય કરનારો હોય, અને આ પૃથ્વી પર આનાથી વધુ પ્રિય મારો કોઈ બીજો હોઈ પણ શકે નહીં."},"18.70":{"chapter":18,"verse":70,"sloka":"अध्येष्यते च य इमं धर्म्यं संवादमावयोः।ज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः।।18.70।।","transliteration":"adhyeṣhyate cha ya imaṁ dharmyaṁ saṁvādam āvayoḥ\njñāna-yajñena tenāham iṣhṭaḥ syām iti me matiḥ","english":"And he who will study this sacred dialogue of ours, by him I shall have been worshipped through the sacrifice of wisdom; such is My conviction.","hindi":"और जो पुरुष हम दोनों के इस धर्ममय संवाद का पठन करेगा, उसके द्वारा मैं ज्ञानयज्ञ से पूजित होऊँगा - ऐसा मेरा मत है।","gujarati":"અને જે કોઈ મનુષ્ય આપણા આ ધર્મમય સંવાદનો પાઠ કરશે, તેના દ્વારા હું જ્ઞાનયજ્ઞથી પૂજાયેલો હોઈશ - એવો મારો મત છે."},"18.71":{"chapter":18,"verse":71,"sloka":"श्रद्धावाननसूयश्च श्रृणुयादपि यो नरः।सोऽपि मुक्तः शुभाँल्लोकान्प्राप्नुयात्पुण्यकर्मणाम्।।18.71।।","transliteration":"śhraddhāvān anasūyaśh cha śhṛiṇuyād api yo naraḥ\nso ‘pi muktaḥ śhubhāl lokān prāpnuyāt puṇya-karmaṇām","english":"And that man who listens with faith and without malice, even he, being liberated, shall attain the auspicious worlds of those who perform righteous deeds.","hindi":"और जो मनुष्य श्रद्धा से युक्त होकर और दोष-दृष्टि से रहित होकर इसका श्रवण भी करेगा, वह भी पापों से मुक्त होकर पुण्य-कर्म करने वालों के शुभ लोकों को प्राप्त होगा।","gujarati":"અને જે મનુષ્ય શ્રદ્ધાવાન તથા દોષદ્રષ્ટિથી રહિત થઈને આનું શ્રવણ પણ કરશે, તે પણ પાપમુક્ત થઈને પુણ્યશાળી પુરુષોના શુભ લોકોને પ્રાપ્ત કરશે."},"18.72":{"chapter":18,"verse":72,"sloka":"कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा।कच्चिदज्ञानसंमोहः प्रनष्टस्ते धनञ्जय।।18.72।।","transliteration":"kachchid etach chhrutaṁ pārtha tvayaikāgreṇa chetasā\nkachchid ajñāna-sammohaḥ pranaṣhṭas te dhanañjaya","english":"O Arjuna, has this been heard by you with a one-pointed mind? O Dhananjaya, has the delusion caused by ignorance been destroyed?","hindi":"हे अर्जुन ! क्या तुमने इसे एकाग्रचित्त होकर सुना है ? हे धनञ्जय ! क्या अज्ञान से उत्पन्न तुम्हारा मोह नष्ट हो गया है ?","gujarati":"હે અર્જુન ! શું તેં આને એકાગ્ર ચિત્તે સાંભળ્યું છે ? અને હે ધનંજય ! શું અજ્ઞાનથી ઉત્પન્ન થયેલો તારો મોહ નષ્ટ થયો છે ?"},"18.73":{"chapter":18,"verse":73,"sloka":"अर्जुन उवाचनष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत।स्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव।।18.73।।","transliteration":"arjuna uvācha\nnaṣhṭo mohaḥ smṛitir labdhā tvat-prasādān mayāchyuta\nsthito ‘smi gata-sandehaḥ kariṣhye vachanaṁ tava","english":"Arjuna said: My delusion is destroyed, and I have regained my memory through Your grace, O Achyuta. I am now firm and free from doubt, and I shall act according to Your word.","hindi":"अर्जुन ने कहा: हे अच्युत! आपकी कृपा से मेरा मोह नष्ट हो गया है और मैंने स्मृति प्राप्त कर ली है। मैं अब संशय-रहित होकर स्थिर हूँ और आपकी आज्ञा का पालन करूँगा।","gujarati":"અર્જુને કહ્યું: હે અચ્યુત! તમારી કૃપાથી મારો મોહ નષ્ટ થયો છે અને મને જ્ઞાન (સ્મૃતિ) પ્રાપ્ત થઈ છે. હું હવે સંશય રહિત અને સ્થિર છું, હું તમારી આજ્ઞાનું પાલન કરીશ."},"18.74":{"chapter":18,"verse":74,"sloka":"सञ्जय उवाचइत्यहं वासुदेवस्य पार्थस्य च महात्मनः।संवादमिममश्रौषमद्भुतं रोमहर्षणम्।।18.74।।","transliteration":"sañjaya uvācha\nity ahaṁ vāsudevasya pārthasya cha mahātmanaḥ\nsaṁvādam imam aśhrauṣham adbhutaṁ roma-harṣhaṇam","english":"Sanjaya said: Thus, I have heard this wonderful and hair-raising dialogue between Lord Krishna and the high-souled Arjuna.","hindi":"संजय ने कहा: इस प्रकार मैंने भगवान् श्रीकृष्ण और महात्मा अर्जुन के इस अद्भुत और रोमांच उत्पन्न करने वाले संवाद को सुना है।","gujarati":"સંજયે કહ્યું: આ પ્રકારે મેં ભગવાન શ્રીકૃષ્ણ અને મહાત્મા અર્જુન વચ્ચેનો આ અદ્ભુત અને રોમાંચક સંવાદ સાંભળ્યો છે."},"18.75":{"chapter":18,"verse":75,"sloka":"व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम्।योगं योगेश्वरात्कृष्णात्साक्षात्कथयतः स्वयम्।।18.75।।","transliteration":"vyāsa-prasādāch chhrutavān etad guhyam ahaṁ param\nyogaṁ yogeśhvarāt kṛiṣhṇāt sākṣhāt kathayataḥ svayam","english":"By the grace of Vyasa, I have heard this supreme and most confidential Yoga, being spoken directly by Shri Krishna, the Lord of Yoga, Himself.","hindi":"व्यास जी की कृपा से मैंने इस परम गोपनीय योग को साक्षात् योगेश्वर श्री कृष्ण के मुख से सुना है।","gujarati":"વ્યાસજીની કૃપાથી મેં આ પરમ ગુહ્ય યોગને સાક્ષાત્ યોગેશ્વર શ્રીકૃષ્ણના મુખેથી સાંભળ્યો છે."},"18.76":{"chapter":18,"verse":76,"sloka":"राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम्।केशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः।।18.76।।","transliteration":"rājan sansmṛitya sansmṛitya saṁvādam imam adbhutam\nkeśhavārjunayoḥ puṇyaṁ hṛiṣhyāmi cha muhur muhuḥ","english":"O King, as I recall this wonderful and holy dialogue between Lord Krishna and Arjuna, I rejoice again and again.","hindi":"हे राजन् ! भगवान् श्रीकृष्ण और अर्जुन के इस अद्भुत और पवित्र संवाद को बार-बार याद करके मैं अत्यधिक आनन्दित हो रहा हूँ।","gujarati":"હે રાજન! ભગવાન શ્રીકૃષ્ણ અને અર્જુનના આ અદ્ભુત અને પવિત્ર સંવાદને વારંવાર યાદ કરીને હું અત્યંત આનંદિત થઈ રહ્યો છું."},"18.77":{"chapter":18,"verse":77,"sloka":"तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः।\n\nविस्मयो मे महान् राजन् हृष्यामि च पुनः पुनः।।18.77।।","transliteration":"tach cha sansmṛitya saṁsmṛitya rūpam aty-adbhutaṁ hareḥ\nvismayo ye mahān rājan hṛiṣhyāmi cha punaḥ punaḥ","english":"And, remembering again and again that most wonderful form of Shri Hari, I am filled with great wonder, O King; and I rejoice again and again.","hindi":"हे राजन! श्री हरि के उस अत्यंत अद्भुत और कल्याणकारी रूप का बार-बार स्मरण करके, मुझे महान आश्चर्य हो रहा है और मैं पुनः-पुनः आनंदित हो रहा हूँ।","gujarati":"હે રાજન! શ્રી હરિના તે અત્યંત અદ્ભુત રૂપનું વારંવાર સ્મરણ કરીને મને મહાન આશ્ચર્ય થાય છે અને હું વારંવાર આનંદ પામી રહ્યો છું."},"18.78":{"chapter":18,"verse":78,"sloka":"यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः।\n\nतत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम।।18.78।","transliteration":"yatra yogeśhvaraḥ kṛiṣhṇo yatra pārtho dhanur-dharaḥ\ntatra śhrīr vijayo bhūtir dhruvā nītir matir mama","english":"Wherever there is Krishna, the Lord of Yoga, and wherever there is Arjuna, the wielder of the bow, there will surely be prosperity, victory, extraordinary power, and firm morality; this is my firm conviction.","hindi":"जहाँ योगेश्वर श्रीकृष्ण हैं और जहाँ धनुर्धारी अर्जुन है, वहीं श्री, विजय, विभूति और अचल नीति है—ऐसा मेरा अटल मत है।","gujarati":"જ્યાં યોગેશ્વર શ્રીકૃષ્ણ છે અને જ્યાં ગાંડીવધારી અર્જુન છે, ત્યાં જ લક્ષ્મી, વિજય, સંપત્તિ અને નીતિ છે—આવો મારો નિશ્ચિત મત છે."}}};
export default gitaData;
